var RANKED=[{"id":6325,"bg":"При тази ситуация пресичането на линията, сигнализирана с конусите, е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60317.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"}],"f":53,"es":"En esta situación, cruzar la línea señalizada con conos está:","explain":"Prohibido: la fila de conos delimita una línea de organización TEMPORAL del tráfico, y cruzarla equivale a cruzar una línea continua. Los conos redistribuyen los carriles (obras, incidente): ignorarlos te mete en la zona cerrada o en el sentido contrario.","val":53,"fase":1},{"id":5428,"bg":"На какво разстояние зад МПС, принудително спряло на автомагистрала, се поставя предупредителният светлоотразителен триъгълник?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":null,"v":null,"a":[{"t":"не по-малко от 100 м","ok":true,"i":null,"es":"no menos de 100 m"},{"t":"не по-малко от 30 м","ok":false,"i":null,"es":"no menos de 30 m"},{"t":"не по-малко от 50 м","ok":false,"i":null,"es":"no menos de 50 m"},{"t":"не по-малко от 70 м","ok":false,"i":null,"es":"no menos de 70 m"}],"f":49,"es":"¿A qué distancia detrás de un vehículo parado forzosamente en autopista se coloca el triángulo de emergencia?","explain":"En autopista rige la distancia de vías rápidas: mínimo 100 m. El tráfico llega a 130 km/h y recorre 36 m por segundo: con 30 o 50 m nadie tendría tiempo de reaccionar ante el vehículo averiado.","val":49,"fase":1},{"id":5658,"bg":"В населено място предупредителният светлоотразителен триъгълник, се поставя:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":null,"v":null,"a":[{"t":"на разстояние не по-малко от 30 м от повреденото ППС","ok":true,"i":null,"es":"a no menos de 30 m del vehículo averiado"},{"t":"в пътната лента, заета от повреденото ППС","ok":true,"i":null,"es":"en el carril ocupado por el vehículo averiado"},{"t":"срещу посоката на движение на превозните средства които заобикалят повреденото ППС","ok":true,"i":null,"es":"en sentido contrario a la circulación de los vehículos que rodean el averiado"},{"t":"на тротоара","ok":false,"i":null,"es":"en la acera"}],"f":50,"es":"En zona urbana, el triángulo de emergencia reflectante se coloca: (3 respuestas correctas) (3 correctas)","explain":"En ciudad el triángulo se coloca: a mínimo 30 m del vehículo, EN el mismo carril ocupado (no en la acera, donde los conductores no lo verían asociado al obstáculo) y de cara al tráfico que se aproxima, para que su reflectante funcione.","val":50,"fase":1},{"id":11733,"bg":"На пътища с разрешена скорост за движение, по-висока от 90 km/h, предупредителният светлоотразителен триъгълник се поставя на разстояние от автомобила, не по-малко от:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":null,"v":null,"a":[{"t":"100 метра","ok":true,"i":null,"es":"100 metros"},{"t":"30 метра","ok":false,"i":null,"es":"30 metros"},{"t":"50 метра","ok":false,"i":null,"es":"50 metros"},{"t":"150 метра","ok":false,"i":null,"es":"150 metros"}],"f":53,"es":"En carreteras con velocidad permitida superior a 90 km/h, el triángulo de emergencia se coloca a no menos de:","explain":"En vías con límite SUPERIOR a 90 km/h el triángulo va a mínimo 100 m: a esas velocidades el que llega necesita mucho más espacio para percibir, reaccionar y frenar. Compara: hasta 90 km/h bastan 30 m.","val":53,"fase":1},{"id":6327,"bg":"Белият бастун, носен от пешеходец, означава, че той е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":null,"v":null,"a":[{"t":"сляп","ok":true,"i":null,"es":"ciego"},{"t":"глухоням","ok":false,"i":null,"es":"sordomudo"},{"t":"много възрастен","ok":false,"i":null,"es":"muy anciano"}],"f":53,"es":"El bastón blanco que lleva un peatón significa que es:","explain":"El bastón blanco identifica al peatón CIEGO: es el símbolo universal reconocido por la ley. Ante él debes extremar la precaución y cederle el paso siempre: no puede verte ni calcular tu velocidad. No existe distintivo de bastón para sordomudos o ancianos.","val":53,"fase":1},{"id":6326,"bg":"При тази ситуация конусите очертават линия, пресичането на която е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60367.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"}],"f":46,"es":"En esta situación, los conos delimitan una línea cuyo cruce está:","explain":"Prohibido: misma regla que su gemela: los conos forman una línea infranqueable de señalización temporal. Su color llamativo no es decorativo: sustituyen a la marca continua mientras dura la situación especial.","val":46,"fase":1},{"id":11734,"bg":"На пътища с разрешена скорост за движение до 90 km/h, предупредителният светлоотразителен триъгълник се поставя на разстояние от автомобила не по-малко от:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":null,"v":null,"a":[{"t":"30 метра","ok":true,"i":null,"es":"30 metros"},{"t":"50 метра","ok":false,"i":null,"es":"50 metros"},{"t":"70 метра","ok":false,"i":null,"es":"70 metros"},{"t":"100 метра","ok":false,"i":null,"es":"100 metros"}],"f":47,"es":"En carreteras con velocidad permitida hasta 90 km/h, el triángulo de emergencia se coloca a no menos de:","explain":"Hasta 90 km/h el triángulo se coloca a mínimo 30 m. Es la pareja de la regla anterior: ≤90 km/h → 30 m; >90 km/h → 100 m. Truco: velocidad 'normal' = distancia corta, velocidad alta = distancia larga.","val":47,"fase":1},{"id":6034,"bg":"При кое от посочените средства за сигнализиране съществува опасност от внезапна поява на деца на платното за движение?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/26647.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/26648.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/26649.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/26650.png","es":""}],"f":50,"es":"¿En qué medio de señalización existe peligro de aparición repentina de niños en la calzada? (múltiple) (3 correctas)","explain":"Los tres medios correctos señalizan lugares con presencia de NIÑOS (advertencia de niños, zona escolar/peatonal, parada donde suben y bajan): ahí pueden irrumpir en la calzada de golpe. El cuarto no guarda relación con niños: señaliza otra cosa. Ante cualquiera de los tres: pie fuera del acelerador.","val":50,"fase":1},{"id":6324,"bg":"Временната пътна маркировка се разпознава по:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":null,"v":null,"a":[{"t":"цвета на маркировката","ok":true,"i":null,"es":"el color de la señalización"},{"t":"широчината на линиите","ok":false,"i":null,"es":"el ancho de las líneas"},{"t":"коефициента на светлоотразяване","ok":false,"i":null,"es":"el coeficiente de reflexión"}],"f":22,"es":"La señalización vial temporal se reconoce por:","explain":"La señalización temporal se reconoce por el COLOR: las marcas temporales son amarillas o naranjas frente al blanco de las permanentes. Ni el grosor de línea ni la reflectancia son el criterio distintivo legal.","val":22,"fase":4},{"id":6307,"bg":"Разрешено ли е пресичането на единичната непрекъсната линия между съседните пътни ленти?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60617.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":18,"es":"¿Está permitido cruzar la línea continua simple entre carriles adyacentes?","explain":"No: continua simple entre carriles adyacentes = infranqueable. Es la formulación más escueta de la familia: la respuesta es siempre la misma, se pregunte como se pregunte.","val":18,"fase":4},{"id":6315,"bg":"Разрешено ли е пресичането на единичната непрекъсната линия, очертаваща границата на платното за движение?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59834.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":17,"es":"¿Está permitido cruzar la línea continua simple que delimita el borde de la calzada?","explain":"Sí: es la línea continua simple que delimita el BORDE de la calzada, no una separadora de carriles. Se cruza legalmente para abandonar la calzada (arcén, entrada a garaje o propiedad). Trampa del examen: te enseñaron 'continua = prohibido cruzar', pero eso aplica ENTRE carriles/sentidos. Borde de calzada = cruzarla está permitido.","val":17,"fase":4},{"id":6309,"bg":"Пресичането на единичната непрекъсната линия между съседните пътни ленти е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59594.png","v":null,"a":[{"t":"забранено във всички случаи","ok":true,"i":null,"es":"prohibido en todos los casos"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"},{"t":"забранено, освен за спиране от другата страна на пътя","ok":false,"i":null,"es":"prohibido salvo para parar al otro lado de la vía"}],"f":21,"es":"Cruzar la línea continua simple entre carriles adyacentes está:","explain":"Prohibido en todos los casos: la continua simple entre carriles adyacentes no se cruza nunca: ni para adelantar, ni para girar, ni 'para parar al otro lado' (el distractor recurrente). La discontinua existe exactamente para permitir lo que la continua niega.","val":21,"fase":4},{"id":6330,"bg":"“Изкуствената неравност” върху платното за движение е предназначена за:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":null,"v":null,"a":[{"t":"ограничаване скоростта на ППС","ok":true,"i":null,"es":"limitar la velocidad de los vehículos"},{"t":"обозначаване на препятствие върху платното за движение","ok":false,"i":null,"es":"señalizar un obstáculo en la calzada"},{"t":"сигнализиране на площи забранени за движение","ok":false,"i":null,"es":"señalizar zonas prohibidas al tráfico"}],"f":22,"es":"El 'resalto artificial' (badén) en la calzada está diseñado para:","explain":"El badén ('policía tumbado') tiene una única función legal: obligar a REDUCIR LA VELOCIDAD mediante un obstáculo físico. No señaliza obstáculos ni delimita zonas prohibidas: para eso existen señales y marcas.","val":22,"fase":4},{"id":6308,"bg":"Пресичането на единичната непрекъсната линия между съседните пътни ленти е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57911.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"}],"f":20,"es":"Cruzar la línea continua simple entre carriles adyacentes está:","explain":"Prohibido: continua simple entre carriles = muro pintado. Es la versión directa de la familia: sin excepciones ni matices.","val":20,"fase":4},{"id":6312,"bg":"Пресичането на единичната прекъсната линия между съседните пътни ленти е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59734.png","v":null,"a":[{"t":"разрешено","ok":true,"i":null,"es":"permitido"},{"t":"забранено","ok":false,"i":null,"es":"prohibido"}],"f":20,"es":"Cruzar la línea discontinua simple entre carriles adyacentes está:","explain":"PERMITIDO.\n\nQUÉ ES ESTA LÍNEA. «Единична прекъсната линия» — línea discontinua simple entre carriles contiguos. En la foto, el coche rojo se está cambiando de carril cruzándola, con el intermitente puesto.\n\nQUÉ SIGNIFICA UNA LÍNEA DISCONTINUA. Se puede cruzar. Marca la separación entre carriles pero no la cierra: es una guía, no una barrera. Cambiar de carril, adelantar o rodear un obstáculo son maniobras legales sobre ella.\n\nQUÉ NO SIGNIFICA. No es un permiso incondicional. Cruzarla exige lo de siempre: intermitente, comprobar el espejo y el ángulo muerto, y no obligar a frenar a quien ya circula por el carril al que entras. La línea autoriza la maniobra; la maniobra sigue teniendo sus reglas.\n\nLA OPUESTA ES LA CONTINUA. «Непрекъсната линия»: no se cruza ni se pisa. Y la doble continua tampoco, en ningún sentido.\n\nCLAVE: discontinua = puedes, con las precauciones de siempre. Continua = no puedes, punto. Es la distinción más rentable de toda la señalización horizontal.\n\nMÉTODO DE CARRILES: 1) ¿cuántos carriles tiene MI sentido? Con dos o más nunca se invade el contrario. 2) ¿la línea es continua o discontinua? 3) ¿hay señal Д1 que declare los carriles? 4) ¿el carril está reservado (BUS, lentos)? Desarrollado en Leyes → «Carriles y líneas: quién puede ir por dónde».","val":20,"fase":4},{"id":6317,"bg":"При тази ситуация на кой от автомобилите е разрешено да пресече пътната маркировка?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60017.png","v":null,"a":[{"t":"синия","ok":true,"i":null,"es":"al azul"},{"t":"червения","ok":false,"i":null,"es":"al rojo"},{"t":"на двата автомобила","ok":false,"i":null,"es":"a ambos vehículos"}],"f":20,"es":"En esta situación, ¿a cuál de los vehículos le está permitido cruzar la señalización vial?","explain":"Al AZUL: en su lado la marca es discontinua (cruzable); el rojo tiene la continua en su lado y no puede pisarla. En las líneas dobles mixtas manda el trazo de TU lado: es la regla que esta imagen enseña.","val":20,"fase":4},{"id":6322,"bg":"При тази ситуация пътната маркировка, поставена напречно на пътя, сигнализира:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60283.png","v":null,"a":[{"t":"изкуствена неравност на платното за движение","ok":true,"i":null,"es":"un resalto artificial (badén)"},{"t":"участък от пътя в ремонт","ok":false,"i":null,"es":"un tramo en obras"},{"t":"линия за изчакване","ok":false,"i":null,"es":"una línea de espera"},{"t":"място за задължително спиране","ok":false,"i":null,"es":"un lugar de parada obligatoria"}],"f":22,"es":"En esta situación, la señalización transversal en la calzada indica:","explain":"Es un RESALTO artificial (badén, 'policía tumbado'): la banda transversal señalizada en la calzada que obliga físicamente a reducir. No es línea de espera ni parada obligatoria: es el aviso del obstáculo moderador de velocidad.","val":22,"fase":4},{"id":6328,"bg":"При несъответствие между временната пътна маркировка и постоянната пътна маркировка, водачите:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":null,"v":null,"a":[{"t":"трябва да се съобразяват с временната пътна маркировка","ok":true,"i":null,"es":"deben atenerse a la señalización temporal"},{"t":"трябва да се съобразяват с постоянната пътна маркировка","ok":false,"i":null,"es":"deben atenerse a la señalización permanente"},{"t":"не трябва да се съобразяват с пътната маркировка","ok":false,"i":null,"es":"no deben atenerse a ninguna señalización"}],"f":24,"es":"Cuando la señalización temporal y la permanente no coinciden, los conductores:","explain":"Cuando la señalización temporal (amarilla, de obras) contradice a la permanente, obedeces la TEMPORAL: refleja la situación real actual de la vía. La permanente quedó desactivada por las circunstancias que motivaron la temporal.","val":24,"fase":4},{"id":11610,"bg":"При тази ситуация, кой от пътните знаци трябва да спазва водачът на синия автомобил?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123582022.png","v":null,"a":[{"t":"поставения на платното за движение преносим пътен знак","ok":true,"i":null,"es":"la señal portátil colocada en la calzada"},{"t":"постоянно поставения пътен знак","ok":false,"i":null,"es":"la señal fija instalada permanentemente"}],"f":18,"es":"En esta situación, ¿qué señal de tráfico debe respetar el conductor del vehículo azul?","explain":"La señal PORTÁTIL colocada sobre la calzada.\n\nQUÉ VES. Dos señales que se contradicen: en el poste, la «P» azul que permite estacionar; sobre un trípode en la calzada, el círculo azul cruzado en rojo que lo prohíbe. El coche azul se dispone a aparcar.\n\nMANDA LA PORTÁTIL. Las señales temporales o portátiles prevalecen sobre las instaladas de forma permanente. Es la misma lógica que pone al agente por encima del semáforo: gana la fuente de información más reciente y más pegada a la situación real.\n\nPOR QUÉ EXISTE ESTA REGLA. Una obra, una mudanza, un rodaje o un evento cambian las condiciones de un día para otro. Sería absurdo tener que retirar la señalización fija cada vez; se coloca una portátil que la deja sin efecto mientras dure.\n\nEL ERROR TÍPICO es descartar la portátil por parecer «provisional» o menos oficial. Precisamente por ser provisional es la que refleja lo que pasa hoy.\n\nCLAVE: recuerda la jerarquía de fuentes de arriba abajo: agente, semáforo, señal portátil, señal fija, marcas viales. Cuanto más humana y más reciente es la orden, más manda.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":18,"fase":4},{"id":12056,"bg":"Какво трябва да направите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":48,"a":[{"t":"да спра в разделителната ивица между платната на релсовия път, където е спрял другият автомобил","ok":false,"i":null,"es":"parar en la mediana donde está parado el otro coche"},{"t":"да спра, преди да завия наляво","ok":true,"i":null,"es":"parar ANTES de girar a la izquierda"},{"t":"да завия наляво, за да не възпрепятствам движението на автомобилите зад мен","ok":false,"i":null,"es":"girar a la izquierda para no obstaculizar el tráfico de atrás"}],"f":21,"es":"¿Qué debe hacer en esta situación? (VIDEO)","explain":"Quiero girar a la izquierda cruzando las vías del tranvía y en el espejo ya asoma un tranvía: lo correcto es DETENERME antes de iniciar el giro y dejarlo pasar. Pararme en la franja divisoria sobre las vías (donde quedó atrapado el otro coche del video) me dejaría en el camino del tranvía; y girar 'para no estorbar a los de atrás' antepone su comodidad a la seguridad. Nunca te detengas sobre raíles.","val":31,"fase":3},{"id":6314,"bg":"При тази ситуация пресичането на единичната непрекъсната линия, очертаваща границата на платното за движение, е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59817.png","v":null,"a":[{"t":"разрешено","ok":true,"i":null,"es":"permitido"},{"t":"забранено","ok":false,"i":null,"es":"prohibido"}],"f":17,"es":"En esta situación, cruzar la línea continua que delimita el borde de la calzada está:","explain":"Permitido: esta línea continua NO separa carriles ni sentidos — marca el BORDE de la calzada. Cruzarla para salir de la calzada (detenerse en el arcén, entrar a una propiedad) está permitido. La regla 'continua = infranqueable' vale para la que separa flujos de tráfico; la línea de borde es la excepción clásica que el examen explota.","val":17,"fase":4},{"id":6321,"bg":"Върху маркираната с коси успоредни линии част от платното за движение навлизането е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60234.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"entrar (prohibido en todos los casos)"},{"t":"разрешено само при изпреварване","ok":false,"i":null,"es":"entrar solo al adelantar"},{"t":"разрешено само за спиране за престой","ok":false,"i":null,"es":"entrar solo para parar"}],"f":26,"es":"En la zona delimitada con líneas oblicuas paralelas está prohibido:","explain":"La zona de líneas oblicuas paralelas (zebrado) es superficie EXCLUIDA del tráfico: prohibido entrar en todos los casos: ni para adelantar ni para parar. Canaliza el tráfico y protege espacios (isletas, bifurcaciones): es un 'no pisar' pintado.","val":26,"fase":4},{"id":12054,"bg":"При тази ситуация трябва да намалите скоростта, с готовност за спиране заради:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":46,"a":[{"t":"мотоциклета","ok":true,"i":null,"es":"la moto"},{"t":"синия автомобил","ok":false,"i":null,"es":"el coche azul"},{"t":"велосипедиста","ok":false,"i":null,"es":"el ciclista"}],"f":17,"es":"En esta situación debe reducir velocidad con disposición de frenar por: (VIDEO)","explain":"En la escena final una moto sale de un camino lateral por la izquierda con trayectoria que corta la mía: aunque circulo por la vía con prioridad (rombo amarillo Б3), reduzco con disposición de frenar POR LA MOTO — tener prioridad no te protege si el otro no la respeta (conducción defensiva). El coche azul viene de frente por su propio carril y el ciclista no invade mi trayectoria: no son la amenaza real.","val":26,"fase":3},{"id":12058,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":50,"a":[{"t":"изчаквам на коловозите","ok":false,"i":null,"es":"espero sobre las vías"},{"t":"внимателно пресичам релсите","ok":false,"i":null,"es":"cruzo las vías con cuidado"},{"t":"изчаквам пред прелеза","ok":true,"i":null,"es":"espero ANTES del paso a nivel"}],"f":15,"es":"¿Cuál es la actuación correcta en esta situación? (VIDEO - paso a nivel)","explain":"Tras el paso a nivel el tráfico está retenido y apenas hay hueco al otro lado: espero ANTES del paso a nivel y solo entro cuando pueda cruzarlo POR COMPLETO. 'Esperar sobre los raíles' es la trampa mortal del examen y de la vida real; 'cruzar con cuidado' tampoco sirve si no hay espacio libre después. Un paso a nivel se cruza entero o no se entra.","val":22,"fase":3},{"id":6311,"bg":"При тази ситуация, на водача на лекия автомобил е разрешено да пресече единичната непрекъсната линия за да спре от другата страна на пътя.","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59668.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":21,"es":"En esta situación, al conductor del turismo le está permitido cruzar la línea continua para aparcar al otro lado. Esto es:","explain":"INCORRECTO: cruzar la continua 'para aparcar al otro lado' no existe como excepción: es la misma trampa de la 6310 formulada al revés. La línea continua es absoluta: el aparcamiento no la perdona.","val":21,"fase":4},{"id":6313,"bg":"При тази ситуация, на водача на лекия автомобил е разрешено да пресече единичната прекъсната линия за да спре от другата страна на пътя.","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59734.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"CORRECTO"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"f":17,"es":"En esta situación, al conductor del turismo le está permitido cruzar la línea discontinua para aparcar al otro lado. Esto es:","explain":"Correcto: la línea DISCONTINUA simple es franqueable por definición — el conductor puede cruzarla para pasar al otro lado de la calzada y detenerse allí, cediendo antes al tráfico en sentido contrario. 'Incorrecto' sería la respuesta si la línea fuera CONTINUA entre carriles: esa sí es infranqueable. Discontinua = se puede pisar y cruzar.","val":17,"fase":4},{"id":12057,"bg":"Искате да продължите движението си направо. Как трябва да постъпите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":49,"a":[{"t":"спирам непосредствено зад жълтото превозно средство","ok":false,"i":null,"es":"paro inmediatamente detrás del vehículo amarillo"},{"t":"спирам пред кръстовището","ok":true,"i":null,"es":"paro ANTES de la intersección"},{"t":"спирам между жълтото и синьото превозно средство","ok":false,"i":null,"es":"paro entre el amarillo y el azul"}],"f":14,"es":"Quiere continuar recto. ¿Cómo debe actuar en esta situación? (VIDEO - semáforo)","explain":"El semáforo está en VERDE pero al otro lado del cruce la cola está detenida (la furgoneta amarilla no avanza): paro ANTES de la intersección. El verde autoriza a entrar solo si también puedes SALIR; detenerte dentro — detrás del amarillo o entre el amarillo y el azul — bloquea el cruce para los demás flujos. Regla de oro: no entres a un cruce que no puedas abandonar.","val":22,"fase":3},{"id":6316,"bg":"Разрешено ли е пресичането на единичната прекъсната линия, очертаваща границата на платното за движение?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59885.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":20,"es":"¿Está permitido cruzar la línea discontinua que delimita el borde de la calzada?","explain":"Sí: la línea discontinua del BORDE de la calzada puede cruzarse: por ejemplo para parar en el arcén o incorporarte desde él. Si el borde fuera continuo, cruzarlo estaría prohibido salvo emergencia: el tipo de trazo decide.","val":20,"fase":4},{"id":6323,"bg":"Върху площта, очертана с жълтата начупена линия е разрешено да спрете за:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/88414.png","v":null,"a":[{"t":"престой","ok":true,"i":null,"es":"parada breve (prestoy)"},{"t":"паркиране","ok":false,"i":null,"es":"aparcar"},{"t":"престой и паркиране","ok":false,"i":null,"es":"parada breve y aparcamiento"}],"f":23,"es":"En la zona delimitada con la línea amarilla quebrada está permitido parar para:","explain":"La línea amarilla quebrada junto al bordillo delimita una zona donde solo se permite el престой: detención breve (subir/bajar pasajeros, cargar/descargar) sin abandonar la actividad. Паркиране (dejar estacionado el vehículo) está prohibido sobre ella — por eso 'aparcar' y 'parada breve y aparcamiento' son falsas. Amarillo en el bordillo = régimen especial, nunca estacionamiento libre.","val":23,"fase":4},{"id":5845,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24421.png","v":null,"a":[{"t":"преминаването ми е забранено","ok":true,"i":null,"es":"me está PROHIBIDO pasar"},{"t":"мога да завия надясно","ok":false,"i":null,"es":"puedo girar a la derecha"},{"t":"мога да завия наляво","ok":false,"i":null,"es":"puedo girar a la izquierda"},{"t":"мога да завия в обратна посока","ok":false,"i":null,"es":"puedo dar la vuelta"}],"f":11,"es":"La señal del agente regulador significa que:","explain":"Me está PROHIBIDO pasar.\n\nLO QUE VES. El agente está de CARA a ti, con los dos brazos bajados a lo largo del cuerpo. Se le ve la cara y el frente del chaleco reflectante.\n\nEL PECHO ES MURO. Con los brazos bajados, la ley abre solo los dos costados. Quien tiene delante el pecho o la espalda del agente tiene «Преминаването е забранено».\n\nGIRAR TAMBIÉN ES PASAR. Por eso las tres opciones de giro son falsas: ni derecha, ni izquierda, ni media vuelta. La prohibición es total hasta que el agente cambie de posición.\n\nEL GESTO, EN LA LEY (чл. 10, ал. 2, т. 2 ЗДвП): «ръка или ръце, протегнати хоризонтално встрани» — brazo o brazos extendidos horizontalmente a los lados; hecho el gesto, el agente puede bajar los brazos y la señal sigue valiendo. Significa «Преминаването е разрешено» para quien está frente a su hombro izquierdo o derecho Y va a seguir recto o girar a la derecha, y «Преминаването е забранено» para todos los demás.\n\nMÉTODO: 1) ¿brazo vertical? alto total. 2) ¿qué te muestra a TI: pecho, espalda o costado? pecho y espalda son muro siempre. 3) ¿costado sin brazo extendido? pasas, recto o derecha. 4) ¿costado CON brazo extendido? solo el izquierdo pasa. Está desarrollado con casos en Leyes → «El agente regulador: los 3 gestos y el método».\n\nCLAVE: dos preguntas antes de responder — ¿qué parte del agente veo? y ¿qué hace con los brazos? Aquí: pecho + brazos abajo = parado.","val":17,"fase":3},{"id":6523,"bg":"При тази ситуация кой от автомобилите трябва да пропуснете?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57175.png","v":null,"a":[{"t":"червения автомобил","ok":true,"i":null,"es":"al vehículo ROJO"},{"t":"синия автомобил","ok":false,"i":null,"es":"al vehículo azul"}],"f":9,"es":"En esta situación, ¿a cuál vehículo debe dejar pasar?","explain":"Al ROJO. Tienes un STOP, así que debes ceder a quien circula por la vía transversal, y el rojo va justo por ella cruzando tu trayectoria. El azul, en cambio, está en TU misma vía, de frente: no te cruza y no le cedes nada. Ahí está la trampa — con un STOP se tiende a ceder a todo lo que se mueve, pero solo obliga con quien circula por la vía con prioridad.","val":13,"fase":3},{"id":12053,"bg":"При тази ситуация трябва да:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":45,"a":[{"t":"осигурите предимство на зеления автомобил","ok":true,"i":null,"es":"ceder el paso al coche verde"},{"t":"осигурите предимство на червения автомобил","ok":false,"i":null,"es":"ceder el paso al coche rojo"},{"t":"изчакате преминаването на велосипедиста","ok":true,"i":null,"es":"esperar al ciclista"}],"f":16,"es":"En esta situación debes: (VIDEO) ⚠️ 2 correctas","explain":"Giro a la izquierda desde la vía preferente (rombo Б3): cedo el paso al coche VERDE que viene de frente — girar a la izquierda nunca da prioridad sobre el sentido contrario, ni siquiera en vía preferente — y espero a que el CICLISTA termine de cruzar. El coche rojo llega por la vía sin prioridad: él me cede a mí. Orden al girar a la izquierda: primero el sentido contrario, luego los vulnerables, después el giro.","val":24,"fase":3},{"id":12062,"bg":"Искате да продължите по пътя с предимство. Какво трябва да очаквате при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":53,"a":[{"t":"че децата ще слязат на платното за движение","ok":true,"i":null,"es":"que los niños bajen a la calzada"},{"t":"че микробусът ще продължи движението си по пътя с предимство","ok":false,"i":null,"es":"que el microbús continúe por la vía preferente"},{"t":"че водачът на червения автомобил няма да ме види навреме","ok":true,"i":null,"es":"que el conductor del coche rojo no me vea a tiempo"}],"f":18,"es":"Quiere continuar por la vía preferente. ¿Qué debe esperar? (VIDEO) ⚠️ 2 correctas","explain":"El microbús naranja está detenido junto a la acera dejando pasajeros mientras la vía preferente tuerce a la izquierda: debo esperar que aparezcan NIÑOS bajando a la calzada ocultos por el microbús, y que el conductor del coche rojo, con la visión tapada por él, NO me vea a tiempo. Que 'el microbús continúe su marcha' no es el peligro: está parado. Vehículo detenido = cortina que oculta peatones.","val":27,"fase":3},{"id":5416,"bg":"При движение по автомобилен път на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да навлиза в разделителната ивица или да я пресича, включително и на местата, където тя е прекъсната","ok":true,"i":null,"es":"entrar en la mediana o cruzarla, incluso donde esté interrumpida"},{"t":"да завива в обратна посока","ok":true,"i":null,"es":"dar la vuelta (cambio de sentido)"},{"t":"да се движи назад","ok":true,"i":null,"es":"circular marcha atrás"},{"t":"да спира за отстраняване на неизправност по автомобила","ok":false,"i":null,"es":"parar para reparar una avería"}],"f":8,"es":"Conduciendo por vía rápida (autopista), al conductor le está PROHIBIDO: (3 correctas)","explain":"Prohibido en vía rápida: entrar o cruzar la mediana (aunque esté interrumpida), dar la vuelta y circular marcha atrás: las tres maniobras van contra el flujo de alta velocidad. Parar para reparar una avería es la excepción permitida.","val":8,"fase":4},{"id":5610,"bg":"Спирането за престой е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на велосипедна пътека","ok":true,"i":null,"es":"en un carril bici"},{"t":"на разстояние, по-малко от 5 метра преди велосипедна пътека","ok":true,"i":null,"es":"a menos de 5 metros ANTES de un carril bici"},{"t":"на разстояние, по-малко от 5 метра след велосипедна пътека","ok":false,"i":null,"es":"a menos de 5 metros DESPUÉS de un carril bici"}],"f":6,"es":"La parada breve (prestoy) está prohibida: (2 correctas)","explain":"Parada breve prohibida SOBRE el carril bici y a menos de 5 m ANTES de él: taparías al ciclista que llega justo donde cruza tu trayectoria. Después del carril la prohibición no rige.","val":3,"fase":4},{"id":12059,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":61,"a":[{"t":"да се движа възможно най-вляво","ok":true,"i":null,"es":"me muevo todo lo posible a la izquierda"},{"t":"продължавам движението си в заеманата лента","ok":false,"i":null,"es":"continúo en mi carril"},{"t":"намалявам скоростта си на движение","ok":true,"i":null,"es":"reduzco la velocidad"}],"f":22,"es":"¿Cuál es la actuación correcta en esta situación? (VIDEO) ⚠️ 2 correctas","explain":"La escena final muestra un triángulo de preseñalización y un incidente en el lado derecho de la autovía: la reacción correcta es doble — REDUCIR la velocidad y apartarme todo lo posible a la IZQUIERDA para dar espacio lateral al lugar del accidente. Seguir en mi carril sin cambiar nada ignora el peligro. Regla: ante incidente u obstáculo en el margen, velocidad abajo + máxima distancia lateral.","val":11,"fase":4},{"id":5888,"bg":"Значението на този сигнал на регулировчика е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39253.png","v":null,"a":[{"t":"„Внимание, спри!”","ok":true,"i":null,"es":"'¡Atención, para!'"},{"t":"„Премини с повишено внимание”","ok":false,"i":null,"es":"'Pasa con precaución redoblada'"},{"t":"„Внимание”","ok":false,"i":null,"es":"'¡Atención!'"},{"t":"„Пропусни движещите се по пресичания път”","ok":false,"i":null,"es":"'Cede el paso a los que circulan por la vía transversal'"}],"f":11,"es":"El significado de esta señal del agente regulador es:","explain":"«¡Atención, para!» — „Внимание, спри!”.\n\nLO QUE VES. El agente, visto desde el coche, con el brazo derecho levantado verticalmente.\n\nALTO PARA TODOS, vengan de donde vengan. Es el gesto más simple de los tres y el único que no exige averiguar qué parte del cuerpo te está mostrando.\n\nLOS TRES DISTRACTORES SON LOS MISMOS de la 5885 y conviene reconocerlos de un vistazo: «Внимание» a secas (le falta la orden de parar), «pasa con precaución» (dice lo contrario) y «cede el paso a la vía transversal» (eso es una señal de prioridad, no un gesto).\n\nEL GESTO, EN LA LEY (чл. 10, ал. 2, т. 1 ЗДвП): «дясна ръка, вдигната вертикално» — brazo derecho levantado en vertical. Significa «Внимание, спри!». No se aplica a quien, tras habérsele permitido el paso, está tan cerca del agente que no puede detenerse sin crear peligro; y quien ya ha entrado en el cruce debe despejarlo.\n\nMÉTODO: 1) ¿brazo vertical? alto total. 2) ¿qué te muestra a TI: pecho, espalda o costado? pecho y espalda son muro siempre. 3) ¿costado sin brazo extendido? pasas, recto o derecha. 4) ¿costado CON brazo extendido? solo el izquierdo pasa. Está desarrollado con casos en Leyes → «El agente regulador: los 3 gestos y el método».\n\nCLAVE: la familia del agente tiene solo tres gestos. Brazo arriba = todos parados. Brazos bajados o en cruz = pasan los costados, recto o derecha. Brazo derecho extendido al frente = pasa solo el hombro izquierdo. Con esos tres se resuelven las 18 preguntas del banco.","val":16,"fase":3},{"id":5914,"bg":"Този сигнал на светофара означава, че е забранено навлизането в кръстовището на ППС, които:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43602.png","v":null,"a":[{"t":"преминават направо","ok":true,"i":null,"es":"continúan recto"},{"t":"завиват наляво","ok":true,"i":null,"es":"giran a la izquierda"},{"t":"завиват надясно","ok":false,"i":null,"es":"giran a la derecha"}],"f":10,"es":"Esta señal de semáforo significa que está PROHIBIDO entrar en la intersección a los vehículos que: (2 correctas)","explain":"A los que continúan RECTO y a los que giran a la IZQUIERDA.\n\nQUÉ VES. Un semáforo con el rojo encendido y, debajo, una FLECHA VERDE apuntando a la DERECHA. El recuadro de la foto lo amplía para que no haya duda.\n\nQUÉ HACE UNA FLECHA VERDE JUNTO A UN ROJO. Abre únicamente la dirección que dibuja. Aquí abre el giro a la derecha y solo ese. Todo lo demás sigue bajo el rojo.\n\nPOR ESO RECTO ESTÁ PROHIBIDO y GIRAR A LA IZQUIERDA TAMBIÉN: ninguna flecha los autoriza y el foco rojo los cubre.\n\nGIRAR A LA DERECHA NO es la respuesta porque sí está permitido — pero cediendo el paso a quien circula con luz verde por la vía a la que te incorporas y a los peatones que cruzan con su propio verde. La flecha da permiso de movimiento, no prioridad.\n\nCLAVE: rojo + flecha verde = todo prohibido menos lo que dibuja la flecha. Y lo que la flecha abre, lo abre cediendo.\n\nMÉTODO DEL SEMÁFORO: 1) ¿parpadea o es fija? Немигащ = fija; мигащ = intermitente, y significan cosas distintas. 2) ¿qué focos están encendidos? 3) ¿hay flecha? Una flecha verde solo abre esa dirección, no las demás. Desarrollado en Leyes → «El semáforo: significado oficial de cada señal».","val":15,"fase":3},{"id":5935,"bg":"При тази ситуация при определяне на реда за преминаване през кръстовището се прилагат следните правила:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/103109.png","v":null,"a":[{"t":"през кръстовището преминават ППС, които имат разрешаващ сигнал от светофара","ok":true,"i":null,"es":"pasan los vehículos con semáforo en verde"},{"t":"завиващите наляво ППС на разрешаващ сигнал пропускат насрещнодвижещите","ok":true,"i":null,"es":"los que giran a la izquierda en verde ceden al tráfico de frente"},{"t":"ППС на разрешаващ сигнал, помежду си прилагат правилото за „предимството на дясностоящия”","ok":false,"i":null,"es":"los vehículos con verde entre sí aplican la regla de prioridad de la derecha"}],"f":8,"es":"En esta situación, para determinar el orden de paso por la intersección se aplican las siguientes reglas: (2 correctas)","explain":"Dos reglas: pasan los vehículos con señal permisiva del semáforo, y los que giran a la izquierda con verde ceden a los que vienen de frente.\n\nQUÉ VES. Un cruce regulado por semáforos, tu coche girando a la izquierda con el intermitente puesto y tráfico en verde de frente.\n\nPRIMERA REGLA: el semáforo ordena el cruce. Pasan los que tienen luz permisiva, y solo ellos. Es el escalón que manda mientras esté funcionando.\n\nSEGUNDA REGLA: el verde no resuelve el conflicto entre quien gira a la izquierda y quien viene de frente, porque los dos tienen verde a la vez. Ahí sigue actuando el чл. 37: quien gira a la izquierda cede a los que circulan en sentido contrario.\n\n«ENTRE LOS QUE TIENEN VERDE SE APLICA LA REGLA DE LA DERECHA» es el distractor, y es falso. Con el semáforo regulando, la regla de la derecha no entra: quedó desplazada al escalón inferior. Lo que resuelve los conflictos entre vehículos con verde es чл. 37, no la posición relativa.\n\nCLAVE: el semáforo apaga la regla de la derecha, pero NO apaga el чл. 37. Son dos reglas que viven en escalones distintos y solo una de ellas sobrevive al verde.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":11,"fase":3},{"id":12055,"bg":"Какво трябва да направите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":47,"a":[{"t":"да намаля скоростта и при необходимост да спра","ok":true,"i":null,"es":"reducir velocidad y si es necesario parar"},{"t":"да осигуря предимство на автомобила, който се движи в кръстовището с кръгово движение","ok":true,"i":null,"es":"ceder el paso al vehículo que circula dentro de la glorieta"},{"t":"да включа десен пътепоказател","ok":false,"i":null,"es":"activar el intermitente derecho"}],"f":14,"es":"¿Qué debe hacer en esta situación? (VIDEO - glorieta) ⚠️ 2 correctas","explain":"Llego a una glorieta (ceda el paso Б1 + señal de circulación giratoria) y un coche azul ya circula dentro: reduzco y, si hace falta, PARO — quien está dentro de la glorieta tiene prioridad sobre quien entra. El intermitente derecho no se pone al entrar: se usa al SALIR de la glorieta para avisar la salida; aquí es el distractor. Entrar = ceder; salir = señalizar.","val":22,"fase":3},{"id":5722,"bg":"Превозването на предмети върху покрива на автомобила води до увеличаване на разхода на гориво.","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"f":13,"es":"Transportar objetos en el techo del coche aumenta el consumo de combustible. Esto es:","explain":"Correcto: la carga en el techo aumenta la resistencia aerodinámica y con ella el consumo, incluso con el portaequipajes vacío. Por eso conviene retirarlo cuando no se usa.","val":6,"fase":4},{"id":6310,"bg":"При тази ситуация пресичането на единичната непрекъсната линия е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59668.png","v":null,"a":[{"t":"забранено във всички случаи","ok":true,"i":null,"es":"prohibido en todos los casos"},{"t":"забранено, освен за спиране от другата страна на пътя","ok":false,"i":null,"es":"prohibido salvo para aparcar al otro lado"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"}],"f":29,"es":"En esta situación, cruzar la línea continua simple está:","explain":"Prohibido en TODOS los casos: la línea continua simple no se cruza jamás, y no existe la excepción 'para aparcar al otro lado': esa opción es el gancho. Si necesitas el otro lado, busca dónde la línea sea discontinua o gira legalmente.","val":29,"fase":4},{"id":5873,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/37386.png","v":null,"a":[{"t":"преминаването ми е забранено","ok":true,"i":null,"es":"me está PROHIBIDO pasar"},{"t":"е разрешено да завия надясно","ok":false,"i":null,"es":"puedo girar a la derecha"},{"t":"е разрешено да завия наляво","ok":false,"i":null,"es":"puedo girar a la izquierda"},{"t":"е разрешено да завия в обратна посока","ok":false,"i":null,"es":"puedo dar la vuelta"}],"f":14,"es":"La señal del agente regulador significa que:","explain":"Me está PROHIBIDO pasar.\n\nLO QUE VES. El agente está de PERFIL con el brazo derecho extendido horizontalmente hacia delante, y el brazo sale hacia tu DERECHA.\n\nESO SIGNIFICA QUE VES SU HOMBRO DERECHO. El brazo derecho apunta hacia donde el agente mira; si apunta a tu derecha, él mira hacia allí y lo que tienes enfrente es su costado derecho.\n\nY EL HOMBRO DERECHO ESTÁ CERRADO. Con el brazo extendido, la ley abre únicamente el hombro IZQUIERDO. Todo lo demás — pecho, espalda y hombro derecho — tiene «Преминаването е забранено».\n\nAQUÍ ESTÁ LA TRAMPA DE LA FAMILIA: con los brazos bajados este mismo costado te dejaría pasar recto o a la derecha. Extender el brazo lo cierra. Mismo costado, respuesta opuesta.\n\nEL GESTO, EN LA LEY (чл. 10, ал. 2, т. 3 ЗДвП): «дясна ръка, протегната хоризонтално напред» — brazo derecho extendido horizontalmente hacia delante. «Преминаването е разрешено» solo para quien está frente al hombro IZQUIERDO del agente (y para los peatones que cruzan por detrás de su espalda); «Преминаването е забранено» para todos los demás.\n\nMÉTODO: 1) ¿brazo vertical? alto total. 2) ¿qué te muestra a TI: pecho, espalda o costado? pecho y espalda son muro siempre. 3) ¿costado sin brazo extendido? pasas, recto o derecha. 4) ¿costado CON brazo extendido? solo el izquierdo pasa. Está desarrollado con casos en Leyes → «El agente regulador: los 3 gestos y el método».\n\nCLAVE: compárala con la 5871, que es idéntica pero con el brazo hacia el otro lado. Mira hacia dónde sale la porra: a tu izquierda pasas, a tu derecha esperas.","val":20,"fase":3},{"id":5900,"bg":"Значението на този сигнал на светофара е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41967.png","v":null,"a":[{"t":"„Преминаването е забранено”","ok":true,"i":null,"es":"'El paso está prohibido'"},{"t":"„Преминаването е разрешено”","ok":false,"i":null,"es":"'El paso está permitido'"},{"t":"„Внимание!”","ok":false,"i":null,"es":"'¡Atención!'"},{"t":"„Внимание, спри!”","ok":false,"i":null,"es":"'¡Atención, para!'"}],"f":9,"es":"El significado de esta señal de semáforo es:","explain":"«Преминаването е забранено» — el paso está prohibido.\n\nQUÉ VES. El ROJO y el ÁMBAR encendidos a la vez.\n\nQUÉ SIGNIFICA LA COMBINACIÓN. Sigue estando prohibido pasar. Lo único que añade es un aviso: el verde llega en un segundo, prepárate. El motor, la marcha, el pie — no las ruedas.\n\nES EL ERROR MÁS CARO DE ESTA FAMILIA. El ámbar encendido junto al rojo se lee instintivamente como «ya casi, sal». Mientras el rojo esté encendido, no se pasa.\n\n«¡ATENCIÓN, PARA!» es el ÁMBAR SOLO, no esta combinación: es el distractor más fino de los cuatro, porque las dos señales prohíben y solo se distinguen por el nombre oficial.\n\n«¡ATENCIÓN!» a secas no es el nombre de ninguna señal del semáforo.\n\nCLAVE: los nombres oficiales, en orden. Verde = «преминаването е разрешено». Ámbar solo = «внимание, спри!». Rojo = «преминаването е забранено». Rojo+ámbar = también «забранено». El examen pregunta el NOMBRE, no solo el efecto.\n\nMÉTODO DEL SEMÁFORO: 1) ¿parpadea o es fija? Немигащ = fija; мигащ = intermitente, y significan cosas distintas. 2) ¿qué focos están encendidos? 3) ¿hay flecha? Una flecha verde solo abre esa dirección, no las demás. Desarrollado en Leyes → «El semáforo: significado oficial de cada señal».","val":14,"fase":3},{"id":6332,"bg":"Когато, на жп прелез без бариери, след преминаването на влака червените светлини на светофара продължават да светят, водачът:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не трябва да навлиза с автомобила на жп прелеза","ok":true,"i":null,"es":"NO debe entrar al paso a nivel"},{"t":"може да премине внимателно през жп прелеза","ok":false,"i":null,"es":"puede cruzar con cuidado"},{"t":"трябва да слезе от автомобила и да провери какво се случва","ok":false,"i":null,"es":"debe bajar del coche a comprobar"},{"t":"може да премине, като включи аварийните светлини","ok":false,"i":null,"es":"puede cruzar con las luces de emergencia encendidas"}],"f":10,"es":"En un paso a nivel sin barreras, después del paso del tren las luces rojas del semáforo siguen encendidas. El conductor:","explain":"Si las luces rojas siguen activas tras pasar el tren, NO entres: puede venir OTRO tren por la segunda vía (es el caso típico de accidente mortal). El semáforo manda mientras esté en rojo; ni el cuidado ni las luces de emergencia lo anulan.","val":14,"fase":3},{"id":6608,"bg":"При тази ситуация, при преминаване през кръстовището, трябва да се съобразявате:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51516.png","v":null,"a":[{"t":"със сигнала на светофара","ok":true,"i":null,"es":"la señal del semáforo"},{"t":"с пьтния знак за задължителна посока за движение в кръстовището","ok":true,"i":null,"es":"la señal de dirección obligatoria en la intersección"},{"t":"с пьтния знак относно предимството","ok":false,"i":null,"es":"la señal de prioridad"}],"f":10,"es":"En esta situación, al pasar por la intersección debes atenerte a: (2 correctas)","explain":"Dos cosas: el SEMÁFORO y la señal de DIRECCIÓN OBLIGATORIA.\n\nQUÉ VES. Desde el coche, tres elementos en el mismo poste y alrededores: una señal de ceda el paso (triángulo rojo invertido), un semáforo en verde y un círculo azul con flecha recta, que es dirección obligatoria.\n\nEL SEMÁFORO GANA A LA SEÑAL DE PRIORIDAD. Es el escalón inmediatamente superior. Con el semáforo funcionando, el ceda el paso queda sin efecto: pasas con el verde sin detenerte.\n\nLA SEÑAL DE DIRECCIÓN OBLIGATORIA SIGUE VIGENTE, y esta es la parte que se falla. El semáforo decide CUÁNDO pasas, no HACIA DÓNDE. Son dos cosas distintas: la prioridad la anula el semáforo, la trayectoria obligatoria no. Con el verde puedes pasar, pero solo en la dirección que marca la flecha azul.\n\n«LA SEÑAL DE PRIORIDAD» es la única falsa de las tres, precisamente porque el semáforo la desplaza.\n\nCLAVE: el semáforo solo anula las señales de PRIORIDAD. Las de obligación, prohibición y dirección siguen mandando. No mezcles «quién pasa antes» con «por dónde se puede ir».\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él, por encima de todo. 2) ¿hay semáforo? manda él sobre las señales de prioridad. 3) ¿hay señales de prioridad? mira el trazo GRUESO de la tabla: dice por dónde va la preferente. 4) si nada de lo anterior separa a los dos coches, decide la regla de la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":15,"fase":3},{"id":7967,"bg":"При тази ситуация трябва да премина преди:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64918031.png","v":null,"a":[{"t":"синия автомобил","ok":true,"i":null,"es":"el coche azul"},{"t":"червения автомобил","ok":true,"i":null,"es":"el coche rojo"},{"t":"жълтия автомобил","ok":false,"i":null,"es":"el coche amarillo"}],"f":8,"es":"En esta situación debes pasar antes que: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: según las reglas de prioridad de esta intersección específica tienes prioridad sobre el azul Y el rojo. Analiza la imagen para identificar quién tiene la derecha.","val":13,"fase":3},{"id":12061,"bg":"На кое превозно средство трябва да осигурите предимство, преди да завиете надясно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":52,"a":[{"t":"на трактора","ok":false,"i":null,"es":"al tractor"},{"t":"на мотоциклета","ok":true,"i":null,"es":"a la moto"},{"t":"на превозните средства, идващи отляво","ok":true,"i":null,"es":"a los vehículos que vienen por la izquierda"}],"f":19,"es":"¿A qué vehículo debes ceder el paso antes de girar a la derecha? (VIDEO) ⚠️ 2 correctas","explain":"Estoy en un ceda el paso (señal Б1 + triángulo pintado en el asfalto) incorporándome a la derecha: debo ceder a la MOTO que circula por la vía principal y a todo lo que venga por mi IZQUIERDA, porque su trayectoria cruza la mía al incorporarme. El tractor ya se aleja por la vía y no corta mi camino: es el distractor. En un Б1 la prioridad es siempre de la vía a la que te incorporas.","val":28,"fase":3},{"id":5391,"bg":"На автомобилен път е забранено движението на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"трактори","ok":true,"i":null,"es":"tractores"},{"t":"леки автомобили с ремаркета","ok":false,"i":null,"es":"turismos con remolque"},{"t":"велосипеди","ok":true,"i":null,"es":"bicicletas"}],"f":10,"es":"En autopista está PROHIBIDA la circulación de: (3 correctas)","explain":"En autopista no pueden circular ciclomotores, tractores ni bicicletas: no alcanzan la velocidad mínima segura para ese tráfico. Los turismos CON remolque sí están permitidos (con su límite de 100 km/h).","val":10,"fase":4},{"id":5544,"bg":"След този пътен знак:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42178.png","v":null,"a":[{"t":"е забранено спирането за престой","ok":true,"i":null,"es":"está prohibida la parada breve (prestoy)"},{"t":"е забранено паркирането","ok":true,"i":null,"es":"está prohibido aparcar"},{"t":"е разрешено спирането за престой","ok":false,"i":null,"es":"está permitida la parada breve"},{"t":"е разрешено паркирането","ok":false,"i":null,"es":"está permitido aparcar"}],"f":6,"es":"Después de esta señal: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: esta señal prohíbe TANTO la parada breve (prestoy) COMO el aparcamiento. Zona de prohibición total de detención.","val":3,"fase":4},{"id":5839,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, че преминаването е забранено във всички посоки?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24291.png","v":null,"a":[{"t":"на червения автомобил","ok":true,"i":null,"es":"para el coche rojo"},{"t":"на зеления автомобил","ok":true,"i":null,"es":"para el coche verde"},{"t":"на жълтия автомобил","ok":false,"i":null,"es":"para el coche amarillo"},{"t":"на синия автомобил","ok":false,"i":null,"es":"para el coche azul"}],"f":15,"es":"¿Para qué conductores esta posición del cuerpo y los brazos del agente es señal de que el paso está PROHIBIDO en todas las direcciones? (2 correctas)","explain":"El ROJO y el VERDE.\n\nEL AGENTE ESTÁ DE CARA A TI, el del coche rojo, con los dos brazos bajados. Míralo bien en la foto: se le ve la cara y el frente del chaleco.\n\nQUIÉN VE QUÉ. El rojo (primer plano) le ve el PECHO. El verde (al fondo, detrás de él) le ve la ESPALDA. El amarillo (izquierda) y el azul (derecha) le ven los COSTADOS.\n\nPECHO Y ESPALDA SON MURO. Con los brazos bajados, la ley da «Преминаването е забранено» a quien tiene delante el pecho o la espalda del agente. Por eso rojo y verde están parados: son la respuesta.\n\nLOS COSTADOS ABREN. Amarillo y azul pueden pasar, pero solo RECTO o girando a la DERECHA — nunca a la izquierda ni media vuelta. Por eso no son la respuesta a esta pregunta.\n\nEL GESTO, EN LA LEY (чл. 10, ал. 2, т. 2 ЗДвП): «ръка или ръце, протегнати хоризонтално встрани» — brazo o brazos extendidos horizontalmente a los lados; hecho el gesto, el agente puede bajar los brazos y la señal sigue valiendo. Significa «Преминаването е разрешено» para quien está frente a su hombro izquierdo o derecho Y va a seguir recto o girar a la derecha, y «Преминаването е забранено» para todos los demás.\n\nMÉTODO: 1) ¿brazo vertical? alto total. 2) ¿qué te muestra a TI: pecho, espalda o costado? pecho y espalda son muro siempre. 3) ¿costado sin brazo extendido? pasas, recto o derecha. 4) ¿costado CON brazo extendido? solo el izquierdo pasa. Está desarrollado con casos en Leyes → «El agente regulador: los 3 gestos y el método».\n\nCLAVE: brazos bajados = el cuerpo del agente hace de semáforo. Pecho y espalda en rojo, los dos costados en verde. Es la pregunta gemela de la 5834, que pide lo contrario sobre la misma escena.","val":23,"fase":3},{"id":5859,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, значението на който е „Преминаването е разрешено”?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/36529.png","v":null,"a":[{"t":"на червения автомобил","ok":true,"i":null,"es":"para el coche rojo"},{"t":"на зеления автомобил","ok":false,"i":null,"es":"para el coche verde"},{"t":"на жълтия автомобил","ok":false,"i":null,"es":"para el coche amarillo"},{"t":"на синия автомобил","ok":false,"i":null,"es":"para el coche azul"}],"f":12,"es":"¿Para qué conductor esta posición del cuerpo y los brazos del agente regulador es una señal cuyo significado es 'El paso está PERMITIDO'?","explain":"El coche ROJO, el del primer plano.\n\nLA POSTURA. El agente está de PERFIL, mirando hacia el coche amarillo (izquierda de la foto), con el brazo derecho extendido horizontalmente hacia delante, con la porra.\n\nLA REGLA DEL BRAZO EXTENDIDO es distinta de la de brazos bajados y mucho más restrictiva: con el brazo derecho extendido hacia delante, «Преминаването е разрешено» SOLO para quien está frente a su HOMBRO IZQUIERDO. Para todos los demás, prohibido.\n\nDÓNDE CAE SU HOMBRO IZQUIERDO. Si él mira hacia la izquierda de la foto y nosotros lo vemos desde el lado del coche rojo, lo que nos muestra es su costado izquierdo. Ese es el rojo. Por eso pasa el rojo, y solo el rojo.\n\nLOS DEMÁS. El amarillo le ve el PECHO: prohibido. El azul le ve la ESPALDA: prohibido. El verde le ve el hombro DERECHO: prohibido también, y este es el que más engaña, porque con los brazos bajados ese costado sí abriría.\n\nEL GESTO, EN LA LEY (чл. 10, ал. 2, т. 3 ЗДвП): «дясна ръка, протегната хоризонтално напред» — brazo derecho extendido horizontalmente hacia delante. «Преминаването е разрешено» solo para quien está frente al hombro IZQUIERDO del agente (y para los peatones que cruzan por detrás de su espalda); «Преминаването е забранено» para todos los demás.\n\nMÉTODO: 1) ¿brazo vertical? alto total. 2) ¿qué te muestra a TI: pecho, espalda o costado? pecho y espalda son muro siempre. 3) ¿costado sin brazo extendido? pasas, recto o derecha. 4) ¿costado CON brazo extendido? solo el izquierdo pasa. Está desarrollado con casos en Leyes → «El agente regulador: los 3 gestos y el método».\n\nCLAVE: el brazo derecho extendido no reparte permisos a los dos costados como los brazos bajados. Abre UN solo lado, el izquierdo. Localiza el hombro izquierdo del agente y ahí está la única respuesta.","val":18,"fase":3},{"id":5906,"bg":"Значението на този сигнал на светофара е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42214.png","v":null,"a":[{"t":"„Преминаването е разрешено”","ok":true,"i":null,"es":"'El paso está permitido'"},{"t":"„Разрешено е преминаването във всички посоки”","ok":false,"i":null,"es":"'Permitido pasar en todas las direcciones'"},{"t":"„Разрешено е преминаването направо и надясно”","ok":false,"i":null,"es":"'Permitido pasar recto y a la derecha'"}],"f":10,"es":"El significado de esta señal de semáforo es:","explain":"«Преминаването е разрешено» — el paso está permitido.\n\nQUÉ VES. Un semáforo de tres focos con el VERDE encendido, rojo y ámbar apagados.\n\nLA RESPUESTA ES LA MÁS SOBRIA DE LAS TRES, y eso es justo lo que hay que aprender: el significado oficial del verde es «el paso está permitido», sin adornos.\n\n«PERMITIDO PASAR EN TODAS LAS DIRECCIONES» es falso, y es el distractor principal. El verde autoriza a pasar, pero no decide direcciones: eso lo marcan las flechas del semáforo, las señales de carril y la marcación del suelo. Y aunque pases en verde sigues obligado a ceder a los peatones que cruzan con su verde y a quien ya está dentro del cruce.\n\n«PERMITIDO RECTO Y A LA DERECHA» es falso también: esa fórmula pertenece a los COSTADOS del agente regulador, no al semáforo. El banco mezcla a propósito el vocabulario de las dos familias.\n\nCLAVE: verde = «puedes pasar», no «puedes hacer lo que quieras». Cualquier opción que añada direcciones al verde es un cebo.\n\nMÉTODO DEL SEMÁFORO: 1) ¿parpadea o es fija? Немигащ = fija; мигащ = intermitente, y significan cosas distintas. 2) ¿qué focos están encendidos? 3) ¿hay flecha? Una flecha verde solo abre esa dirección, no las demás. Desarrollado en Leyes → «El semáforo: significado oficial de cada señal».","val":14,"fase":3},{"id":11584,"bg":"Значението на този немигащ сигнал на светофара е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1098228160.png","v":null,"a":[{"t":"„Внимание, спри!”","ok":true,"i":null,"es":"'¡Atención, para!'"},{"t":"„Преминаването е разрешено”, но водачите са длъжни да бъдат внимателни и предпазливи","ok":false,"i":null,"es":"'El paso está permitido', pero los conductores están obligados a ser atentos y prudentes"},{"t":"„Преминаването е разрешено”","ok":false,"i":null,"es":"'El paso está permitido'"}],"f":11,"es":"El significado de esta señal fija de semáforo es:","explain":"«¡Atención, para!» — „Внимание, спри!”.\n\nQUÉ VES. Un semáforo de tres focos con el ÁMBAR encendido solo, rojo y verde apagados. El enunciado dice «немигащ»: fijo, no intermitente.\n\nEL ÁMBAR FIJO NO ES UN AVISO PARA ACELERAR. Su nombre oficial en la ley es «Внимание, спри!» y prohíbe entrar en el cruce. Solo continúa quien ya ha entrado, o quien está tan cerca que no podría detenerse sin frenar bruscamente.\n\n«PASO PERMITIDO PERO CON ATENCIÓN Y PRUDENCIA» es el distractor fino: describe el ÁMBAR INTERMITENTE, que es otra señal — cruce no regulado, pasa con precaución. Una sola palabra del enunciado, «немигащ», separa una respuesta de la otra.\n\n«PASO PERMITIDO» a secas es el verde.\n\nCLAVE: el ámbar tiene dos vidas. Fijo = para. Intermitente = pasa con cuidado. Busca siempre «немигащ» o «мигащ» en el enunciado antes de responder.\n\nMÉTODO DEL SEMÁFORO: 1) ¿parpadea o es fija? Немигащ = fija; мигащ = intermitente, y significan cosas distintas. 2) ¿qué focos están encendidos? 3) ¿hay flecha? Una flecha verde solo abre esa dirección, no las demás. Desarrollado en Leyes → «El semáforo: significado oficial de cada señal».","val":17,"fase":3},{"id":5944,"bg":"При тази ситуация редът за преминаване на автомобилите през кръстовището се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/82624.png","v":null,"a":[{"t":"от сигналите на регулировчика","ok":true,"i":null,"es":"las señales del agente regulador"},{"t":"от пътните знаци относно предимството","ok":false,"i":null,"es":"las señales verticales relativas a la prioridad"},{"t":"в зависимост от посоката на движение на автомобилите","ok":false,"i":null,"es":"la dirección de circulación de los vehículos"},{"t":"с „правилото на десния”","ok":false,"i":null,"es":"la regla de la derecha"}],"f":10,"es":"En esta situación el orden de paso de los vehículos en la intersección lo determina:","explain":"Las señales del AGENTE regulador.\n\nES LA GEMELA DE LA 5945 con otro rival. Aquí el agente no compite contra un semáforo sino contra el rombo amarillo de vía con prioridad que ves en el poste de la derecha.\n\nEL RESULTADO ES EL MISMO. El agente está por encima de las señales verticales igual que lo está del semáforo. La escalera completa, de mayor a menor: agente, semáforo, señales verticales, marcas viales, reglas generales.\n\n«LAS SEÑALES DE PRIORIDAD» es el distractor, y aquí es especialmente atractivo porque el rombo es grande y llamativo. Da igual: mientras el agente esté regulando, la vía con prioridad no reparte nada.\n\n«LA DIRECCIÓN DE MARCHA» no es fuente de prioridad en ningún caso. Ir recto, girar o dar la vuelta no otorga preferencia — es el mismo cebo que aparece en 6595 y 6521.\n\n«LA REGLA DE LA DERECHA» solo actúa cuando no hay nada por encima.\n\nCLAVE: la escalera se recorre de arriba abajo y te detienes en el primer escalón que esté presente en la escena. Aquí el primero es el agente.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él, por encima de todo. 2) ¿hay semáforo? manda él sobre las señales de prioridad. 3) ¿hay señales de prioridad? mira el trazo GRUESO de la tabla: dice por dónde va la preferente. 4) si nada de lo anterior separa a los dos coches, decide la regla de la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":14,"fase":3},{"id":6333,"bg":"Задължително ли е спирането на ППС пред жп прелеза, когато е включена само звуковата сигнализация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"¿Es obligatorio parar antes del paso a nivel cuando solo suena la señal acústica?","explain":"Sí: la señal acústica activa por sí sola ya obliga a parar. Cualquier señal del paso a nivel (sonido, luz roja o barrera) significa 'tren aproximándose' y todas tienen el mismo valor imperativo.","val":12,"fase":3},{"id":6339,"bg":"На водача е забранено да навлиза на железопътния прелез:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"преди да се е убедил, че към прелеза не се приближава влак","ok":true,"i":null,"es":"antes de asegurarse de que no se aproxima ningún tren"},{"t":"когато от другата страна на прелеза няма достатъчно място за продължаване на движението","ok":true,"i":null,"es":"cuando al otro lado no hay espacio suficiente para continuar"},{"t":"когато на прелеза трябва да се размине с друго ППС","ok":false,"i":null,"es":"cuando en el paso debe cruzarse con otro vehículo"},{"t":"когато на прелеза няма съоръжения за подаване на звуков и светлинен сигнал","ok":false,"i":null,"es":"cuando no hay señales acústicas ni luminosas"}],"f":8,"es":"Al conductor le está PROHIBIDO entrar al paso a nivel: (2 correctas)","explain":"Prohibido entrar sin haber comprobado que no viene tren, y cuando al otro lado no hay hueco para salir (quedarías atrapado sobre las vías). Cruzarse con otro vehículo o la ausencia de señales no prohíben la entrada: solo exigen más precaución.","val":12,"fase":3},{"id":6472,"bg":"За кои водачи са задължителни сигналите за спиране, подавани от застаналия на прелеза железопътен служител?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"за водачите от двете страни на жп прелеза","ok":true,"i":null,"es":"para los conductores de ambos lados del paso"},{"t":"само за водачите, които се приближават от тази страна на прелеза, от която се намира жп служителя","ok":false,"i":null,"es":"solo para los que se aproximan desde el lado donde está el ferroviario"},{"t":"сигналите на жп служителя не са задължителни за водачите на МПС","ok":false,"i":null,"es":"las señales del ferroviario no son obligatorias para vehículos"}],"f":9,"es":"¿Para qué conductores son obligatorias las señales de stop del ferroviario en el paso a nivel?","explain":"Las señales de stop del agente ferroviario obligan a los conductores de AMBOS lados del paso: el peligro (el tren) amenaza a ambos sentidos por igual. Sus señales tienen carácter obligatorio como las de cualquier agente regulador.","val":13,"fase":3},{"id":6558,"bg":"При тази ситуация червеният автомобил е с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66983.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":8,"es":"En esta situación el coche rojo tiene prioridad. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Un cruce sin señales ni semáforo, y el coche rojo llegando por tu IZQUIERDA.\n\nSIN SEÑALES MANDA LA DERECHA, y el rojo no está a tu derecha, está a tu izquierda. Por tanto la prioridad es tuya y el enunciado es falso.\n\nEL ERROR TÍPICO ES DE LATERALIDAD, no de doctrina. Mucha gente sabe la regla y aun así falla estas preguntas porque desde el asiento del conductor, en una imagen, cuesta un segundo situar quién está a qué lado. Ese segundo es el que cuesta el punto.\n\nTRUCO PARA NO EQUIVOCARSE. No pienses «está a la izquierda de la foto»: piensa «me llega por mi ventanilla izquierda». La referencia eres tú al volante, no el encuadre.\n\nCLAVE: es un formato de dos opciones, así que vale un punto entero por resolver bien una sola cosa: de qué lado te llega. Compárala con la 6557, que es la misma escena con el coche cambiado de lado.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":13,"fase":3},{"id":11891,"bg":"Когато мястото за спиране преди жп прелеза се определя по отношение на релсите, разстоянието от първата релса трябва да бъде:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не по-малко от 2 метра","ok":true,"i":null,"es":"no menos de 2 metros"},{"t":"не повече от 2 метра","ok":false,"i":null,"es":"no más de 2 metros"},{"t":"възможно най-малкото","ok":false,"i":null,"es":"la menor posible"},{"t":"по преценка на водача","ok":false,"i":null,"es":"a criterio del conductor"}],"f":8,"es":"Cuando la posición de parada antes del paso a nivel se determina respecto a los raíles, la distancia debe ser:","explain":"No menos de 2 metros del raíl: distancia MÍNIMA de seguridad (el tren y su carga sobresalen del raíl). 'No más de 2 m' invierte la regla acercándote al peligro, y la norma no deja la distancia a criterio del conductor.","val":12,"fase":3},{"id":12060,"bg":"Какъв е правилният начин на действие при тази ситуация? Спирам, изключвам двигателя и:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":51,"a":[{"t":"напускам тунела през най-близкия авариен изход","ok":true,"i":null,"es":"abandono el túnel por la salida de emergencia más cercana"},{"t":"изчаквам в превозното средство на мястото на инцидента, докато пътят се освободи","ok":false,"i":null,"es":"espero en el vehículo hasta que se despeje la vía"},{"t":"спирам автомобила извън лентата за принудително спиране","ok":true,"i":null,"es":"paro el coche fuera del carril de emergencia"}],"f":17,"es":"¿Cuál es la actuación correcta? Paro, apago el motor y... (VIDEO) ⚠️ 2 correctas","explain":"Incendio dentro del túnel (humo, conos, gente corriendo hacia las salidas verdes): paro, apago el motor y hago dos cosas — dejo el coche FUERA del carril de detención de emergencia, que debe quedar libre para los servicios de rescate, y abandono el túnel por la salida de emergencia MÁS CERCANA. Esperar dentro del vehículo junto al incendio es la opción letal: en un túnel el humo mata antes que el fuego.","val":26,"fase":3},{"id":5414,"bg":"При движение по автомагистрала на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да спира за престой извън местата обозначени за паркиране","ok":true,"i":null,"es":"parar fuera de los lugares señalizados para aparcar"},{"t":"да навлиза в разделителната ивица","ok":true,"i":null,"es":"entrar en la mediana"},{"t":"да пресича разделителната ивица, включително и на местата, където тя е прекъсната","ok":true,"i":null,"es":"cruzar la mediana incluso donde esté interrumpida"},{"t":"да се движи с прикачено ремарке","ok":false,"i":null,"es":"circular con remolque enganchado"}],"f":11,"es":"Conduciendo por autopista al conductor le está PROHIBIDO: (3 correctas)","explain":"En autopista está prohibido: parar fuera de los lugares señalizados, entrar en la mediana y cruzarla aunque esté interrumpida (esos huecos son para servicios de emergencia). Circular con remolque SÍ está permitido: por eso esa opción es falsa.","val":11,"fase":4},{"id":8276,"bg":"На скоростен път е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"движението на превозни средства с рекламна цел","ok":true,"i":null,"es":"la circulación de vehículos con fines publicitarios"},{"t":"провеждането на технически изпитания на автомобили","ok":true,"i":null,"es":"la realización de pruebas técnicas de vehículos"},{"t":"движението на рекламни и други шествия","ok":true,"i":null,"es":"la circulación de caravanas publicitarias y desfiles"},{"t":"движението на автомобили с товар над 10 т","ok":false,"i":null,"es":"la circulación de vehículos con carga superior a 10 t"}],"f":8,"es":"En una vía rápida está prohibido: (3 correctas)","explain":"En vía rápida están prohibidas las actividades que entorpecen el flujo: circulación con fines publicitarios, pruebas técnicas de vehículos y caravanas o desfiles. El peso de la carga (10 t) no es motivo de prohibición: los camiones circulan con normalidad.","val":8,"fase":4},{"id":8280,"bg":"В кои случаи автомобилът, спрян върху площадката за принудително спиране на скоростен път, задължително се сигнализира?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"през нощта","ok":true,"i":null,"es":"de noche"},{"t":"при намалена видимост","ok":true,"i":null,"es":"con visibilidad reducida"},{"t":"винаги","ok":false,"i":null,"es":"siempre"},{"t":"при ограничена видимост","ok":false,"i":null,"es":"con visibilidad limitada"}],"f":8,"es":"¿En qué casos debe estar señalizado el coche parado en el área de parada forzosa de vía rápida? (2 correctas)","explain":"El vehículo parado en el área de parada forzosa debe señalizarse de NOCHE y con visibilidad REDUCIDA (niebla, lluvia): cuando los demás no pueden verlo a tiempo. No 'siempre' (de día despejado se ve) y la visibilidad 'limitada' es un concepto geométrico de curvas, no de esta regla.","val":8,"fase":4},{"id":11354,"bg":"При движение по автомобилен път на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да завива в обратна посока","ok":true,"i":null,"es":"dar la vuelta (cambio de sentido)"},{"t":"да се движи в платното за насрещно движение","ok":true,"i":null,"es":"circular en el carril contrario"},{"t":"да тегли повредено МПС с твърда връзка","ok":false,"i":null,"es":"remolcar un vehículo averiado con barra rígida"}],"f":10,"es":"Conduciendo por vía rápida al conductor le está PROHIBIDO: (2 correctas)","explain":"En vía rápida está prohibido dar la vuelta y circular por el carril contrario: maniobras contra el flujo a alta velocidad. Remolcar con barra rígida SÍ se permite (máx. 70 km/h): es la opción trampa.","val":10,"fase":4},{"id":11639,"bg":"На водача е забранено да управлява пътно превозно средство, което е спряно от движение и няма издадено разрешение за временно движение:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"f":8,"es":"Al conductor le está prohibido conducir un vehículo retirado de la circulación y sin autorización de circulación temporal emitida. Esto es:","explain":"Correcto: un vehículo retirado de la circulación solo puede moverse con una autorización TEMPORAL emitida al efecto. Sin ella, conducirlo está prohibido: el vehículo no existe administrativamente para la vía.","val":4,"fase":4},{"id":5869,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, значението на който е „Преминаването е забранено”?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/36662.png","v":null,"a":[{"t":"на зеления автомобил","ok":true,"i":null,"es":"para el coche verde"},{"t":"на жълтия автомобил","ok":true,"i":null,"es":"para el coche amarillo"},{"t":"на синия автомобил","ok":true,"i":null,"es":"para el coche azul"},{"t":"на червения автомобил","ok":false,"i":null,"es":"para el coche rojo"}],"f":10,"es":"¿Para qué conductores esta posición del cuerpo y los brazos del agente significa 'Paso PROHIBIDO'? (3 correctas)","explain":"El VERDE, el AMARILLO y el AZUL. Tres de los cuatro.\n\nLA POSTURA. El agente está DE PERFIL mirando hacia el coche amarillo, con el brazo derecho extendido horizontalmente hacia delante.\n\nEL ÚNICO QUE PASA ES EL ROJO, porque desde el primer plano estamos viendo el costado IZQUIERDO del agente, y el brazo extendido abre exactamente ese lado. Los otros tres están prohibidos: esa es la respuesta.\n\nEL AMARILLO le ve el pecho. EL AZUL le ve la espalda. EL VERDE le ve el hombro derecho: con los brazos bajados ese costado abriría, pero con el brazo extendido no.\n\nEL GESTO, EN LA LEY (чл. 10, ал. 2, т. 3 ЗДвП): «дясна ръка, протегната хоризонтално напред» — brazo derecho extendido horizontalmente hacia delante. «Преминаването е разрешено» solo para quien está frente al hombro IZQUIERDO del agente (y para los peatones que cruzan por detrás de su espalda); «Преминаването е забранено» para todos los demás.\n\nMÉTODO: 1) ¿brazo vertical? alto total. 2) ¿qué te muestra a TI: pecho, espalda o costado? pecho y espalda son muro siempre. 3) ¿costado sin brazo extendido? pasas, recto o derecha. 4) ¿costado CON brazo extendido? solo el izquierdo pasa. Está desarrollado con casos en Leyes → «El agente regulador: los 3 gestos y el método».\n\nCLAVE: gemela de la 5859 sobre la misma postura, preguntada al revés. El brazo derecho extendido cierra el hombro derecho — es la diferencia que separa este gesto del de brazos bajados.","val":15,"fase":3},{"id":5876,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/37468.png","v":null,"a":[{"t":"преминаването ми е забранено","ok":true,"i":null,"es":"me está PROHIBIDO pasar"},{"t":"е разрешено да завия надясно","ok":false,"i":null,"es":"puedo girar a la derecha"},{"t":"е разрешено да завия наляво","ok":false,"i":null,"es":"puedo girar a la izquierda"},{"t":"е разрешено да завия в обратна посока","ok":false,"i":null,"es":"puedo dar la vuelta"}],"f":11,"es":"La señal del agente regulador significa que:","explain":"Me está PROHIBIDO pasar.\n\nLO QUE VES. El agente te da la ESPALDA y tiene el brazo extendido. Ves la parte trasera del chaleco y la nuca; no se le ve la cara.\n\nLA ESPALDA NUNCA DA PASO. Con el brazo derecho extendido la ley abre solo el hombro izquierdo; el pecho, la espalda y el hombro derecho quedan prohibidos. Estar detrás del agente es de las tres posiciones cerradas la más clara.\n\nNINGÚN GIRO TE SALVA. Girar es pasar, así que derecha, izquierda y media vuelta son falsas por igual.\n\nEL GESTO, EN LA LEY (чл. 10, ал. 2, т. 3 ЗДвП): «дясна ръка, протегната хоризонтално напред» — brazo derecho extendido horizontalmente hacia delante. «Преминаването е разрешено» solo para quien está frente al hombro IZQUIERDO del agente (y para los peatones que cruzan por detrás de su espalda); «Преминаването е забранено» para todos los demás.\n\nMÉTODO: 1) ¿brazo vertical? alto total. 2) ¿qué te muestra a TI: pecho, espalda o costado? pecho y espalda son muro siempre. 3) ¿costado sin brazo extendido? pasas, recto o derecha. 4) ¿costado CON brazo extendido? solo el izquierdo pasa. Está desarrollado con casos en Leyes → «El agente regulador: los 3 gestos y el método».\n\nCLAVE: cuando no le ves la cara ni un costado limpio, no hay nada que interpretar en el brazo. Espalda = parado.","val":17,"fase":3},{"id":5882,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/37566.png","v":null,"a":[{"t":"преминаването ми е забранено","ok":true,"i":null,"es":"me está PROHIBIDO pasar"},{"t":"е разрешено да завия надясно","ok":false,"i":null,"es":"puedo girar a la derecha"},{"t":"е разрешено да завия наляво","ok":false,"i":null,"es":"puedo girar a la izquierda"},{"t":"е разрешено да завия в обратна посока","ok":false,"i":null,"es":"puedo dar la vuelta"}],"f":11,"es":"La señal del agente regulador significa que:","explain":"Me está PROHIBIDO pasar.\n\nLO QUE VES. El agente está de CARA a ti, con el brazo derecho extendido horizontalmente hacia delante. Se le ve la cara y el frente del chaleco.\n\nEL PECHO ESTÁ CERRADO CON ESTE GESTO. Con el brazo derecho extendido, la ley da paso ÚNICAMENTE a quien está frente a su hombro izquierdo. Tú tienes delante el pecho, no un hombro: prohibido en todas las direcciones.\n\nNO TE DEJES LLEVAR POR EL BRAZO. Que el agente extienda el brazo hacia un lado no es una invitación a girar hacia allí. El brazo define quién pasa (el del hombro izquierdo), no hacia dónde vas tú.\n\nEL GESTO, EN LA LEY (чл. 10, ал. 2, т. 3 ЗДвП): «дясна ръка, протегната хоризонтално напред» — brazo derecho extendido horizontalmente hacia delante. «Преминаването е разрешено» solo para quien está frente al hombro IZQUIERDO del agente (y para los peatones que cruzan por detrás de su espalda); «Преминаването е забранено» para todos los demás.\n\nMÉTODO: 1) ¿brazo vertical? alto total. 2) ¿qué te muestra a TI: pecho, espalda o costado? pecho y espalda son muro siempre. 3) ¿costado sin brazo extendido? pasas, recto o derecha. 4) ¿costado CON brazo extendido? solo el izquierdo pasa. Está desarrollado con casos en Leyes → «El agente regulador: los 3 gestos y el método».\n\nCLAVE: memoriza el par. Brazos bajados y de frente = parado. Brazo extendido y de frente = parado también. El pecho no abre nunca; lo que cambia entre un gesto y otro es lo que pasa en los COSTADOS.","val":17,"fase":3},{"id":5928,"bg":"Значението на този светлинен сигнал е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44560.png","v":null,"a":[{"t":"„Навлизането е разрешено” по пътната лента, над която е поставен","ok":true,"i":null,"es":"'Entrada PERMITIDA' en el carril sobre el que está colocado"},{"t":"„Задължителна посока за движение”","ok":false,"i":null,"es":"'Dirección obligatoria'"},{"t":"„Навлизането е забранено” по пътната лента, над която е поставен","ok":false,"i":null,"es":"'Entrada PROHIBIDA' en el carril sobre el que está colocado"},{"t":"„Място за задължително спиране” в пътната лента, над която е поставен","ok":false,"i":null,"es":"'Lugar de parada obligatoria'"}],"f":8,"es":"El significado de esta señal luminosa es:","explain":"'Entrada PERMITIDA' en el carril sobre el que está. La flecha VERDE hacia abajo de un semáforo de carril indica que ese carril está abierto; la X roja marcaría el carril cerrado. No es una señal de dirección obligatoria ni un lugar de parada: los semáforos de carril solo dicen abierto o cerrado, carril por carril.","val":11,"fase":3},{"id":5934,"bg":"Когато и двете секции на този светофар не работят и няма пътен знак за броя и посоките на движение по пътните ленти, това означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/45488.png","v":null,"a":[{"t":"навлизането по пътната лента, над която е поставен светофарът, е забранено","ok":true,"i":null,"es":"la entrada al carril sobre el que está colocado el semáforo está PROHIBIDA"},{"t":"навлизането по пътната лента, над която е поставен светофарът, е разрешено","ok":false,"i":null,"es":"la entrada está permitida"},{"t":"водачът трябва да спре на линията, на която е поставен светофарът","ok":false,"i":null,"es":"el conductor debe parar en la línea del semáforo"}],"f":12,"es":"Cuando ambas secciones de este semáforo no funcionan y no hay señal Д1 de número y sentidos de circulación por los carriles, esto significa que:","explain":"Está PROHIBIDO entrar en el carril sobre el que está colocado el semáforo.\n\nQUÉ VES. Un pórtico con dos paneles sobre la calzada, los dos apagados. Son «светофари за регулиране на движението по пътните ленти» — semáforos de carril (чл. 33 ППЗДвП). El rojo de estos semáforos tiene forma de dos bandas inclinadas que se cruzan (un aspa) y el verde forma de flecha hacia abajo.\n\nQUÉ DICE LA LEY CUANDO NO LUCEN. чл. 33, ал. 5: si ninguna de las dos luces está encendida, el sentido de circulación por ese carril lo marca la señal Д1 «Брой на пътните ленти и посоки за движение по тях». El enunciado añade que aquí TAMPOCO hay señal Д1 — ese detalle es el que decide la pregunta y por eso lo he corregido en la traducción, faltaba.\n\nSIN SEMÁFORO Y SIN SEÑAL, NO HAY AUTORIZACIÓN. Y sin autorización no se entra: el carril queda cerrado. La regla de fondo es que un carril reversible o regulado no se usa «por defecto», se usa cuando algo lo abre.\n\n«PARAR EN LA LÍNEA DEL SEMÁFORO» es falso: no tienes que detenerte en el pórtico, tienes que no meterte en ese carril. Puedes seguir por otro.\n\nCLAVE: apagado no es permiso. Si el panel no dice nada y no hay Д1 que lo supla, ese carril no es tuyo.\n\nMÉTODO DEL SEMÁFORO: 1) ¿parpadea o es fija? Немигащ = fija; мигащ = intermitente, y significan cosas distintas. 2) ¿qué focos están encendidos? 3) ¿hay flecha? Una flecha verde solo abre esa dirección, no las demás. Desarrollado en Leyes → «El semáforo: significado oficial de cada señal».","val":18,"fase":3},{"id":6069,"bg":"При тази ситуация разположението на автомобила върху платното за движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59751.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcta"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecta"}],"f":8,"es":"En esta situación la posición del vehículo en la calzada es:","explain":"CORRECTA.\n\nEL VEHÍCULO CIRCULA POR EL CARRIL DERECHO, que es exactamente donde debe ir. Fuera de población la regla es ocupar lo más a la derecha posible: por el carril derecho si hay marcas que delimiten carriles, y pegado al borde derecho si no las hay.\n\nEL CARRIL IZQUIERDO NO ES UN CARRIL DE VIAJE. Se ocupa para adelantar y se abandona en cuanto terminas la maniobra. Que esté libre no te autoriza a instalarte en él.\n\nCLAVE: compara esta imagen con las preguntas donde el coche va por el izquierdo teniendo libre el derecho. La escena es casi idéntica y la respuesta se invierte. Fíjate siempre en qué carril ocupa y si el de su derecha está libre.","val":12,"fase":3},{"id":6077,"bg":"По този път извън населено място водачът трябва да се движи:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/102157.png","v":null,"a":[{"t":"възможно най-вдясно по платното за движение, когато лентите не са очертани с пътна маркировка","ok":true,"i":null,"es":"todo lo posible a la derecha cuando los carriles no están marcados"},{"t":"в дясната пътна лента, когато лентите са очертани с пътна маркировка","ok":true,"i":null,"es":"en el carril derecho cuando los carriles están marcados"},{"t":"в по-удобната за него пътна лента","ok":false,"i":null,"es":"en el carril más cómodo"},{"t":"в лявата пътна лента винаги, когато е свободна","ok":false,"i":null,"es":"siempre en el carril izquierdo cuando esté libre"}],"f":9,"es":"Por esta carretera fuera de población el conductor debe circular: (2 correctas)","explain":"MULTIRESPUESTA. Fuera de población la regla es ir a la derecha, y se aplica de dos formas según el firme: si hay marcas que delimiten carriles, por el carril derecho; si no las hay, lo más a la derecha posible de la calzada. Las otras dos son justo lo contrario: elegir el carril 'más cómodo' vale en población, no fuera, y viajar por el izquierdo porque esté libre nunca vale.","val":14,"fase":3},{"id":6492,"bg":"При тази ситуация водачът на бавнодвижещото се ППС:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65857.png","v":null,"a":[{"t":"е задължен да използва най-дясната пътна лента","ok":true,"i":null,"es":"está obligado a usar el carril más a la derecha"},{"t":"може да използва средната пътна лента при заобикаляне","ok":true,"i":null,"es":"puede usar el carril central al rodear un obstáculo"},{"t":"може да използва крайната лява лента при завиване","ok":true,"i":null,"es":"puede usar el carril izquierdo al girar"},{"t":"може да използва крайната лява лента при изпреварване","ok":false,"i":null,"es":"puede usar el carril izquierdo al adelantar"}],"f":9,"es":"En esta situación el conductor del vehículo lento: (3 correctas)","explain":"MULTIRESPUESTA. La señal marca tres carriles y el vehículo lento debe ir por el MÁS A LA DERECHA. Puede salir de él en dos casos concretos: usar el central para rodear un obstáculo, y el izquierdo para girar. Lo que no puede es usar el izquierdo para ADELANTAR, que es el distractor. Regla: el lento sale de su carril para esquivar o para girar, nunca para adelantar.","val":13,"fase":3},{"id":6229,"bg":"Преди отклонение встрани, за навлизане в съседна пътна лента, водачът:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да подаде сигнал със съответния пътепоказател","ok":true,"i":null,"es":"debe activar el intermitente correspondiente"},{"t":"трябва да се убеди, че няма да създаде опасност за другите участници в движението","ok":true,"i":null,"es":"debe asegurarse de no crear peligro para otros participantes"},{"t":"трябва да пропусне ППС, които се движат по тази лента","ok":true,"i":null,"es":"debe dejar pasar los vehículos que circulan por ese carril"},{"t":"трябва да пропусне ППС движещи се по нея, само ако тази лента е за насрещното движение","ok":false,"i":null,"es":"debe dejar pasar solo los del carril contrario"}],"f":5,"es":"Antes de desplazarse lateralmente para cambiar de carril, el conductor: (3 correctas)","explain":"Antes de cambiar de carril: intermitente, comprobar que no creas peligro y CEDER a quienes ya circulan por el carril de destino: ellos tienen la prioridad. No se trata del 'carril contrario', sino del carril al que te desplazas.","val":8,"fase":4},{"id":6359,"bg":"Когато мястото за спиране преди жп прелеза се определя по отношение на релсите, разстоянието от първата релса трябва да бъде:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не по-малко от 2 м","ok":true,"i":null,"es":"no menos de 2 m"},{"t":"не повече от 1 м","ok":false,"i":null,"es":"no más de 1 m"},{"t":"не повече от 5 м","ok":false,"i":null,"es":"no más de 5 m"},{"t":"по преценка на водача","ok":false,"i":null,"es":"a criterio del conductor"}],"f":11,"es":"Cuando la posición de parada antes del paso a nivel se determina respecto a los raíles, la distancia debe ser:","explain":"Mínimo 2 m desde el raíl más cercano: garantiza que ninguna parte del vehículo (ni la carga del tren, que sobresale del raíl) pueda tocarte. 'No más de 1 m' te pondría bajo el tren y 'a criterio del conductor' no existe en la norma.","val":17,"fase":3},{"id":6525,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57314.png","v":null,"a":[{"t":"само червения автомобил","ok":true,"i":null,"es":"solo al coche rojo"},{"t":"само синия автомобил","ok":false,"i":null,"es":"solo al coche azul"},{"t":"и двата автомобила","ok":false,"i":null,"es":"a los dos coches"}],"f":9,"es":"En esta situación debo dejar pasar:","explain":"Solo al coche ROJO.\n\nQUÉ VES. El rombo amarillo a tu derecha: estás en la vía con prioridad. Llevas el intermitente izquierdo. El rojo viene de frente y la furgoneta azul llega por la calle transversal.\n\nAL AZUL NO LE CEDES. Llega por una vía secundaria y tú estás en la preferente: es él quien te cede a ti. Por eso «a los dos» es falso.\n\nAL ROJO SÍ. Viene de frente por la misma vía preferente, y tú vas a cruzar su trayectoria para girar a la izquierda. El чл. 37 se aplica igual: estar en la vía con prioridad no libera del deber de ceder a los que vienen de cara.\n\nESE ES EL PUNTO DE LA PREGUNTA. Mucha gente lee el rombo y concluye «tengo prioridad sobre todos». No: el rombo te da prioridad sobre las vías que se cruzan, no sobre quien circula por tu misma vía en sentido contrario.\n\nCLAVE: rombo y чл. 37 son dos reglas independientes que actúan a la vez. El rombo resuelve a los laterales; el giro a la izquierda se resuelve aparte, frente a los de cara.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él, por encima de todo. 2) ¿hay semáforo? manda él sobre las señales de prioridad. 3) ¿hay señales de prioridad? mira el trazo GRUESO de la tabla: dice por dónde va la preferente. 4) si nada de lo anterior separa a los dos coches, decide la regla de la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":14,"fase":3},{"id":6539,"bg":"При тази ситуация жълтият автомобил трябва да премине преди синия и червения автомобил защото:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65468.png","v":null,"a":[{"t":"се намира на пътя с предимство","ok":true,"i":null,"es":"está en la vía preferente"},{"t":"се намира от дясната страна на синия автомобил","ok":true,"i":null,"es":"está a la derecha del coche azul"},{"t":"завива надясно","ok":false,"i":null,"es":"gira a la derecha"},{"t":"не напуска пътят с предимство","ok":false,"i":null,"es":"no abandona la vía preferente"}],"f":8,"es":"En esta situación el coche amarillo debe pasar antes que el azul y el rojo porque: (2 correctas)","explain":"Dos razones: porque está en la vía con prioridad Y porque está a la derecha del coche azul. Hacen falta las dos, y cada una resuelve a un rival distinto.\n\nBAJO EL ROMBO AMARILLO HAY UNA TABLA CON EL TRAZADO DEL CRUCE. Léela con calma: el trazo GRUESO — la vía con prioridad — entra por abajo, por donde llega el amarillo, y TUERCE A LA IZQUIERDA, hacia donde está el azul. Los trazos finos, el recto y el de la derecha, son las vías secundarias.\n\nCONTRA EL ROJO GANA POR LA VÍA. El rojo llega por una secundaria, así que cede a todo el que circula por la prioritaria. Primera razón resuelta.\n\nCONTRA EL AZUL NO LE SIRVE LA VÍA, porque el azul también va por la prioritaria. Entre dos que circulan por la misma vía la prioridad de vía no decide nada. Y como la prioritaria cambia de dirección aquí, se aplica el чл. 50, ал. 2: entre los que van por ella vuelve a mandar la regla general de la derecha. El amarillo está a la derecha del azul. Segunda razón resuelta.\n\n«GIRA A LA DERECHA» ES FALSO DOS VECES: de hecho lleva el intermitente izquierdo, y en derecho la maniobra que elijas nunca te da prioridad.\n\n«NO ABANDONA LA VÍA CON PRIORIDAD» ES EL CEBO FINO. Suena a razón de peso y no lo es: el azul tampoco la abandona, así que no distingue a ninguno de los dos. Y justo cuando la prioritaria tuerce, seguir en ella no otorga preferencia — decide la derecha.\n\nCLAVE: rombo y tabla son dos datos distintos. El rombo dice «mando sobre las secundarias»; la tabla dice «por dónde va la prioritaria». Si la tabla muestra que tuerce, entre los que van por ella manda la derecha.","val":12,"fase":3},{"id":6546,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68490.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el coche azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"dejar pasar al rojo"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"dejar pasar al azul"}],"f":11,"es":"En esta situación debo: (2 correctas)","explain":"MULTIRESPUESTA: paso antes que el rojo y antes que el azul. ATENCIÓN, esta pregunta es especial — léela entera.\n\nEL AZUL se entiende sin problema: llega por mi izquierda, así que por la regla de la derecha es él quien me cede a mí.\n\nEL ROJO es el caso raro. Viene de frente siguiendo recto y yo giro a la izquierda. El artículo 37 de la ley dice que quien gira a la izquierda debe ceder el paso a los que vienen en sentido contrario y siguen de frente o giran a la derecha. Por la ley, yo tendría que cederle. Y sin embargo el banco oficial marca 'cedo al rojo' como respuesta FALSA.\n\nEL MOTIVO DE FONDO es que aquí se forma un bucle cerrado de prioridad: yo cedo al rojo, el rojo cede al azul (que cruzando de izquierda a derecha le entra por su derecha), y el azul me cede a mí. Nadie puede arrancar sin que otro ceda primero. La ley búlgara no resuelve estos atascos con una regla: se salen por acuerdo entre conductores.\n\nEN EL EXAMEN marca 'paso antes que los dos'. Es lo que puntúa.\n\nEN LA CARRETERA haz lo contrario: si giras a la izquierda, cede SIEMPRE al que viene de frente. Si hay accidente, el artículo 37 es el que se aplica y responde el que gira. Esta es la única pregunta de las 1487 donde el examen y la práctica no coinciden.\n\nEN LA CARRETERA HAZ LO CONTRARIO: si giras a la izquierda, cede siempre al que viene de frente. Si hay colisión, el atestado se apoya en el чл. 37 y responde el que gira. Esta es la única pregunta del banco donde el examen y la práctica piden cosas distintas, y está desarrollada entera en Leyes → «Caso especial: el bucle de prioridad (заклещване)».","val":17,"fase":3},{"id":6561,"bg":"При тази ситуация водачът на зеления автомобил трябва да пропусне:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68387.png","v":null,"a":[{"t":"двата автомобила","ok":true,"i":null,"es":"a los dos coches"},{"t":"само синия автомобил","ok":false,"i":null,"es":"solo al coche azul"},{"t":"само червения автомобил","ok":false,"i":null,"es":"solo al coche rojo"}],"f":9,"es":"En esta situación el conductor del coche verde debe dejar pasar:","explain":"A los DOS coches.\n\nQUÉ VES. El coche verde en primer plano con el intermitente izquierdo. El rojo está a su izquierda, también maniobrando, y el azul a su derecha.\n\nAL AZUL, POR LA DERECHA. Regla general: en igualdad, cede quien tiene al otro a su derecha.\n\nAL ROJO, POR EL GIRO A LA IZQUIERDA. Aquí sí se activa el чл. 37: el verde va a girar a la izquierda y el rojo circula en sentido contrario. Quien gira a la izquierda cede a los que vienen de frente.\n\nPOR ESO SE ACUMULAN LAS DOS OBLIGACIONES y la respuesta son los dos. Es el contraste directo con la 6540: misma familia, mismo intermitente, y respuesta distinta solo porque cambia de dónde viene el rojo.\n\n«SOLO AL AZUL» sería correcto si el rojo llegara por la izquierda en vez de venir de frente. «SOLO AL ROJO» ignora la regla de la derecha.\n\nCLAVE: estudia 6540 y 6561 juntas. La diferencia no está en lo que tú haces, está en de dónde viene el otro. Un coche a la izquierda te cede; un coche de frente, si giras, no.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él, por encima de todo. 2) ¿hay semáforo? manda él sobre las señales de prioridad. 3) ¿hay señales de prioridad? mira el trazo GRUESO de la tabla: dice por dónde va la preferente. 4) si nada de lo anterior separa a los dos coches, decide la regla de la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":13,"fase":3},{"id":6569,"bg":"При тази ситуация трябва да пропусна червения автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68269.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":8,"es":"En esta situación debo dejar pasar al coche rojo. Esto es:","explain":"⚠️ TRAMPA: la pregunta afirma que debes ceder al rojo, pero es INCORRECTO. Según la imagen eres tú quien tiene prioridad. Lee siempre la situación antes de elegir.","val":12,"fase":3},{"id":6598,"bg":"При тази ситуация преминавам преди синия автомобил защото се движа направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56819.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":10,"es":"En esta situación paso antes que el coche azul porque voy recto. Esto es:","explain":"INCORRECTO.\n\nLA RAZÓN ES FALSA. «Ir recto» no otorga prioridad en ninguna situación. Es el cebo más repetido de todo el banco y aparece con distintos disfraces en 6595, 6521, 6543, 6575 y esta.\n\nY LA CONCLUSIÓN TAMBIÉN FALLA. Llevas un ceda el paso: llegas por una vía secundaria. El azul no tiene esa obligación, así que pasa él y esperas tú.\n\nDOBLE FALLO, UNA SOLA RESPUESTA. En este formato basta con que se caiga una de las dos partes; aquí se caen las dos.\n\nPOR QUÉ SEGUIR RECTO SE SIENTE COMO UN DERECHO. Porque no maniobrar parece «no molestar». Pero la prioridad no premia la sencillez de tu trayectoria: la reparten las señales, el semáforo, el agente o la posición relativa. Tu maniobra no está en esa lista.\n\nCLAVE: en cuanto leas «porque va recto» o «porque voy recto» en un enunciado con justificación, marca incorrecto y sigue. Es un punto en cinco segundos.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":15,"fase":3},{"id":5378,"bg":"При тази ситуация кой от автомобилите нарушава правилата за движение по автомагистрала?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41573.png","v":null,"a":[{"t":"само лекият автомобил","ok":false,"i":null,"es":"solo el turismo"},{"t":"само товарният автомобил","ok":false,"i":null,"es":"solo el camión"},{"t":"и двата автомобила","ok":true,"i":null,"es":"los dos vehículos"}],"f":8,"es":"En esta situación ¿qué vehículo incumple las normas de autopista?","explain":"Ambos vehículos infringen alguna norma de autopista en esta imagen. Identifica qué hace mal cada uno (carril incorrecto, velocidad, distancia...).","val":8,"fase":4},{"id":5385,"bg":"На автомагистрала с три пътни ленти за движение в една посока, на водача на състав от ППС с дължина над 7 метра е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"разрешено да се движи в най-дясната пътна лента","ok":true,"i":null,"es":"permitido circular en el carril más a la derecha"},{"t":"разрешено да се движи в средната пътна лента","ok":true,"i":null,"es":"permitido circular en el carril central"},{"t":"забранено да се движи в крайната лява лента","ok":true,"i":null,"es":"prohibido circular en el carril más a la izquierda"},{"t":"разрешено да навлиза в крайната лява лента при изпреварване","ok":false,"i":null,"es":"permitido entrar en el carril izquierdo para adelantar"}],"f":9,"es":"En una autopista de 3 carriles, al conductor de un convoy de vehículos le está: (3 correctas)","explain":"En autopista de 3 carriles, un convoy puede usar el carril derecho y el central, pero el IZQUIERDO le está prohibido siempre: ni siquiera para adelantar. Por eso 'entrar en el izquierdo para adelantar' es falsa.","val":9,"fase":4},{"id":5412,"bg":"На автомобилен път спирането за престой е разрешено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"само на специално обозначените места за паркиране","ok":true,"i":null,"es":"solo en los lugares señalizados para aparcar"},{"t":"най-вдясно на платното за движение","ok":false,"i":null,"es":"en el extremo derecho de la calzada"},{"t":"само извън платното за движение","ok":false,"i":null,"es":"solo fuera de la calzada"},{"t":"най-вдясно на пътното платно","ok":false,"i":null,"es":"en el extremo derecho del firme"}],"f":8,"es":"En vía rápida la parada está permitida:","explain":"Solo en los lugares señalizados para aparcar: en vía rápida no existe la parada 'a la derecha' ni 'fuera de la calzada' por libre. Todo lo que no sea zona habilitada o emergencia real es infracción.","val":8,"fase":4},{"id":5415,"bg":"При движение по автомагистрала на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да завива в обратна посока","ok":true,"i":null,"es":"dar la vuelta"},{"t":"да навлиза в разделителната ивица или да я пресича, включително и на местата, където тя е прекъсната","ok":true,"i":null,"es":"entrar en la mediana o cruzarla incluso donde esté interrumpida"},{"t":"да се движи по лентата за принудително спиране","ok":true,"i":null,"es":"circular por el carril de emergencia"},{"t":"да тегли повредено МПС с твърда връзка","ok":false,"i":null,"es":"remolcar un vehículo averiado con barra rígida"}],"f":9,"es":"Conduciendo por autopista al conductor le está PROHIBIDO: (3 correctas)","explain":"En autopista está prohibido dar la vuelta, entrar o cruzar la mediana (aunque esté interrumpida) y circular por el carril de emergencia. Remolcar con barra rígida un averiado sí está permitido para sacarlo por la salida más próxima.","val":9,"fase":4},{"id":8279,"bg":"Теглене с гъвкава връзка по скоростен път е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"разрешено само за изтегляне до най-близкото място за напускане на пътя","ok":true,"i":null,"es":"permitido solo para salir por la salida más cercana"},{"t":"разрешено без ограничения","ok":false,"i":null,"es":"permitido sin restricciones"},{"t":"забранено във всички случаи","ok":false,"i":null,"es":"prohibido en todos los casos"},{"t":"забранено само в тъмната част от денонощието","ok":false,"i":null,"es":"prohibido solo de noche"}],"f":12,"es":"El remolque con cable flexible en vía rápida está:","explain":"El remolque con cable FLEXIBLE en vía rápida solo está permitido para llegar a la salida más próxima y abandonarla: el cable no da control suficiente a alta velocidad. Ni está permitido sin límites ni prohibido del todo.","val":12,"fase":4},{"id":11712,"bg":"Когато няма други ограничения, водачът на МПС от категория В при движение по скоростен път не трябва да превишава:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"120 km/h","ok":true,"i":null,"es":"120 km/h"},{"t":"110 km/h","ok":false,"i":null,"es":"110 km/h"},{"t":"100 km/h","ok":false,"i":null,"es":"100 km/h"},{"t":"130 кkm/h","ok":false,"i":null,"es":"130 km/h"}],"f":10,"es":"Sin otras restricciones, el conductor de categoría B en vía rápida puede circular a máximo:","explain":"120 km/h: límite de los turismos categoría B en vía rápida (скоростен път). Ojo a la diferencia con autopista, donde el mismo turismo puede ir a 140 km/h.","val":10,"fase":4},{"id":12067,"bg":"Какво трябва да направите при тази ситуация? Оставам в заеманата лента, като:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":58,"a":[{"t":"се движа в средата на лентата","ok":false,"i":null,"es":"circulo por el centro del carril"},{"t":"се движа възможно най-вдясно","ok":true,"i":null,"es":"circulo todo lo posible a la derecha"},{"t":"се движа възможно най-вляво","ok":false,"i":null,"es":"circulo todo lo posible a la izquierda"}],"f":23,"es":"¿Qué debes hacer en esta situación? Me quedo en mi carril y... (VIDEO)","explain":"En la escena final una moto se abre paso por mi IZQUIERDA entre el tráfico denso de la autovía (camión frenando a la derecha): me quedo en mi carril pero circulando todo lo posible a la DERECHA para dejarle hueco seguro. Por el centro o pegado a la izquierda le cerraría el paso. Regla: cuando una moto filtra o adelanta por un lado, libera ese lado dentro de tu carril.","val":11,"fase":4},{"id":5585,"bg":"При тази ситуация кой от автомобилите е паркиран неправилно?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43351.png","v":null,"a":[{"t":"синият автомобил","ok":true,"i":null,"es":"el coche azul"},{"t":"червеният автомобил","ok":false,"i":null,"es":"el coche rojo"}],"f":8,"es":"En esta situación ¿qué vehículo está aparcado incorrectamente?","explain":"El coche azul infringe alguna norma de aparcamiento en esta imagen — demasiado cerca de una esquina, sobre paso de peatones, o en zona prohibida. Analiza la señalización.","val":4,"fase":4},{"id":6675,"bg":"След кой от тези знаци, при преминаване през кръстовището, трябва да пропуснем ППС, идващи по пътя отдясно?","p":3,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":false,"es":"","i":"55266"},{"t":"","ok":false,"es":"","i":"55265"},{"t":"","ok":true,"es":"","i":"55267"},{"t":"","ok":false,"es":"","i":"55247"}],"f":10,"es":"Después de cuál de estas señales, al cruzar la intersección, debemos ceder el paso a los vehículos que vienen por el camino de la DERECHA?","explain":"La señal del ASPA: triángulo rojo con una X negra dentro (tercera imagen).\n\nESA SEÑAL ES «КРЪСТОВИЩЕ НА РАВНОЗНАЧНИ ПЪТИЩА» — cruce de vías de igual valor. Avisa de que en el cruce que viene ninguna de las dos vías tiene prioridad sobre la otra. Y cuando nadie tiene prioridad se aplica el чл. 50, ал. 1: cedo el paso a los vehículos que se me acercan por la DERECHA. Por eso es la respuesta.\n\nLA PRIMERA IMAGEN (trazo vertical grueso con un ramal fino a la derecha) es «cruce con vía secundaria por la derecha». El trazo grueso soy yo: voy por la vía con prioridad, así que NO cedo a los de la derecha, son ellos los que me ceden.\n\nLA SEGUNDA (trazo grueso con ramales finos a ambos lados) es «cruce con vías secundarias a derecha e izquierda». Mismo razonamiento: sigo en la gruesa, sigo con prioridad.\n\nLA CUARTA es la de glorieta próxima. Allí cede el que entra, y los vehículos que ya circulan por el anillo llegan por tu IZQUIERDA, no por tu derecha. Ni siquiera encaja con el enunciado.\n\nCLAVE: en los triángulos de cruce, el GROSOR del trazo dice quién manda — grueso = vía con prioridad. El aspa no tiene trazo grueso porque no hay jerarquía: devuelve el cruce a la regla de la derecha. Es la única de las cuatro que te obliga a ceder por la derecha.","val":14,"fase":3},{"id":6320,"bg":"Върху маркираната с коси успоредни линии част от платното за движение навлизането е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60183.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibida"},{"t":"разрешено за паркиране","ok":false,"i":null,"es":"permitida para aparcar"},{"t":"разрешено само за спиране за престой","ok":false,"i":null,"es":"permitida solo para parada breve"}],"f":24,"es":"La entrada a la zona marcada con líneas diagonales paralelas está:","explain":"Prohibida: el zebrado diagonal marca superficie vetada al tráfico, sin excepciones de aparcamiento ni parada breve. Misma doctrina que su gemela: la zona rayada es intocable.","val":24,"fase":4},{"id":5850,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/35032.png","v":null,"a":[{"t":"мога да премина направо","ok":true,"i":null,"es":"continuar recto"},{"t":"мога да завия надясно","ok":true,"i":null,"es":"girar a la derecha"},{"t":"мога да завия наляво","ok":false,"i":null,"es":"girar a la izquierda"},{"t":"мога да завия в обратна посока","ok":false,"i":null,"es":"girar en sentido contrario"}],"f":11,"es":"La señal del agente regulador significa que puedo: (2 correctas)","explain":"Puedo seguir RECTO o girar a la DERECHA. Las dos.\n\nLO QUE VES. El agente está de PERFIL: le ves un costado, con los brazos bajados a lo largo del cuerpo.\n\nEL COSTADO ABRE. La ley: con los brazos bajados o extendidos lateralmente, «Преминаването е разрешено» para quien está frente al hombro izquierdo o derecho — y aquí viene la letra pequeña que decide la pregunta: solo para SEGUIR RECTO o GIRAR A LA DERECHA.\n\nPOR ESO GIRAR A LA IZQUIERDA ES FALSO. No es que sea peligroso: es que este gesto no lo autoriza, punto. Y la MEDIA VUELTA tampoco, por lo mismo.\n\nEL GESTO, EN LA LEY (чл. 10, ал. 2, т. 2 ЗДвП): «ръка или ръце, протегнати хоризонтално встрани» — brazo o brazos extendidos horizontalmente a los lados; hecho el gesto, el agente puede bajar los brazos y la señal sigue valiendo. Significa «Преминаването е разрешено» para quien está frente a su hombro izquierdo o derecho Y va a seguir recto o girar a la derecha, y «Преминаването е забранено» para todos los demás.\n\nMÉTODO: 1) ¿brazo vertical? alto total. 2) ¿qué te muestra a TI: pecho, espalda o costado? pecho y espalda son muro siempre. 3) ¿costado sin brazo extendido? pasas, recto o derecha. 4) ¿costado CON brazo extendido? solo el izquierdo pasa. Está desarrollado con casos en Leyes → «El agente regulador: los 3 gestos y el método».\n\nCLAVE: costado con brazos bajados no significa «vía libre». Significa «recto o derecha». Es la limitación que más puntos cuesta en esta familia.","val":16,"fase":3},{"id":5885,"bg":"Значението на този сигнал на регулировчика е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39187.png","v":null,"a":[{"t":"„Внимание, спри!”","ok":true,"i":null,"es":"'¡Atención, para!'"},{"t":"„Премини с повишено внимание”","ok":false,"i":null,"es":"'Pasa con precaución redoblada'"},{"t":"„Внимание”","ok":false,"i":null,"es":"'¡Atención!'"},{"t":"„Пропусни движещите се по пресичания път”","ok":false,"i":null,"es":"'Cede el paso a los que circulan por la vía transversal'"}],"f":11,"es":"El significado de esta señal del agente regulador es:","explain":"«¡Atención, para!» — на български: „Внимание, спри!”.\n\nLO QUE VES. El agente tiene el brazo derecho levantado VERTICALMENTE hacia arriba, con la porra.\n\nES EL ÚNICO GESTO QUE VALE PARA TODOS A LA VEZ. No depende de dónde estés: pecho, espalda o cualquiera de los dos costados, todos paran. Solo termina de cruzar quien ya está dentro de la intersección y no puede detenerse sin frenar bruscamente.\n\nPOR QUÉ «¡ATENCIÓN!» A SECAS ES FALSO. Es el distractor fino: el nombre oficial de la señal en la ley lleva las dos palabras, «Внимание, спри!». La versión corta cambia el significado — avisar no es lo mismo que ordenar parar.\n\n«PASA CON PRECAUCIÓN» ES LO CONTRARIO de lo que ordena el gesto.\n\n«CEDE EL PASO A LOS DE LA VÍA TRANSVERSAL» describe una señal de prioridad, no un gesto del agente.\n\nEL GESTO, EN LA LEY (чл. 10, ал. 2, т. 1 ЗДвП): «дясна ръка, вдигната вертикално» — brazo derecho levantado en vertical. Significa «Внимание, спри!». No se aplica a quien, tras habérsele permitido el paso, está tan cerca del agente que no puede detenerse sin crear peligro; y quien ya ha entrado en el cruce debe despejarlo.\n\nMÉTODO: 1) ¿brazo vertical? alto total. 2) ¿qué te muestra a TI: pecho, espalda o costado? pecho y espalda son muro siempre. 3) ¿costado sin brazo extendido? pasas, recto o derecha. 4) ¿costado CON brazo extendido? solo el izquierdo pasa. Está desarrollado con casos en Leyes → «El agente regulador: los 3 gestos y el método».\n\nCLAVE: brazo arriba = alto total, y su nombre exacto es «Внимание, спри!». En estas preguntas el examen califica el NOMBRE de la señal, no solo su efecto.","val":17,"fase":3},{"id":6097,"bg":"При тази ситуация разположението на червения автомобил върху платното за движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63641.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcta"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecta"}],"f":7,"es":"En esta situación la posición del coche rojo en la calzada es:","explain":"El coche rojo está correctamente posicionado — circula por el lado derecho de la calzada de forma adecuada según la situación mostrada.","val":11,"fase":3},{"id":6234,"bg":"При тази ситуация с предимство е водачът на автомобила, който:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69702.png","v":null,"a":[{"t":"се намира отдясно","ok":true,"i":null,"es":"se encuentra a la derecha"},{"t":"се намира отляво","ok":false,"i":null,"es":"se encuentra a la izquierda"},{"t":"първи е подал сигнал за маневра","ok":false,"i":null,"es":"primero señalizó la maniobra"},{"t":"е по-напред от другия","ok":false,"i":null,"es":"está más adelantado que el otro"}],"f":10,"es":"En esta situación tiene prioridad el conductor del vehículo que:","explain":"El que se encuentra a la DERECHA.\n\nQUÉ VES. Dos coches en carriles contiguos, los dos con el intermitente puesto, convergiendo hacia el mismo espacio. No es un cruce: es una confluencia de trayectorias dentro de la misma calzada.\n\nCUANDO DOS TRAYECTORIAS SE CRUZAN Y NADA MÁS LO RESUELVE, se aplica la regla general: cede el que tiene al otro a su derecha.\n\n«EL QUE PRIMERO SEÑALIZÓ LA MANIOBRA» es el distractor más humano de todo el banco. Poner el intermitente antes no compra prioridad: el intermitente ANUNCIA una intención, no la autoriza. Si fuera al revés, ganaría el más rápido de dedo.\n\n«EL QUE ESTÁ MÁS ADELANTADO» tampoco. Ir medio coche por delante no es un título de preferencia; es una posición de hecho.\n\n«EL DE LA IZQUIERDA» es la inversión directa de la regla.\n\nCLAVE: el intermitente obliga a los demás a saber lo que vas a hacer, no a dejarte hacerlo. Señalizar y ceder son dos obligaciones distintas y las dos son tuyas.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él, por encima de todo. 2) ¿hay semáforo? manda él sobre las señales de prioridad. 3) ¿hay señales de prioridad? mira el trazo GRUESO de la tabla: dice por dónde va la preferente. 4) si nada de lo anterior separa a los dos coches, decide la regla de la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":14,"fase":3},{"id":6335,"bg":"При тази ситуация преминавам с предимство преди трамвая.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70746.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":7,"es":"En esta situación paso con prioridad antes que el tranvía. Esto es:","explain":"⚠️ TRAMPA: los tranvías tienen prioridad sobre los vehículos de motor en la mayoría de situaciones. Afirmar que tienes prioridad sobre el tranvía es INCORRECTO.","val":11,"fase":3},{"id":6426,"bg":"При изпреварване водачът на изпреварваното ППС длъжен ли е да не увеличава скоростта?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":5,"es":"Al adelantar, ¿está obligado el conductor del vehículo adelantado a no aumentar la velocidad?","explain":"Sí: el adelantado tiene prohibido aumentar la velocidad durante el adelantamiento. Acelerar alargaría la maniobra del otro justo cuando está expuesto en el carril contrario.","val":8,"fase":4},{"id":6433,"bg":"Водач, който изпреварва, е длъжен:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да осигури достатъчно странично разстояние между своето и изпреварваното ППС","ok":true,"i":null,"es":"garantizar distancia lateral suficiente entre su vehículo y el adelantado"},{"t":"когато навлиза в лента за насрещното движение, да не създава опасност за превозните средства, движещи се по нея","ok":true,"i":null,"es":"al invadir el carril contrario, no crear peligro para los vehículos de frente"},{"t":"да се убеди, че с безопасна скорост, може да извърши изпреварването за кратко време","ok":true,"i":null,"es":"asegurarse de que a velocidad segura puede completar el adelantamiento rápidamente"},{"t":"да се движи в непосредствена близост до изпреварваното превозно средство","ok":false,"i":null,"es":"circular muy próximo al vehículo adelantado"}],"f":5,"es":"El conductor que adelanta está obligado a: (3 correctas)","explain":"El que adelanta debe: garantizar distancia lateral suficiente, no crear peligro al tráfico de frente al invadir su carril, y poder completar la maniobra RÁPIDO a velocidad segura. Pegarse al adelantado es lo contrario: elimina la visibilidad y el margen.","val":7,"fase":4},{"id":5896,"bg":"При тази ситуация разрешено ли е да завиете надясно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48224.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":8,"es":"En esta situación ¿está permitido girar a la derecha?","explain":"NO. Hay una señal que prohíbe girar a la derecha, y ni el agente ni un semáforo anulan las señales de PROHIBICIÓN. Lo que sí anulan son las de prioridad — STOP, ceda el paso, rombo. Esa distinción se repite en todo el examen: quien regula el paso decide QUIÉN pasa, pero no te autoriza una dirección que otra señal tiene vedada.","val":13,"fase":3},{"id":6521,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64819.png","v":null,"a":[{"t":"червеният автомобил, защото приближава кръстовището от дясната страна на зеления автомобил","ok":true,"i":null,"es":"el coche rojo, porque se aproxima por la derecha del verde"},{"t":"зеленият автомобил, защото се движи направо","ok":false,"i":null,"es":"el coche verde, porque va recto"},{"t":"червеният автомобил, защото се намира на пътя с предимство","ok":false,"i":null,"es":"el coche rojo, porque está en la vía preferente"}],"f":9,"es":"En esta situación tiene prioridad:","explain":"El coche rojo, porque se aproxima por la derecha del verde.\n\nLEE LA TABLA ANTES DE RESPONDER. Bajo el ceda el paso hay una tabla con el trazado: el trazo GRUESO viene de la IZQUIERDA y tuerce hacia ARRIBA. Los trazos FINOS son el de abajo —por donde llega el coche verde— y el de la derecha —por donde llega el rojo.\n\nO SEA: NINGUNO DE LOS DOS ESTÁ EN LA PREFERENTE. Los dos llegan por vías secundarias y los dos tienen que ceder a quien circule por la principal. Entre ellos, la señal no decide nada.\n\nY CUANDO LA SEÑAL NO DECIDE, DECIDE LA DERECHA. El rojo está a la derecha del verde: pasa el rojo.\n\n«EL ROJO PORQUE ESTÁ EN LA VÍA CON PRIORIDAD» es el distractor, y es exactamente lo que la tabla desmiente: su ramal está dibujado FINO. Conclusión correcta, razón falsa — y en este formato de pregunta la razón cuenta.\n\n«EL VERDE PORQUE VA RECTO» es el cebo de la maniobra, que nunca da prioridad.\n\nCLAVE: un ceda el paso no significa que el otro tenga preferencia. Significa que ambos debéis cederla a un tercero. Si el tercero no está, entre vosotros manda la derecha.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él, por encima de todo. 2) ¿hay semáforo? manda él sobre las señales de prioridad. 3) ¿hay señales de prioridad? mira el trazo GRUESO de la tabla: dice por dónde va la preferente. 4) si nada de lo anterior separa a los dos coches, decide la regla de la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":13,"fase":3},{"id":6522,"bg":"При тази ситуация съм с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63240.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"CORRECTO"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"f":7,"es":"En esta situación yo tengo prioridad. Esto es:","explain":"CORRECTO: aquí sí tienes prioridad.\n\nLEE LA TABLA, que es lo que decide. El trazo GRUESO viene de ARRIBA y tuerce a la DERECHA. Los trazos FINOS son el de abajo — tu aproximación — y el de la IZQUIERDA, por donde llega el coche rojo.\n\nLOS DOS ESTÁIS EN SECUNDARIA. Tú llevas ceda el paso, pero el rojo también está sobre un ramal fino. Entre vosotros dos, la señal no reparte nada: ninguno tiene la preferente.\n\nY CUANDO LA SEÑAL NO DECIDE, DECIDE LA DERECHA. El rojo llega por tu izquierda, así que tú estás a su derecha: pasas tú.\n\nPOR QUÉ ES LA GEMELA INVERSA DE LA 6518. Misma señal, misma pregunta, tabla girada. Allí el otro coche estaba sobre el trazo grueso y perdías; aquí está sobre el fino y ganas. La diferencia no está en tu señal, está en dónde cae el OTRO.\n\nCLAVE: llevar un ceda el paso no significa ceder a todo el mundo. Significa ceder a quien vaya por la preferente. Con el resto, sigues jugando con la regla de la derecha.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":10,"fase":3},{"id":6529,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61585.png","v":null,"a":[{"t":"да пропусна трамвая","ok":true,"i":null,"es":"dejar pasar al tranvía"},{"t":"да премина преди лекия автомобил","ok":true,"i":null,"es":"pasar antes que el turismo"},{"t":"да пропусна лекия автомобил","ok":false,"i":null,"es":"dejar pasar al turismo"},{"t":"да премина преди трамвая","ok":false,"i":null,"es":"pasar antes que el tranvía"}],"f":7,"es":"En esta situación debo: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el tranvía tiene prioridad sobre ti (debes cederle) PERO tú tienes prioridad sobre el turismo (puedes pasar antes que él). Dos acciones distintas simultáneas.","val":10,"fase":3},{"id":6545,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66249.png","v":null,"a":[{"t":"да пропусна червения автомобил, защото се намира на пътя с предимство","ok":true,"i":null,"es":"dejar pasar al rojo porque está en vía preferente"},{"t":"да пропусна жълтия автомобил, защото се намира на пътя с предимство","ok":true,"i":null,"es":"dejar pasar al amarillo porque está en vía preferente"},{"t":"да премина преди синия автомобил, защото той завива наляво","ok":false,"i":null,"es":"pasar antes que el azul porque gira a la izquierda"}],"f":11,"es":"En esta situación debo: (2 correctas)","explain":"Dos cosas: ceder al ROJO y ceder al AMARILLO, los dos porque circulan por la vía con prioridad.\n\nQUÉ VES. Tú llegas con un ceda el paso y su tabla. El rojo y el amarillo circulan por la preferente; el azul, como tú, no.\n\nLAS DOS PRIMERAS OPCIONES SON LA MISMA REGLA aplicada a dos coches distintos: quien llega por la secundaria cede a todos los que van por la principal, sin importar cuántos sean ni en qué dirección vayan.\n\n«PASAR ANTES QUE EL AZUL PORQUE GIRA A LA IZQUIERDA» es la falsa, y falla por la razón. Que el azul gire no le quita nada: girar no es una renuncia a la prioridad. Si acaso, entre el azul y tú habría que mirar la posición relativa, nunca su maniobra.\n\nPOR QUÉ ES UNA BUENA PREGUNTA. Te obliga a resolver el cruce con tres vehículos a la vez y a no mezclar criterios: con dos de ellos decide la vía, con el tercero decidiría la posición.\n\nCLAVE: cuando llegas por una secundaria, no cuentes coches: cede a todos los de la preferente. Solo después de que pasen, resuelve con los que están en tu mismo escalón.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":17,"fase":3},{"id":6554,"bg":"При тази ситуация пропускам червения автомобил, защото:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66883.png","v":null,"a":[{"t":"се намира от дясната ми страна","ok":true,"i":null,"es":"está a mi derecha"},{"t":"се движи направо","ok":false,"i":null,"es":"va recto"},{"t":"завивам наляво","ok":false,"i":null,"es":"yo giro a la izquierda"}],"f":10,"es":"En esta situación dejo pasar al coche rojo porque:","explain":"Porque está a mi derecha.\n\nQUÉ VES. Un cruce sin señales, sin semáforo y sin agente. El coche rojo llega por tu derecha y tú llevas el intermitente izquierdo.\n\nLA ÚNICA REGLA QUE QUEDA ES LA DE LA DERECHA, porque no hay ningún escalón superior en la escena. El rojo está a tu derecha: le cedes. Esa es la razón, y la única correcta.\n\n«PORQUE SE MUEVE RECTO» es falsa: la maniobra del otro no reparte prioridad.\n\n«PORQUE YO GIRO A LA IZQUIERDA» es el distractor fino y merece atención. El чл. 37 obliga a ceder cuando giras a la izquierda, pero solo frente a los vehículos que vienen en SENTIDO CONTRARIO. El rojo no viene de frente: llega por la vía transversal. Así que tu giro no es el motivo — le cederías igual yendo recto.\n\nESO ES LO QUE ENTRENA LA PREGUNTA: distinguir cuál de dos reglas verdaderas es la que actúa aquí. Ambas existen; solo una explica esta escena.\n\nCLAVE: чл. 37 solo se activa con tráfico de FRENTE. Con los laterales, siempre la derecha.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":15,"fase":3},{"id":6557,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68421.png","v":null,"a":[{"t":"червения автомобил","ok":true,"i":null,"es":"al coche rojo"},{"t":"синия автомобил","ok":false,"i":null,"es":"al coche azul"}],"f":10,"es":"En esta situación debo dejar pasar:","explain":"Al coche ROJO.\n\nQUÉ VES. Cruce sin señales. Llevas el intermitente izquierdo. La furgoneta azul está a tu izquierda y el coche rojo a tu derecha.\n\nAL ROJO LE CEDES porque llega por tu derecha. Es la regla general del чл. 50, ал. 1 y no necesita nada más.\n\nAL AZUL NO. Está a tu izquierda, así que es él quien te cede a ti.\n\n«EL COCHE AZUL» es la única alternativa y es la inversión exacta de la regla. Este formato de dos opciones es el más rentable del examen: si tienes clara la izquierda y la derecha, es un punto seguro en cinco segundos.\n\nEL INTERMITENTE IZQUIERDO no cambia el reparto: no hay nadie de frente, así que el чл. 37 no entra en juego. Girar no te quita ni te da prioridad frente a los laterales.\n\nCLAVE: sin señales, sin semáforo y sin agente, lo único que importa es de qué lado te llega cada uno.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él, por encima de todo. 2) ¿hay semáforo? manda él sobre las señales de prioridad. 3) ¿hay señales de prioridad? mira el trazo GRUESO de la tabla: dice por dónde va la preferente. 4) si nada de lo anterior separa a los dos coches, decide la regla de la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":15,"fase":3},{"id":6571,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68203.png","v":null,"a":[{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"dejar pasar al coche azul"},{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"dejar pasar al coche rojo"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el coche azul"}],"f":9,"es":"En esta situación debo: (2 correctas)","explain":"MULTIRESPUESTA: cedo al AZUL y paso antes que el ROJO. El azul llega por mi derecha, así que tiene preferencia sobre mí. El rojo llega por mi izquierda, así que soy yo quien pasa primero. Un coche a cada lado y solo uno te obliga: mira siempre de qué lado llega cada uno antes de pensar en hacia dónde va.","val":13,"fase":3},{"id":6582,"bg":"При този немигащ сигнал на светофара:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/103275.png","v":null,"a":[{"t":"е забранено да премина през кръстовището","ok":true,"i":null,"es":"está prohibido pasar por la intersección"},{"t":"мога да премина, но с повишено внимание","ok":false,"i":null,"es":"puedo pasar pero con precaución"},{"t":"преминаването е разрешено само за пешеходци","ok":false,"i":null,"es":"el paso está permitido solo para peatones"}],"f":6,"es":"Con esta señal fija del semáforo:","explain":"Está PROHIBIDO pasar por la intersección.\n\nQUÉ VES. Desde el coche, el semáforo de la derecha con el ÁMBAR fijo encendido.\n\nÁMBAR FIJO = «ВНИМАНИЕ, СПРИ!». Prohíbe entrar. Es la misma señal de la 11584 y la 6583, aquí preguntada en su forma más directa.\n\n«PUEDO PASAR PERO CON PRECAUCIÓN» describe el ámbar INTERMITENTE, que señala un cruce no regulado. Fija e intermitente son dos señales distintas con el mismo color: esa es toda la trampa.\n\n«SOLO PARA PEATONES» no tiene sentido: los peatones tienen su propio semáforo de dos focos, rojo y verde, sin ámbar.\n\nCLAVE: tres preguntas del banco (11584, 6583, 6582) son el mismo ámbar fijo con enunciados distintos. Si dominas una, revisa que puedes contestar las otras dos sin dudar — el examen puede sacarte cualquiera.\n\nMÉTODO DEL SEMÁFORO: 1) ¿parpadea o es fija? Немигащ = fija; мигащ = intermitente, y significan cosas distintas. 2) ¿qué focos están encendidos? 3) ¿hay flecha? Una flecha verde solo abre esa dirección, no las demás. Desarrollado en Leyes → «El semáforo: significado oficial de cada señal».","val":9,"fase":4},{"id":6583,"bg":"При този немигащ сигнал на светофара навлизането в кръстовището е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/103326.png","v":null,"a":[{"t":"забранено освен в случаите, когато не можем да спрем, без да създадем опасност за движението","ok":true,"i":null,"es":"prohibido, salvo cuando no se puede parar sin crear peligro para la circulación"},{"t":"разрешено, без ограничения","ok":false,"i":null,"es":"permitido sin restricciones"},{"t":"забранено във всички случаи","ok":false,"i":null,"es":"prohibido en todos los casos"}],"f":11,"es":"Con esta señal fija del semáforo, entrar en la intersección está:","explain":"Prohibido, salvo cuando no puedas parar sin crear peligro para la circulación.\n\nQUÉ VES. Desde el asiento del conductor, el semáforo de la derecha con el ÁMBAR fijo encendido.\n\nLA RESPUESTA TIENE DOS PARTES y las dos son necesarias. La regla: ámbar fijo = «Внимание, спри!», prohibido entrar. La excepción: si ya estás tan cerca que frenar supondría un frenazo peligroso — piensa en quien viene detrás —, continúas.\n\n«PROHIBIDO EN TODOS LOS CASOS» es falso precisamente por esa excepción. Es el distractor que castiga al que memoriza la regla sin la letra pequeña.\n\n«PERMITIDO SIN RESTRICCIONES» es lo contrario.\n\nPOR QUÉ EXISTE LA EXCEPCIÓN. La ley prefiere que un coche cruce en ámbar a que provoque un alcance por detrás. No es un permiso para pasar: es un reconocimiento de que la física manda.\n\nCLAVE: en las preguntas de ámbar fijo, la respuesta correcta casi siempre lleva la coletilla «salvo cuando no se pueda parar sin peligro». Si una opción es tajante, sospecha.\n\nMÉTODO DEL SEMÁFORO: 1) ¿parpadea o es fija? Немигащ = fija; мигащ = intermitente, y significan cosas distintas. 2) ¿qué focos están encendidos? 3) ¿hay flecha? Una flecha verde solo abre esa dirección, no las demás. Desarrollado en Leyes → «El semáforo: significado oficial de cada señal».","val":16,"fase":3},{"id":5369,"bg":"При тази ситуация с предимство е водачът на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41063.png","v":null,"a":[{"t":"червения автомобил","ok":true,"i":null,"es":"coche rojo"},{"t":"синия автомобил","ok":false,"i":null,"es":"coche azul"}],"f":10,"es":"En esta situación tiene prioridad el conductor del:","explain":"El conductor del coche ROJO.\n\nQUÉ VES. Una autopista. El rojo circula por ella; el azul se incorpora desde el carril de aceleración con el intermitente puesto.\n\nCEDE EL QUE ENTRA. El que se incorpora debe acelerar en el carril de aceleración hasta poder insertarse sin obligar a nadie a frenar ni a cambiar de carril. El que ya circula no tiene que hacer nada por él.\n\nNO SE APLICA LA REGLA DE LA DERECHA, aunque el azul llegue por la derecha. Una incorporación no es una intersección de vías equivalentes: hay una vía principal y un acceso.\n\nES LA HERMANA DE LA 5367, que plantea lo mismo con opciones distintas. Si dominas una, la otra cae sola.\n\nMATIZ PRÁCTICO, PORQUE ESTO SÍ IMPORTA EN LA CARRETERA: el que circula no está obligado a apartarse, pero facilitar la incorporación cambiándose de carril cuando es seguro es lo más razonable. Obligación y buena práctica no coinciden aquí.\n\nCLAVE: identifica el tipo de confluencia antes que las posiciones. Incorporación → cede el que entra, y la derecha no interviene.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":10,"fase":4},{"id":5399,"bg":"На автомагистрала е забранено движението на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"трактори","ok":true,"i":null,"es":"tractores"},{"t":"мотоциклети с кош","ok":false,"i":null,"es":"motos con sidecar"},{"t":"автомобили превозващи живи животни","ok":false,"i":null,"es":"vehículos transportando animales vivos"}],"f":9,"es":"En autopista está PROHIBIDA la circulación de: (2 correctas)","explain":"Ciclomotores y tractores no pueden entrar en autopista: demasiado lentos para ese flujo. Las motos CON sidecar sí pueden (son vehículos de motor rápidos) y transportar animales vivos no está prohibido.","val":9,"fase":4},{"id":5402,"bg":"Движението назад по автомагистрала е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"забранено във всички случаи","ok":true,"i":null,"es":"prohibida en todos los casos"},{"t":"разрешено само в лентата за принудително спиране","ok":false,"i":null,"es":"permitida solo en el carril de emergencia"},{"t":"разрешено без ограничения","ok":false,"i":null,"es":"permitida sin restricciones"},{"t":"забранено само през нощта","ok":false,"i":null,"es":"prohibida solo de noche"}],"f":11,"es":"La marcha atrás en autopista está:","explain":"Prohibida en todos los casos: en autopista nunca se circula marcha atrás, ni siquiera por el carril de emergencia. Un vehículo retrocediendo contra tráfico a 130 km/h es de lo más letal que existe en carretera.","val":11,"fase":4},{"id":5405,"bg":"Разрешено ли е водач, който отмине пътния възел за излизане от автомагистрала, да се придвижи обратно назад по лентата за принудително спиране?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да, във всички случаи","ok":false,"i":null,"es":"sí, en todos los casos"},{"t":"да, ако разстоянието е по-малко от 100 м","ok":false,"i":null,"es":"sí, si la distancia es menos de 100 m"},{"t":"да, ако е с включени аварийни светлини","ok":false,"i":null,"es":"sí, con las luces de emergencia encendidas"}],"f":11,"es":"Si un conductor se pasa la salida de la autopista, ¿puede ir marcha atrás para alcanzarla?","explain":"No: si te pasas la salida, continúas hasta la siguiente. La marcha atrás en autopista está prohibida sin excepciones: ni distancias cortas ni luces de emergencia la legalizan.","val":11,"fase":4},{"id":8282,"bg":"По кой от посочените начини се сигнализира автомобил, спрян върху площадката за принудително спиране на скоростен път, през нощта и при намалена видимост?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"с предупредителен светлоотразителен триъгълник","ok":true,"i":null,"es":"con triángulo reflectante de advertencia"},{"t":"с включен авариен сигнал","ok":true,"i":null,"es":"con la señal de avería activada (luces de emergencia)"},{"t":"с включени дълги светлини","ok":false,"i":null,"es":"con las luces largas encendidas"}],"f":9,"es":"¿De qué forma se señaliza el vehículo parado en el área de emergencia de vía rápida? (2 correctas)","explain":"En el área de emergencia el vehículo se señaliza con el triángulo reflectante Y las luces de emergencia: ambos avisan al tráfico que llega. Las luces largas no señalizan nada parado y deslumbrarían de frente.","val":9,"fase":4},{"id":5561,"bg":"Спряното за престой превозно средство трябва:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да не спира преминаването на другите превозни средства","ok":true,"i":null,"es":"no impedir el paso a los demás vehículos"},{"t":"да бъде с работещ двигател","ok":false,"i":null,"es":"tener el motor en marcha"},{"t":"да бъде с включени къси светлини","ok":false,"i":null,"es":"tener las luces cortas encendidas"}],"f":12,"es":"El vehículo en parada breve (prestoy) debe:","explain":"En parada breve (престой) la única exigencia de la opción correcta es no impedir el paso de los demás. No hay obligación de mantener el motor en marcha ni las luces cortas encendidas.","val":6,"fase":4},{"id":5571,"bg":"Правилно ли е паркиран товарният автомобил?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42806.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"¿Está correctamente aparcado el camión?","explain":"SÍ — en la imagen el camión cumple con las normas de aparcamiento según su posición y la señalización del lugar.","val":4,"fase":4},{"id":5600,"bg":"Правилно ли е спрян за престой товарният автомобил?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43536.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"¿Está el camión correctamente detenido para una parada breve?","explain":"SÍ — el camión cumple con las condiciones del prestoy en esta imagen.","val":4,"fase":4},{"id":5602,"bg":"Правилно ли е спрян за престой товарният автомобил?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43503.png","v":null,"a":[{"t":"да, защото е възможно най-вдясно на пътното платно","ok":true,"i":null,"es":"sí, porque está todo lo posible a la derecha de la plataforma vial"},{"t":"не, защото трябва да е извън платното за движение","ok":false,"i":null,"es":"no, porque debe estar fuera de la calzada"},{"t":"не, защото участъкът не е сигнализиран като място за паркиране","ok":false,"i":null,"es":"no, porque el tramo no está señalizado como zona de aparcamiento"}],"f":10,"es":"¿Está el camión correctamente detenido para una parada breve?","explain":"CORRECTO — el camión está todo lo posible a la derecha del firme, que es la norma básica del prestoy en carretera sin zona específica señalizada.","val":5,"fase":4},{"id":5731,"bg":"Какво влияние оказва ниското налягане на въздуха в гумите върху поведението на превозното средство?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"влошава управляемостта на превозното средство","ok":true,"i":null,"es":"empeora la manejabilidad del vehículo"},{"t":"увеличава разхода на гориво","ok":true,"i":null,"es":"aumenta el consumo de combustible"},{"t":"не оказва влияние","ok":false,"i":null,"es":"no tiene ningún efecto"}],"f":10,"es":"¿Qué efecto tiene la presión baja de los neumáticos en el comportamiento del vehículo? (2 correctas)","explain":"La presión baja tiene doble efecto: empeora la manejabilidad (neumático que flexa) y aumenta el consumo (más superficie de contacto = más resistencia a la rodadura). No es en absoluto neutra.","val":5,"fase":4},{"id":5736,"bg":"Ако по време на движение при натискане спирачният педал “потъне” и спирачките не се задействат, водачът трябва:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да отпусне бързо педала и пак да го натисне","ok":true,"i":null,"es":"soltar rápido el pedal y volver a pisarlo"},{"t":"да продължи да натиска педала, без да го отпуска","ok":false,"i":null,"es":"seguir pisando sin soltarlo"},{"t":"да натисне педала на съединителя","ok":false,"i":null,"es":"pisar el pedal del embrague"}],"f":9,"es":"Si al frenar el pedal de freno 'se hunde' y los frenos no responden, el conductor debe:","explain":"Si el pedal 'se hunde': suelta rápido y vuelve a pisar (bombear) para recuperar presión hidráulica. Mantenerlo pisado no restaura la presión perdida y el embrague no tiene nada que ver con frenar.","val":4,"fase":4},{"id":6487,"bg":"Този знак:","p":3,"s":"Раздел 4","i":"66215","v":null,"a":[{"t":"указва място за излизане на пешеходците от автомагистрала","ok":false,"i":null,"es":"indica salida de peatones de la autopista"},{"t":"сигнализира авариен изход в тунел","ok":true,"i":null,"es":"señaliza una salida de emergencia en túnel"},{"t":"обозначава вход на пешеходен подлез","ok":false,"i":null,"es":"indica la entrada a un paso subterráneo peatonal"}],"f":8,"es":"Esta señal:","explain":"Señaliza una SALIDA DE EMERGENCIA EN TÚNEL.\n\nCÓMO RECONOCERLA. Fondo verde, silueta de una persona corriendo hacia una puerta. El verde en señalización significa seguridad y evacuación, no obligación ni prohibición.\n\nPOR QUÉ NO ES LAS OTRAS. La salida de peatones de una autopista no existe como señal; y la entrada a un paso subterráneo se indica con una señal azul con escaleras, no verde.\n\nDÓNDE LA VERÁS. Dentro de túneles, cada cierta distancia, marcando por dónde salir a pie si tienes que abandonar el vehículo.\n\nCLAVE: verde y persona corriendo = evacuación a pie.","val":12,"fase":3},{"id":11604,"bg":"Този пътен знак предупреждава за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123579205.png","v":null,"a":[{"t":"намалена видимост","ok":true,"i":null,"es":"visibilidad reducida"},{"t":"настъпило пътнотранспортно произшествие","ok":false,"i":null,"es":"accidente de tráfico ocurrido"},{"t":"възможна е поява на силен страничен вятър","ok":false,"i":null,"es":"posible viento lateral fuerte"},{"t":"образувано задръстване","ok":false,"i":null,"es":"retención formada"}],"f":7,"es":"Esta señal de tráfico advierte de:","explain":"Advierte de VISIBILIDAD REDUCIDA — «намалена видимост».\n\nLA SEÑAL. Triángulo con fondo AMARILLO y borde rojo, con un vehículo y líneas horizontales que representan la niebla.\n\nEL FONDO AMARILLO ES LA CLAVE Y NO EL DIBUJO. En Bulgaria el fondo amarillo identifica la señalización TEMPORAL: obras, incidentes, condiciones meteorológicas. Y la temporal manda sobre la fija, igual que la portátil sobre trípode.\n\nQUÉ IMPLICA. Reducir la velocidad hasta poder detenerte dentro del espacio que ves, aumentar la distancia de seguridad y encender el alumbrado adecuado. No es un aviso decorativo: la visibilidad reducida cambia la velocidad legalmente exigible.\n\n«ACCIDENTE OCURRIDO», «VIENTO LATERAL FUERTE» y «RETENCIÓN» son otras señales temporales del mismo grupo, con sus propios pictogramas. Todas comparten el fondo amarillo, así que el color no las distingue entre sí: hay que leer el dibujo.\n\nCLAVE: fondo amarillo = temporal y prevalece. Después, el pictograma dice de qué se trata. Dos lecturas, en ese orden.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Rombo amarillo = prioridad. Rectángulo = información. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo».","val":7,"fase":4},{"id":5871,"bg":"Сигналът на регулировчика означава, че е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/37240.png","v":null,"a":[{"t":"разрешено да завия наляво","ok":true,"i":null,"es":"permitido girar a la izquierda"},{"t":"разрешено да премина направо","ok":true,"i":null,"es":"permitido continuar recto"},{"t":"забранено да завия надясно","ok":false,"i":null,"es":"prohibido girar a la derecha"},{"t":"забранено да завия в обратна посока","ok":false,"i":null,"es":"prohibido cambiar de sentido (media vuelta)"}],"f":9,"es":"La señal del agente regulador significa que está: (2 correctas)","explain":"Está permitido girar a la IZQUIERDA y está permitido seguir RECTO. Y también a la derecha y la media vuelta: con esta señal tienes paso libre en todas las direcciones.\n\nLO QUE VES. El agente está de PERFIL con el brazo derecho extendido horizontalmente hacia delante. Lo que te muestra a ti es su costado IZQUIERDO.\n\nLA REGLA. Brazo derecho extendido hacia delante: «Преминаването е разрешено» para quien está frente a su HOMBRO IZQUIERDO. Sin restricción de dirección — a diferencia de los brazos bajados, que solo abren recto o derecha.\n\nPOR ESO LAS DOS OPCIONES DE «ESTÁ PROHIBIDO» SON FALSAS: ni el giro a la derecha ni la media vuelta están prohibidos aquí. Tienes las cuatro direcciones.\n\nCÓMO SABER QUE ES EL HOMBRO IZQUIERDO Y NO EL DERECHO: el brazo derecho apunta hacia donde el agente mira. Si desde tu asiento el brazo sale hacia tu IZQUIERDA, el agente mira hacia allí y tú estás viendo su costado izquierdo. Si sale hacia tu derecha, ves el derecho y estás parado.\n\nEL GESTO, EN LA LEY (чл. 10, ал. 2, т. 3 ЗДвП): «дясна ръка, протегната хоризонтално напред» — brazo derecho extendido horizontalmente hacia delante. «Преминаването е разрешено» solo para quien está frente al hombro IZQUIERDO del agente (y para los peatones que cruzan por detrás de su espalda); «Преминаването е забранено» para todos los demás.\n\nMÉTODO: 1) ¿brazo vertical? alto total. 2) ¿qué te muestra a TI: pecho, espalda o costado? pecho y espalda son muro siempre. 3) ¿costado sin brazo extendido? pasas, recto o derecha. 4) ¿costado CON brazo extendido? solo el izquierdo pasa. Está desarrollado con casos en Leyes → «El agente regulador: los 3 gestos y el método».\n\nCLAVE: es el único gesto del agente que da paso total. El hombro izquierdo con brazo extendido es el mejor sitio donde puedes estar.","val":14,"fase":3},{"id":5922,"bg":"Мигащата червена светлина или две последователно мигащи една след друга червени светлини означават, че преминаването е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44332.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"}],"f":13,"es":"La luz roja parpadeante o dos rojas parpadeando alternativamente significa que el paso está:","explain":"PROHIBIDO.\n\nQUÉ ES ESTA SEÑAL. «Мигаща червена светлина» — luz roja intermitente — o dos rojas parpadeando alternadamente una tras otra. No es el semáforo de tres focos de un cruce: es el de los pasos a nivel, los puentes móviles, los ferris y las salidas de vehículos de emergencia.\n\nQUÉ ORDENA. Paso prohibido, sin matices. Hay que detenerse antes de la línea de parada o, si no la hay, antes del obstáculo que protege.\n\nPOR QUÉ ES DISTINTO DEL ROJO FIJO. El rojo fijo de un cruce puede cambiar en segundos. Esta luz avisa de que algo se aproxima o de que la vía está cerrada: se queda parpadeando mientras dure el peligro. Que parpadee NO significa «pasa con cuidado», que es la lectura equivocada más común porque en otros contextos el parpadeo suaviza la orden.\n\nCLAVE: rojo + parpadeo = prohibido igual que el rojo fijo. El único parpadeo que suaviza es el ÁMBAR intermitente.\n\nMÉTODO DEL SEMÁFORO: 1) ¿parpadea o es fija? Немигащ = fija; мигащ = intermitente, y significan cosas distintas. 2) ¿qué focos están encendidos? 3) ¿hay flecha? Una flecha verde solo abre esa dirección, no las demás. Desarrollado en Leyes → «El semáforo: significado oficial de cada señal».","val":20,"fase":3},{"id":5923,"bg":"Мигащата червена светлина или две последователно мигащи една след друга червени светлини означават:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44332.png","v":null,"a":[{"t":"че преминаването е забранено","ok":true,"i":null,"es":"que el paso está prohibido"},{"t":"че преминаването е разрешено","ok":false,"i":null,"es":"que el paso está permitido"},{"t":"че това е сигнал само за водачите на релсови превозни средства","ok":false,"i":null,"es":"que es una señal solo para conductores de vehículos sobre raíles (tranvías)"},{"t":"„Внимание!”","ok":false,"i":null,"es":"'¡Atención!'"}],"f":11,"es":"La luz roja intermitente, o dos luces rojas que parpadean alternadamente una tras otra, significan:","explain":"Que el paso está PROHIBIDO.\n\nES LA GEMELA DE LA ANTERIOR sobre la misma imagen, con dos distractores más y por eso vale la pena separarlos uno a uno.\n\n«ЧЕ ПРЕМИНАВАНЕТО Е ЗАБРАНЕНО» es la respuesta: roja intermitente o dos rojas alternas cierran el paso mientras duren.\n\n«SOLO PARA VEHÍCULOS SOBRE RAÍLES» es falso. La señal vale para TODOS los participantes en el tráfico. Este distractor juega con que muchos de estos semáforos están en pasos a nivel y se asocian al tren.\n\n«¡ATENCIÓN!» a secas es falso. «Внимание» sin más no ordena parar, solo avisa; y aquí la orden es detenerse. Es el mismo cebo de vocabulario que en las preguntas del agente, donde «Внимание» compite con «Внимание, спри!».\n\n«PASO PERMITIDO» es lo contrario.\n\nCLAVE: cuando dos preguntas comparten imagen y una tiene más opciones, la difícil es siempre la de más opciones. Aprende los distractores, no solo la respuesta.\n\nMÉTODO DEL SEMÁFORO: 1) ¿parpadea o es fija? Немигащ = fija; мигащ = intermitente, y significan cosas distintas. 2) ¿qué focos están encendidos? 3) ¿hay flecha? Una flecha verde solo abre esa dirección, no las demás. Desarrollado en Leyes → «El semáforo: significado oficial de cada señal».","val":17,"fase":3},{"id":6071,"bg":"Кой от автомобилите се движи неправилно по пътното платно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59984.png","v":null,"a":[{"t":"синият автомобил","ok":true,"i":null,"es":"el coche azul"},{"t":"червеният автомобил","ok":false,"i":null,"es":"el coche rojo"},{"t":"и двата автомобила","ok":false,"i":null,"es":"los dos vehículos"}],"f":8,"es":"¿Qué vehículo circula incorrectamente por la calzada?","explain":"EL COCHE AZUL.\n\nEL AZUL OCUPA LA MITAD IZQUIERDA de la calzada. El triángulo de la derecha avisa de que empieza un tramo de DOBLE SENTIDO, así que esa mitad izquierda está reservada a los que vienen de frente. Circular por ahí es meterse en el sentido contrario.\n\nEL ROJO VA BIEN: se mantiene en su mitad derecha, que es lo correcto.\n\n'LOS DOS VEHÍCULOS' es el cebo de quien no mira la posición de cada uno y responde por intuición. Solo uno de los dos está mal colocado.\n\nCLAVE: la señal triangular con dos flechas opuestas anuncia que se acabó el sentido único. A partir de ella, tu mitad es la derecha y nada más.","val":12,"fase":3},{"id":6084,"bg":"Кой от автомобилите се движи правилно по този път извън населеното място?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61432.png","v":null,"a":[{"t":"синият автомобил","ok":true,"i":null,"es":"el coche azul"},{"t":"червеният автомобил","ok":false,"i":null,"es":"el coche rojo"},{"t":"двата автомобила","ok":false,"i":null,"es":"los dos"}],"f":10,"es":"¿Qué vehículo circula correctamente por esta carretera fuera de población?","explain":"El coche AZUL.\n\nQUÉ VES. Una carretera fuera de poblado con dos carriles en el mismo sentido, declarados por la señal de la derecha. El azul circula por el carril derecho; el rojo va por el izquierdo con el derecho libre.\n\nFUERA DE POBLADO SE CIRCULA POR EL CARRIL LIBRE MÁS A LA DERECHA. Los carriles de la izquierda son para adelantar, no para viajar por ellos. El azul cumple; el rojo no.\n\nLA EXCEPCIÓN DEL CARRIL CÓMODO NO SE APLICA AQUÍ, y es lo que distingue esta pregunta de la 6096. Aquella exigía estar en POBLADO; ésta transcurre fuera. La misma escena con edificios alrededor tendría respuesta distinta.\n\n«LOS DOS» es el distractor de la tolerancia: si nadie viene detrás, parece que da igual. No da igual — la norma no depende del tráfico que haya.\n\nY NO ES UNA REGLA MENOR. Ocupar el carril izquierdo sin adelantar es lo que provoca los adelantamientos por la derecha, que sí son una infracción grave.\n\nCLAVE: poblado o fuera de poblado es la primera pregunta que hay que hacerse en toda esta familia. Cambia la respuesta entera.\n\nMÉTODO DE CARRILES: 1) ¿cuántos carriles tiene MI sentido? 2) ¿la línea es continua o discontinua? 3) ¿hay señal Д1? 4) ¿el carril está reservado? Desarrollado en Leyes → «Carriles y líneas: quién puede ir por dónde».","val":15,"fase":3},{"id":6435,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64344.png","v":null,"a":[{"t":"трябва да премина в дясната пътна лента","ok":true,"i":null,"es":"debo cambiar al carril derecho"},{"t":"трябва да премина в лявата пътна лента","ok":false,"i":null,"es":"debo cambiar al carril izquierdo"},{"t":"мога да продължа движението си в същата пътна лента","ok":false,"i":null,"es":"puedo continuar en el mismo carril"}],"f":8,"es":"En esta situación:","explain":"Debo pasar al carril derecho.\n\nLO QUE CUELGA DEL PÓRTICO SON SEMÁFOROS DE CARRIL (чл. 33 ППЗДвП), uno por cada carril. No regulan el cruce: regulan si ese carril concreto se puede usar en este momento. Se leen mirando el panel que está justo encima de TU carril.\n\nEL PANEL SOBRE MI CARRIL MUESTRA UN ASPA. La ley describe la luz roja de estos semáforos exactamente así: dos bandas inclinadas que se cruzan. Significa «la circulación por el carril está prohibida». Es lo que hace falsa la opción «puedo continuar en el mismo carril».\n\nEL PANEL DEL CARRIL DERECHO MUESTRA UNA FLECHA HACIA ABAJO. Esa es la forma de la luz verde según la misma norma: «la circulación por el carril está permitida». Ese es mi destino.\n\n«PASAR AL CARRIL IZQUIERDO» no lo autoriza nada: ningún panel lo abre y me alejaría del único carril señalizado como transitable.\n\nCLAVE: en un pórtico no mires el panel más llamativo, mira el que tienes encima. Aspa = fuera de ese carril. Flecha abajo = ese sirve. Y si ninguna de las dos luces está encendida, manda la señal Д1 de carriles (чл. 33, ал. 5).","val":12,"fase":3},{"id":6449,"bg":"С този пътен знак се обозначава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66102.png","v":null,"a":[{"t":"пътна лента за движение само на превозни средства от редовните линии за обществен превоз на пътници","ok":true,"i":null,"es":"carril exclusivo para transporte público de línea regular"},{"t":"платно за движение само на превозни средства от редовните линии за обществен превоз на пътници","ok":true,"i":null,"es":"calzada exclusiva para transporte público de línea regular"},{"t":"автомобилен път","ok":false,"i":null,"es":"vía rápida"},{"t":"път за движение само на автобуси","ok":false,"i":null,"es":"camino exclusivo para autobuses"}],"f":8,"es":"Esta señal designa: (2 correctas)","explain":"MULTIRESPUESTA: carril exclusivo Y calzada exclusiva para transporte público de línea regular.\n\nPOR QUÉ LAS DOS. El disco azul con el autobús reserva la vía a los vehículos de líneas regulares. La misma señal sirve para reservar un solo CARRIL o una CALZADA entera, según dónde se coloque. Por eso ambas descripciones son correctas y el examen te obliga a marcar las dos.\n\n'VÍA RÁPIDA' es otra señal distinta, con un dibujo de automóvil, no de autobús.\n\n'CAMINO SOLO PARA AUTOBUSES' es el error fino: lo que manda es el SERVICIO DE LÍNEA REGULAR, no el tipo de vehículo. Un autocar privado es un autobús y no puede entrar.\n\nCLAVE: el criterio siempre es el servicio, nunca la carrocería.","val":12,"fase":3},{"id":6458,"bg":"Кои от посочените условия е необходимо да бъдат налице за да може водачите на мотопеди да използват за движение пътния банкет?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"пътният банкет да е разположен отдясно по посока на движението им и да е годен за това","ok":true,"i":null,"es":"el arcén debe estar a la derecha en el sentido de marcha y apto para ello"},{"t":"да няма специално предназначена за тях пътна лента","ok":true,"i":null,"es":"no debe haber carril especial destinado a ellos"},{"t":"да не пречат на другите участници в движението","ok":true,"i":null,"es":"no deben molestar a los demás participantes en el tráfico"},{"t":"пътният банкет да е сигнализиран с пътен знак","ok":false,"i":null,"es":"el arcén debe estar señalizado con señal de tráfico"}],"f":10,"es":"¿Qué condiciones deben cumplirse para que los ciclomotores usen el arcén? (3 correctas)","explain":"Tres condiciones para que un ciclomotor use el arcén: que esté a su DERECHA y sea apto, que no exista carril especial para ellos, y que no moleste a los demás. No hace falta que el arcén esté señalizado con ninguna señal.","val":15,"fase":3},{"id":9837,"bg":"При тази ситуация, на водача е разрешено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043111.png","v":null,"a":[{"t":"да навлиза в средната пътна лента при изпреварване","ok":true,"i":null,"es":"entrar en el carril central para adelantar"},{"t":"да навлиза в средната пътна лента при заобикаляне","ok":true,"i":null,"es":"entrar en el carril central para rodear un obstáculo"},{"t":"да се движи в най-удобната за него пътна лента","ok":false,"i":null,"es":"circular en el carril más cómodo"},{"t":"да навлизат в крайната лява лента при изпреварване","ok":false,"i":null,"es":"entrar en el carril izquierdo para adelantar"}],"f":7,"es":"En esta situación, al conductor le está PERMITIDO: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: puedes usar el carril central para adelantar Y para rodear obstáculos. El carril izquierdo para adelantar está prohibido aquí. El más cómodo tampoco.","val":10,"fase":3},{"id":6269,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70217.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"dejar pasar al coche rojo"}],"f":8,"es":"En esta situación debo:","explain":"PASAR ANTES QUE EL COCHE ROJO.\n\nYO GIRO A LA DERECHA. Ese giro se hace por el borde derecho de la calzada y no cruza en ningún momento la trayectoria de quien viene en sentido contrario. Por eso el rojo no me obliga a nada.\n\nLA OBLIGACIÓN DE CEDER AL DE FRENTE aparece cuando giras a la IZQUIERDA o cuando cambias de sentido, porque entonces sí atraviesas su carril. No es el caso.\n\nCLAVE: giro a la derecha, no cedo al de frente. Giro a la izquierda, cedo siempre. Es la distinción que más veces se pregunta en todo el examen, y basta con visualizar si tu trayectoria cruza o no la suya.","val":11,"fase":3},{"id":6389,"bg":"Този пътен знак сигнализира, че:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67460.png","v":null,"a":[{"t":"навлизането след него е разрешено, ако пътят е свободен","ok":true,"i":null,"es":"entrar después de ella está permitido si el camino está libre"},{"t":"навлизането след него е забранено","ok":false,"i":null,"es":"entrar después de ella está prohibido"},{"t":"навлизането след него е разрешено във всички случаи","ok":false,"i":null,"es":"entrar está permitido en todos los casos"},{"t":"движението след знака е двупосочно","ok":false,"i":null,"es":"la circulación es bidireccional"}],"f":8,"es":"Esta señal indica que:","explain":"ENTRAR ESTÁ PERMITIDO SI EL CAMINO ESTÁ LIBRE.\n\nLA SEÑAL TE DA PRIORIDAD en un tramo estrecho donde no caben los dos sentidos. La flecha BLANCA marca tu sentido y la ROJA el contrario: el rojo es quien debe esperar.\n\n'PROHIBIDO ENTRAR' es justo lo contrario de lo que dice. Se confunde con la señal redonda de fondo blanco y flecha roja, que sí obliga a ceder al de enfrente. Fíjate en el color de fondo: azul cuadrada te da la preferencia, redonda te la quita.\n\n'PERMITIDO EN TODOS LOS CASOS' es demasiado. Tener preferencia no te autoriza a entrar si ya hay un vehículo dentro del estrechamiento: en ese caso esperas a que salga.\n\nCLAVE: azul cuadrada, flecha blanca grande, tú pasas primero. Pero primero no significa a la fuerza.","val":11,"fase":3},{"id":6417,"bg":"Изпреварването на МПС, с изключение на мотопеди и мотоциклети без кош, е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на кръстовище на равнозначни пътища","ok":true,"i":null,"es":"en intersección de vías equivalentes"},{"t":"на железопътен прелез без бариери","ok":true,"i":null,"es":"en paso a nivel sin barreras"},{"t":"пред пешеходна пътека, когато изпреварваното превозно средство закрива видимостта към пешеходната пътека","ok":true,"i":null,"es":"ante un paso de peatones cuando el vehículo adelantado oculta la visibilidad"},{"t":"на пътища с двупосочно движение","ok":false,"i":null,"es":"en vías con doble sentido de circulación"}],"f":7,"es":"El adelantamiento de vehículos (excepto ciclomotores y motos sin sidecar) está PROHIBIDO: (3 correctas)","explain":"Prohibido adelantar (salvo a ciclomotores y motos sin sidecar): en intersecciones de vías equivalentes, en pasos a nivel SIN barreras y ante pasos de peatones cuando el adelantado te tapa la visibilidad del paso. En vías de doble sentido adelantar es normal y legal.","val":11,"fase":3},{"id":6431,"bg":"Водач, който ще предприеме изпреварване, след като подаде сигнал е длъжен да се убеди, че:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"има свободен път на разстояние, достатъчно за изпреварване","ok":true,"i":null,"es":"hay vía libre a distancia suficiente para adelantar"},{"t":"може да заеме място в пътната лента пред изпреварваното пътно превозно средство","ok":true,"i":null,"es":"puede ocupar el carril delante del vehículo adelantado"},{"t":"няма да принуждава изпреварваното ППС да намалява скоростта или да изменя посоката на движение","ok":true,"i":null,"es":"no obliga al vehículo adelantado a reducir velocidad ni cambiar de trayectoria"},{"t":"че водачът на изпреварвания автомобил е превключил на по-ниска предавка","ok":false,"i":null,"es":"el conductor adelantado ha puesto una marcha inferior"}],"f":5,"es":"El conductor que va a adelantar, después de señalizar, debe asegurarse de que: (3 correctas)","explain":"Tras señalizar, comprueba: vía libre suficiente, que podrás ocupar hueco DELANTE del adelantado, y que no le obligarás a frenar ni desviarse. Él no tiene por qué reducir marcha ni facilitarte nada activamente.","val":7,"fase":4},{"id":5330,"bg":"При приближаване към кръстовище водачът трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"своевременно да прецени как се определя реда за преминаване през кръстовището","ok":true,"i":null,"es":"evaluar a tiempo cómo se determina el orden de paso"},{"t":"своевременно да заеме пътна лента, която е предназначена за неговата посока на движение","ok":true,"i":null,"es":"ocupar a tiempo el carril correspondiente a su dirección"},{"t":"да има готовност за намаляване на скоростта","ok":true,"i":null,"es":"estar listo para reducir velocidad"},{"t":"да увеличи скоростта за да премине по-бързо през кръстовището","ok":false,"i":null,"es":"acelerar para pasar más rápido"}],"f":9,"es":"Al aproximarse a una intersección el conductor debe: (3 correctas)","explain":"Al aproximarte a un cruce: evalúa a tiempo QUIÉN pasa primero (señales, semáforo, regla de la derecha), ocupa el carril de tu dirección y prepárate para reducir. Acelerar 'para pasar rápido' es exactamente lo contrario de la conducción defensiva.","val":13,"fase":3},{"id":5894,"bg":"При тази ситуация разрешено ли е да завиете надясно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48207.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":10,"es":"En esta situación ¿está permitido girar a la derecha?","explain":"NO, no está permitido girar a la derecha.\n\nQUÉ VES. Un círculo AZUL con una flecha blanca recta hacia arriba: dirección obligatoria, seguir de frente. Junto a él, un ceda el paso y un agente en el cruce.\n\nEL CÍRCULO AZUL OBLIGA. No sugiere ni recomienda: impone la única trayectoria permitida. Con esa señal, girar a la derecha es infracción aunque el giro sea cómodo y no moleste a nadie.\n\nTU INTERMITENTE DERECHO NO CAMBIA NADA. Señalizar una maniobra prohibida no la autoriza — el intermitente informa, no habilita.\n\nCUIDADO CON MEZCLAR PRIORIDAD Y DIRECCIÓN. El agente y el ceda el paso deciden CUÁNDO pasas; la flecha azul decide HACIA DÓNDE. Son dos cosas distintas y la respuesta a esta pregunta depende solo de la segunda.\n\nREGLA DE COLORES QUE VALE PARA TODO EL EXAMEN: círculo azul = obligación, círculo rojo = prohibición, triángulo rojo = peligro, rectángulo = información.\n\nCLAVE: cuando la pregunta sea «¿puedo girar?», busca primero las señales de dirección. Las de prioridad no responden a esa pregunta.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":15,"fase":3},{"id":5926,"bg":"Редът за преминаване на тези автомобили през кръстовището се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48294.png","v":null,"a":[{"t":"от пътните знаци относно предимството","ok":true,"i":null,"es":"las señales de prioridad"},{"t":"с правилото за „предимството на дясностоящия”","ok":false,"i":null,"es":"la regla de prioridad a la derecha"},{"t":"в зависимост от посоката на движение на автомобилите","ok":false,"i":null,"es":"la dirección de circulación"}],"f":7,"es":"El orden de paso de estos vehículos en la intersección lo determinan:","explain":"Las señales verticales de prioridad.\n\nQUÉ VES. El rombo amarillo en el poste de la derecha, un coche verde de frente y una furgoneta azul llegando por la derecha. No hay agente ni semáforo.\n\nLA ESCALERA SE DETIENE EN EL PRIMER ESCALÓN PRESENTE. Aquí no hay agente ni semáforo, así que el primero que aparece es la señalización vertical: el rombo reparte el cruce entre la vía preferente y las secundarias.\n\n«LA REGLA DE LA DERECHA» es el distractor, y es el error de método más repetido del bloque: saltar al último escalón sin mirar los anteriores. La derecha solo entra cuando ninguna señal separa a los implicados.\n\n«LA DIRECCIÓN DE MARCHA» no determina nada en ningún caso.\n\nDIFERENCIA CON LA 6606. Allí también había rombo, pero la tabla mostraba que la preferente torcía y los dos coches estaban sobre ella; por eso allí sí volvía la derecha. Aquí la señal basta.\n\nCLAVE: rombo sin tabla, o con tabla que no coloque a ambos sobre la preferente, significa que la señal resuelve. Con tabla que los coloque a los dos, vuelve la derecha.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":11,"fase":3},{"id":5942,"bg":"При тази ситуация, при преминаване през кръстовището, трябва да се съобразявате:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51152.png","v":null,"a":[{"t":"със сигналите на регулировчика","ok":true,"i":null,"es":"las señales del agente regulador"},{"t":"със сигналите на светофара","ok":false,"i":null,"es":"las señales del semáforo"},{"t":"с предписанията на пътните знаци относно предимството","ok":false,"i":null,"es":"las señales de prioridad"}],"f":7,"es":"En esta situación al pasar por la intersección debes atenerte a:","explain":"Las señales del AGENTE regulador.\n\nQUÉ VES. Los tres escalones a la vez: un agente en el cruce, un semáforo en verde y el rombo amarillo de vía con prioridad.\n\nMANDA EL PRIMERO DE LA ESCALERA, y el primero es el agente. Por encima del semáforo y por encima de cualquier señal vertical.\n\nES LA VERSIÓN COMPLETA de las preguntas 5944 y 5945: allí el agente competía contra un rival cada vez, aquí contra los dos a la vez. La respuesta no cambia.\n\n«EL SEMÁFORO» sería correcta solo si el agente no estuviera. «LAS SEÑALES DE PRIORIDAD» solo si no hubiera ni agente ni semáforo.\n\nCLAVE: no hay que evaluar los tres, hay que encontrar el más alto. En cuanto localizas al agente, el resto de la escena deja de importar para decidir el orden de paso — aunque sigas obligado a respetar prohibiciones y direcciones obligatorias, que el agente no anula.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":11,"fase":3},{"id":5945,"bg":"При тази ситуация редът за преминаване на автомобилите през кръстовището се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51266.png","v":null,"a":[{"t":"от сигналите на регулировчика","ok":true,"i":null,"es":"las señales del agente regulador"},{"t":"от сигналите на светофара","ok":false,"i":null,"es":"las señales del semáforo"},{"t":"с „правилото на десния”","ok":false,"i":null,"es":"la regla de la derecha"},{"t":"в зависимост от посоката на движение на автомобилите","ok":false,"i":null,"es":"la dirección de marcha de los vehículos"}],"f":11,"es":"En esta situación el orden de paso en la intersección lo determinan:","explain":"Las señales del AGENTE regulador.\n\nQUÉ VES. Un cruce con un agente en el centro Y semáforos funcionando en verde. Dos autoridades a la vez diciendo cada una lo suyo.\n\nMANDA EL AGENTE. Está en lo más alto de la escalera: por encima del semáforo, de las señales verticales y de cualquier regla general. La ley lo dice expresamente para los casos de discrepancia.\n\nPOR QUÉ. El agente es el único que ve lo que pasa ahora mismo — un accidente, una avería, una comitiva — y puede reaccionar. El semáforo repite un ciclo programado que no sabe nada de la situación.\n\n«EL SEMÁFORO» es el distractor principal, y es tentador porque está en verde y en verde uno se siente autorizado. No lo está: si el agente ordena parar, se para con el verde encendido.\n\n«LA REGLA DE LA DERECHA» y «LA DIRECCIÓN DE MARCHA» son escalones inferiores que ni siquiera llegan a aplicarse: solo entran cuando arriba no hay nadie.\n\nCLAVE: en cuanto veas un agente en la escena, deja de mirar todo lo demás. Es la pregunta más rentable del bloque porque se resuelve en dos segundos.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él, por encima de todo. 2) ¿hay semáforo? manda él sobre las señales de prioridad. 3) ¿hay señales de prioridad? mira el trazo GRUESO de la tabla: dice por dónde va la preferente. 4) si nada de lo anterior separa a los dos coches, decide la regla de la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":17,"fase":3},{"id":6351,"bg":"Как ще сигнализирате през нощта, за да спрете влака, ако автомобилът, който управлявате, поради повреда остане върху релсите?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"с кръгово движение на ръката, в която се държи запалена факла или фенер","ok":true,"i":null,"es":"con movimiento circular del brazo sosteniendo una antorcha o linterna encendida"},{"t":"със запален до релсите огън","ok":false,"i":null,"es":"con un fuego encendido junto a los raíles"},{"t":"с вдигната ръка, в която се държи привличащ вниманието предмет","ok":false,"i":null,"es":"con el brazo levantado sosteniendo un objeto llamativo"},{"t":"със светлоотразителна стоп-палка","ok":false,"i":null,"es":"con pala reflectante de stop"}],"f":8,"es":"¿Cómo señalizarás de noche para detener el tren si tu vehículo está averiado en el paso a nivel?","explain":"De noche el tren se detiene con el movimiento CIRCULAR del brazo sosteniendo antorcha o linterna ENCENDIDA: el maquinista necesita ver luz en movimiento circular. Un fuego junto a los raíles o un objeto sin luz no son la señal reglamentaria.","val":11,"fase":3},{"id":6469,"bg":"Как трябва да постъпите при тази ситуация, ако водачът на синия автомобил, който трябва да ви пропусне, не показва с действията си, че ще спре?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53047.png","v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir velocidad"},{"t":"трябва да управлявам с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"не съм длъжен да се съобразявам с него, защото съм с предимство","ok":false,"i":null,"es":"no tengo que considerarlo porque tengo prioridad"}],"f":8,"es":"¿Cómo debes actuar en esta situación si el conductor del coche azul, que debe cederte el paso, no muestra con sus acciones que vaya a parar? (2 correctas)","explain":"MULTIRESPUESTA: reducir la velocidad y circular listo para frenar.\n\nEL PUNTO DE LA PREGUNTA. Tienes preferencia, sí. Pero la preferencia es un derecho frente a los demás conductores, no una garantía de que vayan a respetarla. Si el azul no da señales de ir a detenerse, tu obligación es adaptarte.\n\nPOR QUÉ EL TERCER DISTRACTOR ES GRAVE. 'No tengo que considerarlo porque tengo prioridad' es exactamente la actitud que provoca los accidentes en cruce. La ley obliga a todo conductor a no crear peligro, tenga o no preferencia.\n\nCLAVE: la preferencia se cede, no se toma. Si el otro no frena, frena tú.","val":12,"fase":3},{"id":6531,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61976.png","v":null,"a":[{"t":"само трамвая","ok":true,"i":null,"es":"solo al tranvía"},{"t":"само автомобила","ok":false,"i":null,"es":"solo al coche"},{"t":"двете превозни средства","ok":false,"i":null,"es":"a los dos vehículos"}],"f":13,"es":"En esta situación debo dejar pasar:","explain":"Solo al TRANVÍA: el tranvía tiene prioridad sobre los no ferroviarios en vías equivalentes: siempre le cedes. Al coche no le debes paso en esta configuración: cederle a él también sería un error de examen (por eso 'a los dos' es falsa).","val":19,"fase":3},{"id":6540,"bg":"При тази ситуация водачът на зеления автомобил трябва да пропусне:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68541.png","v":null,"a":[{"t":"само синия автомобил","ok":true,"i":null,"es":"solo al coche azul"},{"t":"само червения автомобил","ok":false,"i":null,"es":"solo al coche rojo"},{"t":"двата автомобила","ok":false,"i":null,"es":"a los dos coches"}],"f":11,"es":"En esta situación el conductor del coche verde debe dejar pasar:","explain":"Solo al coche AZUL.\n\nQUÉ VES. Cruce sin señales ni semáforo. El coche verde —el que conduce el sujeto de la pregunta— lleva el intermitente izquierdo. El rojo llega por su izquierda y el azul por su derecha.\n\nAL AZUL SÍ: llega por la derecha del verde, y en igualdad de condiciones la derecha manda.\n\nAL ROJO NO: llega por la izquierda del verde, así que es el rojo quien debe cederle a él.\n\n«A LOS DOS» es el distractor de la prudencia mal entendida. Ceder a todo el mundo parece lo seguro, pero en el examen es una respuesta falsa: bloquea el cruce y contradice la regla.\n\nY EL GIRO A LA IZQUIERDA NO AÑADE NADA AQUÍ, porque no hay nadie de frente. El чл. 37 obliga a ceder a los que vienen en sentido contrario cuando giras a la izquierda; si no hay tráfico de frente, esa regla no se activa.\n\nCLAVE: resuelve coche por coche, no de un vistazo. Izquierda → paso yo. Derecha → cedo. Y solo si hay alguien de frente y giro a la izquierda, añado чл. 37.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él, por encima de todo. 2) ¿hay semáforo? manda él sobre las señales de prioridad. 3) ¿hay señales de prioridad? mira el trazo GRUESO de la tabla: dice por dónde va la preferente. 4) si nada de lo anterior separa a los dos coches, decide la regla de la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":17,"fase":3},{"id":6581,"bg":"След подаването на този сигнал от светофара:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/103424.png","v":null,"a":[{"t":"навлизането в кръстовището е забранено","ok":true,"i":null,"es":"está prohibido entrar en la intersección"},{"t":"трябва да се подготвя за потегляне","ok":true,"i":null,"es":"debo prepararme para arrancar"},{"t":"може да завия надясно, но с повишено внимание","ok":false,"i":null,"es":"se puede girar a la derecha con precaución"},{"t":"навлизането в кръстовището е разрешено","ok":false,"i":null,"es":"está permitido entrar en la intersección"}],"f":6,"es":"Después de esta señal del semáforo: (2 correctas)","explain":"Dos cosas: está PROHIBIDO entrar en la intersección Y debo prepararme para arrancar.\n\nQUÉ VES. Rojo y ámbar encendidos a la vez.\n\nLAS DOS RESPUESTAS SON LAS DOS CARAS DE LA MISMA SEÑAL. La orden sigue siendo «прeминаването е забранено»: no se entra. Y el mensaje añadido es «prepárate»: mete la marcha, suelta el freno de mano, mira el cruce. Por eso hay dos correctas y no una.\n\n«ENTRAR ESTÁ PERMITIDO» es falso mientras el rojo siga encendido.\n\n«PUEDO GIRAR A LA DERECHA CON PRECAUCIÓN» es el distractor más peligroso: en algunos países el giro a la derecha en rojo se permite, en Bulgaria NO, salvo que haya una flecha verde específica que lo autorice (la de la 5914). Sin flecha, no hay giro.\n\nCLAVE: rojo+ámbar es la única señal del semáforo que ordena y anuncia a la vez. Prepararse sí, moverse no.\n\nMÉTODO DEL SEMÁFORO: 1) ¿parpadea o es fija? Немигащ = fija; мигащ = intermitente, y significan cosas distintas. 2) ¿qué focos están encendidos? 3) ¿hay flecha? Una flecha verde solo abre esa dirección, no las demás. Desarrollado en Leyes → «El semáforo: significado oficial de cada señal».","val":9,"fase":3},{"id":6589,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56379.png","v":null,"a":[{"t":"трябва да спра, преди да премина през кръстовището","ok":true,"i":null,"es":"debo parar antes de cruzar la intersección"},{"t":"мога да премина, без да спирам, но трябва да пропусна ППС от другия път","ok":false,"i":null,"es":"puedo pasar sin parar pero cediendo el paso"},{"t":"мога да премина без да спирам, ако няма други ППС","ok":false,"i":null,"es":"puedo pasar sin parar si no hay otros vehículos"}],"f":12,"es":"En esta situación:","explain":"Debo PARAR antes de cruzar la intersección.\n\nQUÉ VES. La señal octogonal roja de STOP — «Спри! Пропусни движещите се по пътя с предимство» — a la derecha de tu carril.\n\nEL STOP OBLIGA A DETENERSE SIEMPRE. No es un ceda el paso reforzado: es una parada completa, con el vehículo inmóvil, antes de la línea de detención o, si no la hay, en el punto desde donde se ve la vía transversal.\n\nY DESPUÉS DE PARAR, CEDER. La parada no te da paso: solo cumple la primera obligación. La segunda es dejar pasar a los que circulan por la vía preferente.\n\n«PUEDO PASAR SIN PARAR PERO CEDIENDO» es el distractor principal, y describe exactamente el ceda el paso, que es OTRA señal. La diferencia entre las dos es justo esa: el triángulo invertido te deja seguir si está libre; el octógono no.\n\n«PUEDO PASAR SIN PARAR SI NO HAY NADIE» es el razonamiento práctico que más multas cuesta. La obligación de detenerse no depende de que venga alguien.\n\nCLAVE: STOP = parada obligatoria aunque el cruce esté desierto y aunque se vea perfectamente. Es la única señal del código que obliga a inmovilizar el vehículo sin excepción.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":18,"fase":3},{"id":6595,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57101.png","v":null,"a":[{"t":"лекият автомобил, защото се движи по пътя с предимство","ok":true,"i":null,"es":"el turismo porque circula por la vía preferente"},{"t":"мотоциклетистът, защото се намира от дясната страна на лекия автомобил","ok":false,"i":null,"es":"el motorista porque está a la derecha del turismo"},{"t":"мотоциклетистът, защото се движи направо","ok":false,"i":null,"es":"el motorista porque va recto"}],"f":11,"es":"En esta situación tiene prioridad:","explain":"El turismo, porque circula por la vía con prioridad.\n\nQUÉ VES. El rombo amarillo en el poste de la derecha: la vía por la que circula el turismo rojo es la preferente. El motorista llega por la calle transversal.\n\nLA VÍA MANDA SOBRE LA POSICIÓN. Mientras uno de los dos esté en la vía con prioridad y el otro no, la regla de la derecha ni siquiera se plantea. Solo aparece cuando los dos están en igualdad.\n\n«EL MOTORISTA PORQUE ESTÁ A LA DERECHA» es el distractor central, y es el error más caro del bloque: aplicar la regla de la derecha antes de comprobar si hay señales. La regla de la derecha es el ÚLTIMO escalón, no el primero.\n\n«EL MOTORISTA PORQUE VA RECTO» es el otro cebo clásico: ir recto no da prioridad nunca, en ninguna situación.\n\nY OJO CON LA MOTO. Ser motocicleta no cambia nada aquí. El banco usa motos en estas preguntas porque mucha gente les atribuye reglas propias que no existen.\n\nCLAVE: mira las señales antes que las posiciones. Si hay rombo, el rombo decide y la derecha se queda fuera.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él, por encima de todo. 2) ¿hay semáforo? manda él sobre las señales de prioridad. 3) ¿hay señales de prioridad? mira el trazo GRUESO de la tabla: dice por dónde va la preferente. 4) si nada de lo anterior separa a los dos coches, decide la regla de la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":16,"fase":3},{"id":6668,"bg":"Преминавайки през кръстовището при този сигнал на регулировчика няма да извърша нарушение, при условие, че:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54674.png","v":null,"a":[{"t":"преди подаването на този сигнал е било разрешено преминаването ми","ok":true,"i":null,"es":"antes de la señal me estaba permitido pasar"},{"t":"в момента на подаването на сигнала съм толкова близо, че не мога да спра безопасно","ok":true,"i":null,"es":"en el momento de la señal estoy tan cerca que no puedo parar con seguridad"},{"t":"подам звуков или светлинен сигнал за това, че ще премина през кръстовището","ok":false,"i":null,"es":"doy una señal acústica o luminosa de que voy a pasar"}],"f":10,"es":"Al pasar por la intersección con esta señal del agente no cometo infracción si: (2 correctas)","explain":"Dos condiciones: que antes de esa señal me estuviera permitido pasar, Y que en el momento de darla esté tan cerca que no pueda detenerme con seguridad.\n\nQUÉ VES. El agente con el brazo derecho levantado en vertical. Es «Внимание, спри!» — atención, para — y vale para todos, vengan de donde vengan.\n\nLA LEY PREVÉ SU PROPIA EXCEPCIÓN (чл. 10, ал. 2, т. 1): la señal no se aplica a los conductores que, habiéndoseles permitido ya el paso, se encuentran tan cerca del agente que no podrían detenerse sin crear peligro. Y quien ya ha entrado en el cruce debe despejarlo.\n\nHACEN FALTA LAS DOS COSAS. Que ya tuvieras paso, y que frenar fuera peligroso. Con una sola no basta: si no tenías paso, no puedes ampararte en la distancia; y si tenías paso pero puedes parar tranquilamente, paras.\n\n«DAR UNA SEÑAL ACÚSTICA O LUMINOSA» es el distractor y es falso de raíz. El claxon y las luces no crean derechos. Avisar de que vas a infringir no deja de ser infringir — es la misma lógica del intermitente en la 6234.\n\nCLAVE: la excepción del brazo en alto es física, no de intención. Depende de dónde estabas y de si podías frenar, no de lo que hicieras para avisar.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él, por encima de todo. 2) ¿hay semáforo? manda él sobre las señales de prioridad. 3) ¿hay señales de prioridad? mira el trazo GRUESO de la tabla: dice por dónde va la preferente. 4) si nada de lo anterior separa a los dos coches, decide la regla de la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":15,"fase":3},{"id":5350,"bg":"Автомагистралата е път:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"по който действат специални правила за движение","ok":true,"i":null,"es":"en la que rigen reglas especiales de circulación"},{"t":"предназначен за движение с високи скорости","ok":true,"i":null,"es":"destinada a la circulación a alta velocidad"},{"t":"по който движението се извършва без ограничение на скоростта","ok":false,"i":null,"es":"por la que se circula sin límite de velocidad"}],"f":8,"es":"La autopista es una vía: (2 correctas)","explain":"La autopista se define por dos rasgos: reglas especiales de circulación y diseño para ALTA velocidad. Pero alta velocidad no significa ilimitada: el límite general es 140 km/h para turismos.","val":8,"fase":4},{"id":5375,"bg":"При тази ситуация разположението на автомобила върху платното за движение е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41441.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"incorrecta"},{"t":"правилно","ok":false,"i":null,"es":"correcta"}],"f":12,"es":"En esta situación la posición del vehículo en la calzada es:","explain":"INCORRECTA.\n\nQUÉ VES. Estás en una autopista — la señal verde lo confirma — y circulas por un carril de la izquierda teniendo libre el de la derecha.\n\nLA REGLA ES LA MISMA QUE FUERA DE POBLADO, y en autopista se aplica con más motivo: se circula por el carril más a la derecha que esté libre. Los de la izquierda son para adelantar.\n\nLA EXCEPCIÓN DE POBLADO NO TE SALVA AQUÍ. La regla del «carril más cómodo» exige estar en poblado y que la velocidad máxima no pase de 80 km/h. Una autopista no cumple ninguna de las dos.\n\nPOR QUÉ IMPORTA EN EL EXAMEN. El banco insiste en esta familia porque es la infracción más habitual en la práctica y la que más adelantamientos por la derecha provoca — que es a su vez una maniobra prohibida.\n\nCLAVE: en autopista, terminado el adelantamiento, vuelve a la derecha. Quedarse en el carril izquierdo «porque voy rápido» es posición incorrecta.\n\nMÉTODO DE CARRILES: 1) ¿cuántos carriles tiene MI sentido? Con dos o más nunca se invade el contrario. 2) ¿la línea es continua o discontinua? 3) ¿hay señal Д1 que declare los carriles? 4) ¿el carril está reservado (BUS, lentos)? Desarrollado en Leyes → «Carriles y líneas: quién puede ir por dónde».","val":12,"fase":4},{"id":5380,"bg":"Кое от превозните средства нарушава правилата за движение по автомагистрала?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41655.png","v":null,"a":[{"t":"и трите превозни средства","ok":true,"i":null,"es":"los tres vehículos"},{"t":"само тракторът","ok":false,"i":null,"es":"solo el tractor"},{"t":"само товарният автомобил","ok":false,"i":null,"es":"solo el camión"},{"t":"само лекият автомобил","ok":false,"i":null,"es":"solo el turismo"}],"f":12,"es":"¿Qué vehículo incumple las normas de autopista?","explain":"LOS TRES, y cada uno por un motivo distinto.\n\nEL TRACTOR no debería estar ahí: en autopista solo se admiten vehículos cuya velocidad máxima por construcción supere los 50 km/h. Además circula por el carril de emergencia, que únicamente sirve para detenerse por avería.\n\nEL TURISMO va por el carril central teniendo libre el derecho. En autopista se circula siempre por el carril libre más a la derecha; los de la izquierda son para adelantar y se abandonan al terminar.\n\nEL CAMIÓN ocupa el carril izquierdo. Con tres o más carriles en el mismo sentido, los vehículos de más de 3,5 toneladas y los conjuntos de más de 7 metros solo pueden usar el carril derecho y el contiguo.\n\nTres infracciones distintas en una sola imagen: por eso las opciones que señalan a uno solo fallan.","val":12,"fase":4},{"id":5419,"bg":"Разрешено ли е лентата за принудително спиране на автомагистрала да се използва за движение при теглене на повредено МПС?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да, когато се тегли с гъвкава връзка","ok":false,"i":null,"es":"sí, cuando se remolca con cable flexible"},{"t":"да, но само през нощта","ok":false,"i":null,"es":"sí, pero solo de noche"},{"t":"да, но само при теглене с твърда връзка","ok":false,"i":null,"es":"sí, pero solo remolcando con barra rígida"}],"f":9,"es":"¿Está permitido usar el carril de emergencia de autopista para circular cuando hay retención?","explain":"No: el carril de emergencia se reserva para emergencias reales y vehículos prioritarios. Usarlo para saltarse una retención está prohibido a cualquier hora y con cualquier tipo de remolcado.","val":9,"fase":4},{"id":6707,"bg":"С този пътен знак се обозначава:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/40609.png","v":null,"a":[{"t":"автомагистрала","ok":true,"i":null,"es":"autopista"},{"t":"автомобилен път","ok":false,"i":null,"es":"vía rápida"},{"t":"път, за движение само на леки автомобили","ok":false,"i":null,"es":"vía solo para turismos"},{"t":"пътен възел","ok":false,"i":null,"es":"nudo de autopista"}],"f":10,"es":"Esta señal designa:","explain":"AUTOPISTA — «Автомагистрала».\n\nLA SEÑAL. Rectángulo verde con el dibujo de una calzada que se bifurca en dos. Verde es el color de la autopista en Bulgaria; el azul es el de la vía rápida.\n\nQUÉ IMPLICA ENTRAR EN AUTOPISTA. Velocidad máxima superior, mínima obligatoria de 50 km/h, prohibido pararse, dar media vuelta, circular marcha atrás o entrar con vehículos que no puedan superar 50 km/h. Los peatones, ciclistas y ciclomotores quedan fuera.\n\n«АВТОМОБИЛЕН ПЪТ» — vía rápida — es el distractor principal. Se parece mucho en las reglas pero su señal es AZUL, no verde, y admite algunos vehículos que la autopista no. En el examen la diferencia es el color.\n\n«ПЪТЕН ВЪЗЕЛ» es el nudo o enlace, otra señal distinta.\n\n«VÍA SOLO PARA TURISMOS» no existe como categoría: la autopista admite camiones y autobuses.\n\nCLAVE: verde = автомагистрала. Azul = автомобилен път. Es de las pocas preguntas del banco que se resuelven solo con el color.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Rombo amarillo = prioridad. Rectángulo = información. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo».","val":10,"fase":4},{"id":7792,"bg":"При навлизане на автомагистрала задължени ли сте да пропуснете превозните средства, които се движат по нея?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да, във всички случаи","ok":true,"i":null,"es":"sí, en todos los casos"},{"t":"да, но само когато има пътен знак за осигуряване на предимство","ok":false,"i":null,"es":"sí, pero solo cuando hay señal de ceda el paso"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":9,"es":"Al entrar en autopista ¿está obligado a ceder el paso a los vehículos que circulan por ella?","explain":"Sí, en todos los casos: al incorporarte a la autopista cedes el paso a quienes ya circulan, exista o no señal de ceda. El carril de aceleración es para igualar velocidad y entrar sin estorbar, no para reclamar hueco.","val":9,"fase":4},{"id":11351,"bg":"При движение по скоростен път на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да спира за престой извън обозначените за това места","ok":true,"i":null,"es":"parar fuera de lugares señalizados para ello"},{"t":"да пресича разделителната ивица, включително на местата, където тя е прекъсната","ok":true,"i":null,"es":"cruzar la mediana incluso donde esté interrumpida"},{"t":"да се движи в платното за насрещно движение","ok":true,"i":null,"es":"circular por el carril contrario"},{"t":"да спира за отстраняване на неизправност по автомобила","ok":false,"i":null,"es":"parar para eliminar una avería del vehículo"}],"f":12,"es":"Conduciendo por vía rápida al conductor le está PROHIBIDO: (3 correctas)","explain":"En vía rápida está prohibido: parar fuera de los lugares señalizados, cruzar la mediana (incluso interrumpida) y circular por el carril contrario. Parar para reparar una avería NO está prohibido: la avería es precisamente la excepción de fuerza mayor.","val":12,"fase":4},{"id":11718,"bg":"Когато еднопосочното платно на автомагистрала е с две пътни ленти за движение в една посока, в лявата лента движението е разрешено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"когато дясната пътна лента е заета","ok":true,"i":null,"es":"cuando el carril derecho está ocupado"},{"t":"при изпреварване","ok":true,"i":null,"es":"para adelantar"},{"t":"винаги, когато лентата е свободна","ok":false,"i":null,"es":"siempre que esté libre"},{"t":"само когато е разрешено движение със скорост над 90 km/h","ok":false,"i":null,"es":"solo con velocidad permitida superior a 90 km/h"}],"f":8,"es":"Cuando la calzada de autopista tiene dos carriles en un sentido, el carril izquierdo puede usarse: (2 correctas)","explain":"Con dos carriles por sentido, el izquierdo se usa para adelantar y cuando el derecho está ocupado. No es un carril de crucero 'si está libre': la regla base es circular por la derecha. La velocidad no da derecho al carril izquierdo.","val":8,"fase":4},{"id":5570,"bg":"Правилно ли е спрян за престой товарният автомобил?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42773.png","v":null,"a":[{"t":"да, защото е извън платното за движение","ok":true,"i":null,"es":"sí, porque está fuera de la calzada"},{"t":"не, защото е паркиран след знак, който забранява изпреварването","ok":false,"i":null,"es":"no, porque está parado después de señal que prohíbe adelantar"},{"t":"не, защото участъкът не е сигнализиран като място за паркиране","ok":false,"i":null,"es":"no, porque el tramo no está señalizado como zona de aparcamiento"}],"f":7,"es":"¿Está el camión correctamente detenido para una parada breve?","explain":"SÍ — estar fuera de la calzada es la condición correcta para el prestoy en carretera. Las señales de adelantamiento no afectan al prestoy.","val":3,"fase":4},{"id":5575,"bg":"Престоят от лявата страна на еднопосочните улици в населените места е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"разрешен, ако не се пречи на движението на ППС","ok":true,"i":null,"es":"está permitida si no se obstaculiza la circulación"},{"t":"забранен","ok":false,"i":null,"es":"está prohibida"},{"t":"разрешен без ограничение","ok":false,"i":null,"es":"está permitida sin restricciones"},{"t":"разрешен, но само за товарно-разтоварна дейност","ok":false,"i":null,"es":"está permitida solo para carga y descarga"}],"f":6,"es":"La parada breve (prestoy) en el lado izquierdo de calles de sentido único en población:","explain":"En calle de sentido único la parada breve en el lado izquierdo está permitida SI no obstaculiza la circulación: esa condición es la clave. Ni prohibida, ni libre sin condiciones, ni limitada a carga y descarga.","val":3,"fase":4},{"id":5678,"bg":"Разрешено ли е допълнителните светлини за мъгла да се използват самостоятелно?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да","ok":false,"i":null,"es":"sí"},{"t":"не","ok":true,"i":null,"es":"no"}],"f":5,"es":"¿Está permitido usar las luces antiniebla traseras de forma independiente?","explain":"No: la antiniebla trasera no se usa de forma independiente: solo acompaña al alumbrado normal y únicamente con visibilidad muy reducida. Sola confundiría (parece luz de freno permanente) y deslumbra al que sigue.","val":2,"fase":4},{"id":12068,"bg":"При тази ситуация трябва да намалите скоростта и да управлявате с готовност за спиране заради:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":59,"a":[{"t":"синия автомобил","ok":false,"i":null,"es":"el coche azul"},{"t":"зеления автомобил","ok":true,"i":null,"es":"el coche verde"},{"t":"трактора","ok":false,"i":null,"es":"el tractor"}],"f":10,"es":"En esta situación debes reducir la velocidad y conducir con disposición de frenar por: (VIDEO)","explain":"Nieve intensa y visibilidad reducida: el peligro es el coche VERDE que asoma por la derecha hacia mi trayectoria — reduzco y conduzco listo para frenar por él, porque en nieve la distancia de frenado se multiplica. El coche azul sigue por su carril sin cortar mi camino y el tractor no interfiere: distractores. En invierno, vigila al que ENTRA en tu trayectoria, no solo al que ya circula en ella.","val":5,"fase":4},{"id":5710,"bg":"Движението при едни и същи условия, по ежедневно използван маршрут:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"води до привикване с пътната обстановка","ok":true,"i":null,"es":"lleva a familiarizarse con la situación vial"},{"t":"води до отслабване на вниманието при пътуването","ok":true,"i":null,"es":"lleva a la relajación de la atención durante el trayecto"},{"t":"позволява на водача да се движи безопасно, със скорост по-висока от разрешената","ok":false,"i":null,"es":"permite circular con seguridad a velocidad superior a la permitida"}],"f":8,"es":"Conducir diariamente por la misma ruta en condiciones idénticas: (2 correctas)","explain":"La ruta diaria idéntica familiariza con la situación Y relaja la atención: conduces 'en automático'. Lo que jamás justifica es superar el límite de velocidad: conocer la ruta no la hace más segura a más velocidad.","val":4,"fase":4},{"id":5714,"bg":"Причина за по-бързото настъпване на умора у водача на МПС са:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"неправилната стойка на тялото по време на управлението","ok":true,"i":null,"es":"la postura incorrecta del cuerpo al conducir"},{"t":"разговорите с пътниците в автомобила","ok":false,"i":null,"es":"las conversaciones con los pasajeros"},{"t":"рекламните пана край пътя","ok":false,"i":null,"es":"los paneles publicitarios junto a la carretera"}],"f":8,"es":"Una causa de fatiga más rápida en el conductor es:","explain":"La postura incorrecta al volante fatiga más rápido: músculos en tensión constante y circulación dificultada. Conversar o ver carteles son distracciones, pero no causas fisiológicas de fatiga.","val":4,"fase":4},{"id":5723,"bg":"Превозването на предмети върху покрива на автомобила води до:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"увеличаване на разхода на гориво","ok":true,"i":null,"es":"aumentar el consumo de combustible"},{"t":"увеличаване на устойчивостта на автомобила в завой","ok":false,"i":null,"es":"aumentar la estabilidad en curva"},{"t":"увеличаване на стабилността на автомобила при страничен вятър","ok":false,"i":null,"es":"aumentar la estabilidad con viento lateral"}],"f":8,"es":"Transportar objetos sobre el techo del coche lleva a:","explain":"La carga en el techo aumenta el consumo (resistencia aerodinámica) y además SUBE el centro de gravedad: peor estabilidad en curva y con viento lateral, no mejor. Solo la opción del consumo es correcta.","val":4,"fase":4},{"id":5726,"bg":"Разрешено ли е зареждането с гориво да се извършва при работещ двигател на автомобила?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":8,"es":"¿Está permitido repostar combustible con el motor en marcha?","explain":"No: se reposta con el motor APAGADO. Un motor en marcha junto a vapores de combustible es fuente de ignición (chispas, calor del escape).","val":4,"fase":4},{"id":5732,"bg":"Оказва ли влияние върху управляемостта на превозното средство намаленото налягане на въздуха в гумите?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"¿La presión baja de los neumáticos afecta a la manejabilidad del vehículo?","explain":"Sí: la presión baja deforma el neumático y degrada la respuesta de la dirección. Es de las preguntas más directas del bloque de mantenimiento.","val":4,"fase":4},{"id":5735,"bg":"Как влияе пониженото налягане на въздуха в автомобилните гуми върху разхода на гориво?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"увеличава го","ok":true,"i":null,"es":"lo aumenta"},{"t":"намалява го","ok":false,"i":null,"es":"lo reduce"},{"t":"не оказва влияние","ok":false,"i":null,"es":"no tiene efecto"}],"f":7,"es":"¿Cómo afecta la presión baja de los neumáticos al consumo de combustible?","explain":"Lo aumenta: el neumático con poca presión se deforma más, tiene más resistencia a la rodadura y el motor gasta más para el mismo avance.","val":4,"fase":4},{"id":11637,"bg":"При предстоящо пътуване на дълго разстояние придвижването ще бъде по-безопасно и улеснено:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"ако предварително изберем маршрут","ok":true,"i":null,"es":"si elegimos la ruta con antelación"},{"t":"ако предварително планираме подходящи места за спиране за почивка","ok":true,"i":null,"es":"si planificamos paradas de descanso adecuadas"},{"t":"ако придвижването се извършва с по-малко спирания","ok":false,"i":null,"es":"si hacemos las menos paradas posibles"},{"t":"ако движението се извършва през нощта","ok":false,"i":null,"es":"si viajamos de noche"}],"f":11,"es":"Para un viaje largo la conducción será más segura y fácil: (2 correctas)","explain":"Viaje largo más seguro: ruta elegida con antelación y paradas de descanso planificadas. Minimizar paradas acumula fatiga y viajar de noche añade sueño y menos visibilidad: justo lo contrario.","val":6,"fase":4},{"id":5198,"bg":"Този пътен знак предупреждава за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334669.png","v":null,"a":[{"t":"платно за движение, стеснено отдясно","ok":true,"i":null,"es":"calzada estrecha por la derecha"},{"t":"опасен пътен банкет отдясно","ok":false,"i":null,"es":"arcén peligroso a la derecha"},{"t":"крайпътен обект отдясно","ok":false,"i":null,"es":"instalación junto a la carretera a la derecha"},{"t":"намаляване на броя на пътните ленти","ok":false,"i":null,"es":"reducción del número de carriles"}],"f":4,"es":"Esta señal advierte de:","explain":"Advierte de un ESTRECHAMIENTO DE LA CALZADA POR LA DERECHA — «платно за движение, стеснено отдясно».\n\nLA SEÑAL. El mismo triángulo del trío, pero aquí es el trazo de la DERECHA el que se dobla hacia dentro.\n\nES LA IMAGEN ESPEJO DE LA 5197. Si dominas una, la otra sale sola siempre que recuerdes la regla: el trazo que se dobla marca el lado que se estrecha.\n\n«REDUCCIÓN DEL NÚMERO DE CARRILES» es el distractor con más fundamento y merece separarse bien. Estrecharse no es lo mismo que perder un carril: la calzada puede seguir teniendo los mismos carriles, más angostos. La señal de reducción de carriles tiene su propio dibujo, con una línea que desaparece.\n\n«ARCÉN PELIGROSO A LA DERECHA» avisa de que el borde no aguanta el peso del vehículo, no de que la calzada se estreche.\n\n«INSTALACIÓN JUNTO A LA CARRETERA» ni siquiera es una señal de peligro.\n\nCLAVE: estrechamiento ≠ pérdida de carril. Es la distinción que decide esta pregunta.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información o indicación. Rombo amarillo = prioridad. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo».","val":4,"fase":4},{"id":9856,"bg":"На кръстовище, на пешеходците е разрешено да преминават през платното за движение по продължението на тротоара:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270044567.png","v":null,"a":[{"t":"когато продължението е очертано с пътна маркировка","ok":true,"i":null,"es":"cuando el prolongamiento está marcado con líneas"},{"t":"когато продължението не е очертано с пътна маркировка","ok":true,"i":null,"es":"cuando el prolongamiento NO está marcado"},{"t":"само когато това е указано с пътен знак","ok":false,"i":null,"es":"solo cuando lo indica una señal"},{"t":"само когато продължението е очертано с пътна маркировка тип “Зебра”","ok":false,"i":null,"es":"solo cuando está marcado tipo 'cebra'"}],"f":5,"es":"En intersección, los peatones pueden cruzar por el prolongamiento de la acera: (2 correctas)","explain":"Dos casos: cuando el prolongamiento de la acera está marcado con marca vial y cuando NO lo está.\n\nQUÉ DICE ESTO EN LA PRÁCTICA. En una intersección, los peatones pueden cruzar la calzada por la prolongación imaginaria de la acera, aunque allí no haya nada pintado. Ese cruce es legítimo y el conductor debe contar con él.\n\nPOR ESO LAS DOS OPCIONES QUE PARECEN OPUESTAS SON AMBAS CORRECTAS: la ley no distingue: marcado o sin marcar, el peatón puede cruzar por ahí.\n\n«SOLO CUANDO LO INDICA UNA SEÑAL» y «SOLO CUANDO ES DE TIPO CEBRA» son las falsas, y otra vez el problema es la palabra «solo»: convierten un caso válido en el único válido.\n\nQUÉ SIGNIFICA PARA TI AL VOLANTE. Al girar en una intersección, la prolongación de la acera que vas a cruzar es zona de peatones aunque el asfalto esté liso. Girar mirando solo a los coches es el error que más atropellos causa en ciudad.\n\nCLAVE: es la gemela de la 9854 aplicada a las esquinas. Misma doctrina: la protección del peatón no depende de la pintura.\n\nMÉTODO CON PEATONES: la protección no depende de que el paso esté pintado ni de que haya señal. Depende de que el peatón esté cruzando donde tiene derecho. Desarrollado en Leyes → «Peatones: cuándo hay que cederles el paso».","val":5,"fase":4},{"id":6068,"bg":"Когато пешеходец подава сигнал с ръка за намерението си да премине по пешеходна пътека, водачът на МПС:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"е длъжен да го пропусне без да създава опасност за движението","ok":true,"i":null,"es":"está obligado a dejarlo pasar sin crear peligro"},{"t":"е длъжен незабавно да спре","ok":false,"i":null,"es":"debe detenerse inmediatamente"},{"t":"не е длъжен да се съобразява с него","ok":false,"i":null,"es":"no tiene que considerarlo"},{"t":"трябва да подаде сигнал, към пешеходеца, че ще го пропусне","ok":false,"i":null,"es":"debe señalizar al peatón que va a cederle el paso"}],"f":5,"es":"Cuando un peatón señala con la mano su intención de cruzar por el paso de peatones, el conductor:","explain":"Cuando el peatón señala su intención de cruzar por el paso, debes DEJARLO PASAR sin crear peligro: reduce y cede con suavidad. 'Detenerse inmediatamente' (frenazo) crearía peligro para el que te sigue, e ignorarlo es infracción grave.","val":5,"fase":4},{"id":12022,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":10,"a":[{"t":"изчаквам преминаването на велосипедиста, за да осигуря достатъчно странично разстояние до него","ok":true,"i":null,"es":"espero al ciclista para garantizar distancia lateral suficiente"},{"t":"продължавам движението си, като намалявам скоростта си","ok":false,"i":null,"es":"continúo reduciendo velocidad"},{"t":"продължавам движението си, без да променям скоростта си","ok":false,"i":null,"es":"continúo sin cambiar velocidad"}],"f":5,"es":"¿Cuál es la actuación correcta en esta situación? (VIDEO)","explain":"Calle estrecha adoquinada con un todoterreno blanco estacionado a la derecha y un ciclista delante: si lo adelantara ahora no podría dejarle la separación lateral suficiente en el estrechamiento. Lo correcto es ESPERAR a que el ciclista pase el punto crítico y adelantar solo cuando pueda garantizar esa distancia. Reducir o mantener velocidad sin resolver la separación lateral no protege al ciclista.","val":5,"fase":4},{"id":5837,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, че може да премине направо или да завие надясно?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24081.png","v":null,"a":[{"t":"на червения автомобил","ok":true,"i":null,"es":"para el coche rojo"},{"t":"на зеления автомобил","ok":true,"i":null,"es":"para el coche verde"},{"t":"на жълтия автомобил","ok":false,"i":null,"es":"para el coche amarillo"},{"t":"на синия автомобил","ok":false,"i":null,"es":"para el coche azul"}],"f":10,"es":"¿Para qué conductores esta posición del cuerpo y los brazos del agente significa que pueden seguir recto o girar a la derecha? (2 correctas)","explain":"El ROJO y el VERDE.\n\nEL AGENTE ESTÁ DE PERFIL, mirando hacia el coche amarillo (izquierda de la foto), con los dos brazos bajados. Compárala con la escena de la 5834: es la misma intersección con el agente girado un cuarto de vuelta.\n\nQUIÉN VE QUÉ. Pecho hacia el amarillo, espalda hacia el azul, costados hacia el rojo (primer plano) y el verde (fondo).\n\nBRAZOS BAJADOS ABREN LOS DOS COSTADOS, y solo para seguir recto o girar a la derecha. Rojo y verde están en los costados: pueden pasar.\n\nAMARILLO Y AZUL ESTÁN PARADOS: pecho y espalda son muro.\n\nEL GESTO, EN LA LEY (чл. 10, ал. 2, т. 2 ЗДвП): «ръка или ръце, протегнати хоризонтално встрани» — brazo o brazos extendidos horizontalmente a los lados; hecho el gesto, el agente puede bajar los brazos y la señal sigue valiendo. Significa «Преминаването е разрешено» para quien está frente a su hombro izquierdo o derecho Y va a seguir recto o girar a la derecha, y «Преминаването е забранено» para todos los demás.\n\nMÉTODO: 1) ¿brazo vertical? alto total. 2) ¿qué te muestra a TI: pecho, espalda o costado? pecho y espalda son muro siempre. 3) ¿costado sin brazo extendido? pasas, recto o derecha. 4) ¿costado CON brazo extendido? solo el izquierdo pasa. Está desarrollado con casos en Leyes → «El agente regulador: los 3 gestos y el método».\n\nCLAVE: no memorices colores, memoriza el gesto. Gira mentalmente al agente y los cuatro papeles rotan con él.","val":15,"fase":3},{"id":5841,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, че преминаването е забранено във всички посоки?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24340.png","v":null,"a":[{"t":"на жълтия автомобил","ok":true,"i":null,"es":"para el coche amarillo"},{"t":"на синия автомобил","ok":true,"i":null,"es":"para el coche azul"},{"t":"на червения автомобил","ok":false,"i":null,"es":"para el coche rojo"},{"t":"на зеления автомобил","ok":false,"i":null,"es":"para el coche verde"}],"f":13,"es":"¿Para qué conductores la señal del agente significa paso PROHIBIDO? (2 correctas)","explain":"El AMARILLO y el AZUL.\n\nEL AGENTE ESTÁ DE PERFIL, mirando hacia el coche amarillo, con los dos brazos bajados.\n\nPECHO HACIA EL AMARILLO, ESPALDA HACIA EL AZUL. Los dos tienen el cuerpo del agente cruzado delante: paso prohibido en todas las direcciones. Esa es la respuesta.\n\nROJO Y VERDE VEN LOS COSTADOS y por tanto pasan (recto o derecha). No son la respuesta.\n\nEL GESTO, EN LA LEY (чл. 10, ал. 2, т. 2 ЗДвП): «ръка или ръце, протегнати хоризонтално встрани» — brazo o brazos extendidos horizontalmente a los lados; hecho el gesto, el agente puede bajar los brazos y la señal sigue valiendo. Significa «Преминаването е разрешено» para quien está frente a su hombro izquierdo o derecho Y va a seguir recto o girar a la derecha, y «Преминаването е забранено» para todos los demás.\n\nMÉTODO: 1) ¿brazo vertical? alto total. 2) ¿qué te muestra a TI: pecho, espalda o costado? pecho y espalda son muro siempre. 3) ¿costado sin brazo extendido? pasas, recto o derecha. 4) ¿costado CON brazo extendido? solo el izquierdo pasa. Está desarrollado con casos en Leyes → «El agente regulador: los 3 gestos y el método».\n\nCLAVE: es la pregunta espejo de la 5837 sobre la misma postura. Una pregunta quién pasa y la otra quién no. Si dominas una, la otra es automática — pero lee siempre qué te están pidiendo, porque el enunciado búlgaro cambia entre «разрешено» y «забранено» con una sola palabra.","val":20,"fase":3},{"id":5847,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/25090.png","v":null,"a":[{"t":"преминаването ми е забранено","ok":true,"i":null,"es":"me está PROHIBIDO pasar"},{"t":"мога да завия надясно","ok":false,"i":null,"es":"puedo girar a la derecha"},{"t":"мога да завия наляво","ok":false,"i":null,"es":"puedo girar a la izquierda"},{"t":"мога да завия в обратна посока","ok":false,"i":null,"es":"puedo dar la vuelta"}],"f":11,"es":"La señal del agente regulador significa que:","explain":"Me está PROHIBIDO pasar.\n\nLO QUE VES. El agente te da la ESPALDA, con los brazos bajados. No se le ve la cara: ves la parte trasera del chaleco y la nuca bajo la gorra.\n\nESPALDA Y PECHO VALEN LO MISMO. La ley los trata igual: quien tiene delante el pecho o la espalda del agente no pasa. Ninguna dirección se salva.\n\nES LA GEMELA DE LA 5845, la del agente de frente con brazos bajados. Misma respuesta, cara opuesta. El banco las pregunta las dos porque mucha gente asume que la espalda «no le está diciendo nada».\n\nEL GESTO, EN LA LEY (чл. 10, ал. 2, т. 2 ЗДвП): «ръка или ръце, протегнати хоризонтално встрани» — brazo o brazos extendidos horizontalmente a los lados; hecho el gesto, el agente puede bajar los brazos y la señal sigue valiendo. Significa «Преминаването е разрешено» para quien está frente a su hombro izquierdo o derecho Y va a seguir recto o girar a la derecha, y «Преминаването е забранено» para todos los demás.\n\nMÉTODO: 1) ¿brazo vertical? alto total. 2) ¿qué te muestra a TI: pecho, espalda o costado? pecho y espalda son muro siempre. 3) ¿costado sin brazo extendido? pasas, recto o derecha. 4) ¿costado CON brazo extendido? solo el izquierdo pasa. Está desarrollado con casos en Leyes → «El agente regulador: los 3 gestos y el método».\n\nCLAVE: si no ves ni un costado, estás parado. Da igual que el agente ni siquiera te esté mirando.","val":17,"fase":3},{"id":5857,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, значението на който е „Преминаването е разрешено”?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/36480.png","v":null,"a":[{"t":"на синия автомобил","ok":true,"i":null,"es":"para el coche azul"},{"t":"на червения автомобил","ok":false,"i":null,"es":"para el coche rojo"},{"t":"на зеления автомобил","ok":false,"i":null,"es":"para el coche verde"},{"t":"на жълтия автомобил","ok":false,"i":null,"es":"para el coche amarillo"}],"f":11,"es":"¿Para qué conductor esta posición del cuerpo y los brazos del agente regulador significa 'Paso PERMITIDO'?","explain":"El coche AZUL, el de la derecha de la foto.\n\nLA POSTURA. El agente está DE CARA a ti (el coche rojo) y tiene el brazo derecho extendido horizontalmente hacia delante — hacia el lado del coche amarillo.\n\nLA REGLA. Brazo derecho extendido hacia delante: «Преминаването е разрешено» SOLO para quien está frente a su HOMBRO IZQUIERDO. Nadie más pasa.\n\nDÓNDE CAE SU HOMBRO IZQUIERDO. Está de cara a ti, así que su izquierda es tu derecha: el coche AZUL. Ese es el único que pasa, y pasa en todas las direcciones, sin la limitación de recto-o-derecha que sí tienen los brazos bajados.\n\nLOS DEMÁS. El rojo le ve el PECHO: prohibido, aunque tenga el brazo apuntando a otro lado. El verde le ve la ESPALDA: prohibido. El amarillo está frente a su hombro DERECHO y además es hacia donde apunta el brazo: prohibido igual. Que el brazo te señale no significa que te dé paso.\n\nEL GESTO, EN LA LEY (чл. 10, ал. 2, т. 3 ЗДвП): «дясна ръка, протегната хоризонтално напред» — brazo derecho extendido horizontalmente hacia delante. «Преминаването е разрешено» solo para quien está frente al hombro IZQUIERDO del agente (y para los peatones que cruzan por detrás de su espalda); «Преминаването е забранено» para todos los demás.\n\nMÉTODO: 1) ¿brazo vertical? alto total. 2) ¿qué te muestra a TI: pecho, espalda o costado? pecho y espalda son muro siempre. 3) ¿costado sin brazo extendido? pasas, recto o derecha. 4) ¿costado CON brazo extendido? solo el izquierdo pasa. Está desarrollado con casos en Leyes → «El agente regulador: los 3 gestos y el método».\n\nCLAVE: el brazo extendido es un gesto de UN solo carril abierto. Y no es al que apunta: es el del hombro izquierdo.","val":17,"fase":3},{"id":5925,"bg":"При тази ситуация сигналът от бавно мигаща светлина с луннобял цвят указва на участниците в движението, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44495.png","v":null,"a":[{"t":"светофарната уредба е в изправност","ok":true,"i":null,"es":"el semáforo está en funcionamiento correcto"},{"t":"е забранено преминаването през прелеза","ok":false,"i":null,"es":"está prohibido cruzar el paso"},{"t":"бариерите ще започнат да се спускат","ok":false,"i":null,"es":"las barreras empezarán a bajar"},{"t":"че към прелеза се приближава влак","ok":false,"i":null,"es":"se aproxima un tren"}],"f":12,"es":"En esta situación la señal de luz blanca parpadeante lenta indica a los participantes en el tráfico que:","explain":"Que la instalación del semáforo está EN BUEN FUNCIONAMIENTO.\n\nQUÉ VES. Un paso a nivel con las barreras bajadas, el aspa de San Andrés y un semáforo del prelez.\n\nQUÉ ES LA LUZ BLANCA LUNAR. «Бавно мигаща светлина с луннобял цвят» — luz blanco-lunar de parpadeo LENTO. No es una orden de tráfico: es un testigo de estado. Le dice al conductor que el equipo funciona correctamente y está vigilando la vía.\n\nPOR QUÉ IMPORTA. Su ausencia es la información peligrosa: si esa luz no parpadea, no puedes confiar en que el sistema detecte el tren, y hay que cruzar como si no hubiera señalización, comprobando tú mismo.\n\nLOS TRES DISTRACTORES SON ÓRDENES, y por eso son falsos: «prohibido cruzar» y «se acerca un tren» los indica la ROJA intermitente, no la blanca; «las barreras van a bajar» tampoco lo dice esta luz.\n\nCLAVE: blanco-lunar lento = «el equipo está vivo». Rojo intermitente = «para». Son dos luces del mismo poste con funciones opuestas: una informa, la otra ordena.\n\nMÉTODO DEL SEMÁFORO: 1) ¿parpadea o es fija? Немигащ = fija; мигащ = intermitente, y significan cosas distintas. 2) ¿qué focos están encendidos? 3) ¿hay flecha? Una flecha verde solo abre esa dirección, no las demás. Desarrollado en Leyes → «El semáforo: significado oficial de cada señal».","val":18,"fase":3},{"id":6495,"bg":"Водачът на бавнодвижещо се пътно превозно средство задължително се движи в най-дясната пътна лента, освен при:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"завиване","ok":true,"i":null,"es":"girar"},{"t":"заобикаляне","ok":true,"i":null,"es":"rodear un obstáculo"},{"t":"изпреварване","ok":false,"i":null,"es":"adelantar"}],"f":6,"es":"El conductor de vehículo lento circula obligatoriamente en el carril más a la derecha, EXCEPTO para: (2 correctas)","explain":"El vehículo lento va obligatoriamente por el carril derecho, EXCEPTO para girar y para rodear un obstáculo. Adelantar no es excepción válida para él: si es lento, en principio no adelanta.","val":9,"fase":3},{"id":9839,"bg":"На двулентов път с двупосочно движение навлизането в лентата за насрещно движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043211.png","v":null,"a":[{"t":"разрешено при изпреварване","ok":true,"i":null,"es":"permitido para adelantar"},{"t":"разрешено при заобикаляне","ok":true,"i":null,"es":"permitido para rodear un obstáculo"},{"t":"забранено във всички случаи","ok":false,"i":null,"es":"prohibido en todos los casos"},{"t":"разрешено винаги, когато е свободна","ok":false,"i":null,"es":"permitido siempre que esté libre"}],"f":11,"es":"En vía de dos carriles con doble sentido, entrar en el carril contrario está: (2 correctas)","explain":"Dos casos: al ADELANTAR y al RODEAR un obstáculo.\n\nQUÉ VES. Una carretera de dos carriles con doble sentido: uno para cada dirección. Delante circula un coche gris; al fondo vienen otros de frente.\n\n«РАЗРЕШЕНО ПРИ ИЗПРЕВАРВАНЕ» — permitido al adelantar. En una carretera de un carril por sentido, adelantar exige invadir el carril contrario: es la maniobra prevista, siempre que la marca lo permita (línea discontinua) y haya visibilidad y espacio suficientes.\n\n«РАЗРЕШЕНО ПРИ ЗАОБИКАЛЯНЕ» — permitido al rodear. «Заобикаляне» no es lo mismo que adelantar: es esquivar algo que está PARADO en tu carril — un coche averiado, una obra, un obstáculo. También justifica ocupar temporalmente el otro sentido.\n\n«PROHIBIDO EN TODOS LOS CASOS» es falso: si lo fuera, no se podría adelantar nunca en carretera convencional.\n\n«PERMITIDO SIEMPRE QUE ESTÉ LIBRE» es el distractor de fondo. Que el carril contrario esté vacío no es un motivo: hace falta un MOTIVO — adelantar o rodear — y además que la marca vial y la visibilidad lo permitan. Circular por el lado contrario porque sí es infracción aunque no venga nadie.\n\nCLAVE: no basta con que se pueda, tiene que haber una razón de las dos que la ley admite. Y ojo al contraste con la pregunta de dos carriles por sentido: allí la respuesta es prohibido siempre.\n\nMÉTODO DE CARRILES: 1) ¿cuántos carriles tiene MI sentido? Con dos o más nunca se invade el contrario. 2) ¿la línea es continua o discontinua? 3) ¿hay señal Д1 que declare los carriles? 4) ¿el carril está reservado (BUS, lentos)? Desarrollado en Leyes → «Carriles y líneas: quién puede ir por dónde».","val":17,"fase":3},{"id":11585,"bg":"На път с три пътни ленти за движение в една посока, указани с пътен знак, в крайната лява лента е забранено движението на:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65145.png","v":null,"a":[{"t":"превозни средства, които не могат да развиват максималната за пътя скорост","ok":true,"i":null,"es":"por vehículos que no pueden alcanzar la velocidad máxima de esa vía"},{"t":"превозни средства, на които е забранено да развиват разрешената за пътя максимална скорост","ok":true,"i":null,"es":"por vehículos a los que está prohibido circular a la velocidad máxima"},{"t":"превозни средства, водачите на които са със стаж по-малко от 1 година","ok":false,"i":null,"es":"por vehículos cuyos conductores tienen menos de 1 año de permiso"}],"f":8,"es":"En vía de 3 carriles en un sentido señalizados, el carril izquierdo NO puede usarse: (2 correctas)","explain":"Dos casos: los vehículos que NO PUEDEN alcanzar la velocidad máxima de la vía, y aquellos a los que les está PROHIBIDO alcanzarla.\n\nQUÉ VES. Una vía de tres carriles en un sentido, declarados con la señal azul de carriles que hay a la derecha.\n\nEL CARRIL IZQUIERDO ES EL DE MAYOR VELOCIDAD, y por eso se cierra a quien no puede seguir el ritmo. La ley distingue dos motivos y los dos son respuesta:\n\nNO PODER: limitación física del vehículo. Un tractor, un camión pesado cargado, un ciclomotor. Su máxima constructiva queda por debajo de la de la vía.\n\nNO TENER PERMITIDO: limitación legal. Hay vehículos con un límite propio inferior al de la vía — camiones pesados, vehículos con remolque, autobuses. Pueden ir más rápido mecánicamente, pero no les está permitido.\n\n«CONDUCTORES CON MENOS DE UN AÑO DE PERMISO» es el distractor, y es puro sentido común mal aplicado: los conductores noveles tienen otras restricciones, pero el carril izquierdo no es una de ellas. La ley mira el vehículo, no la antigüedad del carnet.\n\nCLAVE: el carril izquierdo se cierra por velocidad, no por experiencia. Y se cierra por dos vías: la que no puede y la que no debe.\n\nMÉTODO DE CARRILES: 1) ¿cuántos carriles tiene MI sentido? Con dos o más nunca se invade el contrario. 2) ¿la línea es continua o discontinua? 3) ¿hay señal Д1 que declare los carriles? 4) ¿el carril está reservado (BUS, lentos)? Desarrollado en Leyes → «Carriles y líneas: quién puede ir por dónde».","val":12,"fase":3},{"id":11684,"bg":"Кои от посочените условия е необходимо да бъдат налице за да може при движение в населено място водачът да използва най-удобната за него пътна лента?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62168.png","v":null,"a":[{"t":"пътното платно да е с две и повече пътни ленти за движение в една посока","ok":true,"i":null,"es":"la calzada tiene dos o más carriles en una dirección"},{"t":"лентите за двиние да са обозначени с пътна маркировка","ok":true,"i":null,"es":"los carriles están marcados con señalización horizontal"},{"t":"разрешената скорост за движение да е не по-голяма от 80 km/h","ok":true,"i":null,"es":"la velocidad máxima permitida es no superior a 80 km/h"},{"t":"общата маса на превозното средство да е не повече от 3,5 тона","ok":false,"i":null,"es":"la masa total del vehículo no supera 3.5 toneladas"}],"f":13,"es":"¿Qué condiciones deben cumplirse para que en zona urbana se pueda circular por carriles distintos al derecho? (3 correctas)","explain":"Para circular en ciudad por carriles distintos del derecho: dos o más carriles por sentido, marcados con señalización horizontal y límite de velocidad de hasta 80 km/h. La masa del vehículo no pinta nada: el distractor cuela un criterio de otra norma.","val":19,"fase":3},{"id":11687,"bg":"При тази ситуация, движението по обозначената с пътен знак лента за бавнодвижещи се ППС е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123801986.png","v":null,"a":[{"t":"разрешено за автомобили обозначени с опознавателен знак „бавнодвижещи се ППС”","ok":true,"i":null,"es":"permitida para vehículos marcados con señal de vehículo lento"},{"t":"разрешено за автомобили, които не могат да се движат със скорост по-висока от 30 km/h","ok":true,"i":null,"es":"permitida para vehículos que no pueden superar 30 km/h"},{"t":"забранено за трактори","ok":false,"i":null,"es":"prohibida para tractores"},{"t":"забранено за товарни автомобили","ok":false,"i":null,"es":"prohibida para camiones"}],"f":9,"es":"En esta situación, la circulación por el carril señalizado para vehículos lentos está: (2 correctas)","explain":"Dos casos: los vehículos con el distintivo de «vehículo lento» y los que no pueden superar los 30 km/h.\n\nQUÉ VES. Una carretera con un carril adicional a la derecha, la señal azul con el panel que dibuja ese carril y un «40» dentro de un círculo azul. Delante circula un camión con el triángulo rojo de vehículo lento.\n\nQUIÉN DEBE IR POR AHÍ. El carril está reservado para los vehículos lentos, y la ley los define de dos maneras que son las dos respuestas: los que llevan el distintivo «бавнодвижещи се ППС» y los que por construcción no pueden pasar de 30 km/h.\n\n«PROHIBIDA PARA TRACTORES» es falso, y es el distractor más claro: un tractor es justamente el ejemplo típico de vehículo lento. Está entre los destinatarios del carril, no entre los excluidos.\n\n«PROHIBIDA PARA CAMIONES» también es falso. Lo que decide no es el tipo de vehículo sino su velocidad: un camión lento entra en la definición.\n\nEL CÍRCULO AZUL CON «40» es velocidad MÍNIMA obligatoria, no máxima. Círculo azul = obligación; círculo rojo = prohibición. Confundirlos invierte la lectura de la escena entera.\n\nCLAVE: el carril de lentos se define por velocidad y distintivo, nunca por categoría de vehículo. Y el azul manda, el rojo prohíbe.\n\nMÉTODO DE CARRILES: 1) ¿cuántos carriles tiene MI sentido? Con dos o más nunca se invade el contrario. 2) ¿la línea es continua o discontinua? 3) ¿hay señal Д1 que declare los carriles? 4) ¿el carril está reservado (BUS, lentos)? Desarrollado en Leyes → «Carriles y líneas: quién puede ir por dónde».","val":14,"fase":3},{"id":5861,"bg":"След пътния знак движението трябва да се извършва на дистанция от предния автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57706.png","v":null,"a":[{"t":"не по-малка от 70 м","ok":true,"i":null,"es":"no menos de 70 m"},{"t":"не по-голяма от 70 м","ok":false,"i":null,"es":"no más de 70 m"}],"f":6,"es":"Después de esta señal, la distancia de seguridad con el vehículo de delante debe ser:","explain":"NO MENOS de 70 metros.\n\nLA SEÑAL. Círculo rojo con dos vehículos y la distancia escrita: prohíbe circular a una distancia MENOR de la indicada respecto al vehículo de delante. Es una prohibición, no una recomendación.\n\nPOR QUÉ «NO MENOS» Y NO «NO MÁS». Un círculo rojo siempre prohíbe. Lo que prohíbe aquí es acercarse demasiado. Leerlo como «no más de 70 m» invierte el sentido y convierte una norma de seguridad en un absurdo — nadie te obliga a ir pegado.\n\nDÓNDE SE PONE. En túneles, puentes largos, tramos con niebla frecuente o descensos prolongados: sitios donde una frenada en cadena sería grave.\n\nREGLA GENERAL DE DISTANCIA, por si te la preguntan sin señal: la distancia debe permitirte detenerte con seguridad ante una frenada del de delante, y depende de la velocidad, del estado del firme y de tu vehículo.\n\nCLAVE: círculo rojo = prohibición. La cifra marca el mínimo que no puedes bajar, nunca un máximo.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Rombo amarillo = prioridad. Rectángulo = información. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo».","val":9,"fase":3},{"id":6245,"bg":"Коя линия указва правилната траектория за движение при завиване надясно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69818.png","v":null,"a":[{"t":"червената","ok":true,"i":null,"es":"la roja"},{"t":"синята","ok":false,"i":null,"es":"la azul"}],"f":6,"es":"¿Qué línea indica la trayectoria correcta al girar a la derecha?","explain":"La línea ROJA.\n\nQUÉ VES. Un coche verde con el intermitente derecho y dos trayectorias dibujadas: la roja gira pegada a la esquina y la azul se abre antes de girar.\n\nAL GIRAR A LA DERECHA SE VA PEGADO AL BORDE DERECHO de la calzada, tanto al entrar en el cruce como al salir de él. Esa es la roja.\n\nPOR QUÉ LA AZUL ESTÁ MAL. Abrirse hacia la izquierda antes de girar invade el carril contiguo o el sentido contrario, sorprende a quien viene detrás o al lado, y deja un hueco a la derecha por el que se cuelan ciclistas y motos justo donde vas a cerrar. Es la causa clásica del atropello a ciclistas en esquina.\n\nLA REGLA GENERAL DE LAS MANIOBRAS: antes de girar hay que colocarse lo más cerca posible del borde hacia el que se va a girar. A la derecha, pegado a la derecha; a la izquierda, junto al eje de la calzada.\n\nCUÁNDO SE PERMITE ABRIRSE: solo si el vehículo es tan largo que no cabe de otra forma, y avisando con antelación.\n\nCLAVE: la trayectoria correcta es siempre la más ceñida. Si el dibujo se abre, sospecha.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":9,"fase":4},{"id":6247,"bg":"Завиването наляво може да се извършва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от най-лявата пътна лента по посока на движението","ok":true,"i":null,"es":"desde el carril más a la izquierda en el sentido de marcha"},{"t":"от всяка лента, обозначена за завиване наляво","ok":true,"i":null,"es":"desde cualquier carril señalizado para girar a la izquierda"},{"t":"от най-лявата част на еднопосочно пътно платно","ok":true,"i":null,"es":"desde la parte más a la izquierda de una calzada de sentido único"},{"t":"от най-удобната за водача пътна лента","ok":false,"i":null,"es":"desde el carril más cómodo para el conductor"}],"f":7,"es":"Girar a la izquierda puede hacerse: (3 correctas)","explain":"Giro a la izquierda desde: el carril más a la izquierda de tu sentido, cualquier carril señalizado para ello, o la parte más a la izquierda en calzada de sentido único. 'El carril más cómodo' nunca es opción legal.","val":10,"fase":3},{"id":6344,"bg":"При тази ситуация водачът на автомобила задължен ли е да пропусне трамвая?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70912.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":6,"es":"En esta situación ¿está obligado el conductor del coche a dejar pasar al tranvía?","explain":"SÍ — el tranvía tiene prioridad en esta situación. Los tranvías generalmente tienen prioridad sobre los vehículos de motor en intersecciones.","val":9,"fase":4},{"id":6345,"bg":"При тази ситуация водачът на лекия автомобил не е задължен да пропусне трамвая.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70945.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":7,"es":"En esta situación el conductor del turismo no está obligado a dejar pasar al tranvía. Esto es:","explain":"⚠️ TRAMPA: INCORRECTO — el conductor SÍ está obligado a ceder al tranvía. Los tranvías tienen prioridad.","val":10,"fase":3},{"id":6358,"bg":"Как се извършва завиването в обратна посока?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"чрез движение със завиване наляво","ok":true,"i":null,"es":"mediante un giro a la izquierda"},{"t":"чрез движение със завиване надясно","ok":false,"i":null,"es":"mediante un giro a la derecha"}],"f":8,"es":"¿Cómo se realiza el cambio de sentido?","explain":"El cambio de sentido se ejecuta siempre mediante un giro a la IZQUIERDA: giras cruzando el eje de la vía hasta quedar en sentido contrario. Un giro a la derecha te saca de la vía, no invierte tu sentido.","val":12,"fase":3},{"id":6372,"bg":"Завиването в обратна посока е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на жп прелез","ok":true,"i":null,"es":"en paso a nivel"},{"t":"в тунел","ok":true,"i":null,"es":"en túnel"},{"t":"когато с пътен знак е ограничена скоростта на движение","ok":false,"i":null,"es":"cuando hay señal de limitación de velocidad"},{"t":"на 10 м преди пешеходна пътека","ok":false,"i":null,"es":"a 10 m antes de paso de peatones"}],"f":8,"es":"El cambio de sentido está PROHIBIDO: (2 correctas)","explain":"Prohibido cambiar de sentido en paso a nivel y en túnel: en ambos, quedar atravesado es potencialmente mortal. Una señal de límite de velocidad no prohíbe la maniobra, y 10 m antes del paso de peatones tampoco (la prohibición es SOBRE el paso).","val":11,"fase":3},{"id":6383,"bg":"На път с голям надлъжен наклон, когато разминаването е невъзможно и редът за преминаване не е уреден с пътни знаци, предимство има ППС, което:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"се изкачва по наклона","ok":true,"i":null,"es":"sube la pendiente"},{"t":"се спуска по наклона","ok":false,"i":null,"es":"baja la pendiente"},{"t":"се движи по-бързо","ok":false,"i":null,"es":"va más rápido"},{"t":"се намира по-близо до стеснения участък","ok":false,"i":null,"es":"está más cerca del tramo estrecho"}],"f":7,"es":"En vía con gran pendiente, cuando no es posible el cruce y no hay norma establecida, tiene prioridad el que:","explain":"Tiene prioridad el que SUBE: si para en plena pendiente, arrancar de nuevo cuesta arriba es difícil (riesgo de calar o retroceder). El que baja retrocede con la gravedad a favor. La velocidad o la cercanía al estrechamiento no son criterios.","val":11,"fase":3},{"id":6393,"bg":"Изпреварването на товарен автомобил е по-рисковано от изпреварването на лек автомобил защото:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"дължината на товарните автомобили е по-голяма от тази на леките автомобили","ok":true,"i":null,"es":"los camiones son más largos que los turismos"},{"t":"видимостта напред при движение зад товарен автомобил е по-ограничена","ok":true,"i":null,"es":"la visibilidad hacia adelante detrás de un camión es más limitada"},{"t":"спирачките на товарните автомобили не са толкова ефективни","ok":false,"i":null,"es":"los frenos de los camiones no son tan eficaces"},{"t":"товарните автомобили изкачват стръмните наклони по-бавно","ok":false,"i":null,"es":"los camiones suben las pendientes más despacio"}],"f":9,"es":"Adelantar un camión es más arriesgado que adelantar un turismo porque: (2 correctas)","explain":"Adelantar un camión es más arriesgado porque es más LARGO (la maniobra dura más metros y segundos) y porque detrás de él NO VES el tráfico que viene de frente. Sus frenos o su lentitud en subida no son la razón: eso hasta facilitaría adelantar.","val":13,"fase":3},{"id":6408,"bg":"Разрешено ли е да изпреварите мотоциклетиста при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71573.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":9,"es":"¿Está permitido adelantar al motorista en esta situación?","explain":"SÍ, está permitido adelantar al motorista.\n\nQUÉ VES. La señal circular con borde rojo y dos coches dentro: prohibido adelantar. Y delante, una motocicleta de dos ruedas.\n\nLA EXCEPCIÓN QUE DECIDE. Esa señal prohíbe adelantar a los vehículos de motor, PERO no se aplica a las motocicletas de dos ruedas sin sidecar. Puedes adelantar a la moto aunque estés dentro de la zona de prohibición.\n\nPOR QUÉ EXISTE LA EXCEPCIÓN. Una moto de dos ruedas ocupa poco espacio: el adelantamiento es corto y no obliga a invadir el sentido contrario de la misma forma que rebasar un coche o un camión. La prohibición está pensada para maniobras largas.\n\nSIGUE HABIENDO CONDICIONES. Que esté permitido no significa que sea automático: necesitas visibilidad, espacio y no poner en peligro al motorista, que es el usuario más vulnerable de la escena.\n\n«NO» es la respuesta que da casi todo el mundo, porque la señal se ve enorme y la excepción no está dibujada en ninguna parte.\n\nCLAVE: la prohibición de adelantar tiene una excepción y solo una — la moto de dos ruedas sin sidecar. Está recogida en el caso de excepciones de la sección Leyes.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":14,"fase":3},{"id":6448,"bg":"При тази ситуация разрешено ли е да заобиколите трамвая отляво за да не пречите на слизащите и качващите се пътници?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124301.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":10,"es":"En esta situación ¿está permitido rodear el tranvía por la izquierda para no estorbar a los pasajeros que bajan y suben?","explain":"NO. Al tranvía se le rebasa y se le adelanta por la DERECHA: irte por la izquierda te mete en el sentido contrario. Y si el tranvía está parado en una parada sin isleta, la obligación no es esquivarlo sino detenerte y esperar a que suban y bajen los viajeros. La 'buena intención' de no estorbar a los pasajeros es justo el cebo de la pregunta.","val":14,"fase":3},{"id":5878,"bg":"В кой от изброените случаи при този сигнал на светофара е забранено да навлезете в кръстовището?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/102946.png","v":null,"a":[{"t":"когато ще се наложи да остана в кръстовището поради задръстване","ok":true,"i":null,"es":"cuando voy a quedarme dentro por un atasco"},{"t":"когато на платното за движение има стоп-линия","ok":false,"i":null,"es":"cuando hay línea de stop en la calzada"},{"t":"когато на кръстовището са поставени пътни знаци относно предимството","ok":false,"i":null,"es":"cuando hay señales de prioridad en la intersección"}],"f":7,"es":"¿En cuál de los casos enumerados, con esta señal del semáforo, está PROHIBIDO entrar en la intersección?","explain":"Verde pero hay atasco al otro lado = NO entres. No debes bloquear la intersección aunque tengas verde. La línea de stop y las señales de prioridad no cambian el derecho de paso con verde.","val":10,"fase":3},{"id":5924,"bg":"Редът за преминаване на автомобила и мотоциклета през това кръстовище се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48275.png","v":null,"a":[{"t":"с правилото за „предимството на дясностоящия”","ok":true,"i":null,"es":"la regla de prioridad a la derecha"},{"t":"в зависимост от посоката им на движение","ok":false,"i":null,"es":"la dirección en que van"},{"t":"в зависимост от категорията на превозните средства","ok":false,"i":null,"es":"la categoría del vehículo"}],"f":6,"es":"El orden de paso del coche y la moto en esta intersección lo determina:","explain":"La regla de prioridad del que está a la DERECHA.\n\nQUÉ VES. Un cruce sin agente, sin semáforo y sin señales de prioridad. Un coche y una motocicleta.\n\nSIN NADIE EN LOS ESCALONES SUPERIORES, se llega al último: la regla general de la derecha. Es el único caso en que esa regla decide, y por eso la respuesta es esa.\n\n«LA DIRECCIÓN EN QUE VAN» es el cebo de la maniobra, falso siempre.\n\n«LA CATEGORÍA DEL VEHÍCULO» es el cebo específico de esta pregunta, y merece atención: ser moto no da ni quita prioridad. Tampoco ser camión, autobús o taxi. La única categoría con régimen especial son los vehículos de emergencia con sus señales en funcionamiento, y esos no aparecen aquí.\n\nCUIDADO CON LAS MOTOS EN EL BANCO. Aparecen mucho en las preguntas de prioridad porque despiertan dos prejuicios opuestos: unos les conceden ventaja por ser ágiles y otros se la niegan por ser vulnerables. Ninguno de los dos es derecho.\n\nCLAVE: la derecha manda solo cuando arriba no hay nadie. Y cuando manda, manda igual para una moto que para un camión.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":9,"fase":4},{"id":5927,"bg":"При тази ситуация, при определяне на реда за преминаване през кръстовището, се прилагат следните правила:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48311.png","v":null,"a":[{"t":"ППС, които са на пътя с предимство, трябва да преминат преди ППС от другия път","ok":true,"i":null,"es":"los vehículos de la vía preferente pasan antes que los del otro camino"},{"t":"завиващите наляво ППС от пътя с предимство пропускат насрещнодвижещите се ППС","ok":true,"i":null,"es":"los que giran a la izquierda desde la preferente ceden a los de frente"},{"t":"ППС на пътя с предимство, помежду си прилагат правилото за „предимството на дясностоящия”","ok":false,"i":null,"es":"los de la preferente entre sí aplican la regla de la derecha"}],"f":6,"es":"En esta situación, para determinar el orden de paso por la intersección se aplican las siguientes reglas: (2 correctas)","explain":"Dos reglas: los de la vía preferente pasan antes que los del otro camino, y los que giran a la izquierda desde la preferente ceden a los que vienen de frente.\n\nMIRA LA SEÑAL, Y FÍJATE EN LO QUE NO TIENE. Es un ceda el paso SIN tabla debajo. Eso significa que la vía preferente atraviesa el cruce en línea recta: no tuerce.\n\nPRIMERA REGLA: tú llegas por la secundaria, así que cedes a todo el que circule por la preferente.\n\nSEGUNDA REGLA: entre los propios vehículos de la preferente, uno gira a la izquierda y otro viene de frente. Ahí manda el чл. 37: quien gira a la izquierda cede a los que circulan en sentido contrario.\n\n«ENTRE LOS DE LA PREFERENTE, LA REGLA DE LA DERECHA» es la falsa, y aquí está toda la lección. Esa regla solo entra cuando la preferente CAMBIA DE DIRECCIÓN, que es cuando dos vehículos suyos llegan en ángulo. Si la preferente va recta, los que circulan por ella se encuentran de frente, no de lado — y frente a frente no hay «derecha» que aplicar, hay чл. 37.\n\nCLAVE: la ausencia de tabla es información. Sin tabla, la preferente sigue recta y entre sus vehículos manda el чл. 37. Con tabla que tuerce, manda la derecha (5929, 5931).\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":9,"fase":3},{"id":5929,"bg":"При тази ситуация, при определяне на реда за преминаване през кръстовището, се прилагат следните правила:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48329.png","v":null,"a":[{"t":"ППС, на пътя с предимство, трябва да преминат преди ППС на другия път","ok":true,"i":null,"es":"los de la vía preferente pasan antes que los del otro camino"},{"t":"ППС на пътя с предимство, помежду си прилагат правилото за „предимството на дясностоящия”","ok":true,"i":null,"es":"entre sí los de la preferente aplican la regla de la derecha"},{"t":"завиващите наляво ППС от пътя с предимство пропускат насрещнодвижещите се ППС","ok":false,"i":null,"es":"los que giran a la izquierda desde la preferente ceden al tráfico contrario"}],"f":8,"es":"En esta situación, para determinar el orden de paso por la intersección se aplican las siguientes reglas: (2 correctas)","explain":"Dos reglas: los de la vía preferente pasan antes que los del otro camino, y entre ellos se aplica la regla de la derecha.\n\nLEE LA TABLA. El trazo GRUESO entra por abajo y tuerce a la DERECHA. El trazo fino sigue recto.\n\nPRIMERA REGLA, la básica del rombo: quien llegue por el ramal fino cede a los de la preferente.\n\nSEGUNDA REGLA: tú y el vehículo que está a la derecha compartís la preferente. El rombo no reparte entre vosotros, y como la vía cambia de dirección se aplica el чл. 50, ал. 2: manda la derecha.\n\nLA OPCIÓN DEL GIRO A LA IZQUIERDA enuncia una regla verdadera que aquí no tiene a quién aplicarse: ningún vehículo de la preferente realiza ese giro en la escena.\n\nESO ES LO QUE ENTRENA ESTE FORMATO. En las preguntas de «qué reglas se aplican», ser cierta no basta: la regla tiene que tener sujeto en la imagen. Comprueba, para cada opción, si hay alguien haciendo eso.\n\nCLAVE: forma trío con 5931 y 5927. Las tres tienen las mismas tres opciones y cambian las correctas según el trazado de la tabla y según quién gira.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":12,"fase":3},{"id":5940,"bg":"При несъответствие между сигналите на регулировчика, сигналите на светофара и пътните знаци относно предимството трябва да се съобразявате:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51102.png","v":null,"a":[{"t":"със сигналите на регулировчика","ok":true,"i":null,"es":"las señales del agente"},{"t":"с предписанията на пътните знаци","ok":false,"i":null,"es":"las señales de tráfico"},{"t":"със сигналите на светофара","ok":false,"i":null,"es":"las señales del semáforo"}],"f":9,"es":"Cuando hay conflicto entre agente, semáforo y señales de prioridad debes atenerte a:","explain":"A las señales del AGENTE regulador.\n\nLA JERARQUÍA COMPLETA, de mayor a menor autoridad: agente regulador → semáforo → señales verticales → marcas viales → reglas generales de prioridad. Cuando dos escalones se contradicen, manda el más alto.\n\nPOR QUÉ EL AGENTE ESTÁ ARRIBA DEL TODO. Es el único que ve la situación real y puede reaccionar a ella: un accidente, una avería del semáforo, una comitiva, una obra. La ley lo dice expresamente: cuando hay discrepancia entre sus señales y las luces o las señales verticales, los participantes están obligados a atenerse al agente.\n\nEN LA FOTO tienes los tres a la vez: el agente en el cruce, un semáforo y el rombo amarillo de vía con prioridad. Los tres podrían decir cosas distintas; obedeces al agente.\n\nLOS DOS DISTRACTORES son los otros dos escalones, colocados en orden para que dudes. Semáforo por encima de señales sí — pero por debajo del agente.\n\nCLAVE: es la pregunta hermana de la 5950, que solo enfrenta semáforo contra señales. Aprende la escalera entera de una vez y las dos caen juntas.\n\nMÉTODO DEL SEMÁFORO: 1) ¿parpadea o es fija? Немигащ = fija; мигащ = intermitente, y significan cosas distintas. 2) ¿qué focos están encendidos? 3) ¿hay flecha? Una flecha verde solo abre esa dirección, no las demás. Desarrollado en Leyes → «El semáforo: significado oficial de cada señal».","val":14,"fase":3},{"id":5949,"bg":"При тази ситуация разрешено ли е да преминете през кръстовището?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51399.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":9,"es":"En esta situación ¿está permitido pasar por la intersección?","explain":"SÍ, está permitido pasar.\n\nQUÉ VES. Un agente regulador en el cruce Y un semáforo en ROJO a la derecha. Dos autoridades diciendo cosas opuestas.\n\nMANDA EL AGENTE, Y SU COSTADO ABRE. Le estás viendo un costado, y con los brazos bajados el costado significa «Преминаването е разрешено». Pasas, con el rojo encendido.\n\nPOR QUÉ ES LA PREGUNTA MÁS INCÓMODA DEL BLOQUE. Pasar un semáforo en rojo va contra todo lo que uno tiene interiorizado. Pero la escalera es clara: el agente está por encima del semáforo, y cuando se contradicen la ley obliga a atenerse al agente.\n\nCUIDADO CON LA LECTURA A MEDIAS. No es «el agente permite pasar siempre». Es que su señal sustituye a la del semáforo, y en esta escena su señal concreta te da paso. Si el agente te mostrara el pecho o la espalda, estarías parado aunque el semáforo estuviera en verde.\n\nCLAVE: agente presente = el semáforo deja de existir. Lo único que hay que leer es la postura del agente. Compárala con la 5952, donde no hay agente y el semáforo sí manda.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":13,"fase":3},{"id":6506,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62187.png","v":null,"a":[{"t":"червеният автомобил","ok":true,"i":null,"es":"el coche rojo"},{"t":"жълтият автомобил","ok":false,"i":null,"es":"el coche amarillo"}],"f":4,"es":"En esta situación tiene prioridad:","explain":"El coche ROJO.\n\nQUÉ VES. Un cruce donde tú, el coche amarillo, llegas por una vía sin preferencia, y el rojo se aproxima por tu izquierda.\n\nAQUÍ NO DECIDE LA POSICIÓN, DECIDE LA VÍA. El rojo circula por la vía con prioridad y tú no. Mientras uno de los dos esté en la preferente y el otro no, la regla de la derecha ni se plantea — y por eso el hecho de que llegue por tu izquierda es irrelevante.\n\nES LA TRAMPA EXACTA DE LA 6518, con los colores cambiados. Estar a la derecha de alguien solo sirve cuando los dos estáis en el mismo escalón.\n\nY ES EL MOTIVO POR EL QUE «SÉ LA REGLA DE LA DERECHA» NO ALCANZA para aprobar. Esa regla es la última de la lista y la mitad de las preguntas del bloque están diseñadas para que la apliques cuando no toca.\n\nCLAVE: antes de mirar quién está a la derecha, comprueba si los dos jugáis en la misma categoría. Si uno lleva preferencia de vía, la posición sobra.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":6,"fase":4},{"id":6518,"bg":"При тази ситуация съм с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63169.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":9,"es":"En esta situación yo tengo prioridad. Esto es:","explain":"INCORRECTO.\n\nLEE LA TABLA. Bajo tu señal de ceda el paso hay una tabla con el trazado: el trazo GRUESO baja desde arriba y tuerce a la IZQUIERDA. Los trazos FINOS son el de abajo — por donde llegas tú — y el de la derecha.\n\nTU RAMAL ES FINO. Estás en una vía secundaria, y por eso llevas el ceda el paso. No tienes prioridad sobre nadie que venga por la preferente.\n\nLA FURGONETA AZUL ESTÁ A TU IZQUIERDA, sobre el ramal GRUESO. Circula por la vía preferente: le cedes tú a ella.\n\nEL ERROR QUE CASTIGA ESTA PREGUNTA es responder por la posición sin leer la señal. Estar a la derecha de alguien solo importa cuando los dos estáis en igualdad de condiciones, y aquí no lo estáis.\n\nCLAVE: el ceda el paso no es decorativo. Antes de invocar la regla de la derecha, comprueba si tú y el otro estáis en el mismo escalón. Compárala con la 6522, que es la misma señal con la tabla girada y respuesta contraria.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":14,"fase":3},{"id":6520,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62077.png","v":null,"a":[{"t":"двете превозни средства","ok":true,"i":null,"es":"a los dos vehículos"},{"t":"само трамвая","ok":false,"i":null,"es":"solo al tranvía"},{"t":"само автомобила","ok":false,"i":null,"es":"solo al coche"}],"f":8,"es":"En esta situación debo dejar pasar:","explain":"Debo dejar pasar a LOS DOS, y por motivos distintos.\n\nEL TRANVÍA. Todo vehículo sin raíles cede el paso a los vehículos sobre raíles, y lo hace SEA CUAL SEA su posición y su dirección de marcha. Aunque el tranvía venga por tu izquierda, tiene preferencia. Es la única excepción real a la regla de la derecha.\n\nEL COCHE. Llega por tu derecha, así que se aplica la regla de la derecha y también pasa antes que tú.\n\nPOR QUÉ FALLAN LAS OTRAS DOS. Cada una se queda con la mitad del problema. Aquí concurren dos reglas a la vez y hay que aplicar las dos.\n\nCLAVE: el tranvía va siempre primero, venga de donde venga.","val":12,"fase":3},{"id":6550,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68473.png","v":null,"a":[{"t":"да премина преди двата автомобила","ok":true,"i":null,"es":"pasar antes que los dos coches"},{"t":"да пропусна само червения автомобил","ok":false,"i":null,"es":"dejar pasar solo al coche rojo"},{"t":"да пропусна само синия автомобил","ok":false,"i":null,"es":"dejar pasar solo al coche azul"}],"f":8,"es":"En esta situación debo:","explain":"Paso antes que los dos coches.\n\nEL AZUL SE ENTIENDE SIN PROBLEMA: llega por mi izquierda en un cruce sin señales ni semáforo. Por la regla de la derecha (чл. 50, ал. 1) soy yo quien está a su derecha, así que me cede él a mí.\n\nEL ROJO ES EL CASO RARO. Viene de frente y yo giro a la izquierda, y el чл. 37 dice que quien gira a la izquierda cede a los que vienen en sentido contrario. Por la letra de la ley yo tendría que cederle. Y sin embargo el banco marca «ceder solo al rojo» como respuesta FALSA.\n\nEL MOTIVO ES UN BUCLE CERRADO DE PRIORIDAD: yo cedo al rojo, el rojo cede al azul (que cruzando de izquierda a derecha le entra por su derecha) y el azul me cede a mí. Nadie puede arrancar sin que otro ceda primero. La ley búlgara no resuelve estos atascos con una regla, y el examen los resuelve marcando «paso antes que los dos».\n\n«CEDER SOLO AL AZUL» ES FALSO EN CUALQUIER LECTURA: el azul viene por mi izquierda, jamás tiene prioridad sobre mí.\n\nCLAVE: son tres preguntas gemelas con la misma escena (esta, la del enunciado «el rojo tiene prioridad porque va recto» y la de «paso antes que el rojo y antes que el azul»). Reconoce el patrón: cruce sin señales + uno por mi izquierda + uno de frente + yo giro a la izquierda → en el examen paso yo.\n\nEN LA CARRETERA HAZ LO CONTRARIO: si giras a la izquierda, cede siempre al que viene de frente. Si hay colisión, el atestado se apoya en el чл. 37 y responde el que gira. Esta es la única pregunta del banco donde el examen y la práctica piden cosas distintas, y está desarrollada entera en Leyes → «Caso especial: el bucle de prioridad (заклещване)».","val":12,"fase":3},{"id":6559,"bg":"При тази ситуация водачът на зеления автомобил трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68404.png","v":null,"a":[{"t":"да пропусне червения автомобил","ok":true,"i":null,"es":"dejar pasar al coche rojo"},{"t":"да пропусне синия автомобил","ok":true,"i":null,"es":"dejar pasar al coche azul"},{"t":"да премине преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el azul"},{"t":"да премине преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el rojo"}],"f":8,"es":"En esta situación el conductor del coche verde debe: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el verde debe ceder tanto al rojo como al azul — ambos tienen prioridad sobre él en esta intersección.","val":11,"fase":3},{"id":6562,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67115.png","v":null,"a":[{"t":"лекият автомобил е с предимство, защото е отдясно на мотоциклетиста","ok":true,"i":null,"es":"el turismo tiene prioridad porque está a la derecha del motorista"},{"t":"мотоциклетистът е с предимство, защото се движи направо","ok":false,"i":null,"es":"el motorista tiene prioridad porque va recto"},{"t":"мотоциклетистът е с предимство, защото е двуколесно МПС","ok":false,"i":null,"es":"el motorista tiene prioridad porque es vehículo de dos ruedas"}],"f":9,"es":"En esta situación:","explain":"El TURISMO, porque está a la derecha del motorista. Cruce de vías de igual valor: manda la regla de la derecha y nada más. 'Porque va recto' es el cebo habitual — la dirección nunca reparte preferencias. Y 'porque es un vehículo de dos ruedas' es aún peor: las motos no tienen ninguna prioridad especial, se rigen por las mismas reglas que los coches.","val":13,"fase":3},{"id":6573,"bg":"При тази ситуация трябва да премина след:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68203.png","v":null,"a":[{"t":"синия автомобил","ok":true,"i":null,"es":"el coche azul"},{"t":"червения автомобил","ok":false,"i":null,"es":"el coche rojo"}],"f":10,"es":"En esta situación debo pasar después de:","explain":"Después del AZUL. El azul llega por mi derecha y tiene preferencia sobre mí. El rojo llega por mi izquierda, así que él pasa después de mí, no antes. La pregunta invierte el enunciado habitual — pregunta detrás de quién voy, no a quién cedo — pero la respuesta sale del mismo sitio: solo cede el paso quien tiene al otro a su derecha.","val":15,"fase":3},{"id":6597,"bg":"При тази ситуация трябва да пропусна товарния автомобил, защото се движи направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56964.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":8,"es":"En esta situación debo dejar pasar al camión porque va recto. Esto es:","explain":"INCORRECTO, y por dos motivos independientes.\n\nPRIMER MOTIVO: NO DEBES CEDERLE. El rombo amarillo está en tu poste, mirando hacia ti: tú circulas por la vía con prioridad. El camión llega por la calle transversal, sin prioridad. Es él quien te cede a ti.\n\nSEGUNDO MOTIVO: LA RAZÓN TAMBIÉN ES FALSA. Aunque tuvieras que cederle, no sería «porque va recto». Ir recto no otorga prioridad en ninguna situación. Es el cebo que se repite en 6595, 6521 y 6543.\n\nPOR ESO ES DOBLEMENTE FALSA. En este formato de enunciado con justificación, basta con que falle la razón para que la respuesta sea неправилно. Aquí fallan la conclusión y la razón.\n\nY OJO AL CAMIÓN. Ser un vehículo grande y pesado no da preferencia. El banco usa camiones y autobuses en estas preguntas precisamente porque intimidan y mucha gente les concede un derecho que no tienen.\n\nCLAVE: en los enunciados con «porque», evalúa las dos partes por separado. Si la razón es «porque va recto», ya puedes marcar incorrecto casi sin mirar el resto.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":12,"fase":3},{"id":6606,"bg":"Редът за преминаване на тези автомобили през кръстовището се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48346.png","v":null,"a":[{"t":"с правилото за „предимството на дясностоящия”","ok":true,"i":null,"es":"la regla de prioridad a la derecha"},{"t":"в зависимост от посоката на движение на автомобилите","ok":false,"i":null,"es":"la dirección de circulación"}],"f":10,"es":"El orden de paso de estos coches en la intersección lo determinan:","explain":"La regla de prioridad del que está a la DERECHA.\n\nQUÉ VES, Y AQUÍ ESTÁ LA GRACIA. Hay un rombo amarillo de vía con prioridad, así que la respuesta parece que debería ser «la señal». Pero mira la tabla que cuelga debajo: el trazo GRUESO —la vía preferente— entra por abajo, por donde llega el coche rojo, y TUERCE A LA DERECHA, hacia donde está el azul. El trazo fino sigue recto.\n\nLOS DOS COCHES ESTÁN EN LA MISMA VÍA PREFERENTE. Uno en el tramo que entra y otro en el tramo por el que sale. Entre ellos, la señal no reparte nada: los dos tienen lo mismo.\n\nPOR ESO ENTRA EL чл. 50, ал. 2: cuando la vía con prioridad cambia de dirección, entre los vehículos que circulan por ella se aplica la regla general de la derecha.\n\n«LA DIRECCIÓN DE MARCHA» es falsa como siempre: girar o seguir recto no otorga preferencia.\n\nCLAVE: el rombo te dice que mandas sobre las secundarias, la tabla te dice por dónde va la preferente. Si la tabla muestra que TUERCE, y el otro coche también está sobre ella, vuelve la derecha. Es el mismo caso que la 6539.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él, por encima de todo. 2) ¿hay semáforo? manda él sobre las señales de prioridad. 3) ¿hay señales de prioridad? mira el trazo GRUESO de la tabla: dice por dónde va la preferente. 4) si nada de lo anterior separa a los dos coches, decide la regla de la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":14,"fase":3},{"id":6612,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53713.png","v":null,"a":[{"t":"спирам, за да изчакам разрешаващ сигнал от регулировчика","ok":true,"i":null,"es":"paro para esperar la señal de paso del agente"},{"t":"пропускам синия автомобил и преминавам след него","ok":false,"i":null,"es":"dejo pasar al coche azul y paso después"},{"t":"преминавам преди синия автомобил","ok":false,"i":null,"es":"paso antes que el coche azul"}],"f":11,"es":"En esta situación:","explain":"Paro y espero a que el agente me dé paso.\n\nQUÉ VES. Tres cosas a la vez: un agente en el cruce, un semáforo en verde y un ceda el paso. Y el agente te está mostrando el PECHO.\n\nMANDA EL AGENTE, y el pecho es muro. Con el pecho o la espalda del agente delante, el paso está prohibido en todas las direcciones, esté el semáforo como esté.\n\nEL VERDE NO TE SALVA. Es el punto de la pregunta: mucha gente ve el verde y concluye que puede pasar. El semáforo queda desplazado en cuanto hay un agente regulando.\n\n«DEJO PASAR AL AZUL Y PASO DESPUÉS» es falso porque no es cuestión de turno: mientras el agente no cambie de postura, no pasas aunque el cruce se vacíe.\n\n«PASO ANTES QUE EL AZUL» aplica una regla de posición que aquí no llega a entrar en juego.\n\nCLAVE: cuando hay agente, la única pregunta es qué parte de su cuerpo te muestra. Pecho o espalda, parado. Costado, pasas. Consulta el caso «El agente regulador» en Leyes.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":16,"fase":3},{"id":7963,"bg":"При тази ситуация задължени ли сте да пропуснете товарния автомобил?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64917897.png","v":null,"a":[{"t":"да, защото се намира на пътя с предимство","ok":true,"i":null,"es":"sí, porque está en la vía preferente"},{"t":"да, защото се намира отдясно","ok":true,"i":null,"es":"sí, porque está a su derecha"},{"t":"не, защото се движа направо","ok":false,"i":null,"es":"no, porque voy recto"}],"f":9,"es":"En esta situación ¿está obligado a dejar pasar al camión? (2 correctas)","explain":"Dos razones, y las dos son ciertas a la vez: porque está en la vía preferente Y porque está a tu derecha.\n\nLEE LA TABLA. El trazo GRUESO entra por abajo — tu aproximación — y TUERCE A LA DERECHA, hacia donde está el camión. El trazo fino sigue recto.\n\nO SEA: LOS DOS ESTÁIS EN LA PREFERENTE. Tú en el tramo que entra, el camión en el tramo por el que la vía continúa. Por eso la primera razón es correcta: él circula por la vía con prioridad.\n\nY POR ESO TAMBIÉN LA SEGUNDA. Como los dos compartís la preferente, la señal no reparte nada entre vosotros y entra el чл. 50, ал. 2: cuando la vía con prioridad cambia de dirección, entre los que circulan por ella manda la regla de la derecha. El camión está a tu derecha.\n\n«NO, PORQUE VOY RECTO» es el cebo de siempre: la maniobra no da prioridad. Y aquí además va acompañado de la trampa de creer que seguir recto te mantiene en la preferente — no es así, la preferente es la que dibuja la tabla, no la que tú elijas.\n\nCLAVE: cuando la tabla muestra que la preferente TUERCE, las dos razones se acumulan. Es la única configuración del banco en la que ambas justificaciones son correctas simultáneamente.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":14,"fase":3},{"id":11347,"bg":"При навлизане в тунел, на който началото е обозначено с пътен знак, водачът задължен ли е да включи късите светлини на автомобила?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":6,"es":"Al entrar en un túnel señalizado con señal de tráfico ¿está obligado el conductor a encender las luces?","explain":"Sí: en túnel señalizado con señal de tráfico es obligatorio encender las luces, aunque el túnel esté iluminado. Debes ver y sobre todo SER VISTO en el cambio brusco de luminosidad.","val":9,"fase":4},{"id":5367,"bg":"При тази ситуация с предимство е водачът на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/40964.png","v":null,"a":[{"t":"автомобилa, който се движи по автомагистралата","ok":true,"i":null,"es":"coche que circula por la autopista"},{"t":"автомобила отдясно, който навлиза на автомагистралата","ok":false,"i":null,"es":"coche de la derecha que entra en la autopista"},{"t":"автомобилa, който се движи с по-висока скорост","ok":false,"i":null,"es":"coche que va más rápido"}],"f":13,"es":"En esta situación tiene prioridad el conductor del:","explain":"El conductor que circula POR la autopista.\n\nQUÉ VES. Una autopista — la señal verde lo confirma — con un coche circulando por ella y otro que se incorpora desde el carril de aceleración, con el intermitente puesto.\n\nQUIEN SE INCORPORA, CEDE. La regla es clara: el vehículo que entra en la vía debe adaptarse al tráfico que ya circula por ella, acelerando en el carril de aceleración hasta poder insertarse sin obligar a nadie a frenar ni a cambiar de carril.\n\n«EL DE LA DERECHA QUE ENTRA» es el distractor central, y es la regla de la derecha aplicada donde no toca. La incorporación a una vía no es una intersección de vías equivalentes: hay una vía principal y un acceso, y la regla de la derecha no interviene.\n\n«EL QUE VA MÁS RÁPIDO» no es fuente de prioridad en ninguna situación. Velocidad no es derecho.\n\nMATIZ PRÁCTICO. El que ya circula no está obligado a cambiar de carril para facilitar la entrada, aunque hacerlo sea cortés y a menudo lo más seguro. Su obligación es no obstaculizar deliberadamente.\n\nCLAVE: identifica primero qué tipo de confluencia es. Incorporación no es cruce, y por eso la derecha no manda aquí.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":13,"fase":4},{"id":5370,"bg":"При тази ситуация:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41161.png","v":null,"a":[{"t":"червеният автомобил е с предимство, защото се движи по автомагистралата","ok":true,"i":null,"es":"el coche rojo tiene prioridad porque circula por la autopista"},{"t":"синият автомобил, който навлиза на автомагистралата, пропуска червения автомобил","ok":true,"i":null,"es":"el coche azul que entra en la autopista cede el paso al rojo"},{"t":"синия автомобил е с предимство, защото се намира отдясно","ok":false,"i":null,"es":"el azul tiene prioridad porque está a la derecha"},{"t":"червения автомобил е с предимство, защото не променя посоката си на движение","ok":false,"i":null,"es":"el rojo tiene prioridad porque no cambia de dirección"}],"f":8,"es":"En esta situación: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el rojo tiene prioridad (autopista) Y el azul debe cederle el paso. Estar a la derecha no da prioridad al entrar en autopista.","val":8,"fase":4},{"id":5406,"bg":"На автомагистрала, преминаването в платното за насрещното движение е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено на местата, където разделителната ивица между платната за движение е прекъсната","ok":false,"i":null,"es":"permitido donde la mediana está interrumpida"},{"t":"разрешено навсякъде, където е възможно, ако не се пречи на насрещно движещите се ППС","ok":false,"i":null,"es":"permitido donde sea posible sin obstaculizar"}],"f":9,"es":"En autopista, cruzar al carril contrario está:","explain":"Prohibido: en autopista jamás se cruza al carril contrario. Las interrupciones de la mediana existen solo para los servicios de emergencia y mantenimiento, no para los conductores.","val":9,"fase":4},{"id":5407,"bg":"Завиването в обратна посока при движение по автомагистрала е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"забранено във всички случаи","ok":true,"i":null,"es":"prohibido en todos los casos"},{"t":"разрешено само през светлата част от денонощието","ok":false,"i":null,"es":"permitido solo de día"},{"t":"разрешено, но водачът трябва да продължи движението си по лентата за принудително спиране","ok":false,"i":null,"es":"permitido pero continuando por el carril de emergencia"},{"t":"разрешено за напускане на автомагистралата","ok":false,"i":null,"es":"permitido para abandonar la autopista"}],"f":8,"es":"El cambio de sentido en autopista está:","explain":"Prohibido en todos los casos: en autopista jamás se cambia de sentido. Para 'volver' se sale por la siguiente salida y se reentra en sentido contrario. Ni de día, ni por el carril de emergencia, ni para abandonarla.","val":8,"fase":4},{"id":5411,"bg":"При движение по автомобилен път на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да спира за паркиране извън обозначените за това места","ok":true,"i":null,"es":"parar para aparcar fuera de lugares señalizados"},{"t":"да спира за престой извън местата обозначени за паркиране","ok":true,"i":null,"es":"parar en prestoy fuera de lugares señalizados"},{"t":"да спира за отстраняване на неизправност по автомобила","ok":false,"i":null,"es":"parar para eliminar una avería"},{"t":"да се движи с прикачено ремарке","ok":false,"i":null,"es":"circular con remolque"}],"f":8,"es":"Conduciendo por vía rápida al conductor le está PROHIBIDO: (2 correctas)","explain":"En vía rápida está prohibido parar (престой) y aparcar fuera de los lugares señalizados. Parar por avería es la excepción de fuerza mayor, y circular con remolque está permitido: esas dos opciones son las trampas.","val":8,"fase":4},{"id":8274,"bg":"При навлизане на скоростен път, водачът е длъжен да пропусне превозните средства, които се движат по него:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"във всички случаи","ok":true,"i":null,"es":"en todos los casos"},{"t":"само когато е поставен пътен знак за осигуряване на предимство","ok":false,"i":null,"es":"solo cuando hay señal de ceder el paso"},{"t":"само когато те се движат с висока скорост","ok":false,"i":null,"es":"solo cuando van a alta velocidad"}],"f":11,"es":"Al entrar en vía rápida el conductor está obligado a ceder el paso a los que ya circulan:","explain":"En todos los casos: quien se incorpora a la vía rápida cede el paso a quienes ya circulan por ella, haya o no señal. El carril de aceleración sirve para igualar velocidad y buscar hueco, no da prioridad.","val":11,"fase":4},{"id":11349,"bg":"При движение по автомагистрала на водача е забранено да спира в лентата за принудително спиране, освен при:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"повреда на пътното превозно средство","ok":true,"i":null,"es":"avería del vehículo"},{"t":"здравословни проблеми на водача","ok":true,"i":null,"es":"problemas de salud del conductor"},{"t":"здравословни проблеми на пътниците в превозното средство","ok":true,"i":null,"es":"problemas de salud de los pasajeros"},{"t":"необходимост от сън/почивка на водача","ok":false,"i":null,"es":"necesidad de descanso del conductor"}],"f":9,"es":"En autopista ESTÁ PERMITIDO parar en el carril de emergencia por: (3 correctas)","explain":"El carril de emergencia admite parar por avería del vehículo o por problemas de salud del conductor o de los pasajeros: emergencias reales. El simple descanso no es emergencia: para eso están las áreas de servicio.","val":9,"fase":4},{"id":11709,"bg":"Когато няма други ограничения, водачът на състав от ППС от категория ВЕ, при движение по автомагистрала не трябва да превишава:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"100 km/h","ok":true,"i":null,"es":"100 km/h"},{"t":"110 km/h","ok":false,"i":null,"es":"110 km/h"},{"t":"120 km/h","ok":false,"i":null,"es":"120 km/h"},{"t":"130 km/h","ok":false,"i":null,"es":"130 km/h"}],"f":11,"es":"Sin otras restricciones, el conductor de un convoy de categoría BE en autopista puede circular a máximo:","explain":"100 km/h: los conjuntos categoría BE (turismo + remolque) tienen en autopista un límite inferior al de los turismos solos. El remolque alarga la frenada y desestabiliza a alta velocidad.","val":11,"fase":4},{"id":11729,"bg":"При теглене с твърда връзка по скоростен път разрешената максимална скорост за движение е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"70 km/h","ok":true,"i":null,"es":"70 km/h"},{"t":"30 km/h","ok":false,"i":null,"es":"30 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"50 km/h","ok":false,"i":null,"es":"50 km/h"}],"f":12,"es":"Remolcando con barra rígida en vía rápida la velocidad máxima es:","explain":"Remolcando con barra RÍGIDA en vía rápida el máximo es 70 km/h: la barra da control pero el conjunto sigue siendo inestable a alta velocidad. Es uno de los límites especiales de remolcado que hay que memorizar.","val":12,"fase":4},{"id":5563,"bg":"Паркираното превозно средство трябва:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да не пречи на останалите водачи да напуснат мястото си на паркиране","ok":true,"i":null,"es":"no impedir a otros conductores salir de su plaza"},{"t":"да не спира преминаването на другите превозни средства","ok":true,"i":null,"es":"no obstaculizar el paso de otros vehículos"},{"t":"да не остава с включена предавка","ok":false,"i":null,"es":"no dejarse con la marcha puesta"},{"t":"да бъде с изключено радио","ok":false,"i":null,"es":"estar con la radio apagada"}],"f":5,"es":"El vehículo aparcado debe: (2 correctas)","explain":"El vehículo aparcado no debe impedir a otros salir de su plaza ni obstaculizar el paso: sus dos obligaciones hacia los demás. La marcha puesta o la radio no son objeto de esta norma (la marcha puesta en pendiente es incluso recomendable).","val":3,"fase":4},{"id":5580,"bg":"От коя страна на еднопосочен път в населено място е разрешено паркирането?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от дясната страна","ok":true,"i":null,"es":"por el lado derecho"},{"t":"от лявата страна","ok":false,"i":null,"es":"por el lado izquierdo"},{"t":"от двете страни","ok":false,"i":null,"es":"por los dos lados"}],"f":8,"es":"¿Por qué lado de una calle de sentido único en zona urbana está permitido aparcar?","explain":"APARCAR en calle de sentido único: solo por el lado DERECHO. La tolerancia del lado izquierdo existe para la parada breve, no para el estacionamiento: esa es la diferencia con la pregunta gemela.","val":4,"fase":4},{"id":5611,"bg":"Забранено е спирането за престой пред пешеходна пътека на разстояние по-малко от:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"5 м","ok":true,"i":null,"es":"5 m"},{"t":"10 м","ok":false,"i":null,"es":"10 m"},{"t":"15 м","ok":false,"i":null,"es":"15 m"},{"t":"20 м","ok":false,"i":null,"es":"20 m"}],"f":7,"es":"La parada breve (prestoy) está prohibida ante un paso de peatones a una distancia menor de:","explain":"5 m antes del paso de peatones: es la distancia mínima. Más cerca, tu vehículo tapa al peatón que va a entrar en la calzada y te tapa a ti la vista del peatón.","val":3,"fase":4},{"id":5642,"bg":"Паркирането е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на платното за движение, където разстоянието между ППС и пътната маркировка, забранена за пресичане, е по-малко от 3 метра","ok":true,"i":null,"es":"en calzada donde la distancia al marcaje que prohíbe el adelantamiento sería menos de 3m"},{"t":"на платното за движение, където с пътен знак е забранено изпреварването","ok":true,"i":null,"es":"en calzada donde hay señal que prohíbe el adelantamiento"},{"t":"върху пътна лента, предназначена за движение на бавнодвижещи се ППС, обозначена с пътен знак","ok":true,"i":null,"es":"sobre carril destinado a vehículos lentos señalizado"},{"t":"на участък от пътя с интензивно движение","ok":false,"i":null,"es":"en tramo de intenso tráfico"}],"f":6,"es":"El aparcamiento está PROHIBIDO: (3 correctas)","explain":"Prohibido aparcar: a menos de 3 m de una marca infranqueable (obligarías a pisarla), donde una señal prohíbe adelantar (forzarías un adelantamiento ilegal) y sobre el carril de vehículos lentos. El 'tráfico intenso' no es causa legal.","val":3,"fase":4},{"id":5648,"bg":"Престоят върху платното за движение е забранен, ако разстоянието между ППС и пътната маркировка, забранена за пресичане, е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"1 м","ok":true,"i":null,"es":"1 m"},{"t":"2 м","ok":true,"i":null,"es":"2 m"},{"t":"2.5 м","ok":true,"i":null,"es":"2.5 m"},{"t":"3.5 м","ok":false,"i":null,"es":"3.5 m"}],"f":11,"es":"La parada breve (prestoy) en la calzada está prohibida si la distancia entre el vehículo y el marcaje deja: (3 correctas)","explain":"Prohibida la parada breve si entre el vehículo y la marca infranqueable quedan menos de 3 m: obligarías a los demás a pisar la línea. 1 m, 2 m y 2,5 m incumplen; 3,5 m cumple.","val":5,"fase":4},{"id":5705,"bg":"При намалена видимост под 50 м е забранено:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"тегленето","ok":true,"i":null,"es":"remolcar"},{"t":"завиването в обратна посока","ok":true,"i":null,"es":"dar la vuelta"},{"t":"спирането за престой","ok":false,"i":null,"es":"parar en prestoy"},{"t":"движението назад","ok":false,"i":null,"es":"ir marcha atrás"}],"f":6,"es":"Con visibilidad inferior a 50 m está PROHIBIDO: (2 correctas)","explain":"Con visibilidad bajo 50 m está prohibido remolcar y dar la vuelta: dos maniobras lentas que ocupan la vía cuando nadie te ve llegar. La parada breve y la marcha atrás no entran en esta prohibición específica.","val":3,"fase":4},{"id":5729,"bg":"Как влияе върху управляемостта на превозното средство пониженото налягане на въздуха в гумите?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"влошава управляемостта","ok":true,"i":null,"es":"empeora la manejabilidad"},{"t":"подобрява управляемостта","ok":false,"i":null,"es":"mejora la manejabilidad"},{"t":"не влияе на управляемостта","ok":false,"i":null,"es":"no afecta a la manejabilidad"}],"f":10,"es":"¿Cómo afecta la presión baja de los neumáticos a la manejabilidad del vehículo?","explain":"Empeora la manejabilidad: con poca presión el neumático flexa, la dirección responde tarde y de forma imprecisa, y el vehículo 'flota' en curva. Nunca la mejora ni resulta indiferente.","val":5,"fase":4},{"id":5908,"bg":"Значението на кой от показаните немигащи сигнали на светофара е “Преминаването е разрешено”?","p":3,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":false,"es":"","i":"42530"},{"t":"","ok":true,"es":"","i":"42529"},{"t":"","ok":false,"es":"","i":"42532"},{"t":"","ok":false,"es":"","i":"42531"}],"f":10,"es":"¿Cuál de las señales NO PARPADEANTES del semáforo significa 'El paso está PERMITIDO'?","explain":"El semáforo con la luz VERDE encendida — la segunda imagen, con la roja y la ámbar apagadas.\n\nVERDE FIJO ES LA ÚNICA SEÑAL QUE AUTORIZA A PASAR. Autoriza el movimiento, no la prioridad: sigues obligado a ceder a quien ya está dentro del cruce y a los peatones que cruzan por donde tienen permiso.\n\nROJO + ÁMBAR (primera imagen) es el cebo principal. Muchos lo leen como «ya casi, arranca». No: mientras el rojo siga encendido el paso está prohibido. Solo avisa de que el verde viene.\n\nÁMBAR SOLO (tercera) significa «¡Atención, para!». Prohíbe entrar en el cruce.\n\nROJO SOLO (cuarta) es la prohibición pura.\n\nCLAVE: solo hay un color que permite, y es el verde solo. Cualquier combinación que contenga rojo sigue prohibiendo.","val":14,"fase":3},{"id":5452,"bg":"По какво се различават зимните от летните гуми?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"по налягането на въздуха","ok":false,"i":null,"es":"en la presión del aire"},{"t":"по материала, от който е изработен протекторът","ok":true,"i":null,"es":"en el material del dibujo del neumático"},{"t":"по шарките на протектора","ok":true,"i":null,"es":"en el dibujo del neumático"},{"t":"по цвета","ok":false,"i":null,"es":"en el color"}],"f":4,"es":"¿En qué se diferencian los neumáticos de invierno de los de verano? (2 correctas)","explain":"Los neumáticos de invierno se diferencian en el MATERIAL (goma que sigue blanda en frío) y en el DIBUJO (laminillas para nieve). La presión de uso es la misma y el color, obviamente, también.","val":2,"fase":4},{"id":5404,"bg":"С този опознавателен знак се обозначават:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334672.png","v":null,"a":[{"t":"ремаркетата","ok":true,"i":null,"es":"los remolques"},{"t":"полуремаркетата","ok":true,"i":null,"es":"los semirremolques"},{"t":"товарните автомобили над 3,5 тона","ok":false,"i":null,"es":"los camiones de más de 3.5 t"},{"t":"товарните автомобили над 7,5 тона","ok":false,"i":null,"es":"los camiones de más de 7.5 t"}],"f":6,"es":"Con esta señal de identificación se marcan: (2 correctas)","explain":"Dos: los REMOLQUES y los SEMIRREMOLQUES.\n\nQUÉ VES. La parte trasera de un vehículo con la placa reflectante alargada, amarilla con borde rojo. Es un «опознавателен знак», un signo distintivo, no una señal de tráfico.\n\nA QUIÉN IDENTIFICA. A remolques y semirremolques, los dos. La diferencia entre ellos es técnica — el semirremolque apoya parte de su peso sobre la cabeza tractora, el remolque no — pero para el distintivo da igual: los dos lo llevan.\n\n«CAMIONES DE MÁS DE 3,5 t» y «CAMIONES DE MÁS DE 7,5 t» son los distractores, y otra vez traen un umbral de otra norma. Esas cifras existen en el código, pero pertenecen a las categorías del permiso y a los límites de velocidad, no a este distintivo.\n\nPOR QUÉ IMPORTA VERLA DE NOCHE. Esa placa te dice que lo que tienes delante es un conjunto largo, lento y con un ángulo muerto enorme. Adelantar a un conjunto exige mucho más espacio que adelantar a un camión rígido.\n\nCLAVE: es la hermana de la 11820. Allí la pregunta era «¿todos los remolques?» y aquí «¿remolques y semirremolques?». Misma respuesta de fondo: el distintivo no depende de masa, ejes ni tipo.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información o indicación. Rombo amarillo = prioridad. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo».","val":6,"fase":4},{"id":6031,"bg":"При тази ситуация трябва:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/26547.png","v":null,"a":[{"t":"да намаля скоростта","ok":true,"i":null,"es":"reducir la velocidad"},{"t":"да управлявам с готовност за спиране","ok":true,"i":null,"es":"circular listo para frenar"},{"t":"да подам сигнал за маневра и да заобиколя пешеходеца","ok":false,"i":null,"es":"señalizar y rodear al peatón"},{"t":"да подам звуков сигнал и да продължа движението","ok":false,"i":null,"es":"tocar el claxon y continuar"}],"f":6,"es":"En esta situación debes: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: ante peatón en la vía debes reducir velocidad Y circular listo para frenar. Rodearlo con señal o tocar el claxon no son soluciones adecuadas — el peatón tiene prioridad.","val":6,"fase":4},{"id":5932,"bg":"Значението на този светлинен сигнал е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44686.png","v":null,"a":[{"t":"„Навлизането е забранено” по пътната лента, над която е поставен","ok":true,"i":null,"es":"'Entrada PROHIBIDA' en el carril sobre el que está"},{"t":"„Следва кръстовище на равнозначни пътища”","ok":false,"i":null,"es":"'Sigue intersección de vías equivalentes'"},{"t":"„Навлизането е разрешено” по пътната лента, над която е поставен","ok":false,"i":null,"es":"'Entrada PERMITIDA' en el carril sobre el que está"},{"t":"„Място за задължително спиране”","ok":false,"i":null,"es":"'Lugar de parada obligatoria'"}],"f":9,"es":"El significado de esta señal luminosa es:","explain":"'Entrada PROHIBIDA' en el carril sobre el que está. La X roja de un semáforo de carril cierra ese carril concreto, no toda la calzada: los demás siguen abiertos y hay que salir de este antes de llegar. Las otras opciones describen señales distintas — un cruce de vías iguales o una parada obligatoria — que nada tienen que ver con la señalización por carriles.","val":14,"fase":3},{"id":6070,"bg":"При тази ситуация трябва да се движа:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59902.png","v":null,"a":[{"t":"в дясната пътна лента","ok":true,"i":null,"es":"en el carril derecho"},{"t":"в по-удобната за мен пътна лента","ok":false,"i":null,"es":"en el carril más cómodo"},{"t":"в лявата пътна лента","ok":false,"i":null,"es":"en el carril izquierdo"}],"f":7,"es":"En esta situación debo circular:","explain":"En el carril DERECHO — la situación mostrada (vía normal, sin condiciones especiales para usar otros carriles) obliga a ir por el derecho.","val":10,"fase":3},{"id":6090,"bg":"При тази ситуация навлизанетo в лентите за насрещното движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62058.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено без ограничения","ok":false,"i":null,"es":"permitido sin restricciones"},{"t":"разрешено, но само при изпреварване","ok":false,"i":null,"es":"permitido solo para adelantar"},{"t":"разрешено, когато са свободни","ok":false,"i":null,"es":"permitido cuando están libres"}],"f":9,"es":"En esta situación entrar en los carriles del sentido contrario está:","explain":"PROHIBIDO.\n\nQUÉ VES. Una vía con DOS carriles en cada sentido: a tu derecha hay otro carril separado por línea discontinua, y las dos direcciones están separadas por una línea continua. Los coches que ves de frente circulan por el otro lado.\n\nLA REGLA. Cuando la calzada tiene dos o más carriles en tu sentido, está prohibido invadir los carriles del sentido contrario. Sin excepciones: ni para adelantar, ni aunque estén libres.\n\nPOR QUÉ ES ABSOLUTA. Porque ya tienes un carril propio para adelantar. La invasión del sentido contrario solo se tolera cuando no hay alternativa — y aquí la hay, a tu izquierda o a tu derecha.\n\n«PERMITIDO SOLO PARA ADELANTAR» es el distractor principal, y es la respuesta correcta de OTRA pregunta: la de carretera con un solo carril por sentido. Dos escenas casi idénticas, respuestas opuestas.\n\n«PERMITIDO CUANDO ESTÉN LIBRES» y «SIN RESTRICCIONES» son falsos por lo mismo.\n\nCLAVE: cuenta los carriles de TU sentido antes de responder. Uno → puedes invadir para adelantar o rodear. Dos o más → nunca.\n\nMÉTODO DE CARRILES: 1) ¿cuántos carriles tiene MI sentido? Con dos o más nunca se invade el contrario. 2) ¿la línea es continua o discontinua? 3) ¿hay señal Д1 que declare los carriles? 4) ¿el carril está reservado (BUS, lentos)? Desarrollado en Leyes → «Carriles y líneas: quién puede ir por dónde».","val":14,"fase":3},{"id":6091,"bg":"На двупосочен път с четири пътни ленти навлизанетo в лента за насрещното движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62094.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено без ограничения","ok":false,"i":null,"es":"permitido sin restricciones"},{"t":"разрешено при изпреварване","ok":false,"i":null,"es":"permitido para adelantar"},{"t":"разрешено при заобикаляне","ok":false,"i":null,"es":"permitido para rodear obstáculos"}],"f":8,"es":"En vía de doble sentido con cuatro carriles, entrar en el carril contrario está:","explain":"PROHIBIDO.\n\nCUANDO LA CALZADA TIENE CUATRO CARRILES O MÁS con doble sentido, está prohibido invadir los carriles del sentido contrario en cualquier circunstancia. No hay excepciones.\n\n'PERMITIDO PARA ADELANTAR' es el distractor principal y el que más gente marca. Con cuatro carriles no hace falta cruzarse: adelantas por el carril izquierdo de TU propio sentido.\n\n'PERMITIDO PARA RODEAR OBSTÁCULOS' cae por lo mismo. Y 'sin restricciones' se descarta solo.\n\nCLAVE: cuenta los carriles antes de pensar en cruzarte. Con cuatro o más, el sentido contrario deja de ser una opción incluso para maniobras que en otras vías sí estarían permitidas.","val":12,"fase":3},{"id":6468,"bg":"Когато има обозначена с пътен знак пътна лента за бавнодвижещи се ППС, водачите на такива ППС:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"са длъжни да използват за движение тази лента","ok":true,"i":null,"es":"están obligados a usar ese carril"},{"t":"използват тази лента само когато тя е свободна","ok":false,"i":null,"es":"lo usan solo cuando está libre"},{"t":"не са задължени да я използват","ok":false,"i":null,"es":"no están obligados a usarlo"}],"f":5,"es":"Cuando hay un carril señalizado para vehículos lentos, los conductores de esos vehículos:","explain":"Obligados: si existe carril señalizado para vehículos lentos, deben usarlo. No es opcional ni condicionado a que esté libre: su función es precisamente sacar al lento del flujo rápido.","val":8,"fase":4},{"id":9835,"bg":"Разрешено ли е да навлезете и да се движите по BUS-лентата?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043012.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":13,"es":"¿Está permitido entrar y circular por el carril BUS?","explain":"NO.\n\nQUÉ VES. Desde el coche, el carril de la derecha delimitado por una línea AMARILLA y con la palabra BUS pintada en el asfalto. Llevas el intermitente derecho puesto para meterte.\n\nQUÉ ES LA LÍNEA AMARILLA. Delimita un carril reservado. No es una línea de carril normal: marca que ese espacio pertenece a otros vehículos y que cruzarla para circular por él está prohibido.\n\nQUIÉN PUEDE IR POR EL CARRIL BUS. Los vehículos de las líneas regulares de transporte público de pasajeros. Ni todos los autobuses, ni los taxis, ni tú porque el carril esté vacío y tu carril atascado.\n\nPOR QUÉ EXISTE LA REGLA. El carril BUS solo cumple su función si está libre: en cuanto se llena de coches, el autobús pierde su ventaja y el sistema deja de tener sentido. Por eso la prohibición es rígida y no admite el argumento de «estaba vacío».\n\nCLAVE: amarillo en el suelo = no es tuyo. La única excepción práctica es cruzarlo perpendicularmente para entrar o salir de la vía o de un aparcamiento, no para circular por él.\n\nMÉTODO DE CARRILES: 1) ¿cuántos carriles tiene MI sentido? Con dos o más nunca se invade el contrario. 2) ¿la línea es continua o discontinua? 3) ¿hay señal Д1 que declare los carriles? 4) ¿el carril está reservado (BUS, lentos)? Desarrollado en Leyes → «Carriles y líneas: quién puede ir por dónde».","val":19,"fase":3},{"id":9840,"bg":"При тази ситуация навлизането в BUS-лентата е разрешено за:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043260.png","v":null,"a":[{"t":"превозни средства от редовните линии за обществен превоз на пътници","ok":true,"i":null,"es":"vehículos de líneas regulares de transporte público"},{"t":"спиране за престой за всички автобуси","ok":false,"i":null,"es":"parada breve para todos los autobuses"},{"t":"придвижване на повредено МПС","ok":false,"i":null,"es":"traslado de vehículos averiados"},{"t":"движение на бавнодвижещи се МПС","ok":false,"i":null,"es":"vehículos lentos"}],"f":10,"es":"En esta situación entrar en el carril BUS está permitido para:","explain":"Para los vehículos de las LÍNEAS REGULARES de transporte público de pasajeros.\n\nLA FÓRMULA EXACTA IMPORTA. «Превозни средства от редовните линии за обществен превоз на пътници». No dice «autobuses»: dice vehículos de línea regular. Un autobús de excursión privado no entra; un trolebús de línea sí.\n\n«PARADA BREVE PARA TODOS LOS AUTOBUSES» es falso por dos motivos: ni todos los autobuses tienen derecho al carril, ni el carril BUS es un sitio para hacer paradas ajenas al servicio.\n\n«TRASLADO DE VEHÍCULOS AVERIADOS» es falso. Un vehículo averiado se retira por el arcén o con grúa; el carril BUS no es una vía de servicio.\n\n«VEHÍCULOS LENTOS» es falso y confunde dos carriles reservados distintos: el BUS y el carril para vehículos lentos, que tiene su propia señal y sus propias reglas.\n\nCLAVE: aprende la fórmula literal «редовните линии за обществен превоз на пътници». Los cuatro distractores de esta familia son siempre categorías que suenan razonables — taxis, autobuses en general, emergencias — y ninguna está en la ley.\n\nMÉTODO DE CARRILES: 1) ¿cuántos carriles tiene MI sentido? Con dos o más nunca se invade el contrario. 2) ¿la línea es continua o discontinua? 3) ¿hay señal Д1 que declare los carriles? 4) ¿el carril está reservado (BUS, lentos)? Desarrollado en Leyes → «Carriles y líneas: quién puede ir por dónde».","val":15,"fase":3},{"id":11688,"bg":"При тази ситуация, движението по обозначената с пътен знак лента за бавнодвижещи се ППС е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123801988.png","v":null,"a":[{"t":"разрешено за автомобили обозначени с опознавателен знак „бавнодвижещи се ППС”","ok":true,"i":null,"es":"permitido para vehículos marcados con señal de vehículo lento"},{"t":"разрешено за автомобили, които не могат да се движат със скорост по-висока от 30 km/h","ok":true,"i":null,"es":"permitido para vehículos que no pueden superar 30 km/h"},{"t":"забранено за велосипеди","ok":false,"i":null,"es":"prohibido para bicicletas"},{"t":"забранено за мотопеди","ok":false,"i":null,"es":"prohibido para ciclomotores"}],"f":6,"es":"En esta situación, circular por el carril señalizado para vehículos lentos está: (2 correctas)","explain":"Dos casos: permitido para los vehículos con el distintivo de vehículo lento, y para los que no pueden superar los 30 km/h.\n\nLA SEÑAL. El panel azul que dibuja el carril adicional, con el círculo azul de «40» — velocidad mínima obligatoria, no máxima. Marca el «лента за бавнодвижещи се ППС», carril para vehículos lentos.\n\nQUIÉN PUEDE USARLO. La ley define al lento de dos maneras y las dos son respuesta: llevar el distintivo «бавнодвижещо се ППС», o no poder superar los 30 km/h por construcción.\n\n«PROHIBIDO PARA BICICLETAS» es falso, y es el distractor con más gancho: una bicicleta es el vehículo lento por excelencia. No hay ninguna prohibición para ella.\n\n«PROHIBIDO PARA CICLOMOTORES» es falso por lo mismo. Un ciclomotor limitado a 45 km/h no está excluido de un carril pensado precisamente para los que no siguen el ritmo.\n\nEL CÍRCULO AZUL CON «40» vuelve a ser la trampa de color: azul obliga, rojo prohíbe. Aquí impone una velocidad mínima, no un tope.\n\nCLAVE: el carril de lentos se define por VELOCIDAD y DISTINTIVO, nunca por categoría de vehículo. Es la misma doctrina de la 11687.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Rombo amarillo = prioridad. Rectángulo = información. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo».","val":9,"fase":3},{"id":11871,"bg":"На кои от изброените пътни превозни средства е разрешено движението по пътния банкет?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"велосипеди","ok":true,"i":null,"es":"bicicletas"},{"t":"мотоциклети","ok":false,"i":null,"es":"motocicletas"},{"t":"автомобили с допустима максимална маса до 1,5 t","ok":false,"i":null,"es":"automóviles hasta 1.5 t"}],"f":4,"es":"¿A qué vehículos está permitido circular por el arcén? (2 correctas)","explain":"Por el arcén pueden circular ciclomotores y bicicletas (los lentos de dos ruedas, cuando el arcén derecho es apto). Las motocicletas y los coches circulan por la calzada: el arcén no es su sitio.","val":6,"fase":4},{"id":5817,"bg":"При тази ситуация разрешено ли е движение със скорост, по-висока от означената?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/103539.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":3,"es":"En esta situación ¿está permitido circular a velocidad superior a la indicada?","explain":"SÍ — cuando hay una señal de velocidad mínima y las condiciones de la vía lo permiten, puedes superar esa velocidad mínima. La señal es un mínimo, no un máximo.","val":4,"fase":4},{"id":11697,"bg":"Когато няма други ограничения, водачът на автомобил от категория В при движение извън населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"90 km/h","ok":true,"i":null,"es":"90 km/h"},{"t":"80 km/h","ok":false,"i":null,"es":"80 km/h"},{"t":"100 km/h","ok":false,"i":null,"es":"100 km/h"},{"t":"70 km/h","ok":false,"i":null,"es":"70 km/h"}],"f":5,"es":"Sin otras restricciones, el conductor de categoría B fuera de población puede circular a máximo:","explain":"90 km/h: límite general de los turismos categoría B fuera de población en vía convencional. Las cifras mayores requieren vía rápida (120) o autopista (140).","val":7,"fase":4},{"id":12030,"bg":"Какво трябва да очаквате в тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":16,"a":[{"t":"синият автомобил да навлезе в моята лента","ok":false,"i":null,"es":"que el coche azul invada mi carril"},{"t":"мотоциклетистът да намали скоростта си","ok":true,"i":null,"es":"que el motorista reduzca velocidad"},{"t":"тракторът да навлезе на пътя пред мен","ok":true,"i":null,"es":"que el tractor entre en la vía delante de mí"}],"f":8,"es":"¿Qué debe esperar en esta situación? (VIDEO) ⚠️ 2 correctas","explain":"Carretera rural: un tractor está a punto de ENTRAR en la vía desde el acceso del campo, delante del motorista que me precede — debo esperar ambas cosas: que el TRACTOR invada la vía delante de mí y que el MOTORISTA reduzca su velocidad al encontrárselo. La opción del coche azul invadiendo mi carril es el distractor: sigue por su trayectoria. Anticipa la cadena: obstáculo → frenada del de delante → tu frenada.","val":12,"fase":3},{"id":6223,"bg":"При тази ситуация, водачът на червения автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69503.png","v":null,"a":[{"t":"трябва да пропусне синия автомобил","ok":true,"i":null,"es":"debe dejar pasar al coche azul"},{"t":"е с предимство защото се намира отдясно","ok":false,"i":null,"es":"tiene prioridad porque está a la derecha"},{"t":"е с предимство защото е подал сигнал за маневра","ok":false,"i":null,"es":"tiene prioridad porque señalizó la maniobra"}],"f":8,"es":"En esta situación el conductor del coche rojo:","explain":"DEBE DEJAR PASAR AL COCHE AZUL.\n\nEL ROJO NO VIENE DE OTRA VÍA: sale de una zona adyacente a la calzada. Quien se incorpora a la circulación desde una propiedad, un aparcamiento o un camino de tierra cede el paso a todos los que ya circulan por la vía, vehículos y peatones incluidos.\n\n'TIENE PRIORIDAD PORQUE ESTÁ A LA DERECHA' es falso, y es el error más caro de esta pregunta. La regla de la derecha se aplica entre vías que se cruzan, no cuando alguien entra desde fuera de la calzada. Ahí no hay cruce que repartir.\n\n'PORQUE SEÑALIZÓ LA MANIOBRA' también es falso. El intermitente avisa de lo que vas a hacer, no te da derecho a hacerlo.\n\nCLAVE: antes de aplicar la regla de la derecha, comprueba que los dos vienen de vías de verdad. Si uno sale de un patio o un arcén, esa regla ni se toca.","val":11,"fase":3},{"id":6233,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69669.png","v":null,"a":[{"t":"водачът на синия автомобил","ok":true,"i":null,"es":"el conductor del coche azul"},{"t":"водачът на червения автомобил","ok":false,"i":null,"es":"el conductor del coche rojo"}],"f":7,"es":"En esta situación tiene prioridad:","explain":"El conductor del coche AZUL.\n\nQUÉ VES. Dos coches en carriles contiguos, señalización de carriles a ambos lados, y el azul con el intermitente puesto. Las trayectorias convergen.\n\nEL AZUL ESTÁ A LA DERECHA DEL ROJO. No es un cruce de calles, pero el principio es el mismo: cuando dos trayectorias se cruzan y nada las separa, cede quien tiene al otro a su derecha.\n\nQUE EL AZUL SEA EL QUE MANIOBRA NO LE QUITA EL DERECHO, y esto es lo que descoloca. Uno tiende a pensar que quien se mueve de su sitio es quien debe ceder. La ley no lo plantea así: mira la posición relativa, no quién tuvo la iniciativa.\n\nES LA GEMELA DE LA 6234, que pregunta lo mismo en abstracto — «tiene prioridad el que está a la derecha» — mientras que esta te obliga a identificarlo en la imagen. Estúdialas juntas.\n\nCLAVE: el intermitente no cambia la prioridad, ni a favor ni en contra. Solo obliga a los demás a saber qué vas a hacer.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":10,"fase":3},{"id":6254,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69917.png","v":null,"a":[{"t":"трябва да пропусна пешеходеца","ok":true,"i":null,"es":"debo dejar pasar al peatón"},{"t":"не съм задължен да пропусна пешеходеца, защото завивам надясно","ok":false,"i":null,"es":"no estoy obligado a ceder al peatón porque giro a la derecha"},{"t":"не съм задължен да пропусна пешеходеца, защото той не е достигнал средата на платното за движение","ok":false,"i":null,"es":"no estoy obligado porque el peatón no ha llegado al centro de la calzada"}],"f":5,"es":"En esta situación:","explain":"⚠️ TRAMPA IMPORTANTE: SIEMPRE debes ceder al peatón en el paso, incluso si giras a la derecha y aunque el peatón no haya llegado al centro. El peatón en el paso tiene prioridad absoluta.","val":8,"fase":4},{"id":6273,"bg":"Как ще постъпите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/84437.png","v":null,"a":[{"t":"пропускам червения автомобил","ok":true,"i":null,"es":"cedo el paso al coche rojo"},{"t":"преминавам преди червения автомобил","ok":false,"i":null,"es":"paso antes que el coche rojo"}],"f":6,"es":"¿Cómo actuarás en esta situación?","explain":"Cedes al rojo — según la imagen el rojo tiene prioridad sobre ti (vía preferente o regla de la derecha).","val":9,"fase":4},{"id":6286,"bg":"При тази ситуация съм с предимство пред червения автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70448.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":8,"es":"En esta situación tengo prioridad sobre el coche rojo. Esto es:","explain":"INCORRECTO, no tengo prioridad sobre el rojo.\n\nSÍ VOY POR LA VÍA CON PRIORIDAD: el rombo amarillo lo confirma. Y la señal azul me autoriza a seguir recto o a girar a la izquierda, así que la maniobra en sí está permitida.\n\nPERO VOY A GIRAR A LA IZQUIERDA, y quien gira a la izquierda debe ceder el paso a los vehículos que circulan en sentido contrario. El rojo viene de frente por esa misma vía prioritaria.\n\nIR POR LA VÍA CON PRIORIDAD NO TE LIBRA DE ESA OBLIGACIÓN. El rombo te da preferencia sobre quienes salen de las vías secundarias, no sobre quien viene de frente por la tuya.\n\nCLAVE: prioridad y giro a la izquierda son cosas distintas. Puedes tener toda la preferencia del mundo frente a las secundarias y aun así tener que esperar al de enfrente.","val":12,"fase":3},{"id":6290,"bg":"При тази ситуация червеният автомобил е с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70482.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":8,"es":"En esta situación el coche rojo tiene prioridad. Esto es:","explain":"INCORRECTO, el rojo no tiene prioridad.\n\nTENGO VERDE. Hay un STOP en ese poste, pero el semáforo en funcionamiento deja sin efecto las señales de prioridad, así que el STOP no cuenta ahora.\n\nEL ROJO LLEVA EL INTERMITENTE IZQUIERDO: va a girar a la izquierda. Y quien gira a la izquierda cede el paso a los que vienen en sentido contrario. Yo vengo de frente, así que es él quien me cede a mí.\n\nYO GIRO A LA DERECHA, maniobra que no cruza su trayectoria. Ni siquiera nos estorbamos.\n\nCLAVE: mira siempre el intermitente del otro antes de concederle prioridad. El que gira a la izquierda casi nunca la tiene: es el que más cede de todo el reglamento.","val":12,"fase":3},{"id":6373,"bg":"Завиването в обратна посока е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на пешеходна пътека","ok":true,"i":null,"es":"en paso de peatones"},{"t":"при ограничена видимост","ok":true,"i":null,"es":"con visibilidad limitada"},{"t":"на участък от пътя в ремонт","ok":false,"i":null,"es":"en tramo de vía en obras"},{"t":"на 160 м преди жп прелез","ok":false,"i":null,"es":"a 160 m antes del paso a nivel"}],"f":10,"es":"El cambio de sentido está PROHIBIDO: (2 correctas)","explain":"Prohibido cambiar de sentido sobre paso de peatones y con visibilidad limitada. Las obras no lo prohíben por sí mismas, y la prohibición cerca del paso a nivel es EN el propio paso, no a 160 m (esa cifra es de las señales de aviso).","val":14,"fase":3},{"id":6384,"bg":"При тази ситуация задължен да пропусне насрещно движещото се превозно средство е водачът на:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71342.png","v":null,"a":[{"t":"червения автомобил","ok":true,"i":null,"es":"coche rojo"},{"t":"синия автомобил","ok":false,"i":null,"es":"coche azul"}],"f":6,"es":"En esta situación está obligado a ceder al vehículo que viene de frente el conductor del:","explain":"El rojo cede — viene por el lado donde hay menos espacio o tiene el paso bloqueado por la situación mostrada.","val":9,"fase":4},{"id":6387,"bg":"Как трябва да постъпите при тази ситуация, след като червеният автомобил е навлязъл в стеснения участък?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71408.png","v":null,"a":[{"t":"длъжен съм да пропусна червения автомобил","ok":true,"i":null,"es":"estoy obligado a ceder al rojo"},{"t":"трябва да продължа движението си, защото съм с предимство","ok":false,"i":null,"es":"debo continuar porque tengo prioridad"},{"t":"трябва да подам сигнал към червения автомобил за да ми осигури предимство","ok":false,"i":null,"es":"debo señalizarle que me deje pasar"}],"f":6,"es":"¿Cómo debes actuar cuando el coche rojo ya ha entrado en el tramo estrecho?","explain":"Cedes al rojo — aunque tengas prioridad en teoría, el rojo ya está dentro del tramo estrecho. La prioridad de paso no justifica crear un accidente.","val":9,"fase":3},{"id":6395,"bg":"Този пътен знак забранява изпреварването:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67557.png","v":null,"a":[{"t":"на МПС, с изключение на мотоциклети без кош и мотопеди","ok":true,"i":null,"es":"de vehículos a motor excepto motos sin sidecar y ciclomotores"},{"t":"на всички ППС","ok":false,"i":null,"es":"de todos los vehículos"},{"t":"само на леки автомобили","ok":false,"i":null,"es":"solo de turismos"}],"f":6,"es":"Esta señal prohíbe el adelantamiento:","explain":"Prohíbe adelantar vehículos a motor EXCEPTO motos sin sidecar y ciclomotores. Estos últimos están exentos — pueden seguir adelantando.","val":9,"fase":3},{"id":6397,"bg":"Кое от изброените ППС е разрешено да изпреварвате след този пътен знак?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67607.png","v":null,"a":[{"t":"велосипед","ok":true,"i":null,"es":"bicicleta"},{"t":"каруца","ok":true,"i":null,"es":"carruaje (carro de caballos)"},{"t":"трактор","ok":false,"i":null,"es":"tractor"},{"t":"товарен автомобил","ok":false,"i":null,"es":"camión"}],"f":8,"es":"¿Qué vehículo está PERMITIDO adelantar después de esta señal? (2 correctas)","explain":"MULTIRESPUESTA: la BICICLETA y el CARRUAJE.\n\nLA SEÑAL PROHÍBE ADELANTAR VEHÍCULOS A MOTOR. Esa es la clave entera de la pregunta, y está en la palabra 'motor'.\n\nLA BICICLETA Y EL CARRO DE CABALLOS no son vehículos a motor, así que la prohibición ni les afecta: puedes adelantarlos con normalidad.\n\nEL TRACTOR Y EL CAMIÓN sí lo son, aunque vayan despacio. Que un vehículo sea lento no lo saca de la prohibición, y ese es el razonamiento equivocado que buscan.\n\nHAY UNA TERCERA EXCEPCIÓN que conviene añadir: también puedes adelantar motocicletas de dos ruedas sin sidecar.\n\nCLAVE: bajo esta señal puedes adelantar bicis, carros y motos de dos ruedas. Todo lo demás con motor, no.","val":12,"fase":3},{"id":6411,"bg":"Изпреварването е забранено, когато:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"при използване на пътна лента за насрещното движение не е възможно безпрепятственото връщане в напуснатата лента","ok":true,"i":null,"es":"usando el carril contrario no es posible volver sin obstaculizar"},{"t":"видимостта е ограничена","ok":true,"i":null,"es":"la visibilidad es limitada"},{"t":"изпреварващият автомобил е с повредени пътепоказатели","ok":false,"i":null,"es":"el adelantante tiene los intermitentes averiados"},{"t":"се извършва по двулентов двупосочен път","ok":false,"i":null,"es":"se realiza en vía de dos carriles de doble sentido"}],"f":5,"es":"El adelantamiento está PROHIBIDO cuando: (2 correctas)","explain":"Prohibido adelantar cuando, usando el carril contrario, no podrías reincorporarte sin obstaculizar, y cuando la visibilidad es limitada. Los intermitentes averiados no prohíben la maniobra (se señaliza con la mano) y la vía de dos carriles de doble sentido es el escenario NORMAL del adelantamiento.","val":8,"fase":4},{"id":6415,"bg":"Изпреварването на МПС, с изключение на мотопеди и мотоциклети без кош, е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на кръстовище на равнозначни пътища","ok":true,"i":null,"es":"en intersección de vías equivalentes"},{"t":"на железопътен прелез без бариери","ok":true,"i":null,"es":"en paso a nivel sin barreras"},{"t":"при използване на пътна лента за насрещно движение, когато изпреварващият не може да се върне безпрепятствено в напуснатата пътна лента","ok":true,"i":null,"es":"usando el carril contrario cuando no puedes reincorporarte sin peligro"},{"t":"в тунел","ok":false,"i":null,"es":"en túnel"}],"f":5,"es":"El adelantamiento está PROHIBIDO: (3 correctas)","explain":"Prohibido adelantar en intersecciones de vías equivalentes, en pasos a nivel SIN barreras y cuando no puedes reincorporarte sin peligro. En TÚNEL el adelantamiento no está prohibido con carácter general (lo prohibido allí es marcha atrás y cambio de sentido): esa es la trampa.","val":7,"fase":4},{"id":6436,"bg":"Разрешено ли е изпреварването при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128556.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":6,"es":"¿Está permitido adelantar en esta situación?","explain":"SÍ — la situación mostrada permite el adelantamiento: línea discontinua, visibilidad suficiente, sin señal prohibitiva.","val":9,"fase":4},{"id":6450,"bg":"Какво трябва да направи водачът на МПС когато видимостта при движение назад е ограничена?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да осигури човек, който да сигнализира за опасност","ok":true,"i":null,"es":"asegurar una persona que señalice el peligro"},{"t":"да отвори вратата и да гледа назад","ok":false,"i":null,"es":"abrir la puerta y mirar hacia atrás"},{"t":"да отвори страничното стъкло за да гледа назад","ok":false,"i":null,"es":"abrir la ventanilla lateral y mirar atrás"}],"f":6,"es":"¿Qué debe hacer el conductor cuando la visibilidad al hacer marcha atrás es limitada?","explain":"Con visibilidad limitada hacia atrás necesitas una persona fuera del vehículo que vigile y señalice. Abrir la puerta o la ventanilla no elimina los ángulos muertos: sigues sin ver lo que queda detrás y abajo.","val":9,"fase":4},{"id":6452,"bg":"Разрешено ли е движение назад при завиване в обратна посока на кръстовище?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":5,"es":"¿Está permitido ir marcha atrás al dar la vuelta en una intersección?","explain":"No: dar la vuelta en una intersección usando marcha atrás está prohibido. La intersección es zona de conflicto de trayectorias; la maniobra debe completarse con giro continuo hacia delante.","val":8,"fase":4},{"id":5887,"bg":"Ще извърши ли нарушение водачът, ако при тази ситуация завие в обратна посока?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48171.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":9,"es":"¿Cometerá infracción el conductor si en esta situación cambia de sentido (media vuelta)?","explain":"SÍ, cometería infracción.\n\nQUÉ VES. Un semáforo con FLECHAS verdes — una hacia la izquierda y otra hacia la derecha — y el rombo amarillo de vía con prioridad. El coche rojo lleva el intermitente izquierdo y pretende dar media vuelta.\n\nUNA FLECHA VERDE ABRE SU DIRECCIÓN Y SOLO ESA. La flecha izquierda autoriza a GIRAR A LA IZQUIERDA. Dar media vuelta es otra maniobra distinta: un cambio de sentido, no un giro.\n\nPOR QUÉ NO SON LO MISMO. El giro a la izquierda te lleva a la vía transversal. La media vuelta te devuelve por donde viniste, cruzando dos veces el flujo del cruce y ocupando la intersección mucho más tiempo. La señal que autoriza una no autoriza la otra.\n\nEL ROMBO NO AYUDA. Estar en la vía con prioridad no amplía las maniobras que puedes hacer: solo decide quién pasa antes.\n\nCLAVE: con flechas en el semáforo, lee la maniobra exacta que dibuja cada una. Girar a la izquierda ≠ cambiar de sentido, y esa distinción vale varias preguntas del banco.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":13,"fase":3},{"id":5931,"bg":"При тази ситуация при определяне на реда за преминаване през кръстовището се прилагат следните правила:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66850.png","v":null,"a":[{"t":"ППС на пътя с предимство, трябва да преминат преди ППС от другите пътища","ok":true,"i":null,"es":"los de la vía preferente pasan antes que los de otros caminos"},{"t":"ППС на пътя с предимство, помежду си прилагат правилото за „предимството на дясностоящия”","ok":true,"i":null,"es":"los de la preferente entre sí aplican la regla de la derecha"},{"t":"завиващите наляво ППС от пътя с предимство пропускат насрещнодвижещите се ППС","ok":false,"i":null,"es":"los que giran a la izquierda desde la preferente ceden al tráfico contrario"}],"f":7,"es":"En esta situación, para determinar el orden de paso por la intersección se aplican las siguientes reglas: (2 correctas)","explain":"Dos reglas: los de la vía preferente pasan antes que los de los otros caminos, y entre ellos se aplica la regla de la derecha.\n\nLEE LA TABLA. Bajo el rombo, el trazo GRUESO entra por abajo — tu aproximación — y tuerce a la IZQUIERDA. Los trazos finos son el de arriba y el de la derecha.\n\nPRIMERA REGLA: hay jerarquía. Todo el que llegue por un ramal fino cede a los que circulan por la preferente.\n\nSEGUNDA REGLA: tú y el coche que está a la izquierda compartís la preferente, así que el rombo no os distingue. Como la vía CAMBIA DE DIRECCIÓN, entra el чл. 50, ал. 2 y vuelve la regla de la derecha.\n\nLA TERCERA OPCIÓN es la del giro a la izquierda desde la preferente. Es una regla real — чл. 37 — pero en esta escena no hay ningún vehículo de la preferente haciendo ese giro, así que no interviene.\n\nCOMPÁRALA CON LA 5927. Allí la señal no lleva tabla, la preferente sigue recta, y la regla que sí aplica es justo la contraria: el чл. 37 en lugar de la derecha. Misma pregunta, respuestas cruzadas.\n\nCLAVE: la tabla decide cuál de las dos reglas secundarias entra. Si la preferente TUERCE, la derecha. Si sigue RECTA, el чл. 37.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":11,"fase":3},{"id":5948,"bg":"При тази ситуация разрешено ли е да преминете през кръстовището?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51366.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да, но след като пропусна синия автомобил","ok":false,"i":null,"es":"sí, pero después de ceder el paso al automóvil azul"}],"f":8,"es":"En esta situación ¿está permitido pasar por la intersección?","explain":"NO.\n\nHAY AGENTE Y SEMÁFORO A LA VEZ, y eso ya decide la pregunta: las señales del regulador anulan al semáforo. El disco verde de la derecha no cuenta mientras él dirija el tráfico.\n\nEL AGENTE ESTÁ CON LOS BRAZOS BAJADOS y lo ves de frente, no de costado. Con los brazos bajados solo pasan quienes lo ven de perfil, por su izquierda o por su derecha; quienes tienen delante su pecho o su espalda se detienen. Ese es tu caso.\n\n'SÍ, DESPUÉS DE CEDER AL AZUL' es falso, y es un cebo fino: te hace pensar en repartir prioridades cuando el problema es otro. No se trata de a quién cedes, sino de que no puedes entrar en el cruce.\n\nCLAVE: si ves agente y semáforo juntos, mira solo al agente. El semáforo deja de existir.","val":12,"fase":3},{"id":5950,"bg":"При несъответствие между сигналите на светофара и пътните знаци относно предимството трябва да се съобразявате:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51448.png","v":null,"a":[{"t":"със светлинните сигнали","ok":true,"i":null,"es":"las señales luminosas (el semáforo)"},{"t":"с предписанията на пътните знаци","ok":false,"i":null,"es":"las prescripciones de las señales verticales"}],"f":11,"es":"Cuando hay conflicto entre semáforo y señales de prioridad, debes atenerte a:","explain":"A las señales LUMINOSAS, es decir, al semáforo.\n\nLA JERARQUÍA. Cuando el semáforo y una señal vertical de prioridad se contradicen, manda el semáforo. En la foto lo tienes literal: una señal de STOP a la derecha y, junto a ella, un semáforo en VERDE. La señal dice «para», la luz dice «pasa». Pasas.\n\nPOR QUÉ. Las señales verticales son fijas y describen la situación normal de la vía. El semáforo es dinámico y refleja la situación de AHORA. La norma más reciente y más concreta se impone a la general.\n\nY HAY UN ESCALÓN MÁS ARRIBA: el agente regulador. Por encima del semáforo está él. La jerarquía completa, de mayor a menor: agente → semáforo → señales verticales → marcas viales → reglas generales de prioridad.\n\nCLAVE: memoriza la escalera de arriba abajo. Casi todas las preguntas de conflicto se resuelven señalando el escalón más alto que aparezca en la escena.\n\nMÉTODO DEL SEMÁFORO: 1) ¿parpadea o es fija? Немигащ = fija; мигащ = intermitente, y significan cosas distintas. 2) ¿qué focos están encendidos? 3) ¿hay flecha? Una flecha verde solo abre esa dirección, no las demás. Desarrollado en Leyes → «El semáforo: significado oficial de cada señal».","val":16,"fase":3},{"id":6338,"bg":"Задължително ли е спирането на ППС пред жп прелеза, ако бариерите са вдигнати, но светофарът подава мигаща червена светлина?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да, във всички случаи","ok":true,"i":null,"es":"sí, en todos los casos"},{"t":"да, но само когато към прелеза приближава влак","ok":false,"i":null,"es":"sí, pero solo cuando se aproxima un tren"},{"t":"не е задължително","ok":false,"i":null,"es":"no es obligatorio"}],"f":10,"es":"¿Es obligatorio parar ante el paso a nivel si las barreras están levantadas pero el semáforo está rojo?","explain":"Sí, en todos los casos: el semáforo rojo del paso a nivel obliga a parar AUNQUE las barreras estén levantadas: puede tratarse de una avería de las barreras con tren aproximándose. La señal luminosa prevalece.","val":15,"fase":3},{"id":6476,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53752.png","v":null,"a":[{"t":"спирам, за да изчакам разрешаващ сигнал от регулировчика","ok":true,"i":null,"es":"paro para esperar señal de paso del agente"},{"t":"спирам за да пропусна червения автомобил и преминавам след него","ok":false,"i":null,"es":"paro para dejar al rojo y paso después"},{"t":"преминавам преди червения автомобил","ok":false,"i":null,"es":"paso antes que el rojo"}],"f":8,"es":"En esta situación:","explain":"PARO y espero la señal de paso del agente.\n\nCÓMO LEER AL AGENTE. Tiene los brazos BAJADOS y lo estás viendo POR LA ESPALDA. Con los brazos bajados solo pasan quienes lo ven de costado, por su izquierda o por su derecha, y esos pueden seguir recto o girar a la derecha. Quienes ven su pecho o su espalda están detenidos.\n\nPOR QUÉ FALLAN LAS OTRAS. Las dos hablan de repartirte el paso con el coche rojo, pero mientras el agente te tenga detenido no hay reparto que valga: no pasas ni antes ni después, esperas.\n\nCLAVE: antes de mirar a los demás coches, localiza desde qué lado ves al agente. Su postura significa cosas distintas según dónde estés.","val":11,"fase":3},{"id":6477,"bg":"При движение в тунел с дължина над 500 м, дистанцията между леките автомобили, трябва да е равна на разстоянието, изминавано за две секунди с разрешената скорост на движение.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"f":7,"es":"En túnel de más de 500 m la distancia entre turismos debe ser igual a la distancia de seguridad exterior. Esto es:","explain":"Correcto: en túneles de más de 500 m los turismos en marcha mantienen la misma distancia de seguridad que en el exterior. El túnel no reduce la distancia necesaria de frenada: la oscuridad y el encierro la hacen aún más crítica.","val":11,"fase":3},{"id":6483,"bg":"При тази ситуация разрешено ли е да завиете надясно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/103209.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":10,"es":"En esta situación ¿está permitido girar a la derecha?","explain":"SÍ. El semáforo de la derecha tiene el disco VERDE encendido (ámbar y roja apagadas). Un verde redondo, sin flechas y sin ninguna señal que lo prohíba, permite el giro a la derecha igual que seguir recto. La trampa es creer que hace falta una flecha verde: la flecha solo aparece cuando ese giro se regula aparte con una sección adicional.","val":14,"fase":3},{"id":6513,"bg":"При тази ситуация червеният автомобил, който завива надясно, е с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63115.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":8,"es":"En esta situación el coche rojo que gira a la derecha tiene prioridad. Esto es:","explain":"INCORRECTO, el rojo NO tiene prioridad.\n\nLEE EL PANEL. Bajo el rombo amarillo hay un panel con el trazado: el trazo GRUESO llega desde la izquierda y gira hacia tu acceso. Esa es la vía con prioridad. El brazo por el que viene el coche rojo está dibujado con trazo FINO, o sea que es secundario.\n\nQUE GIRE A LA DERECHA NO LE DA NADA. La preferencia depende de la vía por la que se llega, no de la maniobra que se hace ni de lo cómoda que parezca.\n\nCLAVE: cuando veas un rombo con panel, lo primero es identificar qué brazos son gruesos. El resto se deduce solo.","val":11,"fase":3},{"id":6543,"bg":"При тази ситуация червеният автомобил е с предимство, защото се движи направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68524.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":8,"es":"En esta situación el coche rojo tiene prioridad porque va recto. Esto es:","explain":"INCORRECTO.\n\nIR RECTO NO DA PRIORIDAD. Nunca. En la ley búlgara la prioridad sale de tres sitios y solo de esos tres: de las señales, del semáforo o del agente; si no hay nada de eso, de la regla de la derecha (чл. 50, ал. 1); y aparte, el чл. 37 obliga a ceder al que viene de frente cuando tú giras a la izquierda. La maniobra que lleve el otro — recto, derecha o izquierda — no aparece en esa lista.\n\nEN ESTA ESCENA, ADEMÁS, EL ROJO NO PASA PRIMERO. Es un cruce sin señales, el azul me llega por la izquierda, el rojo viene de frente y yo giro a la izquierda. Se forma el mismo bucle cerrado que en la pregunta gemela del coche rojo y el azul: yo debería ceder al rojo, el rojo debería ceder al azul (que le entra por su derecha) y el azul debería cederme a mí. Nadie puede arrancar. El banco oficial deshace el bucle diciendo que paso yo, así que el rojo no tiene prioridad ni siquiera en el resultado.\n\nEL ENUNCIADO FALLA POR PARTIDA DOBLE: la razón es falsa y la conclusión también.\n\nCLAVE: cuando un enunciado justifica la prioridad con la maniobra — «porque va recto», «porque gira a la derecha» — la respuesta es casi siempre неправилно.\n\nEN LA CARRETERA HAZ LO CONTRARIO: si giras a la izquierda, cede siempre al que viene de frente. Si hay colisión, el atestado se apoya en el чл. 37 y responde el que gira. Esta es la única pregunta del banco donde el examen y la práctica piden cosas distintas, y está desarrollada entera en Leyes → «Caso especial: el bucle de prioridad (заклещване)».","val":13,"fase":3},{"id":6544,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66249.png","v":null,"a":[{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"dejar pasar al coche azul"},{"t":"да пропусна жълтия автомобил","ok":true,"i":null,"es":"dejar pasar al coche amarillo"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el coche rojo"}],"f":9,"es":"En esta situación debo: (2 correctas)","explain":"MULTIRESPUESTA: cedo al AZUL y al AMARILLO. El panel bajo el ceda el paso dibuja la vía con prioridad como una CURVA: entra por el brazo del rojo y sale por el del amarillo. Los dos circulan por ella, así que les cedo a ambos. El azul viene por un brazo secundario como el mío, pero por mi derecha, así que también pasa primero. 'Pasar antes que el rojo' es falso por el mismo motivo. Clave: la preferencia la da la vía por la que LLEGAS, no la dirección que tomas después — el rojo la conserva aunque abandone la curva hacia el brazo del azul.","val":14,"fase":3},{"id":6548,"bg":"При тази ситуация трябва да премина след:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/82756.png","v":null,"a":[{"t":"червения автомобил","ok":false,"i":null,"es":"el coche rojo"},{"t":"синия автомобил","ok":true,"i":null,"es":"el coche azul"}],"f":9,"es":"En esta situación debo pasar después de:","explain":"Después del AZUL. El panel bajo el rombo dibuja el trazado: la vía con prioridad llega desde tu acceso y GIRA A LA DERECHA, que es por donde está el azul. Los dos vais por ella, así que entre vosotros decide la regla de la derecha y el azul la tiene. El rojo sigue recto por la secundaria, de modo que te cede a ti. Un mismo cruce, dos reglas distintas según por dónde vengas.","val":14,"fase":3},{"id":6552,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65693.png","v":null,"a":[{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el coche azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"dejar pasar al coche rojo"},{"t":"да премина преди жълтия автомобил","ok":true,"i":null,"es":"pasar antes que el coche amarillo"}],"f":7,"es":"En esta situación debo: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: tienes prioridad sobre el azul Y el amarillo, pero cedes al rojo.","val":10,"fase":3},{"id":6574,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68169.png","v":null,"a":[{"t":"да пропусна мотоциклетиста","ok":true,"i":null,"es":"dejar pasar al motorista"},{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да премина преди мотоциклетиста","ok":false,"i":null,"es":"pasar antes que el motorista"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"dejar pasar al coche rojo"}],"f":9,"es":"En esta situación debo: (2 correctas)","explain":"MULTIRESPUESTA: cedo al MOTORISTA y paso antes que el ROJO. El motorista llega por mi derecha, así que tiene preferencia. El rojo llega por mi izquierda, así que soy yo quien pasa primero. Que uno de los dos sea una moto no cambia nada: las motos se rigen por las mismas reglas que los coches y no tienen ninguna prioridad especial. Cuenta los lados, no los vehículos.","val":13,"fase":3},{"id":6576,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67906.png","v":null,"a":[{"t":"да пропусна лекия автомобил","ok":true,"i":null,"es":"dejar pasar al turismo"},{"t":"да пропусна товарния автомобил","ok":true,"i":null,"es":"dejar pasar al camión"},{"t":"да премина преди лекия автомобил","ok":false,"i":null,"es":"pasar antes que el turismo"},{"t":"да премина преди товарния автомобил","ok":false,"i":null,"es":"pasar antes que el camión"}],"f":7,"es":"En esta situación debo: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: cedes tanto al turismo como al camión — ambos tienen prioridad sobre ti en esta intersección específica.","val":10,"fase":3},{"id":6674,"bg":"Преминавайки през кръстовището при този сигнал на регулировчика няма да извърша нарушение, при условие, че:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54571.png","v":null,"a":[{"t":"преди подаването на този сигнал е било разрешено преминаването ми","ok":true,"i":null,"es":"antes de la señal me estaba permitido pasar"},{"t":"в момента на подаването на сигнала съм толкова близо, че не мога да спра безопасно","ok":true,"i":null,"es":"en el momento de la señal estoy tan cerca que no puedo parar con seguridad"},{"t":"подам звуков или светлинен сигнал за това, че ще премина през кръстовището","ok":false,"i":null,"es":"doy señal acústica o luminosa"}],"f":8,"es":"Al pasar por la intersección con esta señal del agente no cometo infracción si: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: igual que ID 6668 — puedes continuar si ya tenías paso O si frenar sería peligroso por la distancia. El claxon no te da derecho a continuar.","val":12,"fase":3},{"id":7962,"bg":"При тази ситуация задължени ли сте да пропуснете товарния автомобил?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64917864.png","v":null,"a":[{"t":"да, независимо от посоката, в която ще продължи да се движи","ok":true,"i":null,"es":"sí, independientemente de la dirección en que continúe"},{"t":"зависи от посоката, в която ще продължи да се движи","ok":false,"i":null,"es":"depende de la dirección en que continúe"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"En esta situación ¿está obligado a dejar pasar al camión?","explain":"SÍ, independientemente de la dirección en la que el camión continúe.\n\nES LA MISMA ESCENA QUE LA 7963, preguntada de otra forma. La tabla vuelve a mostrar el trazo GRUESO entrando por abajo y torciendo a la DERECHA: los dos estáis en la preferente y el camión está a tu derecha.\n\nPOR QUÉ NO DEPENDE DE HACIA DÓNDE VAYA ÉL. La prioridad se determina por la posición relativa y por la vía, nunca por la trayectoria que el otro vaya a tomar. Tanto si sigue recto, como si gira a un lado u otro, su derecho a pasar antes que tú es el mismo.\n\n«DEPENDE DE LA DIRECCIÓN» es el distractor, y es un razonamiento muy natural: si va a girar hacia otro lado, parece que no me estorba. Pero el orden de paso no se negocia según la conveniencia: se fija antes de entrar en el cruce y no cambia con la maniobra ajena.\n\n«NO» ignora las dos reglas a la vez.\n\nCLAVE: el orden de paso se decide por quién es quién y dónde está, no por adónde va. Es la misma idea que hace falsas todas las opciones del tipo «porque va recto».\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":13,"fase":3},{"id":5368,"bg":"При тази ситуация с предимство е водачът на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/40997.png","v":null,"a":[{"t":"червения автомобил, защото се движи по автомагистралата","ok":true,"i":null,"es":"coche rojo porque circula por la autopista"},{"t":"червения автомобил, защото не променя посоката си на движение","ok":false,"i":null,"es":"coche rojo porque no cambia de dirección"},{"t":"синия автомобил, защото се намира от дясната страна на червения автомобил","ok":false,"i":null,"es":"coche azul porque está a la derecha del rojo"},{"t":"синия автомобил, защото навлиза на автомагистралата","ok":false,"i":null,"es":"coche azul porque entra en la autopista"}],"f":9,"es":"En esta situación tiene prioridad el conductor del:","explain":"El rojo circula por la autopista = tiene prioridad. Los que entran siempre ceden a los que ya circulan, independientemente de su posición relativa.","val":9,"fase":4},{"id":5374,"bg":"При тази ситуация разположението на автомобила върху платното за движение е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41406.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcta"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecta"}],"f":8,"es":"En esta situación la posición del vehículo en la calzada es:","explain":"CORRECTA — posicionado correctamente.","val":8,"fase":4},{"id":5376,"bg":"При тази ситуация:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41507.png","v":null,"a":[{"t":"ако не мога да изпреваря червения автомобил, трябва да премина в дясната пътна лента","ok":true,"i":null,"es":"si no puedo adelantar al rojo debo pasar al carril derecho"},{"t":"мога да продължа да се движа в лявата лента, без да изпреварвам червения автомобил","ok":false,"i":null,"es":"puedo seguir en el carril izquierdo sin adelantar al rojo"},{"t":"мога да използвам най-удобната за мен пътна лента","ok":false,"i":null,"es":"puedo usar el carril más cómodo"}],"f":11,"es":"En esta situación:","explain":"En autopista el carril izquierdo es para adelantar. Si no estás adelantando activamente, debes ceder el carril izquierdo y volver al derecho.","val":11,"fase":4},{"id":5398,"bg":"На автомагистрала е забранено движението на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"трактори","ok":true,"i":null,"es":"tractores"},{"t":"съчленени пътни превозни средства","ok":false,"i":null,"es":"vehículos articulados"},{"t":"мотоциклети с кош","ok":false,"i":null,"es":"motos con sidecar"}],"f":7,"es":"En autopista está PROHIBIDA la circulación de: (2 correctas)","explain":"Ciclomotores y tractores no entran en autopista: no alcanzan velocidad segura. Los vehículos articulados y las motos con sidecar sí circulan legalmente por ella.","val":7,"fase":4},{"id":5417,"bg":"При движение по автомобилен път на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да спира за престой извън местата обозначени за паркиране","ok":true,"i":null,"es":"parar fuera de lugares señalizados"},{"t":"да навлиза в разделителната ивица или да я пресича, включително и на местата, където тя е прекъсната","ok":true,"i":null,"es":"entrar en la mediana o cruzarla"},{"t":"да завива в обратна посока","ok":true,"i":null,"es":"dar la vuelta"},{"t":"да тегли повредено МПС с твърда връзка","ok":false,"i":null,"es":"remolcar un vehículo averiado con barra rígida"}],"f":8,"es":"Conduciendo por vía rápida al conductor le está PROHIBIDO: (3 correctas)","explain":"Prohibido: parar fuera de lugares señalizados, entrar/cruzar la mediana y dar la vuelta. Remolcar con barra RÍGIDA sí está permitido (máx. 70 km/h): no confundir con el cable flexible, que solo sirve para salir.","val":8,"fase":4},{"id":5418,"bg":"При движение по автомобилен път на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да навлиза в разделителната ивица или да я пресича, включително и на местата, където тя е прекъсната","ok":true,"i":null,"es":"entrar en la mediana o cruzarla"},{"t":"да завива в обратна посока","ok":true,"i":null,"es":"dar la vuelta"},{"t":"да се движи назад","ok":true,"i":null,"es":"ir marcha atrás"},{"t":"да тегли повредено МПС с твърда връзка","ok":false,"i":null,"es":"remolcar un vehículo averiado con barra rígida"}],"f":11,"es":"Conduciendo por vía rápida al conductor le está PROHIBIDO: (3 correctas)","explain":"En vía rápida está prohibido: entrar en la mediana o cruzarla, dar la vuelta e ir marcha atrás. Remolcar con barra RÍGIDA sí está permitido (a máximo 70 km/h): la trampa está en confundirlo con el cable flexible.","val":11,"fase":4},{"id":11730,"bg":"На автомагистрала движението в лентата за принудително спиране е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibida"},{"t":"разрешено, без ограничения","ok":false,"i":null,"es":"permitida sin restricciones"},{"t":"разрешено само за МПС, движещи се със скорост по-ниска от 30 km/h","ok":false,"i":null,"es":"permitida para vehículos a menos de 30 km/h"}],"f":9,"es":"En autopista la circulación por el carril de emergencia está:","explain":"CIRCULAR por el carril de emergencia está prohibido: es solo para detenciones de emergencia. Tampoco existe excepción para vehículos lentos: si no alcanzas la velocidad mínima, no puedes estar en autopista.","val":9,"fase":4},{"id":5587,"bg":"При тази ситуация, при преминаване покрай автобуса съм задължен да намаля скоростта.","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39170.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"CORRECTO"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"f":7,"es":"En esta situación, al pasar junto al autobús estoy obligado a reducir velocidad. Esto es:","explain":"CORRECTO — al pasar junto a un autobús parado en parada debes reducir velocidad por la posibilidad de peatones cruzando imprevistamente.","val":3,"fase":4},{"id":5595,"bg":"При тази ситуация, настигайки спиращия на спирката трамвай, трябва:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39353.png","v":null,"a":[{"t":"да спра","ok":true,"i":null,"es":"parar"},{"t":"да продължа движението с повишено внимание","ok":false,"i":null,"es":"continuar con precaución"},{"t":"да увелича скоростта","ok":false,"i":null,"es":"acelerar"}],"f":5,"es":"En esta situación, alcanzando el tranvía que para en la parada, debo:","explain":"PARAR — cuando el tranvía para en parada debes detenerte detrás para que los pasajeros puedan bajar y subir con seguridad.","val":3,"fase":4},{"id":12064,"bg":"При тази ситуация трябва да намалите скоростта с готовност за спиране, защото:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":55,"a":[{"t":"автобусът потегля","ok":false,"i":null,"es":"el autobús arranca"},{"t":"пешеходец, слязъл от автобуса, може да пресече платното за движение пред автобуса","ok":true,"i":null,"es":"un peatón que baja del autobús puede cruzar la calzada por delante"},{"t":"пешеходец, който се движи по тротоара, може да пресече платното за движение пред автобуса","ok":true,"i":null,"es":"un peatón de la acera puede cruzar la calzada por delante del autobús"}],"f":5,"es":"En esta situación debe reducir velocidad con disposición de frenar porque: (VIDEO) ⚠️ 2 correctas","explain":"Paso junto a un autobús amarillo detenido en su parada a la derecha: el autobús es una pantalla que oculta gente — debo esperar que un pasajero recién bajado cruce la calzada por DELANTE del autobús, o que un peatón de la acera haga lo mismo. Por eso reduzco con disposición de frenar. 'El autobús arranca' no es el riesgo principal: lo invisible detrás de su carrocería sí lo es.","val":3,"fase":4},{"id":5546,"bg":"Този пътен знак забранява :","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42035.png","v":null,"a":[{"t":"паркирането","ok":true,"i":null,"es":"el aparcamiento"},{"t":"спирането за престой","ok":false,"i":null,"es":"la parada breve"},{"t":"престоя и паркирането","ok":false,"i":null,"es":"la parada breve y el aparcamiento"}],"f":8,"es":"Esta señal prohíbe:","explain":"Prohíbe el APARCAMIENTO — «паркирането».\n\nLA SEÑAL. Círculo azul con borde rojo y UNA sola barra diagonal.\n\nCUENTA LAS BARRAS, que es todo el truco de este par. Una barra prohíbe estacionar pero permite la parada breve. Dos barras cruzadas en aspa prohíben las dos cosas: ni parada ni estacionamiento.\n\nLA DIFERENCIA ENTRE PARADA Y ESTACIONAMIENTO. «Престой» es la parada breve: detenerse el tiempo justo para subir o bajar pasajeros o cargar, con el conductor presente o cerca. «Паркиране» es dejar el vehículo detenido más allá de eso. Con una barra, lo primero está permitido.\n\n«LA PARADA BREVE» y «LA PARADA BREVE Y EL APARCAMIENTO» son los dos distractores, y ambos describen la señal de DOS barras.\n\nCLAVE: una barra, una prohibición — solo aparcar. Dos barras, las dos prohibiciones. Es de las preguntas más rápidas del examen si tienes el par memorizado.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información o indicación. Rombo amarillo = prioridad. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo».","val":4,"fase":4},{"id":5549,"bg":"След този пътен знак:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42231.png","v":null,"a":[{"t":"е разрешено спирането за престой","ok":true,"i":null,"es":"está permitida la parada breve"},{"t":"е забранено паркирането","ok":true,"i":null,"es":"está prohibido aparcar"},{"t":"е забранено спирането за престой","ok":false,"i":null,"es":"está prohibida la parada breve"},{"t":"е разрешено паркирането","ok":false,"i":null,"es":"está permitido aparcar"}],"f":8,"es":"Después de esta señal: (2 correctas)","explain":"Dos cosas: está PERMITIDA la parada breve y está PROHIBIDO aparcar.\n\nQUÉ VES. La misma señal de una sola barra diagonal de la pregunta 5546, ahora colocada en una calle.\n\nLAS DOS RESPUESTAS SON LAS DOS CARAS de esa única barra: lo que prohíbe y lo que deja intacto. Por eso hay dos correctas y no una.\n\n«ESTÁ PROHIBIDA LA PARADA BREVE» describiría la señal de dos barras.\n\n«ESTÁ PERMITIDO APARCAR» es directamente lo contrario de lo que la señal dice.\n\nPOR QUÉ IMPORTA LA DISTINCIÓN EN LA CALLE. Con esta señal puedes detenerte para que baje un pasajero, pero no dejar el coche e irte. Si te alejas del vehículo, ya es estacionamiento.\n\nY OJO A LAS TABLILLAS. Igual que en la 6239, una tablilla debajo puede acotar el horario o los días en que rige la prohibición. Sin tablilla, rige siempre.\n\nCLAVE: es la gemela de la 5546 preguntada desde la escena en vez de desde el dibujo. Una barra: para sí, aparca no.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información o indicación. Rombo amarillo = prioridad. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo».","val":4,"fase":4},{"id":5564,"bg":"Кой от автомобилите е спрян неправилно за престой?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42463.png","v":null,"a":[{"t":"само товарният автомобил","ok":false,"i":null,"es":"solo el camión"},{"t":"само лекият автомобил","ok":false,"i":null,"es":"solo el turismo"},{"t":"и двата автомобила","ok":true,"i":null,"es":"los dos vehículos"}],"f":6,"es":"¿Qué vehículo está incorrectamente detenido para una parada breve?","explain":"Los dos infringen las normas de prestoy — cada uno por razones diferentes según la imagen.","val":3,"fase":4},{"id":5566,"bg":"Кой от автомобилите е паркиран в нарушение на правилата за движение?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42550.png","v":null,"a":[{"t":"само товарният автомобил","ok":false,"i":null,"es":"solo el camión"},{"t":"само лекият автомобил","ok":false,"i":null,"es":"solo el turismo"},{"t":"и двата автомобила","ok":true,"i":null,"es":"los dos vehículos"}],"f":5,"es":"¿Qué vehículo está aparcado infringiendo las normas?","explain":"Los dos están aparcados incorrectamente — probablemente en zona prohibida, bloqueando la circulación o sin respetar la distancia mínima.","val":2,"fase":4},{"id":5574,"bg":"Спирането за престой по еднопосочен път в населено място:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"е разрешено от дясната страна на пътя","ok":true,"i":null,"es":"está permitida en el lado derecho"},{"t":"се допуска от лявата страна на пътя, ако това не пречи на движението на ППС","ok":true,"i":null,"es":"se admite en el lado izquierdo si no impide la circulación"},{"t":"е разрешено от лявата страна на пътя, без ограничения","ok":false,"i":null,"es":"está permitida en el lado izquierdo sin restricciones"}],"f":8,"es":"La parada breve en calle de sentido único en población: (2 correctas)","explain":"En calle de sentido único en población: parada permitida en el lado derecho y también ADMITIDA en el izquierdo si no impide la circulación. 'Sin restricciones' en el izquierdo es la versión falsa: la condición existe.","val":4,"fase":4},{"id":5581,"bg":"На еднопосочен път в населено място паркирането от лявата страна е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено, когато водачът не напуска превозното средство","ok":false,"i":null,"es":"permitido cuando el conductor no abandona el vehículo"},{"t":"разрешено, ако не се пречи на движението","ok":false,"i":null,"es":"permitido si no se obstaculiza"},{"t":"забранено само за товарни автомобили","ok":false,"i":null,"es":"prohibido solo para camiones"}],"f":5,"es":"En calle de sentido único en zona urbana el aparcamiento en el lado izquierdo está:","explain":"APARCAR en el lado izquierdo de una calle de sentido único está prohibido: la tolerancia del lado izquierdo existe solo para la parada breve (престой) y con condiciones. Aparcar es solo a la derecha.","val":3,"fase":4},{"id":5604,"bg":"Къде по пътищата извън населените места е разрешено паркирането?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"извън платното за движение","ok":true,"i":null,"es":"fuera de la calzada"},{"t":"на обозначените за тази цел места","ok":true,"i":null,"es":"en lugares señalizados para ello"},{"t":"най-вдясно на платното за движение","ok":false,"i":null,"es":"en el extremo derecho de la calzada"}],"f":5,"es":"¿Dónde está permitido aparcar fuera de población? (2 correctas)","explain":"Fuera de población se aparca FUERA de la calzada o en lugares señalizados. El 'extremo derecho de la calzada' sigue siendo calzada: dejarías el coche dentro de la zona de circulación a 90 km/h.","val":3,"fase":4},{"id":5605,"bg":"Правилно ли е паркиран товарният автомобил на този път извън населено място?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43796.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":8,"es":"¿Está correctamente aparcado el camión en esta carretera fuera de población?","explain":"NO — fuera de población el aparcamiento debe ser fuera de la calzada o en zona señalizada. En la calzada, aunque sea a la derecha, no está permitido.","val":4,"fase":4},{"id":5607,"bg":"Правилно ли е паркиран товарният автомобил на този път извън населено място?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43845.png","v":null,"a":[{"t":"не, защото трябва да е извън платното за движение","ok":true,"i":null,"es":"no, porque debe estar fuera de la calzada"},{"t":"да, защото е възможно най-вдясно на пътното платно","ok":false,"i":null,"es":"sí, porque está todo lo posible a la derecha de la plataforma vial"},{"t":"не, защото участъкът не е сигнализиран като място за паркиране","ok":false,"i":null,"es":"no, porque el tramo no está señalizado como zona de aparcamiento"}],"f":7,"es":"¿Está correctamente aparcado el camión en esta carretera fuera de población?","explain":"NO — fuera de población el aparcamiento debe ser fuera de la calzada. Estar a la derecha del firme no es suficiente fuera de ciudad.","val":4,"fase":4},{"id":5641,"bg":"Паркирането е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"в стеснен участък от пътя","ok":true,"i":null,"es":"en tramo estrecho de la vía"},{"t":"в участък с ограничена видимост","ok":true,"i":null,"es":"en tramo con visibilidad limitada"},{"t":"върху трамвайна линия","ok":true,"i":null,"es":"sobre vía de tranvía"},{"t":"на участък от пътя с наклон","ok":false,"i":null,"es":"en tramo de la vía con pendiente"}],"f":7,"es":"El aparcamiento está PROHIBIDO: (3 correctas)","explain":"Prohibido aparcar en tramos estrechos (bloqueas el paso), con visibilidad limitada (nadie te ve a tiempo) y sobre vía de tranvía (el tranvía no puede esquivar). La simple pendiente no prohíbe aparcar.","val":3,"fase":4},{"id":5651,"bg":"Разрешено ли е паркирането на ППС в участъци от пътя, които са в ремонт?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":6,"es":"¿Está permitido aparcar en tramos de vía en obras?","explain":"Sí: aparcar en tramos en obras está permitido salvo que una señal lo prohíba expresamente. Las obras restringen por señalización, no por sí mismas.","val":3,"fase":4},{"id":7809,"bg":"Паркирането е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на пешеходна пътека","ok":true,"i":null,"es":"en paso de peatones"},{"t":"на разстояние по-малко от 5 м преди пешеходна пътека","ok":true,"i":null,"es":"a menos de 5 m ANTES del paso de peatones"},{"t":"на разстояние по-малко от 5 м след пешеходна пътека","ok":false,"i":null,"es":"a menos de 5 m DESPUÉS del paso de peatones"}],"f":11,"es":"El aparcamiento está PROHIBIDO: (2 correctas)","explain":"El aparcamiento está prohibido sobre el paso de peatones y a menos de 5 m ANTES de él (taparía la visibilidad del peatón que va a cruzar). Después del paso no rige la prohibición.","val":5,"fase":4},{"id":8284,"bg":"Паркирането е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на места, определени за ППС, обслужващи хора с трайни увреждания","ok":true,"i":null,"es":"en plazas reservadas para personas con discapacidad"},{"t":"до паркирано или спряно за престой ППС, от страната на движението","ok":true,"i":null,"es":"al lado de un vehículo parado o en prestoy, por el lado del tráfico"},{"t":"на мост","ok":true,"i":null,"es":"en puente"},{"t":"на участък от пътя в ремонт","ok":false,"i":null,"es":"en tramo de vía en obras"}],"f":8,"es":"El aparcamiento está PROHIBIDO: (3 correctas)","explain":"Prohibido aparcar: en plazas reservadas a personas con discapacidad, en doble fila (junto a otro parado, por el lado del tráfico) y en puente. El tramo en obras solo lo prohíbe si está señalizado: por eso es la falsa.","val":4,"fase":4},{"id":11590,"bg":"Спирането върху платното за движение след този пътен знак е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43420.png","v":null,"a":[{"t":"разрешено за слизане на пътник от автомобила","ok":false,"i":null,"es":"permitida para que un pasajero baje del coche"},{"t":"забранено за извършване на товарно-разтоварна дейност","ok":true,"i":null,"es":"prohibida para carga y descarga"},{"t":"забранено за паркиране","ok":true,"i":null,"es":"prohibida para aparcar"},{"t":"разрешено за качване на пътник в автомобила","ok":false,"i":null,"es":"permitida para que un pasajero suba al coche"}],"f":7,"es":"La parada sobre la calzada después de esta señal está: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: la señal prohíbe la carga/descarga Y el aparcamiento. Las paradas para subir o bajar pasajeros siguen permitidas brevemente.","val":3,"fase":4},{"id":11873,"bg":"Когато паркирането върху тротоара е разрешено, допустимата максимална маса на паркираното превозното средство не трябва да е по-голяма от:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"2,5 t","ok":true,"i":null,"es":"2.5 t"},{"t":"1,0 t","ok":false,"i":null,"es":"1.0 t"},{"t":"1,5 t","ok":false,"i":null,"es":"1.5 t"},{"t":"2,0 t","ok":false,"i":null,"es":"2.0 t"}],"f":11,"es":"Cuando el aparcamiento sobre la acera está permitido, la masa máxima del vehículo aparcado es:","explain":"2,5 t: es la masa máxima del vehículo que puede aparcar sobre la acera donde está permitido y señalizado. Por encima, el peso daña el pavimento peatonal.","val":5,"fase":4},{"id":11892,"bg":"Спирането за престой е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на пешеходна пътека","ok":true,"i":null,"es":"en paso de peatones"},{"t":"на разстояние по-малко от 5 метра преди пешеходна пътека","ok":true,"i":null,"es":"a menos de 5 m ANTES del paso de peatones"},{"t":"на разстояние по-малко от 5 метра след пешеходна пътека","ok":false,"i":null,"es":"a menos de 5 m DESPUÉS del paso de peatones"}],"f":12,"es":"La parada breve (prestoy) está PROHIBIDA: (2 correctas)","explain":"La parada breve está prohibida SOBRE el paso de peatones y a menos de 5 m ANTES de él: taparías el paso justo donde el peatón aparece. DESPUÉS del paso no hay prohibición: el peatón ya cruzó por detrás de ti.","val":6,"fase":4},{"id":5687,"bg":"През нощта движението зад друго МПС на разстояние по-малко от 50 м се извършва с включени:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"къси светлини","ok":true,"i":null,"es":"luces cortas"},{"t":"дълги светлини","ok":false,"i":null,"es":"luces largas"},{"t":"само габаритни светлини","ok":false,"i":null,"es":"solo luces de posición"}],"f":5,"es":"De noche, circulando detrás de otro vehículo a menos de 50 m, se circula con:","explain":"Con cortas: a menos de 50 m detrás de otro, las largas lo deslumbran por los tres retrovisores. Solo posición te deja sin ver la vía: las cortas son el equilibrio obligatorio.","val":2,"fase":4},{"id":6685,"bg":"Кое от изброените действия е най-опасно при движение по този заледен пътен участък?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/29191.png","v":null,"a":[{"t":"рязкото подаване на газ","ok":true,"i":null,"es":"dar gas de golpe"},{"t":"задържане натиснат педала на съединителя","ok":false,"i":null,"es":"mantener el pedal del embrague pisado"},{"t":"превключването на скоростния механизъм","ok":false,"i":null,"es":"cambiar de marcha"}],"f":8,"es":"¿Cuál es la acción más peligrosa circulando por este tramo de hielo?","explain":"Dar gas bruscamente en hielo = las ruedas patinan y pierdes el control. En hielo siempre: movimientos suaves y progresivos en todos los pedales y el volante.","val":4,"fase":4},{"id":8285,"bg":"През деня, моторните превозни средства се движат с включени светлини за движение през деня или с къси светлини.","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"f":6,"es":"De día, los vehículos a motor circulan con luces diurnas o luces cortas encendidas. Esto es:","explain":"Correcto: de día es obligatorio circular con luces diurnas o de cruce encendidas: ser visto es la mitad de la seguridad. La norma rige todo el año, no solo en invierno.","val":3,"fase":4},{"id":11634,"bg":"Използването на дългите светлини е забранено, когато при снеговалеж видимостта е намалена.","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"правилно","ok":false,"i":null,"es":"correcto"},{"t":"не е забранено, но е неправилно","ok":true,"i":null,"es":"no está prohibido pero es incorrecto"}],"f":5,"es":"Usar las luces largas está prohibido cuando la visibilidad es reducida por nevada.","explain":"'No está prohibido pero es incorrecto': con nevada las largas no violan la ley, pero la luz rebota en los copos y ves PEOR: es un error técnico, no jurídico. La distinción legal/técnico es exactamente lo que pregunta.","val":2,"fase":4},{"id":12070,"bg":"Какво е правилното поведение при тази ситуация (поради мъгла видимостта е намалена под 50 m)?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":62,"a":[{"t":"намалявам скоростта","ok":true,"i":null,"es":"reduzco la velocidad"},{"t":"включвам задните светлини за мъгла","ok":true,"i":null,"es":"enciendo las luces traseras antiniebla"},{"t":"управлявам с допустимата за пътя скорост","ok":false,"i":null,"es":"circulo a la velocidad permitida para esa vía"}],"f":9,"es":"¿Cuál es el comportamiento correcto en esta situación? Visibilidad reducida a menos de 50 m por niebla. (VIDEO) ⚠️ 2 correctas","explain":"Niebla con visibilidad por debajo de 50 m (el vehículo de delante apenas se distingue): REDUZCO la velocidad adaptándola a lo que realmente veo y ENCIENDO las luces traseras antiniebla para que me localicen por detrás. 'Circular a la velocidad permitida de la vía' es la trampa: el límite legal no es un derecho — con visibilidad reducida debes poder detenerte dentro del tramo que ves.","val":5,"fase":4},{"id":5708,"bg":"Движението при едни и същи условия, по ежедневно използван маршрут, води до привикване с пътната обстановка и отслабване на вниманието.","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"f":11,"es":"Conducir diariamente por la misma ruta en condiciones idénticas lleva a familiarizarse con la situación vial. Esto es:","explain":"Correcto: la ruta diaria idéntica familiariza con la situación... y ahí está el peligro que el banco quiere que reconozcas después: la familiaridad relaja la atención. La afirmación literal es cierta.","val":5,"fase":4},{"id":5995,"bg":"Задължение на водача е превозваният товар:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да е покрит, когато отразява светлината и може да заслепи други участници в движението","ok":true,"i":null,"es":"esté cubierta cuando refleja la luz y puede deslumbrar"},{"t":"да е укрепен","ok":true,"i":null,"es":"esté asegurada"},{"t":"да не закрива светлинните устройства на автомобила","ok":true,"i":null,"es":"no cubra los dispositivos luminosos del vehículo"},{"t":"да е опакован съгласно изискванията на производителя","ok":false,"i":null,"es":"esté embalada según las exigencias del fabricante"}],"f":4,"es":"El conductor está obligado a que la carga transportada: (3 correctas)","explain":"La carga debe: ir cubierta si refleja y puede deslumbrar, estar asegurada (sujeta) y no tapar las luces del vehículo. El 'embalaje según el fabricante' no es requisito del código de circulación: es logística, no seguridad vial.","val":2,"fase":4},{"id":6020,"bg":"Движещите се по пътя три- и четириколесни моторни превозни средства трябва да бъдат оборудвани:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"с аптечка","ok":true,"i":null,"es":"botiquín de primeros auxilios"},{"t":"със светлоотразителна жилетка","ok":true,"i":null,"es":"chaleco reflectante"},{"t":"с обезопасителен триъгълник","ok":true,"i":null,"es":"triángulo de seguridad"},{"t":"с вериги за движение през зимата","ok":false,"i":null,"es":"cadenas para nieve"}],"f":6,"es":"Los vehículos de motor de 3 y 4 ruedas deben ir equipados con: (3 correctas)","explain":"Equipamiento obligatorio: botiquín, chaleco reflectante y triángulo de seguridad. Las cadenas de nieve solo son obligatorias cuando la señalización o las condiciones lo exigen, no como dotación permanente.","val":3,"fase":4},{"id":11441,"bg":"Разрешено ли е водачът на МПС да използва пътищата, отворени за обществено ползване, за други цели, освен в съответствие с тяхното предназначение?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":false,"i":null,"es":"sí"},{"t":"не","ok":true,"i":null,"es":"no"}],"f":4,"es":"¿Está permitido al conductor usar las vías abiertas al público para otros fines?","explain":"No: las vías públicas son para circular. Usarlas para otros fines (carreras, pruebas, eventos) exige autorización especial: por defecto está prohibido.","val":2,"fase":4},{"id":5912,"bg":"Значенето на кой от показаните немигащи сигнали на светофара е “Внимание спри!”?","p":3,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43199.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43200.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43201.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43202.png","es":""}],"f":11,"es":"¿Cuál de las señales NO PARPADEANTES del semáforo mostradas significa '¡Atención, para!'?","explain":"El semáforo con la luz ÁMBAR encendida SOLA — la del medio — con la roja y la verde apagadas.\n\nÁMBAR FIJO SIGNIFICA «ВНИМАНИЕ! СПРИ!». No es un aviso para acelerar: prohíbe entrar en el cruce. Solo sigue el que ya ha entrado o el que está tan cerca que no podría parar sin frenar bruscamente.\n\nEL VERDE es la segunda imagen: paso permitido. Es el opuesto exacto de lo que pide el enunciado.\n\nEL ROJO SOLO es la tercera: prohibido el paso. Prohíbe igual, pero su significado oficial es «преминаването е забранено», no «внимание, спри».\n\nEL ROJO + ÁMBAR es la cuarta: sigue prohibido pasar; solo anuncia que el verde llega en un segundo. Es el cebo más frecuente porque tiene ámbar dentro.\n\nCLAVE: ámbar SOLO = para. Ámbar CON rojo = sigue parado. Y fíjate en «немигащи» (no parpadeantes): el ámbar intermitente es otra cosa, significa cruce sin regular, pasa con precaución.","val":16,"fase":3},{"id":6102,"bg":"С какво трябва да се съобразявате при отварянето на капачката на разширителния резервоар на охладителната уредба при загрят двигател?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"с опасността от заливане с гореща охладителна течност","ok":true,"i":null,"es":"el peligro de quemarse con el líquido refrigerante caliente"},{"t":"с намаляване на количеството на охладителната течност поради изпаряване","ok":false,"i":null,"es":"la reducción del líquido por evaporación"},{"t":"с понижаването на температурата на охладителната течност","ok":false,"i":null,"es":"el enfriamiento del líquido"}],"f":3,"es":"¿Qué debes tener en cuenta al abrir el tapón del depósito de expansión del líquido refrigerante?","explain":"Cuidado con QUEMARTE: el circuito de refrigeración caliente está a presión y por encima de 100 °C: al abrir el tapón puede salir líquido y vapor a chorro. Se abre solo en frío: la evaporación o el enfriamiento no son el peligro.","val":1,"fase":4},{"id":5166,"bg":"Този пътен знак предупреждава за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334664.png","v":null,"a":[{"t":"опасен завой надясно","ok":true,"i":null,"es":"curva peligrosa a la derecha"},{"t":"опасност ППС да излезе от пътя надясно","ok":false,"i":null,"es":"peligro de salirse de la vía a la derecha"},{"t":"кръстовище, на което задължително трябва да се завие надясно","ok":false,"i":null,"es":"intersección con giro obligatorio a la derecha"},{"t":"място за паркиране край пътя","ok":false,"i":null,"es":"zona de aparcamiento junto a la vía"}],"f":4,"es":"Esta señal advierte de:","explain":"Advierte de una CURVA PELIGROSA A LA DERECHA — «опасен завой надясно».\n\nLA SEÑAL. Triángulo rojo con el trazo grueso doblándose hacia la derecha.\n\nES LA IMAGEN ESPEJO DE LA 5167, la curva a la izquierda. Las dos son señales de peligro: avisan de la geometría de la vía, no ordenan nada.\n\nQUÉ TE PIDE. Ajustar la velocidad ANTES de entrar, no dentro. Frenar en plena curva transfiere el peso al eje delantero y hace perder adherencia al trasero; la velocidad se corrige en la recta previa, que es exactamente para lo que sirve el aviso.\n\n«INTERSECCIÓN CON GIRO OBLIGATORIO A LA DERECHA» sería un círculo AZUL. La forma descarta la opción antes de mirar el dibujo.\n\n«PELIGRO DE SALIRSE DE LA VÍA» y «ZONA DE APARCAMIENTO» no corresponden a este pictograma.\n\nCLAVE: dentro de un triángulo, un trazo curvo es siempre una curva. El mismo trazo dentro de un círculo azul sería una orden. Forma primero, dibujo después.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Fondo naranja o amarillo = distintivo del vehículo o señalización temporal. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo».","val":4,"fase":4},{"id":5189,"bg":"При навлизане в завой, с увеличаването на скоростта, устойчивостта на превозното средство се влошава.","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"f":5,"es":"Al entrar en una curva, con el aumento de la velocidad, la estabilidad del vehículo empeora. Esto es:","explain":"Correcto: a más velocidad en la misma curva, más fuerza centrífuga (crece con el cuadrado de la velocidad) y peor estabilidad. Por eso la velocidad se reduce ANTES de entrar en la curva.","val":5,"fase":4},{"id":5193,"bg":"Как се променя устойчивостта на превозното средство, при движение в завой, с намаляване на радиуса на завоя?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"влошава се","ok":true,"i":null,"es":"empeora"},{"t":"подобрява се","ok":false,"i":null,"es":"mejora"},{"t":"не се променя","ok":false,"i":null,"es":"no cambia"}],"f":6,"es":"¿Cómo cambia la estabilidad del vehículo en curva al reducirse el radio de la curva?","explain":"Empeora: a menor radio (curva más cerrada), mayor fuerza centrífuga a igual velocidad, y el vehículo tiende más a salirse o volcar. Radio pequeño exige velocidad pequeña.","val":6,"fase":4},{"id":5196,"bg":"Този пътен знак предупреждава, за приближаване към:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21171.png","v":null,"a":[{"t":"платно за движение, стеснено от двете страни","ok":true,"i":null,"es":"calzada estrecha por ambos lados"},{"t":"мост","ok":false,"i":null,"es":"puente"},{"t":"тунел","ok":false,"i":null,"es":"túnel"},{"t":"съоръжение за аварийно спиране","ok":false,"i":null,"es":"dispositivo de parada de emergencia"}],"f":5,"es":"Esta señal advierte de la aproximación a:","explain":"Advierte de una CALZADA ESTRECHADA POR AMBOS LADOS — «платно за движение, стеснено от двете страни».\n\nLA SEÑAL. El tercer miembro del trío: los DOS trazos se doblan hacia dentro, uno contra otro.\n\nQUÉ IMPLICA. La calzada se cierra por los dos costados a la vez. Es la situación típica de un puente estrecho, un paso bajo un arco o un tramo de obras con vallas a ambos lados.\n\n«PUENTE» y «TÚNEL» son los distractores naturales, porque muchas veces la causa del estrechamiento es precisamente un puente o un túnel. Pero la señal no anuncia la obra de fábrica: anuncia la ANCHURA. El túnel tiene su propia señal, con la boca dibujada.\n\n«DISPOSITIVO DE PARADA DE EMERGENCIA» es otra cosa: se señaliza en descensos largos para camiones sin frenos.\n\nCLAVE: el trío completo, para no dudar nunca. Un trazo doblado a la izquierda → se estrecha por la izquierda. A la derecha → por la derecha. Los dos → por ambos. Y la causa (puente, obras, túnel) no es lo que la señal declara.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información o indicación. Rombo amarillo = prioridad. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo».","val":5,"fase":4},{"id":5258,"bg":"Този пътен знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334673.png","v":null,"a":[{"t":"предупреждава за кръстовище с път отдясно, който е без предимство","ok":true,"i":null,"es":"advierte de intersección con vía a la derecha sin prioridad"},{"t":"указва посоки за преминаване на следващото кръстовище","ok":false,"i":null,"es":"indica direcciones en la próxima intersección"},{"t":"сигнализира място за спиране край пътя","ok":false,"i":null,"es":"señaliza zona de parada junto a la vía"},{"t":"сигнализира за уширение на платното за движение","ok":false,"i":null,"es":"señaliza ensanchamiento de la calzada"}],"f":4,"es":"Esta señal:","explain":"Advierte de una INTERSECCIÓN CON UNA VÍA A LA DERECHA SIN PRIORIDAD.\n\nLA SEÑAL. Triángulo rojo con un trazo vertical GRUESO y un ramal FINO que sale hacia la derecha.\n\nLA GRAMÁTICA DEL GROSOR, la misma que usas en las tablas de dirección: el trazo grueso es la vía con prioridad — la tuya —, y el fino es la secundaria que se incorpora. El aviso es «viene un cruce en el que mandas tú, y entra alguien por la derecha».\n\nQUÉ NO SIGNIFICA. No te obliga a nada. Los triángulos avisan; no ordenan. Sigues teniendo que comprobar que el de la secundaria te cede de verdad, porque un aviso no frena a nadie.\n\nFORMA FAMILIA con la de ramal a la izquierda, la de ramales a ambos lados y la del aspa. Todas son triángulos de cruce y solo cambia el dibujo interior: dónde entra la secundaria, o si no hay jerarquía en absoluto.\n\n«INDICA DIRECCIONES EN LA PRÓXIMA INTERSECCIÓN» sería un panel rectangular de orientación, no un triángulo.\n\nCLAVE: grueso mandas tú, fino cede el otro. Si no hay trazo grueso, es el aspa y vuelve la regla de la derecha.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Fondo naranja o amarillo = distintivo del vehículo o señalización temporal. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo».","val":4,"fase":4},{"id":5296,"bg":"На показаната схема с буква „в” е означен пътният знак, който сигнарлизира, че разстоянието до железопътния прелез е:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27779.png","v":null,"a":[{"t":"80 м","ok":false,"i":null,"es":"80 m"},{"t":"160 м","ok":false,"i":null,"es":"160 m"},{"t":"240 м","ok":true,"i":null,"es":"240 m"}],"f":5,"es":"En el esquema mostrado, con la letra \"в\" está indicada la señal que informa de que la distancia hasta el paso a nivel es:","explain":"En Bulgaria las señales previas al paso a nivel se colocan a 240m (tres barras), 160m (dos barras) y 80m (una barra). La 'в' indica la más alejada = 240 metros.","val":5,"fase":4},{"id":5540,"bg":"При коя от изброените височини автомобилът е извънгабаритен:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"височина 4,5 м","ok":true,"i":null,"es":"altura 4.5 m"},{"t":"височина 4,3 м","ok":true,"i":null,"es":"altura 4.3 m"},{"t":"височина 4,1 м","ok":true,"i":null,"es":"altura 4.1 m"},{"t":"височина 3,9 м","ok":false,"i":null,"es":"altura 3.9 m"}],"f":4,"es":"¿A qué altura es un vehículo fuera de gálibo? (3 correctas)","explain":"El límite de altura es 4 m: 4,1, 4,3 y 4,5 m lo superan y son fuera de gálibo; 3,9 m queda dentro. Basta comparar cada cifra con el umbral de 4.","val":4,"fase":4},{"id":5807,"bg":"Слизането на деца до 12 години от автомобил, спрял на платното за движение, се извършва от:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"страната на тротоара","ok":true,"i":null,"es":"el lado de la acera"},{"t":"страната на пътния банкет","ok":true,"i":null,"es":"el lado del arcén"},{"t":"страната на водача на МПС","ok":false,"i":null,"es":"el lado del conductor"},{"t":"от по-удобната за водача страна","ok":false,"i":null,"es":"el lado más cómodo para el conductor"}],"f":3,"es":"La bajada de niños menores de 12 años de un vehículo parado en la calzada se realiza por: (2 correctas)","explain":"Los menores de 12 años bajan por el lado de la ACERA o del ARCÉN: nunca hacia el tráfico. El lado del conductor da a la calzada: justo donde pasan los coches.","val":3,"fase":4},{"id":6040,"bg":"Сигналът за извършване на маневра се подава:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"преди започване на маневрата","ok":true,"i":null,"es":"antes de iniciar la maniobra"},{"t":"със започване на маневрата","ok":false,"i":null,"es":"al inicio de la maniobra"},{"t":"след започване на маневрата","ok":false,"i":null,"es":"después de iniciar la maniobra"}],"f":4,"es":"La señal de maniobra se da:","explain":"La señal se da ANTES de iniciar la maniobra: su función es avisar con antelación para que los demás reaccionen. Señalizar al inicio o después ya no avisa nada: solo describe lo que ya está pasando.","val":4,"fase":4},{"id":12023,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":7,"a":[{"t":"продължавам да се движа с ниска скорост/бавно, тъй като няма признаци, че някой пешеходец иска да премине по пътеката","ok":false,"i":null,"es":"continúo lentamente porque no hay indicios de que nadie vaya a cruzar"},{"t":"спирам, защото детето на левия тротоар ще слезе на платното за движение","ok":false,"i":null,"es":"paro porque el niño de la acera izquierda bajará a la calzada"},{"t":"спирам, защото човекът, който приближава отдясно бягайки, ще премине по пешеходната пътека","ok":true,"i":null,"es":"paro porque la persona que corre por la derecha cruzará el paso de peatones"}],"f":4,"es":"¿Cuál es la actuación correcta en esta situación? (VIDEO)","explain":"🎬 VIDEO: la persona que corre desde la derecha se dirige al paso de peatones — debes parar. El niño de la izquierda está en la acera sin señales de cruzar. La persona corriendo es la prioridad.","val":4,"fase":4},{"id":6076,"bg":"Разположението върху пътя на червения автомобил, движещ се извън населено място е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60500.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"incorrecta"},{"t":"правилно","ok":false,"i":null,"es":"correcta"}],"f":9,"es":"La posición del coche rojo que circula fuera de población es:","explain":"INCORRECTA. Circula por el carril izquierdo teniendo libre el derecho, y fuera de población hay que ir lo más a la derecha posible. El carril izquierdo se ocupa para adelantar y se abandona al terminar; no es un carril de viaje. Que no moleste a nadie en ese momento no lo legaliza: la obligación de ir a la derecha no depende de que haya tráfico o no.","val":14,"fase":3},{"id":6096,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63543.png","v":null,"a":[{"t":"е разрешено да използвам за движение най-удобната за мен пътна лента","ok":true,"i":null,"es":"está permitido usar el carril que me resulte más cómodo"},{"t":"длъжен съм да се движа възможно най-вдясно на платното за движение","ok":false,"i":null,"es":"estoy obligado a circular lo más a la derecha posible de la calzada"},{"t":"трябва да се движа в най-дясната свободна лента","ok":false,"i":null,"es":"debo circular por el carril libre situado más a la derecha"}],"f":11,"es":"En esta situación:","explain":"Está permitido usar el carril que me resulte más cómodo.\n\nSE CUMPLEN LAS TRES CONDICIONES, y hay que verlas las tres. Primera: estás en poblado, lo dicen los edificios y el tipo de vía. Segunda: la calzada tiene dos o más carriles en tu sentido y están declarados con la señal correspondiente, que ves a ambos lados. Tercera: la velocidad máxima permitida es 60 km/h, por debajo del límite de 80 que fija la excepción.\n\nCON LAS TRES, DESAPARECE LA OBLIGACIÓN de ir por el carril libre más a la derecha. Puedes elegir el que te convenga y mantenerte en él.\n\n«DEBO CIRCULAR LO MÁS A LA DERECHA POSIBLE» y «DEBO IR POR EL CARRIL LIBRE MÁS A LA DERECHA» son las dos formas de enunciar la regla general, y las dos son falsas aquí porque la excepción está activa.\n\nFÍJATE EN EL «60» DEL CÍRCULO ROJO. Círculo rojo es prohibición: velocidad MÁXIMA. Si fuera un círculo azul sería mínima obligatoria, y la lectura de la escena cambiaría por completo.\n\nCLAVE: es la aplicación práctica de la 11685. Poblado + señal de carriles + máxima ≤ 80. Si falta una sola, vuelves a la derecha.\n\nMÉTODO DE CARRILES: 1) ¿cuántos carriles tiene MI sentido? 2) ¿la línea es continua o discontinua? 3) ¿hay señal Д1? 4) ¿el carril está reservado? Desarrollado en Leyes → «Carriles y líneas: quién puede ir por dónde».","val":16,"fase":3},{"id":6099,"bg":"При тази ситуация водачът на червения автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63839.png","v":null,"a":[{"t":"може да продължи да се движи в лявата лента","ok":true,"i":null,"es":"puede continuar en el carril izquierdo"},{"t":"може да използва за движение по-удобната за него пътна лента","ok":true,"i":null,"es":"puede usar el carril más cómodo"},{"t":"трябва да премине в дясната лента","ok":false,"i":null,"es":"debe pasar al carril derecho"},{"t":"трябва да се движи в най-дясната свободна лента","ok":false,"i":null,"es":"debe circular por el carril libre situado más a la derecha"}],"f":9,"es":"En esta situación el conductor del coche rojo: (2 correctas)","explain":"MULTIRESPUESTA: puede seguir en el carril izquierdo y puede usar el que le resulte más cómodo. Estamos EN POBLACIÓN, y con dos o más carriles en el mismo sentido el conductor elige por cuál circula. Las otras dos exigen bajarse al carril más a la derecha, que es la regla de FUERA de población. La misma maniobra es correcta en ciudad e infracción en carretera.","val":14,"fase":3},{"id":6404,"bg":"При тази ситуация няма да извърша нарушение ако:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64182.png","v":null,"a":[{"t":"премина в дясната пътна лента","ok":true,"i":null,"es":"paso al carril derecho"},{"t":"продължа движението си в същата пътна лента","ok":true,"i":null,"es":"continúo en el mismo carril"},{"t":"премина в лявата пътна лента","ok":false,"i":null,"es":"paso al carril izquierdo"},{"t":"спра пред светофара, в лентата, над която е поставен","ok":false,"i":null,"es":"paro ante el semáforo, en el carril sobre el que está colocado"}],"f":9,"es":"En esta situación no cometo infracción si: (2 correctas)","explain":"MULTIRESPUESTA: pasar al carril derecho o seguir en el mismo. El pórtico lleva semáforos de carril: la flecha VERDE hacia abajo indica que ese carril está abierto, y la X marca el carril cerrado. Por eso no puedes irte al izquierdo. Y detenerte ante el pórtico tampoco: la flecha verde ordena continuar, y pararse en un carril abierto crea el peligro que la señal quiere evitar.","val":14,"fase":3},{"id":6438,"bg":"При тази ситуация, на водача на червения автомобил е разрешено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64417.png","v":null,"a":[{"t":"да продължи движението си в същата пътна лента","ok":true,"i":null,"es":"continuar en el mismo carril"},{"t":"да премине в дясната пътна лента","ok":true,"i":null,"es":"pasar al carril derecho"},{"t":"да премине в лявата пътна лента","ok":false,"i":null,"es":"pasar al carril izquierdo"}],"f":8,"es":"En esta situación, al conductor del coche rojo le está PERMITIDO: (2 correctas)","explain":"Dos cosas: continuar en el mismo carril Y pasar al carril derecho.\n\nLA SEÑAL QUE DECIDE ESTÁ A LA DERECHA DE LA CALZADA: es la Д1 «Брой на пътните ленти и посоки за движение по тях» — número de carriles y sentidos de circulación por ellos. Rectángulo blanco con una flecha vertical por carril. Aquí: la flecha de la izquierda apunta HACIA ABAJO y las otras dos HACIA ARRIBA.\n\nFLECHA HACIA ABAJO = ese carril, el de la izquierda, es para el tráfico que viene de frente. La norma permite expresamente que la Д1 indique también los carriles destinados al sentido contrario.\n\nLAS DOS FLECHAS HACIA ARRIBA = los otros dos carriles son de nuestro sentido. El rojo circula por uno de ellos y el otro está a su derecha.\n\nPOR ESO «CONTINUAR EN EL MISMO CARRIL» ES CORRECTO: está en un carril de su sentido y nada le obliga a salir.\n\nY «PASAR AL CARRIL DERECHO» TAMBIÉN: es un carril de su mismo sentido, así que el cambio es una maniobra normal, con intermitente y comprobando el espejo.\n\n«PASAR AL CARRIL IZQUIERDO» ES LO ÚNICO PROHIBIDO: ese carril lleva el tráfico contrario. Meterse ahí es circular en sentido contrario.\n\nCLAVE: cuenta las flechas de la Д1 antes de cambiar de carril. Tres carriles no significa tres carriles tuyos. La señal vale hasta la siguiente intersección.","val":13,"fase":3},{"id":6446,"bg":"На кои ППС е разрешено движението в BUS - лентата след този знак?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64672.png","v":null,"a":[{"t":"на ППС от редовните линии за обществен превоз на пътници","ok":true,"i":null,"es":"a los vehículos de líneas regulares de transporte público"},{"t":"на всички автобуси","ok":false,"i":null,"es":"a todos los autobuses"},{"t":"на таксиметровите автомобили","ok":false,"i":null,"es":"a los taxis"},{"t":"на бавнодвижещите се превозни средства","ok":false,"i":null,"es":"a los vehículos lentos"}],"f":9,"es":"¿A qué vehículos está permitido circular por el carril BUS después de esta señal?","explain":"A los vehículos de las líneas regulares de transporte público de pasajeros.\n\nQUÉ VES. Una calle con el carril derecho delimitado en amarillo y, en el poste de la derecha, la señal que declara ese carril reservado al transporte público.\n\nLA SEÑAL DELIMITA EL DERECHO. Después de ella, ese carril solo es utilizable por los vehículos de línea regular. Lo que cambia respecto a la marca amarilla sola es que la señal fija dónde empieza el régimen.\n\n«TODOS LOS AUTOBUSES» es falso: el criterio es prestar servicio de línea regular, no ser un autobús.\n\n«LOS TAXIS» es falso en Bulgaria. En algunas ciudades europeas los taxis sí pueden; aquí no, salvo que una señal complementaria lo autorice expresamente. Es el distractor que más cae porque se apoya en la experiencia de otros países.\n\n«LOS VEHÍCULOS LENTOS» mezcla dos carriles reservados distintos.\n\nCLAVE: es la pregunta gemela de la 9840, preguntada desde la señal en vez de desde la situación. La respuesta es siempre la misma fórmula literal: «редовните линии за обществен превоз на пътници».\n\nMÉTODO DE CARRILES: 1) ¿cuántos carriles tiene MI sentido? Con dos o más nunca se invade el contrario. 2) ¿la línea es continua o discontinua? 3) ¿hay señal Д1 que declare los carriles? 4) ¿el carril está reservado (BUS, lentos)? Desarrollado en Leyes → «Carriles y líneas: quién puede ir por dónde».","val":14,"fase":3},{"id":6455,"bg":"При тази ситуация в средната пътна лента е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65112.png","v":null,"a":[{"t":"разрешено движението на автобуси с ремаркета","ok":false,"i":null,"es":"permitida la circulación de autobuses con remolque"},{"t":"разрешено движението на леки автомобили с ремаркета","ok":false,"i":null,"es":"permitida la circulación de turismos con remolque"},{"t":"забранено движението на товарни автомобили с ремаркета","ok":true,"i":null,"es":"prohibida la circulación de camiones con remolque"},{"t":"забранено движението на товарни автомобили с полуремаркета","ok":true,"i":null,"es":"prohibida la circulación de camiones con semirremolque"}],"f":8,"es":"En esta situación en el carril central está: (2 correctas)","explain":"MULTIRESPUESTA: en el carril central está PROHIBIDA la circulación de camiones con remolque y de camiones con semirremolque.\n\nLA SEÑAL. El disco rojo con el camión y su remolque prohíbe los conjuntos de vehículos de carga, y el panel de debajo indica a qué carril se aplica. La señal azul de la derecha confirma que la calzada tiene tres carriles.\n\nREMOLQUE Y SEMIRREMOLQUE cuentan igual: los dos forman un conjunto articulado, y la prohibición no distingue entre ellos.\n\nLOS DOS DISTRACTORES invierten el sentido: dicen 'permitida' donde la señal dice prohibida, y además cambian el vehículo — autobuses y turismos con remolque no son a quienes va dirigida esta señal.\n\nCLAVE: mira siempre el panel de debajo; sin él no sabes a qué carril se aplica la prohibición.","val":12,"fase":3},{"id":6462,"bg":"Мотопедистите могат да използват за движение пътния банкет, който:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"се намира отдясно по посока на движението им","ok":true,"i":null,"es":"está a la derecha en su sentido de marcha"},{"t":"се намира отляво по посока на движението им","ok":false,"i":null,"es":"está a la izquierda en su sentido de marcha"},{"t":"е по-удобен за тях, независимо от коя страна на пътя се намира","ok":false,"i":null,"es":"sea más cómodo independientemente de su lado"}],"f":9,"es":"Los ciclomotores pueden usar el arcén que:","explain":"Solo el arcén DERECHO en su sentido de marcha: los ciclomotores circulan siempre pegados a la derecha. Usar el arcén izquierdo significaría circular a contramano del flujo, y la 'comodidad' no es criterio legal.","val":13,"fase":3},{"id":9838,"bg":"При тази ситуация разположението на червения автомобил върху платното за движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043160.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"incorrecta"},{"t":"правилно","ok":false,"i":null,"es":"correcta"}],"f":9,"es":"En esta situación la posición del coche rojo en la calzada es:","explain":"INCORRECTA.\n\nQUÉ VES. Una vía con dos carriles en el mismo sentido. El coche rojo circula por el carril IZQUIERDO teniendo el derecho libre.\n\nLA REGLA. Fuera de poblado se circula por el carril más a la derecha que esté libre. Los carriles de la izquierda son para adelantar, no para viajar por ellos.\n\nPOR QUÉ NO BASTA CON «NO MOLESTAR A NADIE». La norma no depende de que haya tráfico detrás: ocupar el carril izquierdo sin adelantar es incorrecto en sí mismo, porque obliga a los que llegan a maniobrar y porque desordena el uso de la vía.\n\nCUÁNDO SÍ PODRÍAS IR POR LA IZQUIERDA: mientras adelantas, mientras rodeas un obstáculo, o cuando el carril derecho está ocupado. Nada de eso pasa aquí, y por eso la posición es incorrecta.\n\nY OJO: en POBLADO la regla se relaja — puedes usar el carril que te convenga si se cumplen tres condiciones concretas, que son las de la pregunta 11685. Fuera de poblado no.\n\nCLAVE: derecha por defecto, izquierda solo para adelantar. Si tienes el carril derecho libre y no estás adelantando, estás mal colocado.\n\nMÉTODO DE CARRILES: 1) ¿cuántos carriles tiene MI sentido? Con dos o más nunca se invade el contrario. 2) ¿la línea es continua o discontinua? 3) ¿hay señal Д1 que declare los carriles? 4) ¿el carril está reservado (BUS, lentos)? Desarrollado en Leyes → «Carriles y líneas: quién puede ir por dónde».","val":14,"fase":3},{"id":11685,"bg":"Кои от посочените условия е необходимо да бъдат налице за да може при движение в населено място водачът да използва най-удобната за него пътна лента?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62284.png","v":null,"a":[{"t":"пътното платно да е с две и повече пътни ленти за движение в една посока","ok":true,"i":null,"es":"la calzada tiene dos o más carriles en una dirección"},{"t":"броят на пътните ленти и посоките за движение по тях да са обозначени с пътен знак","ok":true,"i":null,"es":"el número de carriles y las direcciones están señalizados"},{"t":"разрешената скорост за движение да е не по-голяма от 80 km/h","ok":true,"i":null,"es":"la velocidad máxima permitida es no superior a 80 km/h"},{"t":"пътят да е с две платна за движение","ok":false,"i":null,"es":"la vía tiene dos calzadas de circulación"}],"f":9,"es":"¿Qué condiciones deben cumplirse para que, circulando en poblado, el conductor pueda usar el carril más cómodo para él? (3 correctas)","explain":"Tres condiciones, y hacen falta las tres a la vez.\n\nLA CALZADA DEBE TENER DOS O MÁS CARRILES EN UN MISMO SENTIDO. Con un solo carril no hay nada que elegir.\n\nEL NÚMERO DE CARRILES Y SUS SENTIDOS DEBEN ESTAR SEÑALIZADOS. Es la señal Д1 «Брой на пътните ленти и посоки за движение по тях», la que ves en el poste. Sin ella no existe la declaración formal de carriles y sigue mandando la regla general de ir por la derecha.\n\nLA VELOCIDAD MÁXIMA PERMITIDA NO DEBE SUPERAR LOS 80 km/h. Por encima de esa velocidad la disciplina de carriles vuelve a ser estricta, porque las diferencias de velocidad se vuelven peligrosas.\n\n«QUE LA VÍA TENGA DOS CALZADAS» es el distractor. Suena a autopista y a más seguridad, pero no es una de las condiciones: lo que importa son los carriles de tu sentido, la señal y el límite de velocidad, no cuántas calzadas tenga la vía.\n\nCLAVE: es la excepción a la regla de circular por la derecha, y solo vale en poblado. Memoriza el trío: dos carriles + señal Д1 + hasta 80 km/h. Si falta una, vuelves a la derecha.\n\nMÉTODO DE CARRILES: 1) ¿cuántos carriles tiene MI sentido? Con dos o más nunca se invade el contrario. 2) ¿la línea es continua o discontinua? 3) ¿hay señal Д1 que declare los carriles? 4) ¿el carril está reservado (BUS, lentos)? Desarrollado en Leyes → «Carriles y líneas: quién puede ir por dónde».","val":14,"fase":3},{"id":5797,"bg":"Този пътен знак:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334711.png","v":null,"a":[{"t":"сигнализира за край на ограничението на скоростта, въведено с пътен знак","ok":true,"i":null,"es":"señaliza el final de la limitación de velocidad impuesta por señal"},{"t":"забранява движението на МПС, които не могат да развият скорост, по-голяма от означената","ok":false,"i":null,"es":"prohíbe circular a vehículos que no pueden alcanzar la velocidad indicada"},{"t":"забрананява движението със скорост, по-висока от означената","ok":false,"i":null,"es":"prohíbe circular a velocidad superior a la indicada"},{"t":"забрананява движението със скорост, по-ниска от означената","ok":false,"i":null,"es":"prohíbe circular a velocidad inferior a la indicada"}],"f":6,"es":"Esta señal:","explain":"Señaliza el FINAL de la limitación de velocidad impuesta por una señal anterior.\n\nLA SEÑAL. Círculo blanco con la cifra tachada por barras diagonales. Las barras son la marca universal de «край» — fin: cancelan lo que la señal decía.\n\nQUÉ PASA DESPUÉS. Vuelve a aplicarse el límite general del tramo: 50 km/h en poblado, 90 fuera, 120 en autopista, salvo que otra señal diga otra cosa. No significa «velocidad libre».\n\n«PROHÍBE SUPERAR LA VELOCIDAD INDICADA» es la señal SIN tachar, que es un círculo rojo con la cifra. Es el distractor central y se distingue por dos cosas a la vez: el borde rojo y la ausencia de barras.\n\n«PROHÍBE CIRCULAR A VELOCIDAD INFERIOR» describiría un mínimo, que es el círculo AZUL.\n\n«PROHÍBE CIRCULAR A LOS QUE NO PUEDEN ALCANZAR ESA VELOCIDAD» no corresponde a ninguna señal de este grupo.\n\nCLAVE: las barras diagonales cancelan. En cuanto veas una cifra tachada, la respuesta es «fin de», nunca «prohibido».\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Rombo amarillo = prioridad. Rectángulo = información. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo».","val":9,"fase":4},{"id":5798,"bg":"След този пътен знак няма ограничение за скоростта на движение.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53963.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":6,"es":"Después de esta señal no hay ninguna limitación de velocidad. Esto es:","explain":"⚠️ TRAMPA: INCORRECTO — aunque haya terminado la restricción específica señalizada, siguen aplicando los límites generales de la vía (50 en ciudad, 90 en carretera, etc.).","val":9,"fase":4},{"id":5821,"bg":"Този пътен знак:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334713.png","v":null,"a":[{"t":"указва задължителна минимална скорост за движение","ok":true,"i":null,"es":"indica velocidad mínima obligatoria"},{"t":"забранява движение със скорост, по-висока от означената","ok":false,"i":null,"es":"prohíbe circular a velocidad superior a la indicada"},{"t":"указва препоръчителна скорост за движение","ok":false,"i":null,"es":"indica velocidad recomendada"}],"f":5,"es":"Esta señal:","explain":"Indica velocidad MÍNIMA obligatoria — «задължителна минимална скорост».\n\nLA SEÑAL. Círculo AZUL con la cifra en blanco. Azul es siempre obligación en el código búlgaro.\n\nQUÉ TE OBLIGA A HACER. A no circular por debajo de esa velocidad. Si tu vehículo no puede alcanzarla, no debes entrar en ese tramo o carril.\n\n«PROHÍBE SUPERAR LA VELOCIDAD INDICADA» es el distractor que responde casi todo el mundo, porque el reflejo es leer cualquier número redondo como un límite máximo. El máximo es círculo ROJO con la cifra en negro.\n\n«VELOCIDAD RECOMENDADA» no es esta señal: la recomendación se indica en un rectángulo, no en un círculo, y no obliga.\n\nDÓNDE SE PONE. En túneles largos, carriles rápidos y tramos donde un vehículo lento crea peligro por sí mismo.\n\nCLAVE: el par que hay que fijar es este — azul con cifra = mínima obligatoria, rojo con cifra = máxima prohibida. Mismo número, órdenes opuestas. Aparece en 5797, 5821, 11687 y 11688.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Rombo amarillo = prioridad. Rectángulo = información. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo».","val":7,"fase":4},{"id":5827,"bg":"При тази ситуация разрешено ли е движение със скорост по-ниска от означената?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57482.png","v":null,"a":[{"t":"да, когато няма необходимите условия за безопасност","ok":true,"i":null,"es":"sí, cuando no hay las condiciones necesarias de seguridad"},{"t":"да, във всички случаи","ok":false,"i":null,"es":"sí, en todos los casos"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":5,"es":"En esta situación ¿está permitido circular a velocidad inferior a la indicada?","explain":"SÍ pero solo cuando la seguridad lo requiere — lluvia, hielo, niebla, obstáculos. La velocidad mínima cede ante la seguridad. No puedes ir más lento por comodidad.","val":8,"fase":4},{"id":5905,"bg":"При тази ситуация, за да осигуря по-голяма безопасност за децата, е достатъчно само да увелича страничната дистанция.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58320.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":3,"es":"En esta situación, para dar mayor seguridad a los niños, es suficiente con solo aumentar la distancia lateral. Esto es:","explain":"INCORRECTO — ante niños en la vía no basta con prestar más atención. Debes reducir velocidad. La atención sin reducción de velocidad no garantiza la capacidad de frenar a tiempo.","val":4,"fase":4},{"id":5907,"bg":"При тази ситуация, за да осигуря безопасността за велосипедиста при изпреварването, е достатъчно само да намаля скоростта.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58514.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":5,"es":"En esta situación, para garantizar la seguridad del ciclista al adelantarlo, es suficiente con solo reducir la velocidad. Esto es:","explain":"INCORRECTO — al adelantar a un ciclista necesitas tanto atención como distancia lateral mínima de 1.5 metros. Solo la atención sin distancia suficiente no es seguro.","val":7,"fase":4},{"id":6696,"bg":"Най-силно влияние върху големината на коефициента на сцепление на автомобилните гуми с пътя оказват:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"състоянието на пътната настилка","ok":true,"i":null,"es":"el estado del pavimento"},{"t":"състоянието на автомобилната гума","ok":true,"i":null,"es":"el estado del neumático"},{"t":"видът на окачването на автомобила","ok":false,"i":null,"es":"el tipo de suspensión del vehículo"},{"t":"диаметърът на автомобилните гуми","ok":false,"i":null,"es":"el diámetro de los neumáticos"}],"f":3,"es":"¿Qué factor influye más en el coeficiente de rozamiento de los neumáticos con el pavimento? (2 correctas)","explain":"Los dos factores dominantes del rozamiento: estado del PAVIMENTO (seco/mojado/hielo) y estado del NEUMÁTICO (dibujo, desgaste). La suspensión y el diámetro no determinan la adherencia.","val":5,"fase":4},{"id":11699,"bg":"Когато няма други ограничения, водачът на автомобил от категория В1 при движение в населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 km/h","ok":true,"i":null,"es":"50 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"}],"f":5,"es":"Sin otras restricciones, el conductor de vehículo categoría B1 en zona urbana puede circular a máximo:","explain":"50 km/h: los B1 (cuadriciclos pesados) siguen el límite urbano general. En población, 50 km/h es el techo para todos los vehículos de motor salvo señal.","val":8,"fase":4},{"id":12003,"bg":"Какво трябва да направите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":12,"a":[{"t":"да намаля скоростта и да управлявам с готовност за спиране","ok":true,"i":null,"es":"reducir velocidad y circular listo para frenar"},{"t":"да продължа движението си, без да променям скоростта си","ok":false,"i":null,"es":"continuar sin cambiar la velocidad"},{"t":"да навляза в лявата пътна лента","ok":false,"i":null,"es":"cambiar al carril izquierdo"}],"f":7,"es":"¿Qué debes hacer en esta situación? (VIDEO)","explain":"🎬 VIDEO: ante obstáculo en la vía siempre reduces velocidad y te preparas para frenar. Cambiar de carril sin visibilidad es peligroso. Continuar igual tampoco.","val":10,"fase":3},{"id":6226,"bg":"При тази ситуация, водачът на червения автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69536.png","v":null,"a":[{"t":"трябва да пропусне синия автомобил, защото навлиза в лентата, по която той се движи","ok":true,"i":null,"es":"debe dejar pasar al azul porque entra en su carril"},{"t":"преди да се включи в движението трябва да се убеди, че няма да създаде опасност за другите участници в него","ok":true,"i":null,"es":"antes de incorporarse debe asegurarse de no crear peligro"},{"t":"е с предимство защото се намира отдясно","ok":false,"i":null,"es":"tiene prioridad porque está a la derecha"}],"f":7,"es":"En esta situación el conductor del coche rojo: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el rojo cede porque invade el carril del azul Y porque al incorporarse siempre debes verificar la seguridad. Estar a la derecha no da prioridad al incorporarse.","val":11,"fase":3},{"id":6231,"bg":"Кой от водачите е с предимство при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69569.png","v":null,"a":[{"t":"водачът на лекия автомобил","ok":true,"i":null,"es":"el conductor del turismo"},{"t":"водачът на товарния автомобил","ok":false,"i":null,"es":"el conductor del camión"}],"f":7,"es":"¿Qué conductor tiene prioridad en esta situación?","explain":"El conductor del TURISMO.\n\nQUÉ VES. Un camión que sale de una posición estacionada o de un acceso, con las luces de emergencia, y un turismo circulando por la calzada.\n\nQUIEN SE INCORPORA A LA CIRCULACIÓN, CEDE. Salir de un estacionamiento, de un patio, de una gasolinera o de una vía sin pavimentar no es entrar en un cruce: es incorporarse al tráfico. El que ya circula tiene preferencia siempre.\n\nEL TAMAÑO DEL CAMIÓN NO CUENTA. Ser grande, pesado o difícil de maniobrar no otorga ningún derecho. El banco usa camiones en estas preguntas precisamente porque imponen respeto en la vida real y mucha gente traduce ese respeto en una prioridad que no existe.\n\nLAS LUCES DE EMERGENCIA TAMPOCO DAN PASO. Advierten de una situación anómala; no autorizan nada. Es el mismo principio que hace falsa la opción del claxon en la 6668.\n\nCLAVE: antes de aplicar reglas de cruce, comprueba si lo que tienes delante es realmente un cruce. Incorporación, salida de estacionamiento y confluencia se resuelven con «cede el que entra», no con la derecha.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":10,"fase":3},{"id":6261,"bg":"При тази ситуация съм с предимство и не съм задължен да пропусна пешеходеца:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70018.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":5,"es":"En esta situación tengo prioridad y no estoy obligado a dejar pasar al peatón. Esto es:","explain":"⚠️ TRAMPA IMPORTANTE: INCORRECTO — los peatones en paso de peatones tienen SIEMPRE prioridad, independientemente de tu prioridad de paso vehicular. El peatón en el paso siempre manda.","val":8,"fase":4},{"id":6301,"bg":"При тази ситуация трябва да премина преди червения автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70581.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":5,"es":"En esta situación debo pasar antes que el coche rojo. Esto es:","explain":"INCORRECTO — el rojo tiene prioridad sobre ti en esta situación. Debes cederle el paso.","val":8,"fase":4},{"id":6305,"bg":"При тази ситуация водачът на товарния автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70647.png","v":null,"a":[{"t":"трябва да пропусне двата автомобила, защото излиза от гараж","ok":true,"i":null,"es":"debe dejar pasar a los dos coches porque sale de un garaje"},{"t":"трябва да пропусне пешеходците","ok":true,"i":null,"es":"debe dejar pasar a los peatones"},{"t":"е с предимство пред синия автомобил, защото се намира от дясната му страна","ok":false,"i":null,"es":"tiene prioridad sobre el azul porque está a su derecha"}],"f":4,"es":"En esta situación, el conductor del camión: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: al salir de un garaje siempre cedes a TODO el tráfico de la calle + a los peatones. El camión no tiene prioridad sobre nadie al salir de una propiedad privada.","val":5,"fase":4},{"id":6334,"bg":"При тази ситуация съм с предимство, защото се движа направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70713.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":9,"es":"En esta situación tengo prioridad porque voy recto. Esto es:","explain":"INCORRECTO. En tu acceso hay un ceda el paso, así que debes dejar pasar a quien circula por la vía con prioridad, y además el tranvía tiene preferencia sobre los vehículos sin carriles. Ir recto no otorga preferencia a nadie: la dirección que lleves no entra en el reparto de prioridad. Es un cebo que se repite mucho en el examen — desconfía siempre de 'porque voy recto'.","val":13,"fase":3},{"id":6343,"bg":"При тази ситуация водачът на автомобила длъжен ли е да пропусне трамвая?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70879.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":7,"es":"En esta situación ¿está obligado el conductor del coche a dejar pasar al tranvía?","explain":"SÍ — el tranvía tiene prioridad. En la mayoría de situaciones los tranvías tienen prioridad sobre los vehículos de motor.","val":11,"fase":3},{"id":6378,"bg":"При тази ситуация водачът на червения автомобил извършва ли нарушение?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71309.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":7,"es":"En esta situación ¿comete infracción el conductor del coche rojo?","explain":"SÍ — el coche rojo está infringiendo alguna norma en la situación mostrada (adelantamiento indebido, invasión de carril, etc.).","val":10,"fase":3},{"id":6380,"bg":"Когато, при голям надлъжен наклон, за разминаване на единично ППС със състав от ППС е необходимо движение назад, то се извършва от:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"единичното превозно средство","ok":true,"i":null,"es":"el vehículo individual"},{"t":"ППС, което се изкачва по наклона","ok":false,"i":null,"es":"el vehículo que sube"},{"t":"ППС, което се спуска по наклона","ok":false,"i":null,"es":"el vehículo que baja"},{"t":"състава от ППС","ok":false,"i":null,"es":"el convoy"}],"f":7,"es":"Cuando en pendiente pronunciada un vehículo individual debe ceder el paso a un convoy, ¿quién retrocede?","explain":"Retrocede el vehículo INDIVIDUAL: hacer retroceder un convoy (vehículo + remolque) es mucho más difícil y peligroso. La regla general sube/baja solo se aplica entre vehículos de condiciones equivalentes.","val":10,"fase":3},{"id":6381,"bg":"Когато, на път с голям надлъжен наклон, за разминаването на лек с товарен автомобил е необходимо движение назад, то се извършва от:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"лекия автомобил","ok":true,"i":null,"es":"el turismo"},{"t":"товарния автомобил","ok":false,"i":null,"es":"el camión"},{"t":"автомобила, който се изкачва по наклона","ok":false,"i":null,"es":"el que sube"},{"t":"автомобила, който се спуска по наклона","ok":false,"i":null,"es":"el que baja"}],"f":7,"es":"Cuando en pendiente pronunciada un turismo debe ceder el paso a un camión, ¿quién retrocede?","explain":"Retrocede el TURISMO: es más corto, más maniobrable y con mejor visibilidad trasera que el camión. Entre vehículos de distinta categoría decide la facilidad de la maniobra, no quién sube o baja.","val":10,"fase":3},{"id":6399,"bg":"Кое от изброените ППС е забранено да изпреварвате след този пътен знак?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67607.png","v":null,"a":[{"t":"лек автомобил","ok":true,"i":null,"es":"turismo"},{"t":"съчленен автобус","ok":true,"i":null,"es":"autobús articulado"},{"t":"мотоциклет без кош","ok":false,"i":null,"es":"moto sin sidecar"},{"t":"каруца","ok":false,"i":null,"es":"carruaje"}],"f":5,"es":"¿Qué vehículo está PROHIBIDO adelantar después de esta señal? (2 correctas)","explain":"Dos: el turismo y el autobús articulado.\n\nLA SEÑAL. Círculo rojo con dos coches, uno de ellos en rojo: «Изпреварването е забранено» — prohibido adelantar a los vehículos de motor.\n\nLO QUE PROHÍBE. Adelantar a cualquier МПС, vehículo a motor. El turismo y el autobús articulado lo son, así que están dentro de la prohibición: son las dos respuestas.\n\n«МОТОЦИКЛЕТ БЕЗ КОШ» — motocicleta sin sidecar — es la EXCEPCIÓN expresa de la señal. A una moto de dos ruedas sí puedes adelantarla dentro de la zona prohibida. Con sidecar, ya no.\n\n«КАРУЦА» — carro de tracción animal — queda fuera por otro motivo: no es un vehículo a motor. Es ППС pero no МПС, y la señal solo alcanza a los МПС.\n\nDOS EXCLUSIONES, DOS RAZONES DISTINTAS. La moto está excluida por una excepción escrita en la norma; el carro, porque nunca estuvo incluido. Conviene distinguirlo: es lo que separa entender de memorizar.\n\nCLAVE: aquí se ve por qué importa la diferencia entre ППС y МПС. Es la misma señal de la 6408, preguntada al revés.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Rombo amarillo = prioridad. Rectángulo = información. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo».","val":7,"fase":4},{"id":6413,"bg":"Изпреварването на МПС, с изключение на мотопеди и мотоциклети без кош, е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"при използване на пътна лента за насрещно движение, когато изпреварващият не може да се върне безпрепятствено в напуснатата пътна лента","ok":true,"i":null,"es":"usando el carril contrario no es posible volver al carril sin obstaculizar"},{"t":"пред и върху сигнализирана пешеходна пътека","ok":true,"i":null,"es":"la visibilidad es limitada"},{"t":"в стеснен участък от пътя","ok":false,"i":null,"es":"el vehículo adelantante tiene los intermitentes averiados"},{"t":"на железопътен прелез с бариери","ok":false,"i":null,"es":"se realiza en vía de dos carriles de doble sentido"}],"f":5,"es":"El adelantamiento está PROHIBIDO cuando: (2 correctas)","explain":"Igual que su gemela: prohibido si no puedes volver a tu carril sin obstaculizar y con visibilidad limitada. La avería del intermitente se suple con señales de mano, y adelantar en vía de doble sentido es legal cuando hay visibilidad y espacio.","val":8,"fase":4},{"id":6418,"bg":"Разрешено ли е изпреварването при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71819.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":8,"es":"¿Está permitido adelantar en esta situación?","explain":"NO.\n\nEL TRIÁNGULO CON LA CRUZ avisa de que llega un cruce con una vía de IGUAL VALOR. No es un aspa de paso a nivel ni un símbolo decorativo: te está diciendo que ninguna de las dos vías tiene preferencia sobre la otra.\n\nESTÁ PROHIBIDO ADELANTAR EN LAS INTERSECCIONES, y la única excepción es circular por una vía con prioridad. Aquí las vías son de igual valor, así que la excepción no te sirve y el adelantamiento queda prohibido.\n\nQUE DELANTE VAYA UNA FURGONETA LENTA no cambia nada. La prohibición depende del lugar, no de lo que te estorbe.\n\nCLAVE: en cuanto veas señal de cruce próximo, deja de pensar en adelantar. Solo se salva quien va por vía con prioridad señalizada.","val":12,"fase":3},{"id":6434,"bg":"Как ще постъпите при тази ситуация, когато автомобилът зад вас е подал сигнал за отклонение вляво?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124384.png","v":null,"a":[{"t":"намалявам скоростта и пропускам автомобила зад мен","ok":true,"i":null,"es":"reduzco velocidad y dejo pasar al coche de detrás"},{"t":"подавам сигнал и заобикалям повредения автомобил, преди автомобила, който се движи зад мен","ok":false,"i":null,"es":"señalizo y rodeo el coche averiado antes que el de detrás"}],"f":8,"es":"¿Cómo actuarás en esta situación cuando el coche detrás señaliza desplazarse a la izquierda?","explain":"REDUZCO LA VELOCIDAD Y DEJO PASAR AL COCHE DE DETRÁS.\n\nEL DE ATRÁS YA HA SEÑALIZADO su desplazamiento a la izquierda: ha iniciado la maniobra antes que tú. Lo ves en el retrovisor con el intermitente puesto.\n\nANTES DE EMPEZAR CUALQUIER MANIOBRA hay que comprobar que no estorbas a quien ya está realizando la suya. Si sales ahora a rodear el vehículo averiado, te cruzas delante de alguien que ya va hacia ese hueco.\n\n'SEÑALIZO Y RODEO ANTES QUE ÉL' convierte la maniobra en una carrera. El orden lo marca quién empezó primero, no quién acelera más.\n\nCLAVE: mirar por el retrovisor forma parte de la maniobra, no es un extra. Quien ya está maniobrando tiene la preferencia sobre quien va a empezar.","val":13,"fase":3},{"id":6451,"bg":"Движението назад при ограничена видимост е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"разрешено само ако е осигурено лице, което да сигнализира при поява на опасност","ok":true,"i":null,"es":"permitida solo si hay alguien que señalice el peligro"},{"t":"разрешено, ако има огледало за виждане назад","ok":false,"i":null,"es":"permitida si hay espejo retrovisor"},{"t":"забранено","ok":false,"i":null,"es":"prohibida"}],"f":7,"es":"La marcha atrás con visibilidad limitada está:","explain":"Con visibilidad limitada, la marcha atrás solo está permitida si alguien desde fuera vigila y señaliza el peligro. El espejo retrovisor no cubre los ángulos muertos precisamente cuando la visibilidad ya es mala; prohibida del todo no está.","val":10,"fase":3},{"id":12036,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":22,"a":[{"t":"продължавам движението си, без да променям скоростта си","ok":false,"i":null,"es":"continúo sin cambiar velocidad"},{"t":"продължавам движението си в лентата за паркиране","ok":false,"i":null,"es":"continúo por el carril de estacionamiento"},{"t":"продължавам движението си, като увеличавам скоростта си","ok":false,"i":null,"es":"acelero"},{"t":"намалявам скоростта си","ok":true,"i":null,"es":"reduzco la velocidad"}],"f":2,"es":"¿Cuál es la actuación correcta en esta situación? (VIDEO)","explain":"🎬 VIDEO: reduce velocidad. Sea cual sea el obstáculo o situación mostrada, la reducción de velocidad es siempre la respuesta correcta ante la incertidumbre.","val":2,"fase":4},{"id":12051,"bg":"Искате да изпреварите. При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":43,"a":[{"t":"изпреварвам трите превозни средства, които се движат пред мен, наведнъж (с една маневра)","ok":false,"i":null,"es":"adelanto los tres vehículos de una vez"},{"t":"не предприемам изпреварване, преди да се убедя, че водачът на синия автомобил няма да изпреварва","ok":true,"i":null,"es":"no adelanto hasta confirmar que el coche azul no va a adelantar"},{"t":"когато синият автомобил започне изпреварването, изпреварвам, като се движа зад него","ok":false,"i":null,"es":"cuando el azul empiece a adelantar, me pongo detrás de él"}],"f":6,"es":"Quiere adelantar. En esta situación: (VIDEO)","explain":"🎬 VIDEO: NO adelantes hasta confirmar que el azul no va a hacer lo mismo. Adelantar por encima de otro que ya adelanta es una maniobra peligrosísima.","val":9,"fase":4},{"id":5884,"bg":"При този сигнал на светофара навлизането в кръстовището е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/102995.png","v":null,"a":[{"t":"разрешено, освен когато водачът може да остане в кръстовището поради задръстване","ok":true,"i":null,"es":"permitido, excepto si quedaras bloqueado dentro por retención"},{"t":"разрешено без ограничения","ok":false,"i":null,"es":"permitido sin restricciones"},{"t":"забранено","ok":false,"i":null,"es":"prohibido"}],"f":9,"es":"Con esta señal del semáforo entrar en la intersección está:","explain":"Permitido, excepto si vas a quedarte bloqueado dentro de la intersección por una retención.\n\nQUÉ VES. El semáforo de la derecha en VERDE.\n\nLA REGLA Y SU LÍMITE. El verde permite entrar, pero no obliga. Si al otro lado del cruce el tráfico está detenido y se ve que te vas a quedar parado dentro, no debes entrar aunque tengas verde: bloquearías la vía transversal cuando ellos reciban su luz.\n\n«PERMITIDO SIN RESTRICCIONES» es el distractor, y es tentador porque el verde parece incondicional. No lo es.\n\n«PROHIBIDO» es lo contrario.\n\nPOR QUÉ ESTO CAE EN EL EXAMEN. Es la regla que convierte el verde de permiso automático en decisión: mira SIEMPRE si tienes salida antes de entrar.\n\nCLAVE: verde con salida = pasas. Verde sin salida = esperas antes de la línea. Lo mismo que en 5906: el verde autoriza el movimiento, no lo impone.\n\nMÉTODO DEL SEMÁFORO: 1) ¿parpadea o es fija? Немигащ = fija; мигащ = intermitente, y significan cosas distintas. 2) ¿qué focos están encendidos? 3) ¿hay flecha? Una flecha verde solo abre esa dirección, no las demás. Desarrollado en Leyes → «El semáforo: significado oficial de cada señal».","val":14,"fase":3},{"id":5952,"bg":"При тази ситуация, при преминаване през кръстовището, трябва да се съобразявате:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51499.png","v":null,"a":[{"t":"със сигнала на светофара","ok":true,"i":null,"es":"la señal del semáforo"},{"t":"с пьтния знак забраняващ завиването надясно","ok":true,"i":null,"es":"la señal que prohíbe girar a la derecha"},{"t":"с пьтния знак относно предимството","ok":false,"i":null,"es":"la señal de prioridad"}],"f":9,"es":"En esta situación al pasar por la intersección debes atenerte a: (2 correctas)","explain":"Dos cosas: la señal del SEMÁFORO y la señal que PROHÍBE GIRAR A LA DERECHA.\n\nQUÉ VES. Un STOP, un semáforo en verde y un círculo rojo con la flecha tachada que prohíbe girar a la derecha.\n\nEL SEMÁFORO DESPLAZA AL STOP. Es el escalón superior: con el verde encendido no tienes que detenerte en la línea de STOP. La señal de prioridad queda sin efecto mientras el semáforo funcione.\n\nLA PROHIBICIÓN DE GIRAR SIGUE EN PIE, y aquí está el aprendizaje. El semáforo solo desplaza a las señales de PRIORIDAD. Las de prohibición, obligación y dirección conservan toda su fuerza: el verde te dice cuándo puedes pasar, no hacia dónde.\n\n«LA SEÑAL DE PRIORIDAD» es por tanto la única falsa de las tres.\n\nES LA HERMANA DE LA 6608, donde el elemento que sobrevive al semáforo es una dirección obligatoria en lugar de una prohibición. Misma lógica, distinto tipo de señal.\n\nCLAVE: con el semáforo en verde, sigue leyendo el resto de señales. La única que puedes ignorar es la de prioridad.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","val":14,"fase":3}];